window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_001"]={"n":"王世贞","dyn":"明","poems":[{"t":"送内弟魏生还里 其四","f":"五言绝句","c":["阿姊扶床泣，诸甥绕膝啼。","平安只两字，莫惜过江题。"]},{"t":"戚将军赠宝剑歌 其五","f":"七言绝句","c":["曾向沧流剸怒鲸，酒阑分手赠书生。","芙蓉涩尽鱼鳞老，总为人间事渐平。"]},{"t":"岳王墓","f":"七言律诗","c":["落日松杉黯自垂，英风萧飒动灵祠。","空传赤帝中兴诏，自折黄龙大将旗。","三殿有人朝北极，六陵无树对南枝。","莫将乌喙论勾践，鸟尽弓藏也不悲。"]},{"t":"梦中得语云百年那得更百年今日还须爱今日因戏成短歌","f":"七言古诗","c":["化人宫中百事无，道书一卷酒一壶。","枝头黄鸟听作曲，西山白云看作图。","朝爱朝暾上东岫，夕爱夕阳映东牖。","任他故人不通谒，任它朝事不挂口。","偶然案头馀酒杯，偶然蹑屩山僧来。","自斟自醉当自去，礼岂能为我辈哉。","昨夜懵腾意超忽，寱时得语醒时述。","百年那得更百年，今日还须爱今日。","纵能拂衣归故山，农耕社剧亦不闻。","何如且会此中趣，别有生涯天地间。"]},{"t":"望江南 即事","f":"古风","c":["歌起处，斜日半江红。","柔绿篙添梅子雨，淡黄衫耐藕丝风。","家在五湖东。"]},{"t":"寓怀 其十五","f":"五言古诗","c":["文景体恭俭，陈粟俯丘山。","易世因其资，气欲盖九纮。","柏梁既以灾，建章遂造天。","蜀汉穷材木，少府罄金钱。","原麓既如髡，闾井宁不然。","感此池上翁，精灵泣帝前。","天心虽仁爱，毋乃滋倒悬。"]},{"t":"杂诗九首 其六","f":"五言古诗","c":["没人游大壑，出入鲛鳄间。","手持珊瑚树，口噤不能言。","务光岂有希，亦自湛于渊。","各顾徇所好，焉能两攀援。","道逢衣冠客，毂击马不旋。","与子行苦殊，何用见疑患。"]},{"t":"过固始许忠节公祠","f":"七言古诗","c":["朱邸殽烝伏兵发，少年使者眦独裂。","建礼门前一腔血，飞作彭湖斗间铁。","义旗十万横江起，忽有长虹穿贼垒。","一时缚累如缚豕，逝者人耶生者鬼。","龙章再锡帝宠稠，犹闻曲突心未酬。","不令长孺寝逆谋，汉阙要挂吴王头。","固始祠中柏色古，父老椎牲考钟鼓。","南有孙侯北有许，令人扼腕悲壬午。"]},{"t":"题仙岩文丞相祠","f":"古风","c":["丞相仓皇出虎穴，夜半真州鬓成雪。","江南是处万马尘，海上堪挥一腔血。","丈夫变名难变心，此心在宋不在身。","从行少年四五辈，倜傥千秋荆聂伦。","崖山波腥鼓欲死，柴市星寒碧初委。","若使黄冠自北还，犹能赤帜从东起。","仙岩之山郁嶙峋，二百年来日月新。","毋论削迹勤王地，大有衣冠荐芷蘋。","君不见真人奋淮北，金戈立扫毡裘色。","鄂国喑呜表后身，瀛公宛转留遗息。","解道狂胡运已微，只今白羽昼长飞。","铁衣自风石马汗，一夕犁庭转战归。"]},{"t":"为钱世重题悬罄室","f":"七言古诗","c":["钱郎坐我悬罄室，要我为作悬罄篇。","我歌欲就须斗酒，君言室中无一钱。","空梁颇受落月色，北窗仅可凉风眠。","门前黄叶霜如洗，刺促归来愧妻子。","已少成都学士裘，祇饶东郭先生履。","挂壁蟏蛸寒欲堕，当门鸟雀时空喜。","自矜顾恺为前身，丹青在手终不贫。","只愁妙画通神去，依旧能生釜底尘。"]},{"t":"经封丘记故尉高适诗有作","f":"七言古诗","c":["我行长夏之封丘，红尘罨汗汗不流。","东邻苦酒苦于药，西舍浊醪浊似油。","马头黄绶令勿跪，恐有当时高蜀州。","拜迎官长亦细事，鞭挞黎庶将何求。","一官大小各有味，不置齿舌应即休。","诸君异日但北首，看我归骑凌清秋。"]},{"t":"领郧阳命出朝口号","f":"七言古诗","c":["五花小龙团墨敕，生新宝钞鸦翎黑。","黄封饵合纷后随，法酒三杯壮行色。","纵然才劣忝军镇，稍喜时清偃兵革。","节度从他学襄样，征南自古多书癖。","碧油幢底见故人，唤作粗官粗亦得。"]},{"t":"怀柔道中","f":"五言律诗","c":["马足吾何限，山行稍自宽。","人家梅雨色，衣袖麦秋寒。","过瀑添新径，归云改故峦。","断肠沙雁起，一一向长安。"]},{"t":"过冶泉","f":"五言律诗","c":["偶经盘石坐，下有暗泉过。","受月苔阴少，分云竹色多。","幽岩答樵斧，小屋见渔蓑。","不浅沧浪兴，风尘可奈何。"]},{"t":"太原道中书事 其一","f":"五言律诗","c":["盘陀十二驿，驿驿似西川。","毕竟中无地，还疑小有天。","居民同伏鼠，宿客傍栖鸢。","不待蝉声苦，秋霜向鬓边。"]},{"t":"太原道中书事 其二","f":"五言律诗","c":["不断峰峦色，何由见晋阳。","傍山兔三穴，入地鼠千仓。","项为泉奔瘿，牙因枣熟黄。","吴儿莫相笑，风俗古陶唐。"]},{"t":"奉寄客部朱丈子价戏效其体","f":"七言律诗","c":["白门啼鸟双垂杨，主人读书殊未央。","经霜柿叶已满屋，过雨薜荔将窥床。","十年清梦飞天姥，几度新诗走夜郎。","为闻青州使君态，胡缨小马绿沈枪。"]},{"t":"闰十月朔病中作","f":"七言律诗","c":["伏枕人间万事轻，偶探残历唤愁生。","初疑玉殿仍颁朔，不谓玄冥再主盟。","病似黄杨多进退，情如芳草易枯荣。","谁怜止酒无多睡，夜夜清霜闰五更。"]},{"t":"履省任后之吴兴部戏作","f":"七言律诗","c":["纵然名姓堕尘寰，身比阇黎可较閒。","锡杖乍飞天竺寺，芒鞋还踏道场山。","三生公案聊须检，十部除书了不关。","细雨斜风应便住，故乡原在一帆间。"]},{"t":"长至夜起坐忆家","f":"七言律诗","c":["一枕乡山路未真，篝灯起坐独伤神。","天心肯傍微阳转，物色从争朔气新。","久客爱听初减漏，唤班羞作未归人。","江南两地俱愁寂，总向天涯话病身。"]},{"t":"游南高峰","f":"七言律诗","c":["从游指点南高胜，蹑屩攀萝兴不赊。","画里馀杭人卖酒，镜中湖曲棹穿花。","千岩半出分秋雨，一径微明逗晚霞。","最是夜归幽绝处，疏林灯火傍渔家。"]},{"t":"山行至虎跑泉庵次苏长公石刻韵","f":"七言律诗","c":["百草沾风蚕月香，双鸠唤雨麦秋凉。","过桥已觉世情少，到寺始知僧日长。","拂藓石留行脚偈，挂瓢泉是洗心方。","良公更有茶瓜在，禅悦能容取次尝。"]},{"t":"初自彭城山行闻莺","f":"七言律诗","c":["水宿逶迤不计程，有无春事未分明。","白门渡口逢三月，黄鸟行边始一声。","句向清时稀感慨，官因迟暮减心情。","祇园桃李花如锦，秖为游人特底生。"]},{"t":"卫河八绝 其二","f":"五言绝句","c":["河流曲曲转，十里还相唤。","那比下江船，扬帆忽不见。"]},{"t":"卫河八绝 其四","f":"五言绝句","c":["十五谁家女，红妆娇自多。","低头浣衣坐，不解听吴歌。"]},{"t":"卫河八绝 其六","f":"五言绝句","c":["人家半侵河，屋后晒渔网。","夜深唤小妇，篝灯听波响。"]},{"t":"卫河八绝 其八","f":"五言绝句","c":["人云风波恶，风波信自恶。","生长在家乡，那得容华落。"]},{"t":"闺恨","f":"五言绝句","c":["兴庆坊前柳，萧郎手自栽。","藏鸦今渐稳，只是不归来。"]},{"t":"西宫怨二首 其二","f":"七言绝句","c":["点点莲花漏未央，乍寒如水透罗裳。","谁怜金井梧桐露，一夜鸳鸯瓦上霜。"]},{"t":"小伊州","f":"七言绝句","c":["频年转战未封侯，还逐高阳酒伴游。","醉后秖今愁出塞，双鬟又唱小伊州。"]},{"t":"从军行八首 其一","f":"七言绝句","c":["蹋臂归来六博场，城中白羽募征羌。","相逢试解吴钩看，已是金河万里霜。"]},{"t":"弘治宫词十二首 其二","f":"七言绝句","c":["南海珠池贡已稀，西川又罢锦文机。","朝来御服三经浣，贱妾宁希曳地衣。"]},{"t":"弘治宫词十二首 其三","f":"七言绝句","c":["禁苑先朝红药台，御筵亲为两宫开。","莫嫌宫监希恩赏，玉辇何曾更一来。"]},{"t":"弘治宫词十二首 其四","f":"七言绝句","c":["午槐圆影覆彤除，今日天颜喜气舒。","稳坐御床无一语，但称难得老尚书。"]},{"t":"弘治宫词十二首 其六","f":"七言绝句","c":["黄帕朱奁覆御羞，手题颁赐寿宁侯。","昆明督亢从渠请，今日台官在殿头。"]},{"t":"弘治宫词十二首 其九","f":"七言绝句","c":["静数莲筹第五更，寒鸦金井未分明。","披衣欲坐犹疑早，前殿连传警跸声。"]},{"t":"弘治宫词十二首 其十二","f":"七言绝句","c":["急遣追锋召外家，南宫桃李正如霞。","自从光禄裁宣索，长日从容且赐茶。"]},{"t":"正德宫词二十首 其三","f":"七言绝句","c":["仙《韶》别院奏新声，不按唐山曲里名。","青鹞白翎俱入破，十三弦底似雷鸣。"]},{"t":"正德宫词二十首 其四","f":"七言绝句","c":["金鳌桥畔柳丝长，舴艋舱头有柘黄。","六院少儿初病酒，御前亲自过鱼汤。"]},{"t":"正德宫词二十首 其六","f":"七言绝句","c":["窄衫盘凤称身裁，玉靶雕弓月样开。","红粉别依回鹘队，君王亲自虎城来。"]},{"t":"正德宫词二十首 其八","f":"七言绝句","c":["玉水垂杨面面栽，豹房官邸接天开。","行人莫爱缠头锦，万乘亲歌压酒杯。"]},{"t":"正德宫词二十首 其九","f":"七言绝句","c":["夜半毬灯出未央，俄传鞞铎向平阳。","六宫处处秋如水，不独长门玉漏长。"]},{"t":"正德宫词二十首 其十","f":"七言绝句","c":["绨案东头有皂囊，不知畴日进封章。","付教河下金珰手，莫遣君王甲夜忙。"]},{"t":"正德宫词二十首 其十三","f":"七言绝句","c":["平明东阁下恩纶，兽铠鸾翿色色新。","大内别开元帅府，传声侍女莫称臣。"]},{"t":"正德宫词二十首 其二十","f":"七言绝句","c":["敕扫椒风第二房，俱传倩女出平康。","天宫欲晓人间事，约伴相过话夕阳。"]},{"t":"西城宫词十二首 其一","f":"七言绝句","c":["芙蓉新样紫霞冠，细拥珠琲小凤团。","一片香烟丛里出，玉真朝罢簇回銮。"]},{"t":"西城宫词十二首 其二","f":"七言绝句","c":["新传牌子赐昭容，第一仙班雨露浓。","袋里相公书疏在，莫教香汗湿泥封。"]},{"t":"西城宫词十二首 其三","f":"七言绝句","c":["五雷坛上雷一声，海子闸口雨纵横。","祈灵验后催传赏，马上朱提玉手擎。"]},{"t":"西城宫词十二首 其四","f":"七言绝句","c":["色色罗衫称体裁，铺宫新例一齐开。","菱花小样黄金合，昨夜真人进药来。"]},{"t":"西城宫词十二首 其五","f":"七言绝句","c":["花底传筹到五更，隐囊斜倚到天明。","寒霜不敢蒙头坐，暖阁时聆謦欬声。"]},{"t":"西城宫词十二首 其七","f":"七言绝句","c":["两角鸦青双箸红，灵犀一点未曾通。","自缘身作延年药，憔悴春风雨露中。"]},{"t":"西城宫词十二首 其十一","f":"七言绝句","c":["侍女俱传厌虏符，猫为铁骑鼠为奴。","挦扯一博天颜喜，八宝金钱踠地铺。"]},{"t":"甘泉歌","f":"七言绝句","c":["千尺通星井干楼，玉盘天酒夜来收。","白茅螭捧黄金印，五利明朝欲拜侯。"]},{"t":"偶成 其二","f":"七言绝句","c":["三载寒庐梦不成，悔将馀债伴残生。","南楼酒力初微后，依旧萧萧夜雨声。"]},{"t":"解任后得明卿罢官报寄赠二章 其二","f":"七言律诗","c":["邮书一到不堪闻，起剔残灯坐夜分。","塞马论来终是失，冥鸿去后许谁群。","无妨中散来千里，更喜延之咏五君。","与说近踪应稍慰，买山全占洞庭云。"]},{"t":"姚匡叔以道术为用晦诸王上客携其书来访惓惓七子之盛有感而赠","f":"七言律诗","c":["握手相知柰晚何，且将鱼素慰蹉跎。","淮南道术宾初盛，邺下风流事已过。","见数八公君第几，空传七子世无多。","春来社酒能从否，莫道闲门雀可罗。"]},{"t":"书怀","f":"七言律诗","c":["风为开扉旋掩扉，春催花发又花飞。","客歌夫子哀时命，天与先生杜德机。","久自青云词伯少，从他白简酒人非。","兴来烂漫挥毫罢，且复婆娑里社归。"]},{"t":"和王百谷怀出妾","f":"七言律诗","c":["离怀黯■未分明，祗忆郎君一句清。","妾与书生俱薄命，花随春帝不长情。","愁回樊素行时首，枉却红儿死后名。","谁道两坊三百步，阳关分作断肠声。"]},{"t":"将赴留尹出门作","f":"七言律诗","c":["迭鼓鸣榔试晓风，倦游心事寄冥鸿。","已拚车畔闻歌凤，何必幡头有画熊。","游客似夸轻薄尹，居人应唤冶城公。","离筵欲向清洋尽，依旧三弇醉梦中。"]},{"t":"抵丹阳闻南中有流言即返棹","f":"七言律诗","c":["幸不将身与念违，艖符转首便成归。","紫衫频着难长是，白简虽烦未尽非。","耳惯酒酣元不热，心安食少也能肥。","江东尽有容人处，水石中间一钓矶。"]},{"t":"投劾南归抵家作","f":"七言律诗","c":["剥啄应令稚子疑，雀门风雨昼凄其。","能如五日张京兆，又作当年柳士师。","瓮底尚残斟别酒，尊前能咏解嘲诗。","祗嫌三老来催直，不及山阴兴尽时。"]},{"t":"偶成 其一","f":"七言律诗","c":["匡床眠坐尽优游，兴至三杯过即休。","小出便支邛竹杖，轻寒旋进木棉裘。","争春桃李差嫌富，滴雨空阶不起愁。","较得近来诗句拙，肯容心力费雕搜。"]},{"t":"闭关","f":"七言律诗","c":["虚自群喧草大还，不多青眼畏尘寰。","由他国士谁谋国，若个山人肯往山。","长病医方无胜懒，渐贫生计莫如悭。","地垆榾柮煨生芋，风雨萧萧且闭关。"]},{"t":"九月闭关谢笔砚而千里故人讯问不绝又多以诗及者遂成此二律志苦且代荅 其一","f":"七言律诗","c":["小径衡门鸟雀余，祗因才尽爱闲居。","诸缘暂息交犹在，一病虽轻懒未除。","玉案有无知莫较，银钩早晚竟难虚。","于今却羡桓司马，博得空函省报书。"]},{"t":"斋室初成有劝多栽花竹者走笔示之","f":"七言律诗","c":["一室缘溪断俗尘，翛然吾自爱吾真。","浇花怕结春时业，种竹防惊梦里神。","梧叶到秋无那病，芭蕉过暑不堪贫。","何如且放空庭在，月色风光好近人。"]},{"t":"癸未元日过敬美小酌试笔","f":"七言律诗","c":["献岁家园倚杖过，剧欢儿辈奈衰何。","寒贪棣萼连枝暖，病怯屠苏半户多。","白屋千家同惨淡，黄冠一老自婆娑。","长安日有维新诏，不必春风到薜萝。"]},{"t":"送殷无美赴夷陵守","f":"七言律诗","c":["十年清问满公车，今睹方州建隼旟。","东下江平知禹凿，西来土黑是秦余。","渚宫人去烟俱冷，巫峡才多雪不如。","俱道大夫饶赋咏，莫因天远废双鱼。"]},{"t":"有感","f":"七言律诗","c":["出处频年尚属人，于今不出始由身。","留将顶相称居士，洗却头衔字道民。","一锸随身那讳死，三餐度口不缘贫。","寄声无限同盟者，苦海中间学问津。"]},{"t":"有所闻作 其二","f":"七言律诗","c":["闻道弓旌及隐沦，可缘真遇爱龙人。","虚云展氏曾三黜，其那王尊仅一身。","苜蓿总肥沙塞晚，桃花无恙武陵春。","欲知元亮篮舆意，畏踏丹阳郭里尘。"]},{"t":"游潘顾诸园毕自题弇园","f":"七言律诗","c":["踏遍名园意未舒，大都京洛贵人居。","穿钱作埒难调马，镂石铺池碍种鱼。","似比幼舆输一壑，转令元亮爱吾庐。","兴来呼得尖头艇，喂蚁烹鳞信所如。"]},{"t":"徐二公子邀与陆司寇吴司空游东园","f":"七言律诗","c":["六月冰壶生昼凉，侯家池馆胜平阳。","楼头霁色开鳷鹊，台上新云似凤皇。","客诧郇公厨味好，人惊卫尉厕衣香。","不烦投辖深相挽，小舫青油系绿杨。"]},{"t":"徐九公子园亭即事","f":"七言律诗","c":["粉窦斜通宛转廊，壶中山水待长房。","轻云入坐笼朱阁，小雨将歌逗画梁。","客重不虚公子席，花娇欲施令君香。","已教昼漏迟迟报，犹自贪闻子夜长。"]},{"t":"过大宗伯徐公留饮山池出所欢明童佐酒","f":"七言律诗","c":["轻榕小舫受凉飔，正及东山行乐时。","杨柳腰新宫傅宅，芙蓉客满卫军池。","朱颜不待餐云母，白苎亲调付雪儿。","欢剧翻追少年事，射阳帆底对弹棋。"]},{"t":"徐大宗伯同唐张娄三子见饯至新洋江始别","f":"七言律诗","c":["新洋江口好停舟，淡月笼烟破暝愁。","君卧可能忘象阙，予行终拟问菟裘。","娇歌易作双青眼，别酒难禁两白头。","总是秣陵多胜地，却惭人唤凤凰游。"]},{"t":"山僮言游客放歌折花者戏答之 其二","f":"七言绝句","c":["携酒看花不碍频，唯求酒后护残春。","不辞树树凭攀折，孤却明朝花下人。"]},{"t":"寄卢次楩","f":"七言绝句","c":["大伾山头花满烟，春来竟日酒垆眠。","不知妻子关何事，乞取囊中卖赋钱。"]},{"t":"浣溪沙 春闷","f":"古风","c":["窗外閒丝自在游。","隔山花鸟弄?辀。","一庭芳草怨清幽。","权把束书钩午梦，起沽村酒泼春愁。","放教残日过墙头。"]},{"t":"菩萨蛮","f":"古风","c":["断风依约愁砧乱。","乱砧愁约依风断。","无语对灯孤。","孤灯对语无。","冷香留去影。","影去留香冷。","思后梦来期。","期来梦后思。"]},{"t":"虞美人 别思","f":"古风","c":["摩诃池上金丝柳。","惯爱纤纤手。","折来将表片时心。","记取浅黄柔绿、泪痕深。","博山香细银灯吐。","乍识黄昏雨。","娇花欲展半蔫红。","错道褪残春事、骂东风。"]},{"t":"虞美人 寄怀","f":"古风","c":["浮萍只待杨花去。","况更廉纤雨。","鸭头虚染最长条。","酝造离亭清泪、几时消。","珊瑚翠色新丰酒。","解醉愁人否。","薄寒撺送汝南鸡。","偏向碧纱厨畔、醒时啼。"]},{"t":"渔家傲","f":"古风","c":["细雨轻烟装小暝。","重衾不耐春寒横。","袅尽博山孤篆影。","閒自省。","天涯有个人同病。","十二巫峰围昼永。","黄莺可唤梨花醒。","两点芳波揩不定。","临晚镜。","真珠簌簌胭脂冷。"]},{"t":"河满子 春郊独行","f":"古风","c":["卵色遥垂别浦，鱼鳞浅甃平沙。","小拂东风无甚力，悠扬自在杨花。","轻暖轻寒天气，半村半郭人家。","碧贮莲花露酒，香分谷雨前茶。","呼取自斟还自劝，乌纱任汝欹斜。","返照一行归骑，隔林几点残鸦。"]},{"t":"玉蝴蝶 拟艳","f":"古风","c":["记得秋娘，家住皋桥西弄，疏柳藏鸦。","翠袖初翻金缕，钩月晕红牙。","启朱唇、含风桂子，唤残醉、微雨梨花。","最堪誇。","玉纤亲自，浓点新茶。","嗟呀。","颠风妒雨，落英千片，断送年华。","海角山尖，不应飘向那人家。","惹新愁、高楼燕子，赚人泪、芳草天涯。","况浔阳，偶然江上，一曲琵琶。"]},{"t":"谒金门 落花","f":"古风","c":["风渐陡。","排比饯花春酒。","憔悴一枝红欲皱。","问花花恋否。","寂寞乍长清昼。","无计与他拖逗。","犹胜销魂人去后。","折来还在手。"]},{"t":"承左虞兄过访赠余长歌感激用壮聊尔志答","f":"古风","c":["张侯若乳虎，少负食牛气。","生平所不平，舍儿比国士。","懒为大将长揖人，何况州司折腰吏。","腰间累累金符黄，再悬再掷还君王。","桃叶渡头解兔鹘，柳花店中脱鹔鹴。","宁容醉尉呵止宿，甘与侏儒共一囊。","虽然落魄高阳里，毕竟难呼纨裤子。","当怀明月将报恩，入匣清霜少知己。","以兹宿草荒蒋径，时复扁舟下娄水。","兴来赠我长歌行，伯氏复与施丹青。","恍如辋川入我案，又似易水溅溅鸣。","虹云缭绕气郁勃，珠玑错落光纵横。","丈夫有才终有用，为汝感慨神俱竦。","生欲椎周子南床，死欲掘顾元公冢。","嗣宗见忌双眼色，宣明可憎一面孔。","汝慎勿学灌将军，我非窦家老秃翁。","偶然小醉漏消息，前身自是汝南公。","但遇人间失意事，相将跳入玉壶中。"]},{"t":"看仲德与张子予轰饮作","f":"七言律诗","c":["小阮时时酒债多，况逢江左步兵过。","相看只解呼红友，半醉犹能卷白波。","百斛从倾银凿落，两山旋对玉傀俄。","欲投客辖翻愁住，将耻吾罍柰若何。"]},{"t":"上帝之什十四章","f":"古风","c":["上帝曰咨，爰揽宏纲。","海内宴然，日月重光。","泗流汤汤，厥源清明，遹发我高皇。","上帝曰咨，祖仁玄德惟身，湛泽惟民。","天之既厌元，则莫我屯。","云龙骧骧，艮索乃降。","笃高皇帝，锡之益益。","用凶德，蚤罹于厄。","亦勤于穑，亦逃于释。","是省是即，靡务不绎。","笃高皇，有晦含章。","迫发厥庆，烈烈元戎。","在濠之阳，骏拔于行。","谋夫孔臧，遂纂大邦。","天之辟隘，维江若带。","惟钟若砺，楼船叇叇。","旭日在铠，抚有江介。","以刘蟊虿，是蒂是刈。","彭蠡浑浑，火波掣云。","旦师陈军，立埽厥氛。","震泽之濆，踯躅惟羵。","王旅于勤，袒缚以奔。","帝省其配，淑人后氏。","夙夜在公，言御言剂。","帝省其辅，曰善长基，如心如股。","曰达遇春，如髀如膂。","达往徂征，驷车彭彭。","庵庐冥冥，如岳不惊。","春也辅行，喑乌迅霆。","飘摇旆旌，目靡衡兵。","玄黄在筐，浆食攸同。","九衢若夷，市不改容。","胡遁于荒，民即其宫。","谁其将者，太傅魏公。","乃下闽粤，乃徂岭服。","田秦巴蜀，滇池羌笮。","庸麇百濮，不宁方来，悉臣悉仆。","元之孙子，厥丽靡纪。","改辫承冠，盘躄其趾。","诗书九有，曷不汪濊。","载俶昆弟，载俶父子。","明明日月，阖辟更始。","于戏高皇，焕肃其制。","济济列辟，大夫三事。","亦既精白，亦既凛畏。","无谪于室，动言及累。","于戏高皇，圣躬聿脩。","翼翼小心，以敬迓休。","声色无荒，无畋于游。","无好是卮言，无忽是远犹。","莫崇匪乾，峻功符之。","莫丽匪阳，昭明仪之。","式廓版图，寓宇其家。","光彼黄虞，曷厉是涤除。","唯俭唯恭，皇贲厥谟。"]},{"t":"皇哉之什十一章","f":"古风","c":["奕奕国枋，累累如冈。","九有茂明，郁积融昌。","帝念蒸氓，以笃孝皇。","孝皇皇哉。","皇统俶纂，时于婴冠。","默黜千嗜，渊穆有灿。","惟函惟璞，惟琢惟瓒。","孝皇皇哉。","帝曰宰恕，毋即而家。","予蓍蔡是趣，恕拜稽首，对扬休谟。","佛逆为愉，罔言不俞。","斋宫甍甍，皇肃厥容。","爰屏厥明，爰塞厥聪。","上帝居歆，百神类从。","辟雍济济，皇肃厥珥。","爰辟厥听，爰廓厥视。","有来青衿，是则是媚。","惟苑在西，勿剪芜莱。","皇戒于离，哕哕鸾輗，喈喈鹍丝。","皇奉太母，式燕以嬉。","无已太康，遄言旋归。","惟苑在北，勿剪芜棘。","皇戒于逸，宛宛醇䮥，煌煌金镝。","皇奉太庙，式狩以猎。","无已太康，遄言旋息。","峨峨诤冠，有廌其颜。","沈沈讲帷，有鸑其端。","彼美翱翔，既衎且闲。","皇曰有三老，皇曰有司马，皇曰有御史。","爰庇爰启，爰父爰子。","密勿共体，佐予于理。","皇曰司会，女其予治，毋析民之脂。","茹俭服素，是积是资。","亟赐赋租，惠我蒸黎。","皇之既徂落，百辟卿士，爰逮四海。","讴吟思痗，若丧考妣。","爰配覆载，爰配我祖。","令闻不已，为亿世轨。"]},{"t":"东门之什二章","f":"楚辞体","c":["东门之梓，其文理兮。","岂其枳哉，毋若而毁。","东门之鸑，其文郁兮。","岂其鵩哉，毋若而诼。"]},{"t":"隰有木之什四章","f":"古风","c":["隰有木，其乔则蠹，师氏削尔以居。","风之飘斯，卒陨卒队。","岂不尔诟，匪尔之故。","隰有苇，其夭孔仪，师氏缉尔以衣。","风之飘斯，卒陨卒隳。","岂不尔诟，匪尔之为。","隰有雈矣，湿有蓷矣。","闵尔之乖然，余已焉怀。","隰有萑矣，湿有蓷矣。","乐尔之惛然，余已焉怀。"]},{"t":"迷阳之什三章","f":"楚辞体","c":["迷阳如束，母罥子足。","伊其埽除，视葹则馥。","媒媒厥好，以余贻辱。","迷阳如荼，母罥子裾。","视葹则馥，伊其埽除。","媒媒厥觏，以余贻诛。","迷阳施施兮，葹离离兮。","将疢子治兮，益子之菑兮。"]},{"t":"菀菀者丛之什四章","f":"楚辞体","c":["菀菀者丛，孔集维鸒。","中一文鸟，其鸣雊雊。","岂不尔类，唯尔之夸。","视棘则黍，有救在嗉。","踯躅毛跣，块不得吐。","凡今之良，无蹈厥队。","嗟我宰父，惟王来绥。","畴不兴止，娥媌令仪。","五马既同，六服孔加。","密云油油，雨窃其施。","淫来无端，亦莫之何。","人有恒言，耳属于墙。","堑崧践华，岂曰匪常。","逝茀洋洋，至菑汤汤。","何以自明，曜灵西藏。","何用重明，纤阿未扬。","机斯伏矣，懵其蹴矣。","机之蹴兮，吁骇速矣。","机之伏兮，伊胡忸矣。"]},{"t":"雨雪之什六章","f":"古风","c":["雨雪滂滂，我马??。","不有劳者，谁其得宁。","受赋于旻，亦莫敢明。","夫既宁止，曰又淫止。","雨雪霏霏，我马蓰蓰。","不有宁者，厥劳焉施。","受赋于旻，亦莫敢辞。","夫既劳止，曰又谣止。","厥谣惟诼，匪齿以角。","岂不尔好，裾接则涅。","人亦有言，投之有庳。","毋投有庳，彼人奚罪。","毋谓尔蜮，毋谓尔回泬。","纵生憧憧，独我之孽。","毋谓余璠，毋谓余靡愆。","曷不悄悄，言思其端。"]},{"t":"谷宫之什二章","f":"楚辞体","c":["谷之宫，不可以风。","畴为栋梁，樕槚檿桑。","彼狡童兮，称干城兮。","谷之宇，不可以雨。","畴为梁栋，檿桑樕槚。","彼狡竖兮，称藩辅兮。"]},{"t":"田车之什二章","f":"楚辞体","c":["毋御田车，樗其轭兮。","毋走乘丘，倾而积兮。","于嗟积兮，于嗟轭兮。","毋汎胶舟，柽其桨兮。","毋之反灉，湛而藏兮。","于嗟藏兮，于嗟桨兮。"]},{"t":"麔䴠之什六章","f":"楚辞体","c":["濯濯麔䴠，逝言窜枳。","虽则匪罞，将创而趾。","我徂唯郊，于以矢死。","我严我诲，创若周体。","天之方威，赫焉焉理。","交交黄鹂，逝言窜棘。","虽则匪罿，将罬而翼。","我徂唯野，于以矢贼。","我严我鞠，罬若通息。","天之方怒，赫焉焉辟。","祸之初萌，厥亦细微。","嗟彼巧言，如雨如霏。","其端如丝，润里孔滋。","匪天行之，人十能之。","祸之方张，厥亦纵横。","嗟彼暴言，如庉如霆。","其疾如飏，受肤孔戕。","匪天成之，人百能之。","天兮人兮，我胡不陈。","翼翼君子，笃棐忱恂。","猃狁内侵，女柅其轮。","王曰禦侮，女锡女珍。","师曰延侮，毋再而身。","皇皇大明，庶几丽旻。","人兮天兮，我曷敢宣。","翼翼君子，靖恭塞渊。","猃狁内侵，女躅其辕。","师曰延侮，女憯女愆。","王曰侮予，毋令而全。","皇皇大明，庶几丽乾。"]},{"t":"钟山之什四章","f":"古风","c":["岩岩钟山，閟我国桢。","赫赫留都，副我国灵。","万雉登登，九墉甍甍。","凡百有位，则于天京。","三事大夫，是瞻是冯。","嗟尔大夫，胡弗靖共。","泄泄司马，龂龂司农。","去食去信，厥兵曷终。","一夫跳踉，刃戕于胸。","为蟊为螟，乃虿乃蜂。","司农逝矣，司马止矣。","司农逝矣，惟国之痗。","司马止矣，惟国之耻。","先民岂不言，施生僇死。","毋纵柙逸，毋泄椟毁。","使者于来，虎嵎以壑。","使者于返，虎翼以角。","虎翼以角，畴不靡止。","虎冠以游，畴不拟止。","太师谋之，以报天子。"]},{"t":"醇驷之什六章","f":"古风","c":["醇驷惟皇，镛贲其镗。","赤芾重英，游环锵锵。","蒙虎煇煌，在蓟之阳。","在蓟之阳，堠戍相望。","零雨霏霏，公徂不归。","蟏蛸绣戈，有鱼在锜。","吐纩离丝，角解筋麋。","毋尔施施，猃狁孔滋。","自昔徵兵，爰始改霜。","今我启行，蔚彼青阳。","及霜遣矣，及冰而转。","青阳晚矣，三时靡选。","稗我甫田，虉我故墉。","笃老在公，妇困于红。","嶷嶷官胥，以佐岁凶。","岂不怀归，王事靡终。","维金与帛，司农所宣。","劳我玺书，什伍在轩。","褐暑絺霜，半菽并飧。","岂不怀悲，沈深九阍。","王曰师氏，女其于辅。","王曰保氏，命女于里。","女其奔走，女其禦侮。","于嗟耄矣，式相好矣。"]},{"t":"泽兰之什六章","f":"楚辞体","c":["泽兰之皓兮，卒以黝兮。","惟子之敖兮，使我不终好兮。","泽兰之芬兮，卒以荤兮。","惟子之惛兮，使我愧弟昆兮。","子在?兮，痗若积兮，饘予之食兮。","予颠踬兮，子泄泄兮，代越视兮。","予之友也，予之谬也。","人之多言，不足道也。","子之友也，予之疚也。","人之多言，亦可丑也。"]},{"t":"奕之什十二章","f":"古风","c":["奕奕昌运，炎炎元后。","尚郁蒸哉，应龙斯奏。","猗我琅琊，寔克英胄。","显祖之假，以锡我父。","是孽是苞，是颖是茂。","猃狁孔炽，蚕我冀方。","我父捍之，爰城大邦。","大邦维城，千雉不崩。","四牡其?，爰锡爰旌。","爰作卿士，朱绂皇皇。","王曰仲氏，岛夷为雠。","匪夷匪犹，女往作辟。","鋈軜乔矛，铺敦旋抽。","剪棘筚路，以遏衡流。","槜李之师，执讯获丑。","狡狡岛夷，思复其痏。","番番馀皇，剽我井里。","逝梁发笱，敝庐如燬。","曾是我人，不恤其梓。","方舟厉兵，用濯厥耻。","帝曰嘉哉，女镇于辅。","作朕股肱，奔走禦侮。","何以申之，镠荡袅蹄。","何以重之，织文檿丝。","召伯之禄，逮尔孙枝。","父拜稽首，孙肤殷锡。","谆谆嗣人，匪树莫克。","昼尔戎行，宵于筹画。","亦既丝鬒，亦既骈足。","刷克厥私，以播休德。","曰余冲人，选于誉髦。","甫刑既攻，乃佐爽鸠。","躁辞好佻，弗剪其骄。","再沐恩纶，出藩齐郊。","钩膺乔乔，露冕逍遥。","曰有介弟，初辞于稚。","岂弟干禄，超彼素士。","维日而中，维月而望。","曷怙不颠，于柏峣冈。","寤寐有摽，食居不遑。","飘风自南，翳眯黄道。","有晤静女，思媚思好。","静女之来，于色于笑。","曷慎脩哉，载咷载噭。","长舌忮哉，我脩则悼。","飘风自南，煽我天威。","司寇民之瞻，匪善骫韦。","天威赫曦，在迩蔑遗。","我父岂不勤，小子是离。","静言思之，痗矣莫追。","言裂其裳，言絓其冠。","薪我乘车，纵牡淄湍。","奏鼓大廷，割析肾肝。","人亦有云，处死实难。","匪已之难，虞彼狴犴。","有斐君子，德音昭融。","肃如清飔，释我蕴隆。","于爚大明，既西则东。","霈泽霈沾，庶逮父以躬。","甫耒于耜，君子之从。"]},{"t":"天梁之什二章","f":"楚辞体","c":["郁彼崇墉，天梁造空。","矫如飞龙，脩如螮蝀。","越岭汎江，以达大邦。","慄兮慄兮，兆室之室也噫。","郁彼崇谯，天梁造霄。","焕若霞绡，伟若云寮。","自淮徂漕，以达大朝。","屯兮屯兮，兆人之人也噫。"]},{"t":"岱宗之什四章","f":"古风","c":["瞻彼岱宗，伏云濛濛。","有美君子，言栖其宫。","峰何峛崺厜且㠑，彼君子哉。","瞻彼济濑，伏流濊濊。","有美淑人，言卜其舍。","水何奫沦清且涟，彼淑人哉。","自我不睹，徂寒迨暑。","药房翛翛，粉泽如赭。","岂无令颜，谁适子处。","自我不睹，徂暑再寒。","蕙轩䡅䡅，粉泽如丹。","岂无皓齿，谁发子叹。"]},{"t":"维夏之什四章","f":"楚辞体","c":["维夏有霰，冬则雷兮。","赫彼灵台，猰㺄来兮，血人于隈兮。","维夏有雹，冬则烧兮。","赫彼阿阁，䲭枭遨兮，食母于筄兮。","人之血也，菑其所也。","母之食也，谁育女也。","麟逝于碛，凤翔于野。","彼苍者何。","人之血也，人之菑也。","母之食也，育汝谁也。","麟戢其趾，凤揫其仪。","彼苍者何。"]},{"t":"素华之什六章","f":"古风","c":["皎皎素华，骓菼赭之。","有怀清流，含沙寔夥。","岂不骈衣，踧如宵裸。","皎皎素丝，朱绿移之。","有怀中林，窃毛寔多。","岂不再餐，惄如朝饥。","严霜在阳，松柏萎黄。","厥材孔臧，厥遘孔戕。","迷离芃芃，于彼高冈。","严霜夏骄，松柏焦烧。","厥谥孔乔，厥质孔夭。","迷离芃芃，于彼高峣。","谁堂构是恤，谁穴女墙室。","谁嬿婉嘉匹，谁罗网谗疾。","谓皇听卑，吞声若噎。","不鹬其巢，风雨飘飖。","彼人如之何，谓子哓哓。","鸡鸣永矣，东方未鼌。"]},{"t":"有皑之什八章","f":"古风","c":["有皑者麋，厥麀宜之。","如玉其煇，差池差池，遵彼山阿。","有皑者麀，厥麋将之。","如玉其章，尚羊尚羊，遵彼山冈。","言设其罝，胪我中除。","静好孔愉，万年之符。","谁其虞者，大夫君胡。","言设其罥，胪我中殿。","静好孔绚，万年之荐。","谁其献者，大夫君宪。","海人贸贸，鸱张以吼。","饰甲援胄，曷不疾斗。","民曰寇只，匪寇则媾。","海人憍憍，獝狂以嚣。","枉矢厉槊，曷不疾要。","民曰仇只，匪仇则交。","大夫如之何，爰飞其捷。","九章煜煜，八銮蹀蹀。","双旌猎猎，郁哉孙子，曷不世业。","兔离于罗，亦泽其姿。","载驱载驰，猿晰而脂。","龟角而岐，思媚君子，云胡不宜。","猗欤大夫，诸侯之师。"]},{"t":"有冢之什四章","f":"楚辞体","c":["有冢累累，松柏阿那。","黄鸟式嬿以歌，子之今矣，乐如之何。","有冢累累，松柏阿那。","黄鸟式嬿以歌，子之昔矣，忧如之何。","朔风萧萧，草不怨凋。","朔风条兮，嗟子之暮兮，不复朝兮。","景风调调，草不谢葽。","景风飘兮，愉子之暮兮，不复朝兮。"]},{"t":"终风之什四章","f":"楚辞体","c":["终风自西，零雨其丝。","灼灼夭桃，惄如其离。","彼一而离，此胡不睽。","终风自北，零雨其羃。","灼灼夭桃，頖如其拆。","彼一而拆，此胡不忒。","泽有王鴡，原有雉兮。","耿兮鸷兮，以游以厉兮，庶予契兮。","原有鳼泽，有阳鱎兮。","淫兮恌兮，以泳以翱兮，毋予挠兮。"]},{"t":"维旄之什六章","f":"古风","c":["维旄茀蓠，在泽之湄。","子来自燕，于以将睽。","维旄茀荟，在泽之涘。","予之来邢，于以将贽。","既觏则降，胡惙其忧。","河岳中移，两曜不仇。","白驹既餔，云何不辕。","裳衣在躬，启明流天。","虽有餔浆，无裨渴饥。","岂鲜弟昆，在生则依。","安能离形，与子周还。","优哉游哉，庶以愉年。"]},{"t":"宜人之什十二章","f":"楚辞体","c":["帝曰宜人，光汝于武。","笃生令子，为予哲辅。","汝翟汝茀，汝翣乃舆。","玼兮流瑱，佩环锵如。","宜人曰吁，昔余天是弃。","顾谓大夫，惟余诞弥。","尔岂不偕逝，不康禋祀。","惟余甘荼，勤力夙莫。","禔禔厥躬，以怙存者。","濯濯厥肝，毋恧原土。","惟余与汝，念兹初艰。","毋枳于衢，毋家于官。","曷不临履，靖共塞渊。","金拜稽首，夙莫祗服。","惟帝温纶，如丹如雘。","顾惟母训，如石如药。","既肃于公，言省其私。","酌彼金罍，以颂维祺。","晰尔毋■，鬒尔毋丝。","何以申之，绳绳孙枝。","载崇厥堂，言树之柏。","何以表之，维霜维雪。","载荣厥庭，言树之梓。","何以袭之，维桃与李。","猗欤宜人，家人是宜。","岂惟家人之宜，惟大夫是仪。","毖哉大夫，宜人是效。","岂惟宜人之效，亦惟先子是耀。"]},{"t":"维邑之什八章","f":"古风","c":["维邑之阳，有龙其冈。","畴布厥庆，侯曾子良，以邑敉宁。","维邑之厓，有龙其泜。","畴霈厥施，侯曾惠釐，以邑永和。","番番黄叟，共洁瀡脩。","爰荐于侯，侯实鞠育汝，汝祢汝父。","粲粲门子，共洁脩瀡。","爰用侯祀，侯鞠育汝父，汝格汝祖。","甘棠在国，其叶薿薿。","畴忍摧之，匪惟勿摧，又护培之。","甘棠在宫，其盖童童。","畴忍剪之，匪惟勿剪，又护衍之。","汝祖汝父，其德不远，夫是以勿摧剪。","之孙之子，其闻弥显，夫是以培衍。","蜀绩猗隆，郢德猗丰，我怀二邦敢用。","规于裔孙甫，衮衣西土，绳其祖武。"]},{"t":"崧溟之什","f":"楚辞体","c":["莫高匪崧，寸木陟之。","莫浩匪溟，涓流益之。","彼亢弗降，孰适与上。","彼盈弗挹，孰适与濈。","授之窦也，能毋与钻也。","道之蠹也，能无为刓也。","骄来无方兮，噫曷之知。","侈来有端兮，嘻曷之治。"]},{"t":"汉郊祀歌二十首 其一 练时日","f":"古风","c":["练时日，帝徵祥。","血膋殷，醴齐芳。","辟天扉，章上驰。","猋肃肃，灵来思。","泛崇兰，砌赤琼。","注神光，灵之宫。","曳紫旓，冠翠华。","雷霆激，灵之车。","骖若组，辔捷舞。","左右射，灵之御。","佩瑶错，履珠遗。","纷济济，灵之贽。","揄阿锡，吐芳润。","巧笑倩，灵之媵。","灵之暑，奏清徵。","飞霜激，粟余体。","灵之夕，籋珠烂。","鉴毛发，炯若旦。","灵连蜷，若有顾。","精流属，谐余慕。","倏而翔，将安逝。","愿偕女，宵以诣。"]},{"t":"汉郊祀歌二十首 其二 帝临","f":"古风","c":["帝临紫宫，万祇竦息。","天阊穆穆，以候舒辟。","神飙徐流，爰簸芳泽。","夭乔飞走，厥性咸若。","七曜孔仪，九溟不波。","恬穆象先，徜徉太和。"]},{"t":"汉郊祀歌二十首 其三 青阳","f":"古风","c":["青阳开荄，太皞司始。","穷阴夕遁，农祥晨启。","甲张气飞，仰希大布。","条风披盝，恍若寱寤。","敢假羲仲，爰荐羊麦。","二有熙熙，唯春之锡。"]},{"t":"汉郊祀歌二十首 其四 朱夏","f":"古风","c":["朱夏蔚蕃，炎帝司亨。","畅哉承离，万有茂明。","嘉雨霢霂，惠施下土。","污莱剪削，鴽鼠伏窜。","敢假羲叔，荐鸡逮菽。","庶我蒸黎，无替景福。"]},{"t":"汉郊祀歌二十首 其五 西颢","f":"古风","c":["西颢澄素，少皞司收。","万实坚强，秀颖内遒。","芃芃禾黍，登我场圃。","既徵既狝，克诘外侮。","敢假和仲，爰荐麻犬。","神之庇之，柔迩能远。"]},{"t":"汉郊祀歌二十首 其六 玄冥","f":"古风","c":["玄冥陵劲，颛顼司藏。","肃将天烈，凋攰万象。","墐户坯城，家有盖蓄。","夭乔反始，伏蛰敛育。","敢托和叔，荐彘与黍。","毋泄其真，以为物媪。"]},{"t":"汉郊祀歌二十首 其七 惟泰元","f":"古风","c":["巍巍寿宫，瑶瑰其阍。","于惟泰元，称天之尊。","胚始无极，厥眹泯泯。","两仪渐辟，五序因循。","凝精为曜，微者星辰。","气噫而风，亦润以雨。","霏霏雾露，粉泽下土。","夭乔鳞羽，顺性归所。","涵泳熙沐，忘已繇造。","惟我思媚，式献以报。","玄酒既熟，郁鬯斯馥。","有鲜者犊，寔茧其角。","是祼是燔，取彼膻芗。","以达霄潢，庶几来翔。","玉弁俄俄，璚琯洋洋。","延庇亿年，总齐万荒。"]},{"t":"汉郊祀歌二十首 其八 天地","f":"古风","c":["于皇上帝，以逮富媪。","惟予有况，爰父爰母。","靡嘉不承，博施九纮。","岁是用登，百秩绳绳。","显相列辟秉肃穆，燎芗叆叇成雾幄。","回干接翟散金辉，下管镛鼗竹敔丝璆然。","接之泗滨浮玉皦，如绎如乱而不绝。","肥刍之犍芍药酱，亨粔籹，有餦餭，玄酒清苾奈乐何。","展诗奏音发升歌，含宫调角商徵多。","窈眇流梁激尘飞，丰隆击节风伯和。","玄黄改色尊颜酡。","朱凤委羽雍雍鸣，赤龙夭矫迅长征。","垂休肇贶示炎祯，神夕逶迤嘉孔明。"]},{"t":"汉郊祀歌二十首 其九 日出入","f":"古风","c":["日出入，浴咸池，度白石，令我不得休息。","故令应龙在吾东，格泽在吾西，长离在吾南，玄武在吾北。","为我骖驾虚无，遨游太清都。","下视浊世，一如浮蛆。","我欲返，不得欢娱。","安用忧愁悲思，且为娱。"]},{"t":"汉郊祀歌二十首 其十 天马之一","f":"古风","c":["帝图协，天马生。","配乾行，函地精。","喷明玉，汗殷赭。","房为祖，龙为父。","争回飙，掣流电。","晨琅琊，夕沙苑。"]},{"t":"汉郊祀歌二十首 其十一 天马之二","f":"古风","c":["天马徕，来中国。","超虚无，蹑恍忽。","天马徕，归有道。","飞而黄，服余皂。","天马徕，谁攻尔。","造不足，虞刘累。","天马徕，迅若禽。","咈一窍，万马喑。","天马徕，出阴山。","六骡死，金人还。","天马徕，余与女。","踰昆崙，谒王母。"]},{"t":"汉郊祀歌二十首 其十二 天门开","f":"古风","c":["天门旭，呀然豁。","窍混沌，金精发。","猋若电，烛潢汉。","十二楼，袅鱼贯。","琉璃蹙阶，火齐鎏圮。","光液四射，不可仰视。","屏翳走，彴约驰。","霓晻霭，若摇支。","朱明跃以东起，纤阿迫以西垂。","白榆历历河之湄，天浆潆洄示昭仪。","天门开，朝紫宫，中有使者冠芙蓉。","朱衣璧简缥缃青，类有疑无触若冥，将上帝命况群生。","颛精稽恳胪所希，惠我来思庇蒸黎，皞皞帝功敛希夷。"]},{"t":"汉郊祀歌二十首 其十三 景星","f":"古风","c":["煜煜景星，爰灿其蕊。","休光彪蔚，以开瑞始。","昔在强嬴，鼎窜于泗。","炎德茂明，汾睢是吐。","人文属空，金精流融。","百象窾呈，渺悠天工。","刷以纯茅锦承之。","错奏匏管文以丝。","酸鹄臇凫二牢披。","糗饵甘芬行稻粢。","九酝泠泠写琼卮。","神露湛湛布柯枝。","河伯拜享前致辞。","唯帝蕃锡鄙敢私。","九有穰穰被恩釐。","家有盖藏阓书诗。","乐哉君王万岁期。"]},{"t":"汉郊祀歌二十首 其十四 斋房","f":"古风","c":["煜彼三秀，产自斋房。","后皇储精，遹发帝祥。","律中金石，于霞有烂。","屑以玄饴，后天之荐。"]},{"t":"汉郊祀歌二十首 其十五 后皇","f":"古风","c":["后皇欣合，昉孳兆因。","唯是慈爱，私于我人。","降假明辟，拼乂式廓。","徂蛮逮貊，靡届不格。"]},{"t":"汉郊祀歌二十首 其十六 华煜煜","f":"古风","c":["华煜煜，酝澄鲜。","神下来，辞钧天。","帝亲飨，奏清县。","神下来，度九阍。","龙伏趺，豹缤翻。","神下来，空中跸。","云羽旂，风瑶瑟。","神下来，史巫舞。","擘嘉胏，行齐酤。","神下来，脩娥侍。","䐂腾媚，鬋若黛。","神安坐，燎九蕴。","灵虬吭，吐氤氲。","神欲休，博山床。","帷流苏，角明珰。","神之逝，旌裔裔。","车斑斑，马沛沛。","神之愉，锡土田。","踰敦煌，抵昆崙。","蹑恍忽，乘飘瞥。","流翠眊，汾之澨。","望若觌，不可即。","使余怊，怊安极。"]},{"t":"汉郊祀歌二十首 其十七 五神","f":"古风","c":["五神帝，佐太乙。","肃象禦，扬清跸。","左青旓，右白旂。","前朱芾，后玄圭。","谁者尊，服中黄。","灵之朝，肃然风。","臛神枭，体冥羊。","鬯郁金，吐芬芳。","意恍忽，精披靡。","若将翔，复丽体。","籋沉云，酝灵霈。","报休会，泽无外。"]},{"t":"汉郊祀歌二十首 其十八 朝陇首","f":"古风","c":["朝陇首，蒐大荒。","帝沛祥，白麟降。","嶷脩角，文周定。","万走怿，共余命。","骖玉辂，导鸾旂。","左赤豹，右青猊。","踰弱水，宾金母。","霞醴汎，云璈举。","頫东牖，顾中原。","杳如发，憯不欢。","御飘忽，晻飞迣。","耳留跸，目穷旆。","朝玄圃，夕沙墅。","坐明堂，餔四海。"]},{"t":"汉郊祀歌二十首 其十九 象载瑜","f":"古风","c":["象载瑜，角其牙。","越昆崙，度流沙。","飘若霞，赤雁仪。","尾若芾，声中规。","秣者谁，芝田禾。","荐宣房，万福来。"]},{"t":"汉郊祀歌二十首 其二十 赤蛟","f":"古风","c":["帝临渤，冲波却。","櫜天弧，张广乐。","赤蛟来，俛其角。","芬牢醴，旨且博。","胡以荐，酬海若。","露飘洒，云容裔。","澹复殢，灵之醉。","灵欣欣，来媵予。","应昌符，启甘澍。","报丰岁，多稌黍。","箱陈陈，万亿秭。","敕阳侯，波不芒。","导出日，际穷荒。","陈玉帛，至梯航。","赤蛟来，灵柔之。","千万祀，思祯期。"]},{"t":"汉铙歌十八曲 其一 朱鹭","f":"古风","c":["朱鹭矫以翔，倏如腾光。","腾逝耶，之胡际耶。","曷不思翔，高而尽下。","彼茄之畔，鱼游雅雅。","茄蔽上瞩，谓是藏止。","他人之怵，思恬葬厥喙。"]},{"t":"汉铙歌十八曲 其二 思悲翁","f":"古风","c":["思悲翁，徂何之。","玄云?阴，霜霰如期。","山耶溪耶，斧枯网冰，于胡不归。","炊麋作饭，翁不及饭。","胡不从之游，将庐井是挽。"]},{"t":"汉铙歌十八曲 其三 艾如张","f":"古风","c":["艾而张罗，人乏马饥。","谁令艾之，令禽惊磔飞。","罗不得禽，谪子无处。","禽大欢喜，复集于所。","将禽与子，齐适天地。","置酒高堂中，愿尔百千万岁。"]},{"t":"汉铙歌十八曲 其四 上之回","f":"古风","c":["上之回，至祠雍。","千灵洽，百辟从。","上何以幸雍，仁必世帝禧钟。","西臣流沙，安息条支。","都梁郁金，符拔狻猊。","南荡百粤，下濑苍梧。","孔翠桂蠹，明珠珊瑚。","诸夏安服，奇珍咸集。","降王母，假太乙。","答神贶，行斋祀。","金支彩毦，恍不见际。","庸作歌，耀万世。"]},{"t":"汉铙歌十八曲 其五 翁离","f":"古风","c":["拥离趾中，筑宫其颠。","高天无风自寒，念欲移彼岩壑之间。","何用重筑宫，杞梓楩楠，豫章富奇材。","宁不知蕙与兰，芬且芳，将固焉哉。"]},{"t":"汉铙歌十八曲 其六 战城南","f":"古风","c":["战城南，城南壁。","黑云压，我城北。","伏兵捣我东，游骑抄我西，使我不得休息。","黄埃合匝日，为青天模糊。","钲鼓发，乱欢呼。","敌骑敛，飙迅驱。","树若荠，草为枯。","啼者何，父收子，妻问夫。","戈甲委积，血淹头颅。","家家招魂入，队队自哀謼。","告主将，主将若不知。","生为边陲士，野葬复何悲。","釜中食，午未炊。","惜其仓皇遂长诀，焉得一饱为。","野风骚屑魂依之。","曷不睹主将，高牙大纛坐城中。","生当封彻侯，死当庙食无穷。"]},{"t":"汉铙歌十八曲 其七 巫山高","f":"古风","c":["巫山高，一何高。","湘水深，一何深。","上有猱，木森森。","峰冠天，易旸阴。","流清梦，托君音。","含思弄态若不任。","翠旗金支玳瑁簪。","疑明乍晦迥何寻。","寓目岑岑荡精淫。","迫欲近之殆惊猜。","将远离之复徘徊。","安能为期旦暮来。","巫山高，高以峻。","湘水深，深以大。","愿君王，志意正。","澹愉穆，绌非境。","后天不凋三光并。"]},{"t":"汉铙歌十八曲 其八 上陵","f":"古风","c":["上陵一何高，高亘天宫阙，武夫璘斑。","又有青龙白兽，列峙云端。","银海汎澜，金凫游戏其间。","谓不如乘龙而见上帝，赐药一丸，令汝遨游自然。","肃肃桥陵，岂藏衣冠。","寿千万岁，乐不可言。"]},{"t":"汉铙歌十八曲 其九 将进酒","f":"古风","c":["将进酒，乘大白。","皇帝百千万年，垂衣御极。","轻刑税，陈礼乐。","父不哭子，战斗长息。","原田膴膴，于何不穫。","童行至老，欣欣曷颇。","挹青阳，蒸太和。","露为浆，斗?之，一再举，霜颜酡。","青天流眸，忽为庆云。","嗟彼曲蘖胡以云。"]},{"t":"汉铙歌十八曲 其十 君马黄","f":"古风","c":["君马黄，臣马白。","衔金羁，度紫陌。","秣流沙，径昆崙。","宴王母，瑶池滨。","饵灵馔，天乐一何殷殷。","辞归东土，和洽诸夏。","期以三载，复来晤女。","君饵灵馔，貌青于童。","臣贱眉宇，飒如秋霜。","安能御君，驱驰八荒。"]},{"t":"汉铙歌十八曲 其十一 芳树","f":"古风","c":["芳树一何乱予思。","扶疏磊砢，下临兰池。","上有一双之乌，丹趾而翠衿。","自名为鹦䳇，若怨似矜态何深。","缴絷之，令彼不得奋飞。","嗟我不得奋飞，陇山辽辽望难归。","虽有四海志，翮仄翅剪竟焉施。"]},{"t":"汉铙歌十八曲 其十二 有所思","f":"古风","c":["有所思，乃在大海之北。","卒然太行，起若立壁。","驱车畏轴折，驱马畏蹄仄。","岂无珠宫贝阙，黯■或成碧。","有所思，思纷来，其端类丝。","或糺之手，弄一白圭。","云彼昔所治，手弄之三载不忍释，渐成璧。","一心为一心，安能两相测。","严霜下，青阳晞。","朱华剥落不自持。"]},{"t":"汉铙歌十八曲 其十三 雉子斑","f":"古风","c":["雉子斑，离其母，来遨游田间。","田间多稻禾，人于其所复张罗。","倏忽被絷，不能高飞。","前有鸟，乃是其母，羽毛摧披大堪哀。","迫欲救之已焉哉。","相咎此稻禾，为生复为菑。","曷不睹南溟垂天之鸟，千里万里一徘徊。","虽有矰缴，青天曷猜。"]},{"t":"汉铙歌十八曲 其十四 圣人出","f":"古风","c":["圣人出，奉昌期。","百六遘，九五归。","白帝死，赤龙飞。","指函谷，度崤坻。","封府库，戢兵师。","戒父老，起伤痍。","五诸侯，从义旗。","猎天狼，网妖鸱。","裂茅胙，巩鸿基。","垂百祀，永无为。"]},{"t":"汉铙歌十八曲 其十五 上邪","f":"古风","c":["上邪，与君相知。","譬彼结发而盟，山摧海枯志不移。","白日迥瞩，肝膈洞披。","我手君腕，用不得私。","车轮坏，马足罢，东家宴，西家毁。","何用钱刀丘积，横金垂紫龌龊为。"]},{"t":"汉铙歌十八曲 其十六 临高台","f":"楚辞体","c":["临高台，瞰横江，井干百尺郁连空。","下何以江，上何以空。","不有北泳之鱼，必有南逝之鸿。","望不极兮意无终。","乌织西，兔投东。","袖中有短札，渐将陈。","口语数百千言，削为数言复湮沦。","秦筝扬，赵瑟侍。","曷不欢，各心意。","人何乐，乐得遂。"]},{"t":"汉铙歌十八曲 其十七 远如期","f":"古风","c":["远如期，招四夷。","皇帝坐殿上，麒麟辟邪，符拔騊駼。","拖沓焉施弛，苑囿付民居。","诏司农，罢轮台。","皇帝坐殿上，干羽舞两阶。","群臣上，寿玉卮。","单于来，单于来。"]},{"t":"汉铙歌十八曲 其十八 石流","f":"古风","c":["石流者，何汤汤。","使者来，自扶桑。","赤日所起，烂烂铄金而沃焦地。","不爱宝石来献膏，汎恒沙，攀悬度。","奉明主，饵之与天齐数。"]},{"t":"岐山操","f":"古风","c":["哀哀我民，愚圣狎主。","余之弗庇，忍以贻虏。","率西水浒，至于岐下。","伐材中林，陶瓦堲土。","民未休舍，余敢宁处。","顾视周原，厥田膴膴。","是穮是蓘，以待来者。"]},{"t":"拘幽操","f":"楚辞体","c":["雷霆纷如日晻瞖兮，天威方煽庸敢怠兮。","不知纪历寒暑递兮，潜志消息恍惊寐兮。","庶几君王一感悔兮，臣不爱死虞圣累兮。"]},{"t":"文王操","f":"楚辞体","c":["矫矫长离将翱翔兮，肃雍和鸣中宫商兮。","奉王威灵揆不庭兮，庶邦子来后夫亡兮。","上帝临汝敢遑宁兮，地道无成中心伤兮。"]},{"t":"箕子操","f":"楚辞体","c":["于嗟王子跳兮，生以系我宗祧。","于嗟王子磔兮，死以殉我社稷。","嗟余之不及兮，默默以苟存。","弃道毁质兮，离人伦。","余贞疢兮，敢望瘳。","晻日垂照兮，没齿奚尤。"]},{"t":"采薇操","f":"古风","c":["上山采薇，斧冰炊之。","旷荡八垠，顾瞻若縻。","何所非人，季昆是依。","达者互贤，曷救其非。","句吴之乡，彼髡庶几。"]},{"t":"越裳操","f":"古风","c":["赫赫文考，秉德渊冲。","奕世而仁，八荒来同。","彼荒越裳，侏㒧其音。","何以贽我，有斐驯禽。","驯禽伊何，耿介洁茂。","言荐文庙，言扰灵囿。","厥雊喔喔，厥羽鹤鹤。","天质应金，其音中角。","嗟予小子，敢尸国祥。","无怠无荒，敬勖嗣王。"]},{"t":"龟山操","f":"楚辞体","c":["龟之山吐云蔽龟山兮，彼龟不知以云藩兮。","予望鲁社龟兮间之，君臣交贤谁兮辨之噫。"]},{"t":"将归操","f":"楚辞体","c":["美哉水洋洋兮，中有潜龙变无方兮。","饵欲蔽灵黯行藏兮，黾蚁伏窥胡弗祥兮。","盍归乎来惠吾党兮，息魄虞渊众趋冥兮，加我数年绍馀光兮。"]},{"t":"猗兰操","f":"古风","c":["猗猗丛兰，芬于幽阻。","彼美蘅杜，风所揄吐。","芃芃禾黍，罹此暑雨。","槁实不恤，世有饥者。","徘徊九方，靡即宁处。","君子悦心，不在爵土。","嗟余已迈，归从兰所。"]},{"t":"残形操","f":"楚辞体","c":["有梦维狸兮，而残其形。","吉兮胡祥灾兮，而使我怦营。","临深渊兮履薄冰，奉先人遗兮敢隳成。"]},{"t":"履霜操","f":"楚辞体","c":["皇旻佐威兮夜陨霜。","苴屦茄衣兮透若亡。","霜胡为兮加憯悽。","君晨朝兮毋粟乃肌。","欲自明兮伤君志。","泪滂沱兮念宗祀。"]},{"t":"雉朝飞","f":"楚辞体","c":["有雉朝雊兮呼其雌。","角角粥粥兮光陆离。","我欲呼兮应者谁。","阳春被天兮蹇独憯悽。","西乌欲没兮余将安归。"]},{"t":"别鹄操","f":"楚辞体","c":["双鹄摩天兮翼中垂。","临当诀兮感仳离。","有子无子兮帝命之。","轻弃置兮谁适为妃。"]},{"t":"采芝操","f":"古风","c":["坡陀崇阜，草木菁茂。","畴其餦者，郁郁三秀。","皇帝创始，功冠万古。","唐哉虞哉，巢许不知。","我以为芝，人以为薇。","扣镰长谣，白云沾衣。"]},{"t":"霹雳引","f":"七言古诗","c":["七曜受署五气调。","八荒来同万国朝。","后来防风伏欧刀。"]},{"t":"走马引","f":"楚辞体","c":["山空兮，狗不吠、鸡不啼。","马胡来兮，踯躅而悲嘶。","吁嗟天马警余兮，以徙余敢宁止。"]},{"t":"思归引","f":"五言古诗","c":["不睹宫中贵，安知妾家贫。","火齐饰交疏，蜀锦充下陈。","玉馔不能名，兰膏自氤氲。","新王富春秋，炫饰夺朝霞。","奉妾金条脱，永愿托姻娅。","三千蛾眉女，一一让容华。","妾人坐忳悒，忳悒如探汤。","目视等埃尘，肠类刀矢攻。","蚤奉父母身，为礼以乱终。","淇水浩无津，方舟曷相援。","先王未面命，何以待黄泉。","怦营深宫里，天地狭如弦。","杀身良不易，苟遇诚亦非。","引领就高县，黄鸟为哀啼。","我欲竟此曲，此曲令心悲。"]},{"t":"思归引","f":"古风","c":["思归引，归东吴。","鼓余翼，翱翔恣所如。","泛七泽，凌五湖。","睹我钓所，中悦愉。","云郁术，波萦纡。","帷天烛星无恒居。","浮家水猎乐有馀。","宜城稻，松江鲈。","妇奏飧，妾湛酤。","饱鸣琴，醉呼卢。"]},{"t":"榜枻歌","f":"楚辞体","c":["张翠盖兮汎青翰，褕脩裾兮气芬芬其以兰。","口欲吐兮中阏之，中心惭惶兮贪夺之。","顾薇贱兮焉匹离，君心妍兮自色飞。"]},{"t":"采葛","f":"古风","c":["欲明不明闻杼机，卧薪君王来起之，我今采葛以后时。","欲明不明闻鐯?，卧薪君王日不休，我今采葛以逍遥。"]},{"t":"精列","f":"古风","c":["独何之，天地相雠诅，其间安得怡，其间安得怡。","亮怀千秋向，焉能度一时。","愿攀飞龙翼，故里以徘徊，故里以徘徊。","飞龙腾天去，鳅鳝来相依，鳅鳝来相依。","眸子向内生，谁为辨雄雌，谁为辨雄雌。","和光同其尘，老氏我所师。","金石随年销，真人旷无期。"]},{"t":"对酒","f":"古风","c":["对酒歌，少年白发蒙其颠。","四坐且勿喧，踯躅吞声内相怜。","欲有叙家世，二千石、乘朱轮者将十人。","弱冠明经，射策甲第。","为郎无状，偃蹇不迁。","无蔽芾以藏其朱颜，绛灌将相大臣自愧其妍。","侧目而睊睊，安令文墨操吏权。","斥之去，一往勿复言。","惭无贾生之策，彷徨公车靡阶以自前。","月请囊粟十百钱，陛下万寿，小臣归田。"]},{"t":"日重光行","f":"古风","c":["日重光，拂扶桑，耀嵎夷。","日重光，天老乃复洗沐之。","日重光，左右五色菌离披。","日重光，灿若明镜火齐。","日重光，万象同志仰昭回。","日重光，告羲和勿频挥。","日重光，留昃且为中。","日重光，覆盆之烛鄙所希。"]},{"t":"月重轮行","f":"古风","c":["缭绕霞虹，太清之府。","烛龙者，何煌煌，炯若虞帝华瞳。","飞鞅不周，以方羲驭。","陛下皇后坐宫中，各百千万岁。"]},{"t":"步出夏门行四首 其一 观沧海","f":"古风","c":["六神诸山，沦涟大壑。","北风勃来，簸荡不息。","帝命巨鳌，更负危揭。","冠簪东出，以为碣石。","烛龙双眸，以为日月。","下苞苍苍，浩荡靡极。","幸甚至哉，歌以咏志。"]},{"t":"步出夏门行四首 其二 十月","f":"古风","c":["孟冬十月，王师振旅。","旌旗扬天，鞞铎万舞。","橐驼騊駼，不知纪数。","犀毗黄金，跪而衔组。","归马华山，放牛桃林。","大酺三日，黔首欢霪。","幸甚至哉，歌以咏志。"]},{"t":"步出夏门行四首 其三 土不同","f":"古风","c":["西游秦中，板屋以处。","东折宋鲁，逢掖章甫。","断发文身，以凌句吴。","燕赵慷慨，弹铗歌呼。","八方异施，等若五时。","义问休畅，所底如归。","幸甚至哉，歌以咏志。"]},{"t":"步出夏门行四首 其四 龟虽寿","f":"古风","c":["神龟支床，生理中绝。","不如刳肠，逝而见筴。","干霄之材，谥曰柽榉。","风雨飘飖，狐鸟托处。","纵生而雄，厥名丈夫。","安能百年，与饮食俱。","幸甚至哉，歌以咏志。"]},{"t":"平陵东行三首 其一","f":"五言古诗","c":["郁郁平陵树，日夜生秋风。","风声一何悲，树色何朦胧。","不敢出声啼，掩咽歌义公。","平陵多贵豪，不为商与农。","黄绶二千石，墨绶侍中郎。","出用牛车载，户用金碧蒙。","老少六七辈，气色何昂藏。","口但新室臣，何论我高皇。","嗟哉义公里，榛棘复污潢。","狐兔欢索群，鱼鳖亦来宫。","安得冥途轨，侧身以相从。"]},{"t":"平陵东行三首 其二","f":"古风","c":["平陵东，车隆隆，郭家小儿葬若翁。","葬若翁，来送丧，谁其最贤槐里公。","槐里公，多奇客，迅如飙鹰虎如力。","虎如力，卒夷灭，曷不将去击胡貊。"]},{"t":"平陵东行三首 其三","f":"古风","c":["平陵东，谁最雄，父为丞相子侍中。","子侍中，气成虹，黄金不归大司农。","大司农，走钱龙，承相之室金为梁。","金为梁，玉为圮，曷不舍去居天子。"]},{"t":"王子乔","f":"古风","c":["王子乔，变化白鹤长逍遥。","变化白鹤长逍遥，下游来，王子乔。","璠玉为衣砂为冠，垂玄裳。","朝谒紫清轩辕大道皇。","谁者介，广成老公授尔浮丘之伯，令尔吹笙复鼓簧。","下视尘界三千霜，今上圣灵发百祥。","安期之鹿离哉双，胡弗至止相翱翔。","侑以紫芝荐琼浆，柏梁之臣前奏章，今上圣灵永无疆。","离披短翮角殷璘，唶欲报帝还靡因。"]},{"t":"桂之树行","f":"古风","c":["桂之树，桂之树，乃在苍梧之阳，岭曼衍而崷崒。","翠羽为叶，苍虬为株。","萼何葳蕤，葐敷黄如。","黄金粟赤，如珊瑚珠。","桂之树，仙者四五人，骖驾凤皇来。","谓是日精月华，教迩采服不衰。","一岁口泽馨，二岁体骨轻，三岁毛羽生。","朝见上帝，赐女麟车霓旌，翱翔玉虚太清。","翱翔太清天，为乐不可言。"]},{"t":"钓竿行","f":"五言古诗","c":["饥饭渭水旁，渴饮渭水流。","大鱼绝饵去，小鱼不回头。","不知何王子，施施来上钩。"]},{"t":"满歌行","f":"古风","c":["为善无近名，不见古人，逊天下躬耕。","逃之渭水，洗耳见轻。","又言为恶无近刑，不见古人，佯狂漆身。","清质浊文，卒称逸民。","桓文假仁，乃霸四海。","盗蹠脯肝，以牖下死。","乾坤失信，刚柔安纪。","五星背躔，焉所照理。","我欲为善，善不可为。","我欲为恶，恶非所知。","刑名之间，余其庶而。","何以导之，仪狄我师。","栖山得玉，将刖而足。","泅海得珠，将剖而肉。","不如种田亩，得秫与粟。","家蓄五母鸡，二母彘。","一日一饱，三日一醉。","出则止野，归则止舍。","不知有天，无论在地。","东邻送丧，西邻生儿。","寒暑为垆，风雨鼓之。","销冶红颜，以就衰羸。","旷视今古，曷如蜉蝣。","智者亡何，聊以不忧。","王孙达生，厥师庄周。","庄周怖死，抑孰与俦。"]},{"t":"空城雀","f":"古风","c":["雀不能飞向天，又不能游深渊，胡为刺促草莽间。","曷不愧其朝东而暮西，决翼仅寻丈，枪榆为天池。","皇皇者何忧稻粱，田家罘罝正高张。","何不舍去复彷徨，志命相就罹祸殃。"]},{"t":"蛱蝶行","f":"古风","c":["蛱蝶来，踰苑墙，为是百卉芬芳。","悲哉蛱蝶，不睹百卉。","但睹翩翩之燕，衔哺其子。","燕有三子，忽失其二。","燕乃舍我而东西，仰见一老鸱。","耽耽下视，喙血流离。","蛱蝶耸身而奋飞。","顾谢此燕，始谓尔彊。","曷不更哺其子，令我揶揄道旁。","今日乐相乐，别后莫相忘。"]},{"t":"西门行二首 其一","f":"古风","c":["出西门，冢累累。","车中幸有酒，不饮奚之。","但复饮，沈醉当自知。","焉能前驺后殿，束缚乃翁为。","雷大鼓，炙鸣笙，试问冢中枯，曷不为，起听飞霜激流徵。","六月清霜零，即呼道傍子为我，辨其声。","虽无故人钟子期，但操山水中所私。","虽无故人钟子期，但操山水中所私。","相逢侠邪路，轮仄伤马蹄。","与君非一体，何用不相疑。"]},{"t":"西门行二首 其二","f":"古风","c":["步出城西门，但见两两垂杨。","高枝自相樛，低枝亦成行。","昔者手植之，不敢望人长。","十年不相遘，睹此参天势莫当。","东家秃柏偃蹇气欲尽，令我箕踞叹息此树傍。","人间世，一何茫茫。","丈夫宛转间，倏忽生辉光。","巧命搏参差，奇贤避颉颃。","扶杖且归来，兄呼醪，嫂呼豨，大妇洗爵，小妇前致辞。","俱睹百年树，不睹人生百岁时。","今日乐相乐，何用戚戚缠思悲。"]},{"t":"东门行二首 其一","f":"古风","c":["出东门，曷不言归。","我欲从九夷，不赍八月粮，未满十二驽驹蹄。","手操蒯缑剑，囊裹一束书。","但趋咸阳道上，鹊啄乌栖竟何之。","竟何之，东有霍家骠骑，西有丞相屈氂。","黄金如山，风雨立前，安用蒯缑束书为。","黄金如山，风雨立前，安用蒯缑束书为。","咄女从九夷，咸阳道上生不支。"]},{"t":"东门行二首 其二","f":"五言古诗","c":["遥睇城东陌，冠盖郁峥嵘。","主称且尽觞，客辞不胜情。","徒御亦相属，眤眤作私声。","古来涕泪地，春草不易青。","生年未期百，过迹在长征。","抚悼髀肉消，栉悼鬓发星。","白日为风雷，皇乾乍冥冥。","居人恬卧起，道途失精灵。","弧矢固畴志，垂堂毋乃轻。"]},{"t":"却东西行","f":"五言古诗","c":["黄鹄从东来，饮啄且裴徊。","不知将何意，延颈向我啼。","渺渺行役子，三载客东沂。","将托千仞风，及我万里归。","耸身从之去，扶摇不支持。","一举决云汉，再举历天池。","敛翼下置我，乃在弱水西。","弱水浩茫茫，终古日月迷。","愿迩更成遥，为恩亦何施。","不愿故乡归，不愿黄鹄来。","但愿得美酒，日进百千卮。"]},{"t":"秋胡行","f":"古风","c":["寒暑易遭，天地难为仁。","寒暑易遭，天地难为仁。","重华作相，焉宥四臣。","周公虽圣，不得亲亲。","鲁用仲尼，曷利壬人。","歌以言之，天地难为仁。","昼夜相敚，日月难为明。","昼夜相敚，日月难为明。","幽谷蔀屋，伏阴卒萌。","象共滔天，水土是冯。","岳荐何重，帝言何轻。","歌以言之，日月难为明。","七雄斗驱，英佐亦何多。","七雄斗驱，英佐亦何多。","等智齐力，卒莫相加。","老骥皂伏，致远者驽。","岂必中才，逢数则哿。","歌以言之，英佐亦何多。","脩辞曷量，显者自为工。","脩辞曷量，显者自为工。","等彼鸿鹄，唳霄则雄。","世无太师，孰采民风。","槐里渺邈，曷折充宗。","歌以言之，显者自为工。","俗累易捐，九州不足居。","俗累易捐，九州不足居。","道逢仙长，自称安期。","手执大药，其甘如饴。","谓女愤嫉，秘莫肯贻。","歌以言之，九州不足居。"]},{"t":"孤儿行","f":"古风","c":["孤儿来，乞食一何惨悽。","问汝父兄何之，长跪答言：父为酒泉太守，匈奴来遮，贰师入酒泉，血肉付枭与鸱。","有一老胡絷我母，马蹄倏忽不见，隐隐闻啼。","兄行贾海南，十载不得归。","人云鲸波山立而血人，安能远相期。","孤儿中气咽，不复更致辞。","我有匕首赠女，令从材官雪女仇。","迫暮无食，穷冬乏衣。","形容皲瘃尽，手足自相樛。","黄泉渐迩，白日易晞。","父仇虽重，焉能奋飞。"]},{"t":"苦思行","f":"古风","c":["帝母治金天，戴胜光陆离。","弱水中间隔，安能奉仙仪。","感此青鸟音，电毂下瑶池。","遣信要上元，飘飖双玉衣。","再拜前致诚，乞取五岳之真形。","谓女胎，性多淫，杀毋为慕长生。","柏梁亘穹霄，宇宙正佳兵。","北风凄凄，白日就冥。","虽有蟠桃，不栽茂陵。"]},{"t":"当事君行","f":"古风","c":["丈夫委质事君，薄命多苦辛。","窈窕不胜冶容，靡复奉清尘。","鸡皮者妇三少，六宫当一身。","羊车轻薄谁子，轧轧入宫闉。","桃李乃擅阳春，松柏摧为薪。","已矣殆哉归欤，草莽竟何陈。"]},{"t":"燕歌行 其一","f":"楚辞体","c":["秋霜肃肃摧庭枯，晨风何悲夜鸣謼。","使妾为遘不须臾，恍兮类君忽若无。","为君中夜起踌躇，雕栏簌簌悬真珠。","二十八宿罗天衢，欲明未明焉所如。","君当为龙妾云俱，冲飙在天忽驱之。","西流之蟾东飞乌，乐往忧来不相虞。","盛年冉冉辞人徂，裁吟代哭中成吁，安能为情自卷舒。"]},{"t":"燕歌行 其二","f":"七言古诗","c":["白日晼晚夜何其，兰缸茕茕照妾悲。","带长髻短中自支，妾人少年工愁思。","忧来无方不可治，丈夫桑弧谁制之。","谁令璆然不下帷，鸿鹄双翻复为谁。","援琴奏弦歌和词，宫折商促指间离。","白葛巾裙衫弋绨，念君寒暄并一时。","南山乔松青不移，虽有中坚色难期，愿君归来及时归。"]},{"t":"妍歌","f":"五言古诗","c":["今日乐相乐，与君恣游遨。","霞车扶飙御，天酒汎星匏。","安期羞大枣，阿母荐蟠桃。","王子奏玉笙，夫人击云璈。","月姊将明镜，天孙奉织绡。","双成扶入帐，飞琼脱我袍。","千年为一宴，万年为一宵。"]},{"t":"古八变歌","f":"五言古诗","c":["秋风何憭慄，恶我罗裳衣。","昼短不成匹，中夜理鸣机。","晨风俱南翔，熠耀竟何之。","皑皑枝头霜，隐隐上蛾眉。","盛年忽已过，游子安用归。"]},{"t":"同声歌","f":"五言古诗","c":["今夕复何夕，得奉君子欢。","明烛在高堂，三星灿以烂。","卺饮不逮终，缡结自成宽。","绸缪非一状，要约故万端。","感君缠绵意，报以中心肝。","愿为黍与臛，奉君朝夕餐。","愿为缟与絺，备君衣中单。","二候愿多夕，三时愿多寒。","金石有时泐，中怀长不刊。","鸣鸡何咿喔，北斗渐阑干。","欲起复彷徨，人生会面难。"]},{"t":"妾薄命","f":"古风","c":["西家艳女罗敷，柔肌金城土酥。","皎若清冰玉壶，双波滟滟睛矑。","娇啼芙蓉露珠，吹气兰醒蕙苏。","头上倭堕俄俄，暖金雀钗婀娜。","鬓云对侵翠蛾，湘裙十二纤罗。","衣䘯无风自波，下隐双莲绣靴。","柔荑飞梭流黄，织成比翼鸳鸯。","娇歌激尘绕梁，浮云如掣不扬。","妙舞婉盻生光，四坐粉黛摧藏。","十六狂且见求，要眇微言不酬。","黏竿挟弹遨游，凉飔翛翛药裯。","徘徊顾影无俦，昼永更长岁脩。","东邻冶容少年，娶妇曷鼻魋颜。","怨耦等诽齐怜，目成色授神传。","沈吟却行不前，命矣夫复何言。"]},{"t":"短歌行","f":"古风","c":["置酒中堂，伐丝比簧。","湎以益欢，志人慨慷。","慨慷生迹，类此繁响。","盈盈在耳，忽忽沦往。","灼灼其华，朔凋春敷。","所并枝叶，不作根株。","劳我以人，伊何莫遐。","天地偶尔，逢之者嗟。","仰穷二曜，高不得掇。","頫即大壑，深不得没。","王乔安期，服食难量。","锢兹委蜕，仅三千霜。"]},{"t":"长歌行","f":"五言古诗","c":["轩皇亿万纪，三光恒若斯。","人生百年内，譬若朝露晞。","前者吾不作，后者亦焉知。","平生异荣贱，冢墓识为谁。","华榱及膏亩，安得遂相携。","托体于子孙，痛痾各自支。","株株同根蒂，叶叶自轻离。","蒙庄等彭殇，终复脩文辞。","尼轲固随化，垂言亦庶几。"]},{"t":"长歌行答于鳞 其一","f":"五言古诗","c":["昭昭阳春色，令我好容姿。","庶草各自骄，谁能念先萎。","秋气发鸣蝉，噭噭多伏悲。","逝水但知东，逝日但知西。","人生坚强志，乃欲与时违。"]},{"t":"长歌行答于鳞 其二","f":"五言古诗","c":["蜿蜿云中龙，煜煜双飞翼。","扶侍日月车，周旋于八极。","中有芙蓉冠，蛾眉何脩淑。","盼我若旧欢，贻我药五色。","顾恋尘中乐，徘徊不能食。","旷劫不再逢，怊怅安所即。"]},{"t":"长歌行答于鳞 其三","f":"五言古诗","c":["白露秋澄澄，漙我桂树林。","愁思中夜发，披衣不逮衿。","晨风无停号，蟋蟀时再吟。","举头见明月，低头泪涔霪。","明月万里光，妾人万里心。","愿为随光去，万里不能任。","北斗酿酒浆，南斗为我斟。","言欲解我忧，忧来一何深。"]},{"t":"相逢行","f":"五言古诗","c":["相逢美少年，俱在洛城东。","绣毂珊瑚鞭，驱马若游龙。","华韝臂苍鹰，马后好妖童。","周道不肯分，呵叱争如风。","各言父兄业，不独誇身雄。","小吏二千石，大吏至三公。","男当执金吾，女当备椒房。","铁券恕十死，金书尚煌煌。","壁藏亡命侠，睚眦不肯空。","行旅为弛肩，居者起相从。","不睹少年争，安知富贵功。"]},{"t":"皇都篇","f":"五言古诗","c":["皇都丽宫阙，柏梁复建章。","列宿散金铺，驰道绝天阊。","车声属旦暮，马足浩纵横。","丞相东阁开，冠盖倏成行。","不爱丞相怜，但爱侍中郎。","宇宙销黄金，大海为垆缸。","风雷白日变，精灵俱走藏。","昔日平津馆，今为斗鸡场。"]},{"t":"长干行","f":"古风","c":["上客酒莫倾，请听长干行。","长干十二高楼，夭矫若飞虹。","回飙却檐楣，赤日眩雕甍。","楼中何所有，娇女字倾城。","五尺明珊瑚，睹者无不惊。","姊妹不得骄，父母不敢高声。","流盼灼朝霞，缓齿兰芳生。","头上金雀钗，一一衔珠珰。","腰间琼瑶佩，行步中宫商。","鸳鸯生不识，绣出便成双。","十五嫁小吏，小吏焦仲卿。","三朝上府牍，四夕践府更，府公拮据不得宁。","十五休浣期，中厨刺刺宰猪羊。","不见小吏还，乃过邯郸倡。","邯郸倡，善为蛊，不可方。","长干女，守空房。","峨峨凤凰桥，焉见飞且鸣。","淼淼天河水，指影竟无形。","女身既已非，为妇空得名。","恒恐容华变，薄命委秋霜。","温衾不甘暖，涕泪沾衣裳。"]},{"t":"白头吟","f":"五言古诗","c":["南山有匹鸟，自呼为凤凰。","虽复具五色，不能顾其双。","昔者呼凤皇，凤皇不成双。","今者呼凤皇，凤意不求皇。","昔求一何难，今飞一何易。","今去呼不来，昔来推不去。","新人芙蓉花，旧人芙蓉枝。","新人山作眉，旧人霜作眉。","妾无百种态，是君当心际。","妾无百种嗤，是君心别时。","床上五弦琴，一弦今一心。","新弦终须断，旧弦不可寻。"]},{"t":"苦寒行","f":"五言古诗","c":["驱马度阴山，积雪何茫茫。","疾风四隅来，马首浩纵横。","高原无俦迹，顾影仅为双。","孤兽索其群，栖鸟向阳翔。","寒暑客路深，况乃异戎荒。","沈怀幽闺妇，玉箸啼红妆。","旭日未及旦，轧轧涩流黄。","年命不在已，安能顾四方。","人生今失职，岁暮问他乡。"]},{"t":"怨歌行","f":"古风","c":["啼不必溯风而振柯，泪不必决溜而倾河。","中心自樛郁，五情竟焉他。","吾顾松与栝，众视等春华。","冠裳为徽纆，文语强相加。","随涉诣扶桑，弱樯试鲸波。","操者竟何言，他人其奈何。","念欲开耳目，周体悉尘沙。","自非洪乔质，焉能凌紫霞。"]},{"t":"怨诗行","f":"五言古诗","c":["忠臣不可为，良臣不可求。","李牧却秦师，功多竟不侯。","朝谗进郭开，夕骨委荒丘。","千金卖社稷，举宗托仇雠。","蒙恬破匈奴，挟箠河南收。","长城五千里，雉堞如云浮。","赵高从中制，片纸下沙丘。","扶苏掩袂啼，一剑死阳周。","合若投胶漆，弃若覆水杯。","捐脰非所难，谁为终国忧。","我欲寄此曲，此曲多悲思。","今日乐相乐，别后莫相疑。"]},{"t":"独漉篇","f":"古风","c":["独漉独漉，水清泥浊。","知人惟艰，圣哲斯恧。","蓄豹捕鼠，捷不如狸。","狐裘施燠，曷如绤絺。","煜煜绮罗，服丧柰何。","郁郁兰蕙，饥后稻禾。","骐骥千里，水用曷神。","吐绶五色，曷能丝纶。","岂不怀贤，在敌则雠。","虽有南威，外遇莫求。","国之云亡，憸夫孔壬。","嗟彼负乘，莫非行禽。"]},{"t":"乌生八九子","f":"古风","c":["乌生八九子，营巢高树颠。","得食不充腹，置之咽嗉间。","八九子争向，乌力不能任诸雏。","毛羽剥落，皮骨憔悴尾毕逋。","八九子，翼以肥，各自东西飞。","光乌夜悲，啼血继之。","八九子，争食喧野田，谁来念乌饥。","乌且死，愿天莫生乌，但生枭与鸱。","陛下仁圣，海宇咸庆，乌不返哺莫知故。"]},{"t":"野田黄雀行","f":"五言古诗","c":["黄雀摩天飞，乃遭鸷鸟搏。","不遇訇农君，微物焉见录。","东家张罗网，黏竿黏黄雀。","西家得黄雀，置之巾箱中。","哺食养毛羽，纵之归大空。","何以报弘农，四世作三公。","何以结信缘，约指一双环。","道逢白额虎，帖尾复低头。","流矢在足心，刺刺如有求。","不忍为拔矢，踊跃登山坳。","矫为风伯鞭，㸌为电光流。","返顾决一咀，皮骨倏无存。","命亦不在大，报亦不在恩。","念此野田雀，气结不能言。"]},{"t":"鞠歌行","f":"古风","c":["狡容颜，誇子都，以适师冕同狂且。","承五弦，峄阳梧，搆爨宿火让焦枯。","案驺虞，搏妖狐，扰捷安得同韩卢。","骥骨立，仰晨餔，不遘伯乐竟盐车。","鹰扬谁，老匹夫，徒手迫暮簏无鱼。","相仲父，出囚拘，霸齐曷繇管夷吾。"]},{"t":"君子行","f":"五言古诗","c":["莫以君子交，断绝小人欢。","小人蓄疑毒，君子受其患。","鲛蜃岂不雄，力能排丘山。","所遇无完物，齿锷如刀镮。","大造为馀种，置之溟海间。","神龙不羞宅，喣沫各相安。","所以太丘长，广道以自全。","恻怆东京客，达者悲其贤。"]},{"t":"上留田","f":"古风","c":["晨兴陟彼南冈，上留田。","采薪不得盈筐，上留田。","稍后食时釜空，上留田。","别室罗酒及浆，上留田。","毳貉为衣葛裳，上留田。","手足寒燠异方，上留田。","中夜暴客踰垣，上留田。","气迫不得呼援，上留田。","目中谁耶所恩，上留田。","捧足鸟兽窜奔，上留田。","冒刃者何卫兄，上留田。","仓卒亲疏见情，上留田。","俯肝掐心怦营，上留田。","枯枝离披更荣，上留田。"]},{"t":"度关山","f":"古风","c":["度关山，诘曲复崔嵬。","虽有车，畏轮摧。","十步五坐泣且啼，啼声一何悲。","疾风吹尘自我后来，回望故乡茫何睹哉。","前睹黄河水，水流何瀺灂。","一夜胡马过，河边草如削。","河边草如削，安能更民居。","居民尚远徙，行子欲何之。","鸱枭为好音，豺虎亦规行。","四方不识人，来称弟与兄。","温铁益知柔，茹荼益知甘。","平生少自足，临难追故欢。","度关山，那得不沾衣。","日夜见去人，寥寥归者稀。"]},{"t":"前缓声歌","f":"古风","c":["天倾西北，一如地之东南。","頫仰大造，安得两相兼。","猛兽爪牙一何威，欲搏雉鹜不能奋飞。","鲸鱼跋浪雷奔，焉见走陆若人。","王子乔，独身化为鹤，不能挈父母而逍遥。","宾客满堂前致辞，愿君福寿与天齐。","情知非真实，且为进金罍。"]},{"t":"置酒行","f":"五言古诗","c":["置酒高堂上，乐声惨不发。","手抱三鹍弦，檀槽如秋月。","此乐名为谁，言是胡中出。","本以写哀思，云何虞宾客。","听曲各称好，竟令沈怀郁。","繁响赴流光，悠悠逝仓卒。","末坐而楚衣，一听三叹息。"]},{"t":"悲哉行","f":"五言古诗","c":["四坐且罢欢，听我悲哉行。","悲从中心发，轻言涕自零。","疾风吹难散，春阳不能平。","矫矫南山松，屈为虬龙形。","干霄自本性，焉用美好称。","宁为折蕙兰，安为令不芳。","但睹连城碎，谁睹改其光。","与世既殊辙，各自伸所长。","悲哉复悲哉，古今尚茫茫。"]},{"t":"当墙欲高行","f":"古风","c":["墙欲高，雉堞何崔嵬。","室中之藏永无菑，蹻蹠过之，不能竦身而奋飞。","我谓墙欲高，彼谓曷不卑。","丈夫快举事，安能两相全。","当为雠敌忌，莫受亲戚怜。"]},{"t":"枯鱼过河泣","f":"五言古诗","c":["鲂鲤水中居，寄声于枯鱼。","女欲顾俦匹，不能保其躯。","主饮过三爵，短袖出中厨。","脯腊无不为，还得我时否。","枯鱼泣寄声，鲂鲤太不慈。","我当无女日，女当有我时。","大海天茫茫，喣沫各相怡。","但睹长千岁，焉睹后来菑。"]},{"t":"白石歌","f":"古风","c":["白石烂，饥为黍。","兜鍪臼，干戈杵。","男何耕，生远戍。","女何织，生当户。","腰镰牧鸡豚，散走不复顾。","尧舜邈，生不逢汤与武。","羲轮仓皇焉得暮，人欤鬼耶悲哉伍。"]},{"t":"补铙歌四章 其一 钓竿","f":"古风","c":["钓竿青漓漇，钓饵一何芬旨且肥。","小鱼疾走不敢回顾，大鱼施施来。","大鱼恒苦饱，小鱼恒苦饥。","大鱼既失故，小鱼施施去。","乃不知东有属玉鵁鶄，西有鸥与鹭。"]},{"t":"补铙歌四章 其二 玄云","f":"古风","c":["玄云衡空，自西徂东。","暧曃承日，万族无光。","风伯为前导，雨师应后驰。","膏我畛亩，惠我蒸黎。","嗟嗟，惠我蒸黎，天公不任怨，亦不任受德。","县官大酺，欢乐无极。"]},{"t":"补铙歌四章 其三 务成","f":"古风","c":["崇伯子禹，佐舜平水土。","告成上皇，皇锡之大夏。","化益佐禹乱天下。","告成上皇，皇屈为夏辅。","功施既殊等，引分安所存。","吁吁，胡至如务成子，光乃遽湛奫。","霜霰自表坚，曷捐天地仁。"]},{"t":"补铙歌四章 其四 黄雀","f":"古风","c":["黄雀儿，头如栗，翅如双桃叶，飞鸣一何翾捷。","黄雀儿，三时常苦饥。","一时不饥得身肥，前有网罗，不能奋飞。","嗟嗟，生饥曷与死饱。","充君之鼎俎，曷若不利君之禾稻。"]},{"t":"豫章行","f":"五言古诗","c":["豫章富奇植，晻冉经大年。","上摩千仞霄，下荫百顷田。","飞羽无窥地，栖足莫睹天。","精灵若附冯，风雷自樛缠。","东都宏制作，制作首明堂。","万材悉以周，所希在栋梁。","一经匠氏顾，宁辞剪刈伤。","毁质应世求，两重竟何当。"]},{"t":"董逃行","f":"古风","c":["仰见东京郁盘，城郭半摧不完。","虽有室家无烟，荧荧赤烬几寒。","道途者何啼声，父呼他人不应。","血肉杂潦纵横，梦不睹织与耕。","旌旄撇沓虎贲，下有金紫纷纷。","青天无飙忽尘，县官仓皇曷云。","西京高帝所方，万户枳棘夷伤。","峨峨未央建章，百一郿坞盖藏。","忼矫我公司徒，独任捐体扫除。","焕若一气昭苏，延敌追雠大屠。"]},{"t":"吁嗟篇","f":"五言古诗","c":["吁嗟得为人，生世胡不宜。","瞽行趋荆棘，侧足舍周逵。","谁谓八纮广，束身渐如丝。","越舟而向北，齐辕而更西。","盻睐绝穷途，安得展光辉。","汎汎江湖萍，预欲远相期。","明月虽有光，不照浊水泥。","与世既殊适，吁嗟竟安归。"]},{"t":"蒲生篇","f":"五言古诗","c":["青青水中蒲，结根何卑弱。","甘无长年固，所望归履席。","虽蹈剪刈伤，微质终有托。","恒恐秋霜至，百卉坐俱索。","荣茂本不偕，云胡先摇落。","感此中郁蒸，喟焉芳华烁。","君明倘垂照，埽除安为薄。"]},{"t":"煌煌京洛行","f":"古风","c":["煌煌京洛，肇迹光武。","服行共俭，奄宅中土。","天关玉门，以界夷夏。","外户不闭，中夜行旅。","爰及二宗，肃雍明堂。","畴其宾者，三老五更。","邑多藏餦，亩栖赢粮。","声实华鬯，西京有光。","煌煌京洛，常侍燬之。","燬伊成之，司徒伯始。","常侍暴哉，蠹齧天纪。","司徒栖栖，不恤其纬。","煌煌京洛，董逃仇之。","仇伊殴之，将军何侯。","唶彼董矣，卒颠厥室。","嗟彼何矣，自贻伊戚。"]},{"t":"门有车马客行","f":"五言古诗","c":["上客停轮筐，小妇罢流黄。","小妇出肃客，呼水进酒浆。","问客何方来，客亦不肯言。","但睹双荔枝，朱实自殷斓。","谢客忽唯昔，荔枝生南海。","欲因求欢耗，车马去不待。","炎洲翡翠鸟，双双互相乐。","宁知鸿雁若，飞不度湘岳。"]},{"t":"善哉行二首","f":"古风","c":["唯昔帝辛，任志淫刑。","三分失二，施然自矜。","唯周王发，纯心向贤。","诸侯八百，虎贲三千。","大白帝辛，小白妲己。","毋言臣分，寔示君轨。","武庚何圣，管蔡何惛。","畴无父母，畴无季昆。","桀为不道，汤放南巢。","周有桓文，以遏其骄。","秦政卑臣，二世而灭。","䝟貐海宇，为千秋孽。","上严昊天，下严匹夫。","黄屋左纛，曾为而躯。","今胡不乐，烹鲤炰雁。","篪管嘈杂，众大称善。","天光渐倾，咸谓无归。","纤阿受御，嗣其扬辉。","客有韩娥，偻行曼歌。","哀激当心，涕泗滂沱。","斯为相国，卒霸秦世。","晨朝百僚，夕送东市。","错衣朝衣，谓调兵食。","忽见前后，森如霜戟。","哀乐矢催，当身乃知。","酒不速沥，日昃之离。"]},{"t":"太山梁甫吟","f":"五言古诗","c":["嵬嵬天门山，郁郁梁父禅。","金泥閟玉册，荣光曀昭倩。","贤圣七十二，其名几称见。","何况于谋臣，飘沦同春霰。","阙里困韦裳，千秋丽河汉。","亦有抱膝人，居然恬贫贱。","吴趋行上客，且缓骖请听。"]},{"t":"吴趋行","f":"五言古诗","c":["太伯让周王，剪发窜蛮荆。","季子守遗节，屈体臣后生。","要离捐肢体，伍员抉目睛。","岂若被裘子，兼复韬其名。","言游佩端委，文学启休明。","赁舂无凡客，门卒亦仙卿。","震泽含变化，大海发精灵。","焉类十室邑，步趋恒自矜。"]},{"t":"磐石篇","f":"五言古诗","c":["山石何盘盘，水流何溅溅。","溅溅东流水，乃在磐石间。","长与本根辞，一往竟不还。","委蛇东到海，经过诸神山。","巨鳌来戏游，日月双回旋。","珊瑚鲛人珠，光彩烂纠缠。","丹虾须如戟，龙炬照神渊。","旷荡无终止，大壑易沦涟。","磐石有本性，屹立竟何言。"]},{"t":"白马篇","f":"五言古诗","c":["白马西北驰，矫若云中电。","胡锦作障泥，络头珊瑚钿。","片片汗桃花，喷嘶赤琼霰。","捐身出大漠，雄才为君见。","祁连春如赭，白日苍黄变。","所至自无坚，腾骁必居先。","横悬单于首，驰奏未央殿。","改从中黄服，遂压天闲选。","苜蓿春正饶，力疲不成咽。","遗像在凌烟，英风飒然变。","亮无百年物，得施躯不贱。"]},{"t":"邯郸才人嫁为厮养卒妇","f":"五言古诗","c":["高若升高木，幽若栖幽谷。","雨落归川泽，浮云遂不属。","飞萼谢琼枝，卒为泥中辱。","西施苧罗村，红颜初殊俗。","朝为民家女，暮颛吴宫宿。","赵王有才人，皎洁明如玉。","一朝事势异，养卒来相逐。","两世当一身，荣衰何其促。","寄言宫中侣，为恩谁终笃。"]},{"t":"齐讴行 其一","f":"五言古诗","c":["莫以敖辟讥，听我奏齐讴。","右顾枕岱宗，左负沧海流。","维昔师尚父，建册表营丘。","四履征不庭，一钺奠成周。","烈哉桓公筴，首政举其雠。","九合匪兵车，衣食东诸侯。","妖吕荡氛波，炎烬几不收。","哀王倡大义，绛灌始协谋。","九有提一隅，三勋古无俦。","乱民矜炙輠，养客悲蒯缑。","小惠薄陈常，非和诮梁丘。","愤誂杀士桃，刺促媚姬裘。","鄙矣牛山宴，泣涕言爽鸠。"]},{"t":"齐讴行 其二","f":"五言古诗","c":["骋望平原路，郁葱何所有。","狐兔不足陈，麋鹿窜乱走。","鹿走何迷离，血肉俄缭绕。","饥鹰食不多，饱犬食亦少。","马尾捎归来，鷩于退飞鸟。"]},{"t":"仙人篇","f":"五言古诗","c":["结茅华山颠，上有苍鳞车。","仙者四五人，要我偕所如。","遨游天汉上，经历万里馀。","人间所见星，乃是千白榆。","玫瑰切庭阶，木难交绮疏。","不知何宫殿，但怪非人居。","呀然珠帘起，四角垂流苏。","中坐太乙君，夹侍青童姝。","饮我丹霞浆，令我易肌肤。","碧藕错朱桃，玉馔芬且腴。","天乐不能名，但用穷欢娱。","回首望故乡，妻孥不得俱。","坐此一念谪，聊复在泥涂。","疆畴虽历历，他姓治田庐。","欲返渺何因，恻怆但含吁。"]},{"t":"艳歌行","f":"古风","c":["手种梧桐树，竹实何累累。","绿叶间紫茎，玄露自垂饴。","不为游居念，但愿凤皇来。","凤皇不相顾，但见乌鹊群，争栖一何喧。","逐令为伐倒此树，乌鹊惊飞向天悲。","南山五文鸟，自称为凤皇。","听此梧桐竹实，千里飞相从。","下睹荒畴何依，百鸟拱之，缭戾而徘徊。","乌鹊得志，凤皇畴归。","终始失据，曷已心悲。"]},{"t":"艳歌何常行","f":"五言古诗","c":["生男不为贵，都尉执金吾。","生女不为贵，小者号婕妤。","不为家人产，鄠杜千顷馀。","不为富第宅，宝玉厕门枢。","鸣钟会子姓，列鼎荐膏腴。","温爽易炎寒，欢宴乱昏晡。","醉履不及尘，妖姬递来扶。","妖姬十四五，颜色胜罗敷。","但愿长如是，不愿更何如。"]},{"t":"折杨柳行","f":"古风","c":["曷不为男子，不睹苧罗村。","种蠡两谋臣，不能胜妇人。","齐讴走仲尼，秦乐逐由余。","但施妇人巧，贤圣亦不如。","绛灌及樊郦，手扶汉天子。","匈奴北方来，不如一公主。","东家有匹雏，牝者亦司晨。","西家妇女坐床上，男子拜伏堂下尘。"]},{"t":"淮南王","f":"古风","c":["淮南王，习长生，金匕玉鼎琉璃瓶。","珊瑚抄药飞雪轻，役属草木尽成兵。","前殿赤节，后园辎軿。","八公先导之，锵球瑟琴相谐鸣。","青鸾白鹿，杂沓迎生。","汉藩不为臣，见上帝，称寡人。","守厕三载多苦辛，曷不忠孝位天真。"]},{"t":"陇上壮士歌","f":"七言古诗","c":["陇上壮士南安陈，便便腹干藏千人。","绣袍窄袖黄金鳞，双虹熻㸌盘秋旻。","大刀蛇矛近辄嗔，何来一校交逡巡。","蛇矛去腕刀不神，雠尔䯀骢迹何新。","可怜养士同心肝，死者陇上生长安。","西吹晨风东逝澜，为尔抵节歌盘桓。"]},{"t":"行路难三首 其一","f":"古风","c":["寒不入阿房中，春不出轮台东。","轮台岂无春，层冰?砢焉能通。","策驽马，上剑阁，悬度絙索贯复穷。","发白帝，下峡江以风。","目不得瞬，飞不得同。","人生本末竟焉岐，积贱累荣各因之。","南山有鸟易凤皇，毛羽剥落便摧藏。","行路难，君自伤。"]},{"t":"行路难三首 其二","f":"古风","c":["虎肉同类，更向驺虞骄。","鸿飞大冥鹡鸰招，神龟刺促化阳鱎。","销冶干将成铅刀，黄金山重义秋毫。","坦坦天衢趋侠邪，前车轴折后争誇，不臣县官臣私家。","珠琲络钩于阗珂，意气悦怿若春花。","月请十百恒苦饥，名刺漫灭竟安之。","后衣露胫冠达剃，蒯缑一弹幡哉归。","行路难，君自悲。"]},{"t":"行路难三首 其三","f":"古风","c":["陆不必车昆崙，水不必航扶桑。","恩爱苟一亏，咫尺天茫茫，三飧诣莽苍。","其腹犹果然，安能飧风吸露穷岁年。","纵有王子晋，安得日日好容颜。","出门各自顾，他人肯容恤。","千言成桃李，一言变荆棘。","白刃如雪金如丘，侠客报恩行报雠。","不在里巷间，多在长安之道周。","行路难，君自愁。"]},{"t":"秋闺曲二首 其一","f":"七言古诗","c":["药房秋深兽金环，美人参差语霜寒。","深浅自当竟何言，戚戚准君道途间。","江有鲤鱼峨哉山，虽欲裁信逝无还。","鸣蜩肃然损朱颜，蕙草三枯折复捐，安得明镜长少年。"]},{"t":"秋闺曲二首 其二","f":"七言古诗","c":["三星灼灼照鸣机，素腕盈盈出绛帷。","夫君何在在辽西，夏裁霜衣冬裁絺。","以此及君犹后时，惟昔罗縠迫参差。","忽来酒间山岳移，怆若庭前丹桂枝，难何荣茂易何衰。"]},{"t":"白苧词二首 其一","f":"七言古诗","c":["美人含娇出中堂，鸣环饬步齐宫商。","流目一盼自馀光，恍若轻云扶太阳。","娱君青春志意荒，白日易短夜难长。","弦迫柱促乐渐终，鞶鉴掩收意烦忡，安能双驻酡颜红。"]},{"t":"白苧词二首 其二","f":"七言古诗","c":["美人列行烛明辉，丝扬肉奋技争驰。","中有纤娃字夷施，蕴香含粉天然眉。","流星迥月秋山低，轻弦手语私念之。","令君抵节复沈吟，愲结心志内不禁，安能双飞度遥岑。"]},{"t":"隔谷歌二首 其一","f":"古风","c":["兄在城中弟在野，饥食水，寒衣火。","昼行罗飞夜掘鼠，救我来，救我来。"]},{"t":"隔谷歌二首 其二","f":"七言绝句","c":["弟为官人兄束缚，鹡鸰双飞何刺促。","一遘罗网一饮啄，安用生死长相逐。"]},{"t":"斗鸡篇","f":"五言古诗","c":["雄吹间清鼍，列綵冠长筵。","上客不言快，主请更乐端。","金骹抗高尾，介距何轩轩。","虚憍争恃气，竦立怒仍专。","星炬闪朱眸，飙轮搏双拳。","嗉血何漓漇，峨冠坼如莲。","为君效一决，微命安足言。","宁如东郊雉，伏窜受人怜。"]},{"t":"箕山行","f":"古风","c":["唐尧厌九有，授舜中复疑。","顾谓许武仲，为我一代治。","对坐平阳宫，北风吹茅茨。","武仲仰天笑，咄嗟长眉儿。","吾宁箕山饿，如此天下安用之。","富贵日以浓，志意日以移。","老聃长守藏，仲尼但栖栖。","前人自尊，后人愈卑。","大鹏横空，鹪鹩一枝。","鹓雏徘徊，误嚇老鸱。","所怜寂寂挂瓢意，犹有千秋清颍知。"]},{"t":"华周杞梁行","f":"五言古诗","c":["华杞感宾车，骈刀灿双缨。","长驱荡莒师，千里不留行。","岂为齐君死，肯负隰侯生。","二婺争写哀，中夜不绝声。","皇天为摧噫，百雉拉然崩。","朋友自有心，夫妇自有经。","始知乾坤大，不胜一寸诚。","二绰岂不雄，惜哉殉淫朋。","毋以鸿毛重，遂令泰山轻。"]},{"t":"箜篌谣","f":"楚辞体","c":["公无渡河，咨咨河波生鳞。","公无渡河，咨咨河伯不仁。","公不知兮，渡河而公溺之。","妾知公兮，非兹流谁与归，呜呼噫嘻。"]},{"t":"鸡鸣歌","f":"七言古诗","c":["银河迢迢星烂烂，汝南鸣鸡夜将半。","行人出门中道叹，欲归不能何时旦。","曲阳酒酣起更衣，新声乍移霜乍飞。"]},{"t":"轻薄篇","f":"五言古诗","c":["末俗誇轻薄，轻薄生有馀。","骄意盘眼睫，贵骨满头颅。","仲氏二千石，伯兄千户侯。","小弟颇妍好，出入尝奉车。","大母脩成君，女姊班婕妤。","问我汤沐邑，鄠杜最上腴。","问我无名钱，敕赐蜀山垆。","从奴衣火浣，下客蹑真珠。","丸金弹飞鸟，椎铁击珊瑚。","挥霍和氏璧，蹀躞大宛驹。","臂鹰出长楸，斗鸡绝九衢。","帟油雨击鞠，席绮寒摴蒲。","调笑采桑妇，阑入酒家胡。","腰间雌雄剑，双双玉辘轳。","一日不出匣，中夜自呜謼。","破壁藏翁伯，骂坐轻灌夫。","七贵为低眉，将相薄不图。","不礼关都尉，可怕执金吾。","道逢谈天者，复矜意气殊。","千秋若指掌，九州不足居。","一言无骚雅，只字夺典谟。","李耳老秃翁，仲尼亦竖儒。","謦欬细旃表，立可成唐虞。","飞书招越裳，挟箠鞭匈奴。","宁必卿曹子，饮啖类屠沽。","相睨不相下，异路请各趋。","扰扰两蜉蝣，自贵亦自愚。","宁知青门土，贤豪始同途。"]},{"t":"夜坐吟","f":"古风","c":["唧唧夜虫吟，起我东西南北心。","丈夫户庭间，行穷越巂度天山。","高枝肃肃留远风，追我少年及老翁。","邻家有酒沽不得，岂须道途凋颜色。"]},{"t":"铙歌短箫曲","f":"古风","c":["太白蚀月，条支息烟。","积雪数丈，高没祁连。","鸟兽猬缩不得前，穹庐两三沬星悬。","单于今何适，休屠日逐左右贤。","谷蠡当户两薁鞑，曷不度漠而南逐水草，汉兵咆哮正当道。","颇闻置三将军，其一猿臂疾若飞，大者善射习兵机。","小者号嫖姚，天子最亲，信多神威。","射生超乘良家儿，衽金浴铁设长围。","六畜孕殰，马弱不得逐。","归来祭天，金人曷属。","寡妇抱儿哭，哀哀死丧势不复。","唯有中国万里，长偃兵革。","皇帝置酒群臣，欢乐无极。"]},{"t":"东武吟","f":"古风","c":["罢鸟厌离枝，罢客厌离乡。","听君行泣复坐诉，令我断绝少年肠。","始从张侯号博望，寻源凿空竟西方。","问君何所历，身毒安息大月支。","问君何所见，深目高鼻卷眉髭。","其人何所宝，葡萄汗血香都夷。","其俗何所尚，嗜利轻杀易汉儿。","结营勃律河，士卒樵汲供炊麋。","斧冰十指半堕落，又有猛兽搏食之。","经行十三载，皮肉消尽馀音声。","音声固未改，舌强亦难明。","忽睹嵬峨之宫阙，不敢遽谓长安城。","不知张侯见天子何所言，独封大邑金帛蕃，甲第亦轩轩。","馀者公车门，十上不得论。","最后稍为郎，给钱十万令还乡。","庐井渐非故，急欲问爷娘。","行逢耆旧为相指，双冢累累置道旁。","新妇逐他人，他人生儿已扶床。","对讫始大悲，耆旧内相疑。","别时朱颜复鬒鬓，今来其人鬼邪非。","又闻甘泉宫，召按西边事。","乡导不乏兴，应须故时吏。","家乡空荡尽，枯骨终远弃。","吁嗟哉，丈夫功成差足乐，不如贫贱佣力作。"]},{"t":"猛虎行","f":"古风","c":["北山饶风雪，东山西山多网罗。","唯有南山足樵采，其若白额斑文之虎何。","嗟虎胡乃白额而斑文，目为流电飙若奔。","低头前告言：“汝虎既为百兽之王，奈何搏噬绝其群。","不见鸟中之凤，饥食竹实，众羽自归尊。","神龙变化岂后汝，鱼鳖喣沫相和欣。","”虎对之若不闻，咆哮木叶风纷纷。","但欲得汝充虎腹，安用繁辞诉苦辛。","天造万物岂为人，上穷泱旷下沈沦。","巧网必遂私其身，况尔同类多相食，虎一食人何遽论。"]},{"t":"东飞伯劳歌","f":"七言古诗","c":["伯劳飞东燕飞西，马头儿郎机头妻。","机声轧轧马凿落，愿得两风并吹却。","织师误教织鸳鸯，令我厌取向流黄。","儿郎三十年尚未，珊瑚具装藕丝辔。","银镫碧篆温春宵，俱留可怜向谁骄。"]},{"t":"结客少年场行","f":"古风","c":["骢马玉连钱，流苏障泥玛瑙鞭。","经过五陵畔，结客多少年。","如渑之酒倾肯惜，突兀黄金若山积。","散尽姓名都不问，肝胆但许英雄识。","扶风夜深雪花白，手提人头刎君侧。","为君报雠身并掷，细看乃是当时客。","君不见东家钱刀坐朱紫，魏其为朝武安夕，如此结交竟何益。"]},{"t":"登高丘而望远海行","f":"七言古诗","c":["登高丘而望远海，秦王者何二千载。","阿阙王基竟已灰，瀛洲仙药空谁采。","初从梁甫匮金书，七十二君俱不如。","已借神鞭驱怒石，复张连弩射游鱼。","归来尽灭儒生口，徐市茫茫竟何有。","祖龙未朽骊山身，亡鹿先归赤帝手。","赤帝诸孙犹不闻，文成五利日纷纷。","请君试上长安问，唯有甘泉一片云。"]},{"t":"长相思","f":"古风","c":["长相思，望难期，美人如花隔深闺。","轻霜剪涩凝胭脂，青黄碧绿诸色丝，织成鸳鸯心自悲。","两心为一心，明月照秋水。","一心成两心，各悬三千里。","昔为比翼鸟，翼折不能飞。","今为双星界河汉，年年夜夜盼光辉。"]},{"t":"杨白花","f":"七言律诗","c":["宫中小女髻如鸦，连臂蹋足唱杨花。","唱得杨花浑胜雪，不知飘向阿谁家。","塞北江南望何极，衠道藏鸦白门色。","沙深日冷不得青，独抱长条三叹息。"]},{"t":"阳春曲","f":"古风","c":["汉女三千人，一一盼阳春。","花开不见日，愁绕翠蛾颦。","君王雨露在一身，那得遍洒东门尘。","君不见赵家姊妹玉不如，昭阳乍亲椒殿疏，何况增成班婕妤。"]},{"t":"双燕离","f":"古风","c":["双燕若双剪，翩翾吴王宫。","自愿同生死，岁岁掠春风。","吴宫火起焚其雄，雌鸣啾啾入棘丛。","曷不从新鳏翼，物微心重挑不得。","今春共衔泥，明春黄口血漓漇。","不如庐江小吏妇，犹胜会稽太守妻。"]},{"t":"于阗采花歌","f":"古风","c":["于阗采花女，采花置瓶中。","三日花憔悴，红颜翻更红。","明年花纵破，的应不胜我。","明年更明年，渐不胜花妍。","西头黄金轮，东头白银毂。","人生颜色得坚牢，何必勃律河中三尺玉。"]},{"t":"中山孺子妾歌","f":"古风","c":["中山孺子妾，出自君王宫。","玉蕊堕九天，犹能挂帘栊。","不见东家儿，邯郸才人厮养妻。","朝来系马栈，生割流黄帷。","江姬屈，阴姬伸。","屈伸有奇亦有真，犀角偃月为何人。"]},{"t":"临江王节士歌","f":"古风","c":["临江国城多侠儿，?翿锦韝冠雄鸡。","跪推王毂中尉府，中尉府前乌夜啼。","不如蜩唽江头燕，犹解衔来坟上泥。","夷门少年隐酒屠，将身付心心不孤。","淮南金椎辟阳颅，匈奴偶人射郅都，若曹冠韝胡为乎。"]},{"t":"山人劝酒","f":"古风","c":["日迩不怿，披寻幽沦。","道逢山人，被山衣巾。","酌我葡萄九酝之美酒，盛以瘿藤五华之灵尊。","尽倾尊中酒，为唱青天歌。","一歌还一杯，柰此青天何。","踞坐问山人，汝今欲何为。","行将出山去，搏弄造物为婴儿。","四皓归来，皲■头皮。","赤符自新，紫芝已萎。","羔雁三至，卧龙遂起。","行雨不休，卒以暍死。","天施白玉棺，生瘗王子乔。","何如留此口，时进美酒长逍遥。","欲知出山者我是，悔不老作吴山樵。"]},{"t":"日出入歌","f":"五言古诗","c":["日出东旸谷，赤若赤琼毂。","日入西虞渊，赪若赪玉盘。","空中日稍定，团团黄金镜。","南陆令我暖，北陆令我寒。","寒暖嗟自可，为汝销朱颜。","但见日出入，不见日后先。","长歌出入歌，起我长恨端。"]},{"t":"结袜子歌","f":"古风","c":["小吏摩足日，腐儒结袜时。","张家两伧父，不复顾腰肢。","博得公卿名，且为帝王知。","男儿事事仗人口，安用区区七尺为。","自斟自咏自老死，从他门外浮云驰。"]},{"t":"秦女卷衣曲","f":"古风","c":["萯阳宫中漏未央，荧荧初月丽初妆。","此时秦女唤梳沐，此际泪湿罗衣裳。","邯郸倡姬秦国母，秦王相国邯郸贾。","邯郸大贾秦仲父，仲父舍人秦假父。","可怜君王才十五。","秦女贱，赵女骄，寄生茑萝出松标。","耐向民间击土缶，难同贵邸伴吹箫。"]},{"t":"行行且游猎","f":"古风","c":["行行且游猎，遂出光禄塞。","秦地一掌间，黄河落天外。","六郡良家五陵豪，于阗玉鞭大食刀。","不爱县官封博望，自从私客取临洮。","盘马弯弓月相向，万族蹒跚魄先丧。","突出霜蹄狡兔先，争看鸣镝苍鹰上。","黄沙一缕冲紫微，角声四起胡霜飞。","少年割鲜且莫饮，待我生挟单于归。"]},{"t":"采莲曲","f":"古风","c":["兰为楫，桂为桡，青丝笮，沙棠舠。","十五女儿茜红绡，轻裾明珰芬自飘。","花深叶高柰何腰，中有文鹥并逍遥。","红蘤绿的一双娇，回眸誇君心语要。","何意水长不通桥，横塘别浦多风潮，稀星薄露夜迢迢。"]},{"t":"梅花落","f":"五言律诗","c":["窗外梅花落，辽西尚未归。","霜风吹玉笛，寒月满金微。","此际征人幕，应同少妇机。","那堪驿使断，心逐岭鸿飞。"]},{"t":"铜雀伎 其一","f":"五言律诗","c":["往事秦云逝，深恩漳水流。","月归金雁冷，风至玉衣秋。","粉黛年年薄，弦歌夜夜愁。","谁同汉武帝，还向茂陵游。"]},{"t":"铜雀伎 其二","f":"五言律诗","c":["奉寝传遗教，分香更系情。","履犹明主迹，弦是向时声。","寂寞无新故，荣华有重轻。","尚疑仙乐动，别院夜相迎。"]},{"t":"爱妾换马","f":"五言律诗","c":["只解驱驰易，宁言离别难。","兰膏啼玉箸，桃雨汗金鞍。","物喜酬新主，人悲恋故欢。","横行度辽海，那问剪刀寒。"]},{"t":"夜夜曲","f":"五言律诗","c":["夜夜连枝帐，不复知惆怅。","夜夜同心绮，亦复忘欢喜。","唯有梦梁州，追欢更解愁。","匡床凉似水，初月澹如钩。"]},{"t":"小垂手","f":"五言律诗","c":["小院炙瑶笙，红妆按队呈。","都将兰麝口，吹作凤皇鸣。","曲终仍教舞，垂手故盈盈。","讵是长持履，临风骄怨声。"]},{"t":"大垂手","f":"五言律诗","c":["秋水剪明眸，亭亭出画楼。","邀他大垂手，不惜锦缠头。","舞罢香无迹，歌残翠未收。","留髡烛尽灭，更与按伊州。"]},{"t":"乐府变十九首 其一 治兵使者行当雁门太守","f":"古风","c":["今皇帝时，治兵使者任君繇。","别驾稍迁，别驾坐府，俨若明神。","大吏畏公，小吏畏民。","倭奴扬帆来，疾如冲飙。","杀掠吏士，奉首伏逃。","任君当之，数折其骄。","殷殷师鼓，任君在先。","鍧鍧师金，任君在殿。","止若春风，动则夏电。","士女避敌走，不敢开门。","任君令开门，全活千万人。","生我父母，存我任君。","入夜不宿，或昼辍飧。","胄而拊循，挟纩一言。","愿与同死，不蕲独全。","贤哉我师任君，媪死不归，墨而戎绖。","慈母令子，明君良臣。","辑兵持服，舍车而徒。","老弱奔走，巷哭旅呼。","家斲一木，以像君躯。","天祸王室，早就奄迷。","何以祠君，姑苏台西。","千秋万年，俎豆其间。"]},{"t":"乐府变十九首 其二 白日引","f":"七言古诗","c":["白日烛天被八方，穴凤薮龙来游翔。","三事庶尹万友邦，靡尸不鳏徵俊良。","将作少府六局坊，一切报罢诸不详。","封墓式闾直谏彰，四门大辟晨煌煌。","皂囊白简纷纵横，单于谷蠡左右王。","解辫顿颡称恐惶，鲸鲵戢甲波不扬。","公卿上寿报举觞，隆庆天子坐明堂。"]},{"t":"乐府变十九首 其三 寿宁泣","f":"古风","c":["何当快乐无忧，长兄太师上公。","小弟太傅彻侯，太后不避傅姬。","两宫睥睨参差，中外嗫嚅忧疑。","有妄男子数人，上书告密纷纷。","缇骑东西逐奔，黄金大贝明珠。","木难火齐珊瑚，散入咸阳贾胡。","兄弟骈首琅珰，太师夺封道亡。","小弟杀人坐偿，念昔蒙恩紫宫。","左掖夜启铜龙，亡酒不论椒风。","君心顷刻万端，何况彼此异天。","掩袂饮泣重泉，敬谢太后主臣。","在昔王法无亲，大德不德奚论。"]},{"t":"乐府变十九首 其四 尚书乐","f":"古风","c":["扬翠毦，曳金支。","马駊騀，车逶迤。","手将两黄钺，大者诛二千石，小者僇偏裨。","九卿班饯日崦嵫。","相君眤眤前致辞。","尚书行出师。","乐哉尚书柰乐何。","所过二千石，丧魂魄。","日夜辇重称军食。","黄金如山莫谯诃。","累女对对嚬青蛾。","回鹘小队桃叶歌。","中丞奉觞舞回波。","乐哉尚书柰乐何。","大宛骢，珊瑚鞭。","天吴绣蹙当胸盘。","麒麟玉刻称腰圆。","珍怪百宝装千船。","席捲三吴向青天。","九卿班，迎晡不得前。","相君眤眤前致词。","中官黄纸纷而驰。","尚书告班师。","乐哉尚书柰乐何。","朝赐尚书，夕宴尚书。","尚书第中锦不如。","檀床八角垂流苏。","紫衣屏息骈街衢。","欲进不进足次且。","左右十二波斯胡。","平头奴子貂襜褕。","醉着不下公侯车。","乐哉尚书柰乐何。","云霾辞天，雨洗白日。","诏收尚书下请室。","削之归，一官不得著。","昔来一何驶，今归一何疾。","念欲乘柴车，病不得驱。","欲呼估客舟，估客不肯相于。","妇女谇骂，小儿拍手揶揄。","道逢九卿睥睨之，谒辞相君：相君新门十二重。","东流之水西飞鸿。","昔日父子今华戎。","乐哉尚书柰乐何。"]},{"t":"乐府变十九首 其五 将军行","f":"古风","c":["娄猪化为龙，头角故不分。","贪狼长百兽，那不食其群。","有何短老公，自称大将军。","从兵三十万，华盖若飘云。","尺一丹棱箧，细刺蛟螭文。","一署臣某字，直入铜龙门。","忽开青天笑，雷公不得闻。","前驱碧眼儿，惯骑大宛驹。","与公同卧起，锦带貂襜褕。","朝令谒天子，暮令拜单于。","单于开箧看，中有尺一书。","织成紫?毹，恰恰覆穹庐。","犀毗黄金造，密嵌珊瑚珠。","团龙五色帛，百匹为一角。","单于大欢喜，亲为割肉炙。","小妇弹琵琶，大妇奉羊酪。","手取一束箭，墨文何错落。","为语而将军，物微意不薄。","箭锋但相近，各各相引却。","归还告将军，将军大欢喜。","今年敌却去，好复开茅土。","幕府上功簿，两两对金紫。","鬼伯何催促，将军向蒿里。","严霜一夜零，华堂遍荆杞。","翩翩执金吾，缇骑类貔虎。","急为发其私，丞相下御史。","支磔将军骸，分枭十二边。","车裂两分张，刬肉施乌鸢。","红颜夫人妇，悬首映旌旃。","白面羽林郎，含咽向重泉。","小女配人奴，歌舞侯家筵。","田园亿千彊，各自称新阡。","生为众人恨，死为众鬼怜。","寄语二心臣，贻臭空万年。"]},{"t":"乐府变十九首 其六 越台高","f":"古风","c":["越台高高，以临吴会，下视岢峨。","千艘万艘来不知，外戟如霜炮如雷。","妇女累戟底，丈夫头悬戟支。","遥问乃是故乡之人，何畏哉。","遥问乃是故乡之人，何畏哉。","男儿生世须黄金，令汝?载归。","男儿但得多黄金，安用刺促斗争为。","大夫坐越台中央，诸君但坐两头。","织成氍毹锦地衣，流苏八角珊瑚钩。","酌大酒，烹肥牛。","诸君但坐两头，为汝楚歌不得休。","下有一百二十红妆，璆枝㔩叶摇明珰。","枝枝玉相对，叶叶翠相当，银烛迷离复昏黄。","共醉捉大夫，不知大夫在阿旁。","众中有小女，自名董妖娆。","入门拜大夫，刺刺重憢憢。","出门拜大夫，施施重蹻蹻。","十疋红番罗，下压银狻猊。","上有大夫字，但受不得辞。","鼓瞳眬，报出日。","诏书来，众缩瑟。","大夫笑谓诸君：但坐无所苦，长安相君日卓午。","越城机轧轧，旦莫为相君，织作何所苦。","黄金南北走，大夫中央卧，御史濡沫不得祻。"]},{"t":"乐府变十九首 其七 钦䲹行","f":"古风","c":["飞来五色鸟，自名为凤皇。","千秋不一见，见者国祚昌。","飨以钟鼓坐明堂，明堂饶梧竹，三日不鸣意何长。","晨不见凤皇，凤皇乃在东门之阴。","啄腐鼠，啾啾唧唧不得哺。","夕不见凤皇，凤皇乃在西门之阴。","媚苍鹰，愿尔肉攫分遗腥。","梧桐长苦寒，竹实长苦饥。","众鸟惊相顾，不知凤皇是钦䲹。"]},{"t":"乐府变十九首 其八 金吾缇骑行","f":"古风","c":["缇骑一何?翻，轻裘怒马上兰。","念欲陆海沈山，金吾府中大难。","城南老姥雌孤，生有剪头吃雏。","凌晨出游逮晡，乃从缇骑游趋。","教以胡言数言，金鼓缚送紞紞。","将至大司马门，太保首功次论。","廷尉当之五刑，血肉模糊吞声。","东市烹羊宰牲，西市击鼓吹笙。","争贺缇骑遝来，男子步武崔嵬。","罢归拊心徘徊，儿今出入危哉。"]},{"t":"乐府变十九首 其九 钧州变","f":"五言古诗","c":["富贵且莫求，贫贱且莫忧。","奉君一卮酒，为君奏钧州。","钧州先王日，恩宠冠诸侯。","斗大黄金玺，真人刻上头。","下令黔黎伏，上用神鬼愁。","后宫五百人，一一玉搔头。","工作侔尚方，永巷儗长秋。","枚马不足谭，八公日从游。","守令惕惕来，白事长叩头。","御史昂昂来，旬月论为囚。","数极终有归，祻至不自谋。","急风覆破樯，天火烧枯桑。","前人抽栋去，后人压空房。","可怜少年子，急利好儿郎。","深宫不足居，要走高皇乡。","红粉厌为土，改作估客装。","谬称平阳骑，去狎秦淮倡。","秦淮欢不足，逻骑忽纵横。","旦夕长安道，冠盖郁相望。","中坐中贵人，貂裘金左珰。","先收真人玺，后夺诸王章。","昔日甘泉殿，千里若咫尺。","今日未央门，一叩不复得。","手种桃李花，须臾变荆棘。","投书太保府，行金丞相宅。","但进不复论，杳如海沈石。","四门陈刁斗，击令心肠坼。","鸡犬寂无声，幸弄争逃匿。","掩泣复沈沦，洒谓众夫人。","昔忝千乘主，安能縳辎轮。","谁言乃公勇，千载不复晨。","但没从我去，存者他人亲。","华容慨起舞，虞姬絮前陈。","急风覆破樯，畴不喂饥鳞。","天火烧空桑，女萝亦见焚。","引颈各高悬，举宫向沈沦。","我欲竟此曲，罢曲涕泗涟。","日月与雷霆，往往任高天。"]},{"t":"乐府变十九首 其十 江陵伎","f":"五言古诗","c":["江陵伎人子，掩袂作啼声。","家家叉帘立，送王上台城。","王欲别太姬，门前黄纸催。","出亦以徘徊，入亦以徘徊。","王入台城后，不省作悲啼。","妆台铅粉骄，别接冶游儿。","朱门一家哭，万家得安宿。","一家亦不哭，太姬方啖粥。","门外双乌栖，哑哑枝上啼。","官今当大赦，不愿赦王归。","二十四皇孙，譬如南陇树。","一半枝撑天，半不知爨处。"]},{"t":"乐府变十九首 其十一 白莲花","f":"古风","c":["白莲花，捧世尊。","左跪圣母，右拜神君。","莲花水，浴金盆。","男女行照之，女为后妃男侯王。","金貂罗纨耀两行。","生当踏玉阶，死当坐天堂。","谁为遣汝来，丘太师、周太师，却立那，颜东西。","授汝尺一锦牍，赤白号带两头垂。","但入上谷云中得，好儿郎，因依精兵十万骑，一一衔枚后头随。","天运好反覆，白发所谋私。","反接向市中，号呼众男女，曷不救我为。","救我死者坐天堂，生当踏玉阶。","忽有一书生，众不识为谁。","书生从何来，乃是阙下上书男子，长流关外醉卧阛阓间，夜半缚致之。","桃李种山冈，莲花种湖陂。","刺舟摘莲花，却折桃李枝。","东市标，书生头。","鼓曈昽，使者輶。","千金赏，万户侯。","道傍跌足涕被面。","中丞封，御史转。","丞相阁中三日宴。"]},{"t":"乐府变十九首 其十二 凌节妇行","f":"五言古诗","c":["郁郁九里松，虽悴不改真。","五尺无瑕璧，是君百年身。","明明两高月，不受浮云侵。","寸铁成寸丹，是君百年心。","膏沐辞镜台，髧髦涩金剪。","白雪白双蛾，是君诀时面。","丸胆佐朝饔，当食何大苦。","虽苦不如汝，是君诀时语。","昂藏二千石，鬑鬑颇有髭。","横金照里闾，是君襁中儿。","始讽柏舟篇，载陈断机言。","应知循吏传，当归列女编。"]},{"t":"乐府变十九首 其十三 莫州谣","f":"古风","c":["兄何在，南伐吴。","弟何在，北幽都。","老父何在，呼役夫。","少妇具晨餔，大妇行唤姑。","行唤姑，姑不起。","溺床下，波瀰瀰。"]},{"t":"乐府变十九首 其十四 小儿谣之一","f":"古风","c":["木稼木稼，胡不日稼。"]},{"t":"乐府变十九首 其十五 小儿谣之二","f":"古风","c":["谁谓瓜土，而实其李。","谁谓卵小，而犬其子。"]},{"t":"乐府变十九首 其十六 小儿谣之三","f":"古风","c":["一虎挟两羊，后有乳贙不可当。"]},{"t":"乐府变十九首 其十七 小儿谣之四","f":"楚辞体","c":["有蠹齧栋，几其隳兮。","吁嗟隳兮，子安归兮。"]},{"t":"乐府变十九首 其十八 小儿谣之五","f":"古风","c":["猴而冠者酣耶，虎而冠者耽耽耶。"]},{"t":"乐府变十九首 其十九 乙卯市人谣","f":"古风","c":["日蚀不吐，社人奏鼓。","大妇辍浆，小妇辍哺。","昨日之日，汝于何所。","回光不瞩，焉为救汝。"]},{"t":"琅琊王歌 其一","f":"五言绝句","c":["小女十四五，许嫁琅琊王。","新婿呵殿来，旧婿趋道傍。"]},{"t":"琅琊王歌 其二","f":"五言绝句","c":["女儿年十三，手种银杏树。","银杏已结子，问母还女处。"]},{"t":"琅琊王歌 其三","f":"五言绝句","c":["琅琊骑儿马，七尺银缠騣。","不能上天去，对人呼作龙。"]},{"t":"琅琊王歌 其四","f":"五言绝句","c":["十日教新声，呼瑟捧来筝。","非无好颜色，难事琅琊王。"]},{"t":"琅琊王歌 其五","f":"五言绝句","c":["三钱买屠刀，日日将杀猪。","东家有宝剑，七世匣中居。"]},{"t":"琅琊王歌 其六","f":"五言绝句","c":["种苗高山颠，下荫松柏树。","大姊儿郎妾，妹是儿郎妇。"]},{"t":"琅琊王歌 其七","f":"五言绝句","c":["要识琅琊门，前有石虎卧。","黄金东西来，及门不得过。"]},{"t":"琅琊王歌 其八","f":"五言绝句","c":["人是官家人，马是官家马。","原不属女郎，安能不相舍。"]},{"t":"企喻歌 其一","f":"五言绝句","c":["男儿好横行，横行自身乐。","那见摩天鹞，结伴寻鸟雀。"]},{"t":"企喻歌 其二","f":"五言绝句","c":["女子爱妆束，妆束头上钗。","男儿爱妆束，妆束坐下騧。"]},{"t":"企喻歌 其三","f":"五言绝句","c":["以我大羽笴，试君铁裲裆。","两家俱言利，那得无一强。"]},{"t":"企喻歌 其四","f":"五言绝句","c":["饥拔两刃刀，割肉行自吞。","情知饥难忍，不拟受人恩。"]},{"t":"黄淡思歌 其一","f":"五言绝句","c":["归归黄淡思，百结系郎衣。","归归黄淡思，千结系郎足。"]},{"t":"黄淡思歌 其二","f":"五言绝句","c":["与郎指刀头，明镜中天流。","一夕深一夕，明镜化为钩。"]},{"t":"黄淡思歌 其三","f":"五言绝句","c":["黄金将作盌，独饮不得满。","白玉将作床，独眠不得长。"]},{"t":"黄淡思歌 其四","f":"五言古诗","c":["床盌忽光辉，报郎骑马归。"]},{"t":"地驱乐歌 其一","f":"古风","c":["穹沙大潴，天公模糊。","逐得一羊，走死一驹。"]},{"t":"地驱乐歌 其二","f":"古风","c":["媪爱小女，不愿女苦。","愿女成长，多得夫婿。"]},{"t":"地驱乐歌 其三","f":"古风","c":["头上倭髻，珍珠累垂。","要郎解髻，妾自解衣。"]},{"t":"地驱乐歌 其四","f":"古风","c":["愿为郎席，不愿为被。","得郎在身，胜郎下睡。"]},{"t":"地驱乐歌 其五","f":"七言古诗","c":["郎骑白马妾坐车，偷眼少年郎不如。"]},{"t":"慕容家自鲁企由谷歌","f":"五言绝句","c":["人言慕容恶，慕容剧不恶。","凤皇化鸱枭，生缘好逐雀。"]},{"t":"陇头歌 其一","f":"古风","c":["陇水霏微，望如一丝。","中有百调，令人伤悲。"]},{"t":"陇头歌 其二","f":"古风","c":["将刀画水，水断不流。","男儿心肠，不在眉头。"]},{"t":"幽州马行客歌 其一","f":"五言绝句","c":["为郎闺中妇，不若辕下驹。","百金买鞍鞯，十金买辔头。"]},{"t":"幽州马行客歌 其二","f":"五言绝句","c":["爱马有何好，马走千里道。","郎但不出门，那得颜色老。"]},{"t":"幽州马行客歌 其三","f":"五言绝句","c":["女郎初嫁时，日日称阿母。","女郎抱儿归，日日称儿父。"]},{"t":"幽州马行客歌 其四","f":"五言绝句","c":["郎赠倭堕髻，妾报倭堕髻。","知郎非女娘，郎无男儿气。"]},{"t":"幽州马行客歌 其五","f":"五言绝句","c":["阿母不嫁女，阿母故相恼。","教作绣鸳鸯，鸳鸯是何鸟。"]},{"t":"捉搦歌 其一","f":"七言绝句","c":["阿母三十育五女，长作南邻北邻妇。","野雌遗壳伏雌乳，总为他人劳阿母。"]},{"t":"捉搦歌 其二","f":"七言绝句","c":["黄絺作衫绣作里，贫家驱犊当驹使。","儿郎饱饭坐屋底，万事不理问女子。"]},{"t":"捉搦歌 其三","f":"七言绝句","c":["当门种葵棘盖井，卷毛生睫项垂瘿。","成长二十不得逞，招将倩郎生作梗。"]},{"t":"捉搦歌 其四","f":"七言绝句","c":["销金中裙翡翠鬌，千钱衬僧结因果。","愿奴生身勿再堕，负心儿郎行作我。"]},{"t":"折杨柳歌 其一","f":"五言绝句","c":["懊恼杨柳枝，窣地黄金丝。","门前不种尔，那得管别离。"]},{"t":"折杨柳歌 其二","f":"五言绝句","c":["妾肠如车轮，日日千万转。","闻郎发咸阳，妾已在沙苑。"]},{"t":"折杨柳歌 其三","f":"五言绝句","c":["可怜孟诸岸，春草绿芊芊。","羌儿骑汉马，牵著上床眠。"]},{"t":"折杨柳歌 其四","f":"五言绝句","c":["莫作中女郎，懊憹不可言。","大姊得蚤嫁，小妹得娘怜。"]},{"t":"折杨柳歌 其五","f":"五言绝句","c":["下马绣盘龙，上马金裲裆。","男儿好光彩，只是耀他乡。"]},{"t":"折杨柳歌 其六","f":"五言绝句","c":["牝马接神龙，生儿尚为驹。","娇女嫁仆夫，生儿唤作奴。"]},{"t":"折杨柳歌 其七","f":"五言绝句","c":["桃花二三月，故爱东风吹。","阿母不嫁女，忘取少年时。"]},{"t":"折杨柳歌 其八","f":"五言绝句","c":["桃花八九月，树头无一枝。","女儿作阿母，不作阿母痴。"]},{"t":"高阳王乐人歌 其一","f":"五言绝句","c":["男儿但意气，不复论须钱。","无钱酒家过，有钱酒家眠。"]},{"t":"高阳王乐人歌 其二","f":"五言绝句","c":["手携双雕弧，射杀双飞凫。","不将向家去，将向酒家胡。"]},{"t":"雀劳利歌 其一","f":"七言古诗","c":["场禾肃肃雀劳利，雄雀嗉饱向天外。"]},{"t":"雀劳利歌 其二","f":"七言古诗","c":["二十儿郎太狡狯，来如调饥去如掣。"]},{"t":"读曲歌 其一","f":"五言绝句","c":["欢掷芙蓉花，悴如菉葹草。","欢不见侬时，芙蓉也应好。"]},{"t":"读曲歌 其二","f":"五言绝句","c":["宝妆千金辔，香刻六萌车。","将欢过南陌，见者捋髭须。"]},{"t":"读曲歌 其三","f":"古风","c":["流苏三重帐，欢来不知曙。","谁遣乱乌啼，恨杀庭前桠臼树。"]},{"t":"读曲歌 其四","f":"五言古诗","c":["为欢制衣带，秋风吹瘦侬，欢腰讵偏耐。"]},{"t":"读曲歌 其五","f":"古风","c":["柰何许，鱼吞熊胆钩，衔苦不得吐。"]},{"t":"读曲歌 其六","f":"五言绝句","c":["人言欢薄情，侬道欢不薄。","欢家贩吴丝，新绮是侬著。"]},{"t":"读曲歌 其七","f":"五言绝句","c":["青菱白板舫，丝系双桥柱。","侬道殊可憎，只解将欢去。"]},{"t":"读曲歌 其八","f":"五言绝句","c":["竹竿何篱筛，湛井不到底。","欢持眼色去，那得复盻尔。"]},{"t":"前溪歌 其一","f":"五言绝句","c":["邻家俱种桑，侬自种黄葛。","那得四时寒，与欢裁衫襭。"]},{"t":"前溪歌 其二","f":"五言绝句","c":["竹竿何篱筛，上有馨香饵。","两鱼参差到，不知合谁死。"]},{"t":"前溪歌 其三","f":"五言绝句","c":["侬家十亩竹，个个青琅玕。","与郎作怨耦，俱作湘妃瘢。"]},{"t":"前溪歌 其四","f":"五言古诗","c":["竹竿何篱筛，钓饵何馨香。","前鱼方吞吐，后鱼自徬徨，为侬死不妨。"]},{"t":"前溪歌 其五","f":"五言绝句","c":["沙糖将黄檗，俱是业中味。","欢真酿师手，一言千条泪。"]},{"t":"青阳度 其一","f":"五言绝句","c":["欢爱二月风，吹枯作红紫。","侬爱五月风，吹花结成子。"]},{"t":"青阳度 其二","f":"五言绝句","c":["玉勒紫丝缰，是郎果下騧。","到门不肯走，识侬双桃花。"]},{"t":"上声歌 其一","f":"五言绝句","c":["闻郎好新变，缓歌为上声。","危弦依柱走，犹是故时情。"]},{"t":"上声歌 其二","f":"五言绝句","c":["百层黄蜂蜡，里有苏合油。","不得郎手擘，芬芳中自愁。"]},{"t":"懊侬歌 其一","f":"五言绝句","c":["布帆珂峨头，飞花自在流。","欢饮宜城酒，那得忆扬州。"]},{"t":"懊侬歌 其二","f":"五言绝句","c":["手插桃李树，先祝嫁东风。","欢将盛年去，留衰掷与侬。"]},{"t":"长乐佳 其一","f":"五言绝句","c":["南州翡翠鸟，雄来太液池。","得鱼不肯食，衔著待其雌。"]},{"t":"长乐佳 其二","f":"五言绝句","c":["十二金凤皇，一一衔明珰。","八角合欢带，欢不在中央。"]},{"t":"欢闻歌","f":"五言绝句","c":["感欢千金赠，亦拟报千金。","数尽人间物，无如侬寸心。"]},{"t":"欢闻变歌 其一","f":"五言绝句","c":["不知欢心变，约侬月出时。","欢自知月晚，要接侬家鸡。"]},{"t":"欢闻变歌 其二","f":"五言绝句","c":["耶婆不肯睡，呼侬到五更。","欢如树头鹘，侬似韝中鹰。"]},{"t":"欢闻变歌 其三","f":"五言绝句","c":["小妹笑大姊，结欢莫作侬。","东垞鸳鸯桥，不见双飞虹。"]},{"t":"石城乐","f":"五言绝句","c":["欢来迎石城，欢去送石城。","生憎竟陵水，解作两般声。"]},{"t":"三洲歌","f":"五言绝句","c":["龙须编作席，象牙装作床。","不用侬双腕，那得稳著郎。"]},{"t":"丁督护歌 其一","f":"五言绝句","c":["督护初北征，挥手便作去。","可怜杨子水，画成死生路。"]},{"t":"丁督护歌 其二","f":"五言绝句","c":["红罗八角帐，摺摺鸳鸯嘴。","懊念丁督护，不肯为侬死。"]},{"t":"华山畿","f":"古风","c":["华山畿，天地为情转，生人作鬼妻。","上有石莲花，是侬洗头池。"]},{"t":"碧玉歌","f":"五言绝句","c":["碧玉好女儿，自谦无倾城。","阿大李家姊，枉得佳人名。"]},{"t":"白团扇歌","f":"五言绝句","c":["郎持白团扇，商风来吹袖。","宁为便拆坏，不忍离郎手。"]},{"t":"明下童曲","f":"五言绝句","c":["结束珊瑚钩，㚟跃果下骝。","问渠那得尔，祖父豫章侯。"]},{"t":"同生曲","f":"五言绝句","c":["郎年十六少，十五女有馀。","携手西陵下，琼瑶双不如。"]},{"t":"采莲童曲","f":"五言绝句","c":["莲童白如雪，见侬眼相媚。","侬家在南垞，井傍双杨树。"]},{"t":"江陵女歌","f":"五言绝句","c":["流凘结作冰，冰化复为凘。","与郎心相变，还我未见时。"]},{"t":"青阳度","f":"五言绝句","c":["堂前女萝草，缠绵依松柏。","虽怀千秋契，亮无齐年质。"]},{"t":"襄阳蹋铜鞮","f":"五言绝句","c":["重铠飞上马，桃花汗金铃。","儿是襄阳客，助汝下台城。"]},{"t":"采桑度 其一","f":"五言绝句","c":["东家乞蚕种，西家乞柔桑。","桑蚕尚未得，许欢制衣裳。"]},{"t":"采桑度 其二","f":"五言绝句","c":["使君停五马，不复顾蚕饥。","侬不食桑叶，那得腹中丝。"]},{"t":"翳乐","f":"五言绝句","c":["百淬扬州水，秦王照胆铜。","欢今心意变，不将持赠侬。"]},{"t":"那呵滩","f":"五言绝句","c":["郎来如上滩，五步三步留。","郎去如下滩，瞥疾不回头。"]},{"t":"采桑度 其三","f":"五言绝句","c":["侬归亦未久，欢去俄已远。","下水一尺深，上篙一尺短。"]},{"t":"夜黄","f":"五言绝句","c":["凤皇一双飞，百鸟尊为王。","侬今妆洗去，与欢助辉光。"]},{"t":"夜度娘","f":"五言绝句","c":["昏星送侬去，晨星送侬归。","窗前百种鸟，为谁不安栖。"]},{"t":"双行缠","f":"五言绝句","c":["两窝尖尖玉，秀出金莲花。","生憎寘地上，腕臂作交加。"]},{"t":"长松标","f":"五言绝句","c":["袅袅千尺藤，亭亭百尺松。","但令根株近，到顶作相逢。"]},{"t":"来罗 其一","f":"五言绝句","c":["并蒂青莲花，下覆双鸳鸯。","秋风昨夜来，那得似侬长。"]},{"t":"来罗 其二","f":"五言绝句","c":["步出西昌门，行经少年道。","所遇无故物，焉得不速老。"]},{"t":"白符鸠","f":"五言绝句","c":["酃酒银丝鲫，留欢不肯住。","鹊洲风浪起，欢今那得去。"]},{"t":"阿子曲","f":"五言古诗","c":["东家挽郎歌，西家嫁女哭。","郎作口头语，那得见衷曲，阿子汝闻否。"]},{"t":"孟珠","f":"五言绝句","c":["手种夭桃花，与欢同颜色。","花若解人意，那能不亲惜。"]},{"t":"黄鹊曲 其一","f":"五言绝句","c":["黄鹄摩天来，金衣菊为裳。","唼喋稻禾美，不复顾高翔。"]},{"t":"黄鹊曲 其二","f":"五言绝句","c":["黄鹄摩天来，不及青鸳鸯。","鸳鸯虽小鸟，出入定成双。"]},{"t":"娇女诗","f":"五言古诗","c":["两山东西峙，一水中间流。","上有双栖鸟，下有并泳鱼。","侬自羞见汝，抱影守寒庐。"]},{"t":"拔蒲","f":"五言绝句","c":["七尺水中蒲，下有三寸白。","语欢勿尽根，留为来年息。"]},{"t":"寿阳乐 其一","f":"古风","c":["可怜秦淮水，送郎舟，诅作向西流。"]},{"t":"寿阳乐 其二","f":"古风","c":["箧中辟寒金，制成钗，故试郎君怀。"]},{"t":"寿阳乐 其三","f":"古风","c":["泥金沙棠舫，候郎来，春水没篙长。"]},{"t":"寿阳乐 其四","f":"古风","c":["织成红半臂，化为碧，是侬相思泪。"]},{"t":"宿阿曲","f":"五言绝句","c":["玉帝投宝坛，上清为辟易。","高真辞牒去，收奏不遑食。"]},{"t":"安东平 其一","f":"古风","c":["荒鸡嚘喔，残月沈魄。","三三五五，小星不没。"]},{"t":"安东平 其二","f":"古风","c":["惭愧小星，导郎归程。","要郎指誓，莫负此星。"]},{"t":"安东平 其三","f":"古风","c":["吴丝越罗，制郎中裙。","曷不为衣，与郎体亲。"]},{"t":"安东平 其四","f":"古风","c":["报侬白玉，双龙连环。","但令一心，不在多端。"]},{"t":"安东平 其一","f":"古风","c":["孟冬十月，雨雪霏霏。","入门孤冷，出门沾衣。"]},{"t":"安东平 其二","f":"古风","c":["夹河为家，期至无船。","摇心失望，不见所欢。"]},{"t":"安东平 其三","f":"古风","c":["交南龙须，百钱一尺。","是我手制，与郎作席。"]},{"t":"安东平 其四","f":"古风","c":["奉郎坐卧，偕郎起息。","懊憹微躯，生不如席。"]},{"t":"安东平 其五","f":"古风","c":["博山沈烟，以祈上玄。","愿郎一夕，不愿百年。"]},{"t":"青骢白马","f":"七言古诗","c":["青骢白马汗连钱，来往䟤跋骄可怜。","琉璃紫鞍光射人，倏忽灭没化若神。","有足不作女行缠，那可局蹐守故园。","东邻双缠鸦头袜，生老不踏门前月。","马蹄烁电耳决风，何不遣置迎取侬。","娇娘逞娇不肯行，碧幰五步一步停。","娇娘到时不逞娇，银缸穗帷可怜宵。","唱著可怜令人慆，久唱人怜令人老。"]},{"t":"共戏乐 其一","f":"七言古诗","c":["玉烛濙濙调化机，日月寒暑生四时。"]},{"t":"共戏乐 其二","f":"七言古诗","c":["梁肉美酒合大宴，骨腾肉飞赴流湎。"]},{"t":"共戏乐 其三","f":"七言古诗","c":["扬袂顺风去若轻，徘徊顾盻若深情。"]},{"t":"共戏乐 其四","f":"七言古诗","c":["仙仙妙舞乐未央，陛下万寿民悦康。"]},{"t":"钜鹿公主歌 其一","f":"七言古诗","c":["七萌香车五华旆，黄犊遥遥出花外。"]},{"t":"钜鹿公主歌 其二","f":"七言古诗","c":["去如流飙不相待，馀芬吹尘帖裙带。"]},{"t":"钜鹿公主歌 其三","f":"七言古诗","c":["钜鹿公主殷郎妹，万乘玉体慎自爱。"]},{"t":"乌夜啼 其一","f":"五言绝句","c":["窗前白颈乌，双飞复双栖。","不知何懊恼，犹自恰恰啼。"]},{"t":"乌夜啼 其二","f":"五言绝句","c":["欢作马行客，妾歌乌夜啼。","妾啼端忆汝，乌啼今为谁。"]},{"t":"西乌夜飞","f":"五言绝句","c":["朴遫乌夜飞，去踏谁家树。","欢须无两翼，教住不肯住。"]},{"t":"女儿子 其一","f":"七言古诗","c":["猿啼一声发一变，不待出峡鬒如霰。"]},{"t":"女儿子 其二","f":"七言古诗","c":["上牢虽迟下牢险，玉箸分残女儿脸。"]},{"t":"子夜吴歌 其一","f":"五言古诗","c":["采桑长干陌，绿叶正毵毵。","远驻青骢马，相遗玳瑁簪。","不愁无语对，归恐误春蚕。"]},{"t":"子夜吴歌 其二","f":"五言古诗","c":["兰桡太湖曲，垂柳覆金堤。","香气时时发，歌声处处迷。","残妆汗欲尽，留著可怜眉。"]},{"t":"子夜吴歌 其三","f":"五言古诗","c":["姊妹欺相命，星前闭洞房。","携灯挑促织，罗袜下东廊。","明日争邀赌，钗头金凤皇。"]},{"t":"子夜吴歌 其四","f":"古风","c":["?毹依小阁，鹦鹉写流霞。","锦瑟卢家女，温香玉辟邪。","推窗见飘雪，惊道是杨花。"]},{"t":"子夜春歌","f":"五言绝句","c":["双枕不成起，单枕不成眠。","春风饶冷暖，吹作两种天。"]},{"t":"子夜夏歌","f":"五言绝句","c":["人言侬多憨，侬憨信非一。","不植春时花，要结夏时实。"]},{"t":"子夜秋歌","f":"五言绝句","c":["秋风击百卉，憔悴无光泽。","侬能破一笑，还侬春时色。"]},{"t":"子夜冬歌","f":"五言绝句","c":["漫天一夜雪，门前解消未。","憎侬去时迹，非关殢侬睡。"]},{"t":"子夜警歌","f":"五言绝句","c":["并蒂芙蓉枕，下压金鸳鸯。","教妾成独自，若个不成双。"]},{"t":"子夜变歌","f":"五言绝句","c":["长干月烂漫，是郎初变时。","莫谓无情黠，耐作有情痴。"]},{"t":"七日夜女歌","f":"五言绝句","c":["一夕当一年，一年千万年。","不那扶桑君，驱轮警我眠。"]},{"t":"长史变歌","f":"五言绝句","c":["莫呼侬作官，官今不得脱。","那能人上死，乍可草间活。"]},{"t":"黄竹歌","f":"五言绝句","c":["黄竹生来黄，不烦唤为碧。","与娘作笼具，共誇真金色。"]},{"t":"圣郎曲","f":"古风","c":["来亦不寂寂，去亦不匆匆。","曲盖飘婀娜，旌?结玲珑。","不烦宛姨导，知他两心通。"]},{"t":"白石郎曲","f":"古风","c":["白玉连环，与雪等色。","置郎腕中，不辨谁白。"]},{"t":"青溪小姑曲","f":"古风","c":["小姑出门，日射雨缭。","小姑归来，日抱虹腰。"]},{"t":"湖就姑曲","f":"五言古诗","c":["湖就赤山足，大姑芬于兰，次姑白于玉。"]},{"t":"姑恩曲","f":"五言绝句","c":["鹄雏二三月，毛羽如长离。","为感姑恩养，徬徨不忍飞。"]},{"t":"江陵曲","f":"五言绝句","c":["江陵城外地，处处青楼曲。","百钱一买醉，千钱一买宿。"]},{"t":"作蚕丝","f":"五言绝句","c":["别侬浴蚕日，忽作缲茧时。","侬不食桑叶，腹中那得丝。"]},{"t":"杨叛儿","f":"五言绝句","c":["六尺龙须席，尺二虎珀枕。","甲夜不见侬，丙夜不成寝。"]},{"t":"蹛林歌","f":"古风","c":["双行马，单白羽，蹛林祭天集诸部。","脯橐驼，卤騊駼，新秦家家买僮奴。"]},{"t":"自君之出矣","f":"五言绝句","c":["自君之出矣，不复吐嬿婉。","思君如车轮，腹中千回转。"]},{"t":"浮游花","f":"五言绝句","c":["侬作树头花，日日波上红。","欢作波上花，浮游无定踪。"]},{"t":"武溪深","f":"古风","c":["于嗟武溪，一何毒煎。","飞鸢站站，堕人马前。","畴能衔恩贪百年。"]},{"t":"登楼曲","f":"五言绝句","c":["登高欲穷趣，眺望反伤神。","方悟冶游子，无地不宜人。"]},{"t":"映江曲","f":"五言绝句","c":["杏脸杨柳眉，秋江映如觌。","那能映妾心，令君一察识。"]},{"t":"永明乐","f":"五言绝句","c":["玉烛调五夜，金轮驭八方。","合唱永明乐，嵩呼应神皇。"]},{"t":"春江行","f":"五言绝句","c":["春江浪拍天，两岸吐春烟。","中流一点黑，知是下江船。"]},{"t":"江皋曲","f":"五言绝句","c":["白浪接天高，黑风不断号。","赧郎轻舴艋，不敢向江皋。"]},{"t":"忧且吟","f":"五言绝句","c":["丝桐在秋色，秋色在丝桐。","一弹鬒已变，何烦奏曲终。"]},{"t":"树中草","f":"五言绝句","c":["共承雨露恩，俱作青袍色。","方朔与侏儒，根柢不相直。"]},{"t":"越城曲","f":"五言绝句","c":["秦望画中山，若耶镜中水。","十家九浣纱，为取苧萝女。"]},{"t":"从军五更转 其一","f":"五言绝句","c":["一更明月寒，歌舞帐中残。","酒为壮士胆，独骑斩楼兰。"]},{"t":"从军五更转 其二","f":"五言绝句","c":["二更刁斗鸣，却比捣衣轻。","南风好吹去，并作断肠声。"]},{"t":"从军五更转 其三","f":"五言绝句","c":["三更月未斜，凄切送胡笳。","天山无草木，空听落梅花。"]},{"t":"从军五更转 其四","f":"五言绝句","c":["四更山月昏，屈指旧从军。","白骨年年是，何人入玉门。"]},{"t":"从军五更转 其五","f":"五言绝句","c":["五更听乌啼，乌是汝南鸡。","闺中双玉箸，点点为辽西。"]},{"t":"采菱曲","f":"五言绝句","c":["蜻蛉刺水去，不复畏欹斜。","渠自爱菱角，侬自爱菱花。"]},{"t":"江南乐八首 其一","f":"五言绝句","c":["少小阊门住，不爱阊门道。","约伴礼社还，羞人道侬好。"]},{"t":"江南乐八首 其二","f":"五言绝句","c":["窗前樱桃树，累垂红靺鞨。","侬爱结子时，的应胜花发。"]},{"t":"江南乐八首 其三","f":"五言绝句","c":["与欢皋桥别，日日上皋桥。","不比西陵浦，唯看两度潮。"]},{"t":"江南乐八首 其四","f":"五言绝句","c":["妒杀宜城酒，夜夜将欢醉。","昨夜欢不来，翻怜醉时味。"]},{"t":"江南乐八首 其五","f":"五言绝句","c":["郎家流苏帐，对对玉蟠螭。","登车辞阿母，强作数行啼。"]},{"t":"江南乐八首 其六","f":"五言绝句","c":["闻欢夜中语，轻舟汎若耶。","兴阑须返棹，来泼雨前茶。"]},{"t":"江南乐八首 其七","f":"五言绝句","c":["东女日鸣机，西女日条桑。","侬今袖手坐，绡绮亦盈箱。"]},{"t":"江南乐八首 其八","f":"五言绝句","c":["芍药百种花，真红大难得。","侬家众姊妹，无侬好颜色。"]},{"t":"估客乐","f":"五言绝句","c":["醉后美人舞，落花江上席。","不是此地堪，何缘作估客。"]},{"t":"襄阳乐","f":"五言古诗","c":["大堤诸女郎，妆成出芳阁。","瞥见千树空，馀花乱飞落。","道是避妾妆，不信风雨恶。"]},{"t":"江南曲 其一","f":"五言古诗","c":["欢似吴江水，西去不通潮。","妾如独活草，无风长自摇。","安能对阊阖，暮暮复朝朝。"]},{"t":"江南曲 其二","f":"五言古诗","c":["庭前百合花，露冷烟脂赤。","对镜理新妆，羞他好颜色。","从此不簪花，恐欢心更易。"]},{"t":"江南曲 其三","f":"五言古诗","c":["杨花眠更起，飞向阿谁家。","曲槛青丝箔，雕鞍白鼻騧。","垆头无那醉，小妇摘琵琶。"]},{"t":"江南曲 其四","f":"五言古诗","c":["西湖水似油，袅袅采莲舟。","双鬟正十五，垂手玉葱柔。","罗带飘相近，风波可自由。"]},{"t":"乌栖曲 其一","f":"七言绝句","c":["碧烟作幮月作钩，双星荧荧对如眸。","天鸡叫昏日吹海，欢娱辞人不能待。"]},{"t":"乌栖曲 其二","f":"七言绝句","c":["城乌哑哑唤春曙，只解将啼诱郎去。","玉笼金索娇鹦哥，呼郎不来奈尔何。"]},{"t":"乌栖曲 其三","f":"七言绝句","c":["青纱羃䍦象牙毂，皎如柔冰浸温玉。","还君一掬鲛人珠，持将染衣茜不如。"]},{"t":"乌栖曲 其四","f":"七言绝句","c":["宁馨玉儿雪白马，丝鞭软垂不相舍。","妾家采菱东渡头，来往风水木兰舟。"]},{"t":"江南弄","f":"古风","c":["江南百花百般香。","江南少娃百样妆。","百端撩人百念狂。","百念狂，殊未已。","千欢尽，万恨起。"]},{"t":"龙笛曲","f":"古风","c":["苍龙啸波夜泬寥。","美人如云袂飘飖。","历乱纤玉启樱桃。","启樱桃，吹杨柳。","度关山，尽回首。"]},{"t":"凤笙曲","f":"古风","c":["瑞垆兽焙蜀锦床。","要眇倡凤复和皇。","馀音弥弥郁金梁。","郁金梁，宿流烟。","与女偕，逝缑山。"]},{"t":"后采莲曲","f":"古风","c":["密叶藏艇花迷妆。","中有清歌逐芬芳。","随风去来咽复扬。","咽复扬，雨缭起。","摘叶归，忘收子。"]},{"t":"采菱曲","f":"古风","c":["下裙鹅黄衫藕丝。","拨蔓纤指玉参差。","采菱倾筐露未晞。","露未晞，甘且芳。","折腰红，持赠郎。"]},{"t":"朝云曲","f":"古风","c":["巫云欲阑接朝日。","流辉斗艳无定质。","若恋如惊态非一。","态非一，境将残。","拟追寻，渺无端。"]},{"t":"秦筝曲","f":"古风","c":["咸阳少娃十三馀。","十三新弦莺不如。","商偏羽弱调乌乌。","调乌乌，和纂纂。","新欢长，旧欢短。"]},{"t":"赵瑟曲","f":"古风","c":["素女留弦清且悲。","谁其工者邯郸姬。","玫瑰贴柱黄金徽。","黄金徽，白玉管。","侬意长，欢意短。"]},{"t":"游女曲","f":"古风","c":["双蛾作眉鸦作髻。","睩波芙蓉近相媚。","不买新丰意先醉。","意先醉，可奈何。","千金舞，百金歌。"]},{"t":"阳春曲","f":"古风","c":["杨柳窣地万千丝。","金堤碧桃花吐荑。","攀条折花将遗谁。","将遗谁，心自了。","人耳多，黄耳少。"]},{"t":"莫愁乐","f":"五言绝句","c":["绕渡碧桃花，停鞭白鼻騧。","客程无暇问，先访莫愁家。"]},{"t":"秋日于鳞邢州郡斋分韵赋十二体","f":"古风","c":["白日来，凄以阴。","柅余车，将余衾。","觏倾国，申同心。","目流■，意荡淫。","酿高霞，弋遥岑。","鲙沧海，脯穷林。","饔者何，字兰金。","削峥嵘，缓萧森。","觞前跃，无停斟。","万木飞，变徵音。","洪涛走，北陆沈。","衷愲结，竟沾襟。"]},{"t":"卮语二首 其一","f":"古风","c":["贵为掾，三语荐。","贫为客，万言策。","饱欲死，长三尺。","饥欲死，东方朔。","厕中鼠，空仓雀。","卵有毛，马生角。","巧抱瓮，愚炙毂。","真渐离，假孙叔。","叶公龙，淳于鹄。","矢欲直，钩欲曲。","归去来，卧空谷。"]},{"t":"卮语二首 其二","f":"古风","c":["世间事，那有此。","齐国王，卒饿死。","沛亭长，作天子。","岁百战，垂千祀。","并六合，传二世。","厕中人，断君头。","堂下客，代君侯。","魏冉走，刚成入。","白起逝，安平出。","吕易嬴，政僇韦。","歇在楚，亦如之。","臣相君，窃其母。","君僇臣，弑其父。","人既工，天亦巧。","唶何为，日胶扰。"]},{"t":"黄河之诗 壬子南使至徐邳间事","f":"古风","c":["黄河南奔，疾风北来。","两重莫下，激而为灾。","万籁喧呼，三维震颓。","鹢首戒南，风斯忌而。","亦言戒北，河其厉而。","悠悠我心，曷既济之。","谁云利涉，不复改辙。","谁云走峻，不复理楫。","川平为陆，陆汇作泽。","芃芃禾黍，登之场圃。","下有守人，匿而左顾。","彼实自卫，曷不疑我。","虽有季昆，远不相援。","虽有雠敌，难思共存。","仰天长歌，涕泗汍澜。"]},{"t":"西山诗 其一 戊申冬以秩祀行作","f":"古风","c":["朝上西山，艰哉?崟。","溪谷多风，倏旸而阴。","胗䁾中肤，?慄缘音。","十步五步，不能见人。","牛马却走，熊罴号吟。","仆夫告痡，口舌屈噤。","修途无端，北陆遵沈。","道有鼷鼠，结穴何深。","忽而过我，杳不可寻。","菀菀好鸟，栖栖中林。","我独何为，伛偻不禁。","皇命秩祀，俾孔之钦。","肃肃卿相，咫尺尔临。","我躬不遑，简书是忱。","念思愲结，盻此高岑。"]},{"t":"西山诗 其二","f":"古风","c":["皇命卿士，尔往祗谒。","夙戒卒事，毕礼以发。","仰盻河汉，如近寝阙。","敛其狂飙，纵以明月。","绵绵连山，与月见没。","峨峨隧途，松柏郁杌。","茫茫平原，积气如渤。","巉巉冰岩，忽起飘鹘。","耳听骚屑，足蹑恍忽。","岂不遄返，悯此驭卒。"]},{"t":"戒诗 其一","f":"古风","c":["行逢宋人，狂且见妍。","虽有夷施，为谁朱颜。","南山之雾，可以隐斑。","埋照韬光，其乐闲闲。","浮云自逝，大化长还。","畏垒祀我，贤人之间。"]},{"t":"戒诗 其二","f":"古风","c":["黄帝肃驾，南游具茨。","襄城之野，七圣皆迷。","慰暋亡途，道逢小儿。","一语瞭彻，拜称天师。","岂必大隗，治其庶而。","足已不逊，他人之资。"]},{"t":"自青诗 其一","f":"古风","c":["赫赫始兴，绍晋维庸。","爰启家族，于江之东。","圭组蝉嫣，郁为大宗。","改社改邑，我祀无穷。"]},{"t":"自青诗 其二","f":"古风","c":["谔谔司谏，为帝喉舌。","棠彼晋陵，菟裘于越。","乃启闻孙，乃脂宦辙。","惟良吴会，以卜堂棁。"]},{"t":"自青诗 其三","f":"古风","c":["世益其滋，畀我皇祖。","厥秩伊何，贰卿司马。","恺悌君子，民之父母。","姻族闾里，是粥是乳。"]},{"t":"自青诗 其四","f":"古风","c":["遹发厥祥，严君奋扬。","绣绂皇皇，被汉及江。","如冬之日，如秋之霜。","作屏王畿，以承宠光。"]},{"t":"自青诗 其五","f":"古风","c":["唯余小子，甫离于蒙。","鸣鹿陪京，班鹓上宫。","曾是衮裳，而荐雕虫。","驿驿秋官，方迓聿从。"]},{"t":"自青诗 其六","f":"古风","c":["严君曰咨，毋女作敖。","毋旷女守，毋好是导。","毋恣狎侮，以贻余诮。","人亦有言，匪疢则药。"]},{"t":"自青诗 其七","f":"古风","c":["嗟予小子，胡言弗受。","般淫于咏，沈湎于酒。","惟我狂简，一二朋友。","亦既肆口，亦既濡首。"]},{"t":"自青诗 其八","f":"古风","c":["小道可观，致远则非。","从臾如流，狂张若驰。","嶭彼乔山，蹇拟陟之。","爚彼烈炎，徒思炙之。"]},{"t":"自青诗 其九","f":"古风","c":["高冠切云，长裾被趾。","联臂蹋足，遨于都市。","玄白惟心，雌黄在齿。","曲突将炎，燕雀恬止。"]},{"t":"自青诗 其十","f":"古风","c":["天觏闵凶，突如来如。","猃狁孔蕃，元戎用驱。","王锡未终，谁将竹书。","薮雉翩翩，凤离于罝。"]},{"t":"自青诗 其十一","f":"古风","c":["嗟嗟小子，越隔千里。","冠裳其燬，手足其胝。","号旻莫应，呼霜莫起。","人而得死，何所无死。"]},{"t":"自青诗 其十二","f":"古风","c":["嗟嗟小子，饮息覆盆。","白日未昭，畴为启昏。","宇宙虽广，胡颜自存。","咎衅实招，已矣何言。"]},{"t":"悯生篇","f":"古风","c":["上坐莫喧，下坐一言。","今者食荠，焉知我酸。","南山有柏，朝牂暮斤。","北山有柽，生而参天。","何以弹乌，请用随侯。","何以攻革，请用吴钩。","案鹓从禽，命豹逐鼠。","谓汝不捷，卒当僇汝。","迷阳升堂，国香道傍。","土杯在坫，玉卮汲浆。","嫫母挟瑟，夷施幽闭。","师涓教射，夔习击技。","磁石引金，阿锡禦冰。","扬舲太行，骋骏洞庭。","寄愁九天，渺旷无梯。","埋忧九渊，沈深无蹊。","千日之外，中山曷力。","百岁而往，司命奚德。","金丹在口，噤不能餐。","岂无永生，逝者实叹。"]},{"t":"寓怀 其一","f":"五言古诗","c":["大禹迷终北，黄帝游华胥。","化城高天表，古莽西南隅。","阴阳亡交气，民人恒晏愉。","乃知八极外，至乐故有馀。","沴戾堕中央，令我不可居。","阴谋相挡㧙，肉攫自纷拿。","冥心超形外，冀得恣所如。"]},{"t":"寓怀 其二","f":"五言古诗","c":["矫氏脉季梁，任治为众医。","泣者既不肖，歌者亦焉知。","王孙戒祼葬，其友遂因之。","庄氏等彭殇，达人守其规。","求化焉能化，齐物故不齐。","万类日樛纷，忘言将庶几。"]},{"t":"寓怀 其三","f":"五言古诗","c":["甲兵被天来，朝野无偃居。","思欲从园绮，筑坯商山庐。","优游终馀日，俯仰多所愉。","恒恐坤维拆，陵谷荡为墟。","展转不克谋，憣然悟微躯。","吾闻至人造，水火置若无。","浊酒且自浇，块然还太初。"]},{"t":"寓怀 其四","f":"五言古诗","c":["成季推郤縠，礼乐贵戎机。","范宣让伯游，汰者亦不违。","端揖堂皇上，彊楚辑衡雎。","六氏为三家，蚕食公室卑。","岂惟惭先节，晋德日言衰。"]},{"t":"寓怀 其五","f":"五言古诗","c":["神龙含夜光，千祀自无饥。","即且甘其带，栩栩来见嗤。","刘累气块结，上诉咸巫师。","大化偶万形，此妍彼宁媸。","两好各自固，焉在相是非。"]},{"t":"寓怀 其六","f":"五言古诗","c":["骊姬适晋侯，戎车啼妆湿。","入宫与君欢，匡床愧其泣。","才人邯郸艳，自誇倾城国。","朝陪君王荐，夕作厮养匹。","履荣仍讥贱，在约方念适。","焉知非梦幻，役役劳真则。"]},{"t":"寓怀 其七","f":"五言古诗","c":["左氏饰繁辞，乃在丧其明。","子长下蚕室，述史拟麟经。","毋论委质亏，所爱千秋名。","夸诩尺寸长，冀与大化争。","无趾笑仲尼，桎梏被天刑。","何况于二生，没齿徒营营。"]},{"t":"寓怀 其八","f":"五言古诗","c":["孔德岂不弘，匡人恨阳虎。","参孝亦以孚，曾母为投杼。","平原虚掩涕，毛生非溺者。","古有两秋胡，空惊茂陵女。","似是诚有端，偶来故无主。","君子修冥冥，毁誉安足数。"]},{"t":"寓怀 其九","f":"五言古诗","c":["彘王蔑周武，中兴振宣谟。","殷忧歌云汉，虽旱不告逋。","山甫实明哲，方召有良谟。","徐夷既宁只，猃狁亦奔徂。","人情戒其恒，勤思内自渝。","祈父怨爪牙，杜伯蹈淫诛。","遂令轮台诏，千古惜终初。"]},{"t":"寓怀 其十","f":"五言古诗","c":["秋风杀万物，春气滋群苗。","何如谢寒暑，不荣亦不凋。","老氏薄圣人，赏罚日哓哓。","天地为之端，生人安不浇。","寄情太始外，恬穆日逍遥。"]},{"t":"寓怀 其十一","f":"五言古诗","c":["大禹甘旨酒，愀然若有惩。","万机日坌至，焉能事尊罂。","陶公但湛饮，千载自休名。","贫贱足肆志，富贵长营营。","黼衮与布衣，交伸不可争。"]},{"t":"寓怀 其十二","f":"五言古诗","c":["昔有无支祈，佻负百夫力。","终古腥淮流，金锁时掣搦。","贰负杀窫窳，帝讨羁石室。","梏拲锢其形，千载郁如腊。","中祀无百年，滔滔恶焉极。","宣淫荡天纪，一死事以息。","怅然念休代，奸人易为贼。"]},{"t":"寓怀 其十三","f":"五言古诗","c":["皇王宪天则，广覆物不遗。","四门列九服，大开明堂基。","嬴帝吞六雄，扬兵震四垂。","炎武因遗迹，滇岭悉来归。","魋结袭冠簪，卉服改裳衣。","西琛并南赆，王会无后期。","善哉太史公，谓得圣人威。","竖儒守一经，安能知是非。"]},{"t":"寓怀 其十四","f":"五言古诗","c":["渥丹未离色，返服岂不早。","念此有尽年，徇彼无穷道。","角犊挂遗编，春原日游好。","紫云西北来，慨然商山皓。","为人作羽翼，短发何皓皓。","赤松骂留侯，钓奇污诸老。","处则为远志，出则为小草。"]},{"t":"寓怀 其十六","f":"五言古诗","c":["蜀有严夫子，渊博世无俦。","九州历其八，意者辞帝州。","五经亦以四，将无废春秋。","春秋不忍读，帝州不可游。","伐国且问谀，君子非所酬。","是以终岩穴，冥心蹈清幽。"]},{"t":"寓怀 其十七","f":"五言古诗","c":["四大偶然合，六尘遂缘生。","幻心从兹起，空华竟何形。","执幻既为幻，离幻亦无成。","积渐由奢靡，既得不可名。","万动顺其轨，杳然空中澄。","定静与寂感，吾闻之孔经。"]},{"t":"寓怀 其十八","f":"五言古诗","c":["卫人迎妇人，上车戒笞马。","至门教送母，灭灶将失火。","入室见臼曰，徙牖妨来者。","此岂非所言，于时未为可。","荆棘横周道，雷霆纷来下。","硁硁小人哉，君子言不果。"]},{"t":"寓怀 其十九","f":"五言古诗","c":["严仲怨韩相，避之轵深里。","顾盻屠酤间，聂生为知己。","百金何当道，片言杀心起。","老母既以归，为君报睚眦。","阑入白刃林，瞥然刺侠累。","皮面不可迹，欲以存其姊。","人间捐生士，殉名安足齿。"]},{"t":"寓怀 其二十","f":"五言古诗","c":["■力见距山，浑夕出肥遗。","軨軨娱空桑，鹿台啸凫徯。","念欲耕沃沮，妖氛缠四维。","回首盼天阍，沈深叩无期。","相柳食九州，膏血瀰川坻。","巫咸不能招，伥伥焉所归。"]},{"t":"寓怀 其二十一","f":"五言古诗","c":["步出城西门，踟蹰中不夷。","道逢一仙长，自称广成师。","授我一丸药，令我杜德机。","揽镜朱颜凋，隤然废威仪。","禽游无惊翼，兽逐鲜辟蹄。","良玉岂不珍，在璞全光辉。","惜哉和氏子，三刖乃其宜。"]},{"t":"寓怀 其二十二","f":"五言古诗","c":["西方有圣人，自然坐莲花。","跏趺黄金相，下照千恒沙。","庄严先帝释，纷诡诸罗叉。","种种明心地，安在斗毗夸。","奈何浮屠教，土木被诸华。","求因还生障，积幻遂成魔。","智士达其根，愚者将奈何。"]},{"t":"寓怀 其二十三","f":"五言古诗","c":["杨朱嗟旅人，二妇不相当。","美好由心造，贵贱亦何常。","屈平避上官，楚材湛沅湘。","李牧中郭开，赵氏血纵横。","俯念千秋感，畴能竟其方。","揖莸登兰席，虽尊故不芳。","投璧陨磻阶，虽碎不移光。"]},{"t":"寓怀 其二十四","f":"五言古诗","c":["衰周渝王纪，战伐浩相寻。","兵戈无宁绪，诗书故不任。","贾竖亦钓奇，王孙折豪心。","片言双白璧，一字千黄金。","虽非吐哺节，收名良已深。","挟瑟华阳宫，朱门日沈沈。","所以蓬蒿士，宁为抱膝吟。"]},{"t":"寓怀 其二十五","f":"五言古诗","c":["春秋宁无战，国辞良已修。","获主称下臣，伏剑不相尤。","虽靡赓歌代，优然见文柔。","冯轼观士戏，无礼为君羞。","况乃杯酒间，语笑皆戈矛。"]},{"t":"寓怀 其二十六","f":"五言古诗","c":["老父哀龚生，天年胡轻掷。","孙登诮中散，不能含龙德。","被裘舍遗金，恶在留其迹。","生名为杀身，君平悟真易。","二士岂不显，四贤胎余则。","知白而守黑，乃为天下式。"]},{"t":"寓怀 其二十七","f":"五言古诗","c":["越石豪贵姿，贾氏为密亲。","苟无晋阳操，若濡意何伸。","深源苍生望，何如渭川滨。","高卧不克全，北伐丧其真。","慎始固所贵，薄终不足陈。","狐兔当衢跃，豺虎争齧人。","七尺犹未掩，是非遽难论。"]},{"t":"寓怀 其二十八","f":"五言古诗","c":["赤水三珠树，横条贯中天。","金气何陆离，窃窥太乙躔。","执法不能纠，紫微竟何言。","下土虮虱臣，中夜心茫然。","岂无弯弓志，腕弱意何宣。","矫首太阳升，胡为向虞渊。"]},{"t":"寓怀 其二十九","f":"五言古诗","c":["在天恶疾风，飘飖无定期。","一决土囊口，迭宕不支持。","强排浮云出，又复拘阂之。","吹沙荡青冥，日月改光辉。","波涛甘湛溺，借汝发其私。","此物何足论，但恐伤天威。"]},{"t":"寓怀 其三十","f":"五言古诗","c":["吾闻共工氏，力欲吞九州。","馀愤竟何伸，举首触不周。","天为西北摧，地为东南浮。","万姓弃嬴秦，项籍首相雠。","白骨填函谷，濉水血不流。","虽无君人业，千载起雄谋。","战伐浩无终，吾生已马休。"]},{"t":"杂诗九首 其一","f":"五言古诗","c":["季夏薄火旻，出游汗徒御。","浮云迥生惨，凛然被霜露。","戈甲满道周，行留泣相顾。","匈奴为我雠，安能罢遣戍。","往甘三时逸，今征匪秋莫。","死地身独任，焉用亲与故。","壮恐当军锋，弱恐弃中路。","西邻贾人子，一充嫖姚部。","黄金橐驼装，貤封及千户。","瀚海天如赭，彼人曾何睹。"]},{"t":"杂诗九首 其二","f":"五言古诗","c":["日予追祸遘，往者祅氛逼。","时平无二人，难起有群策。","英英赵司成，抗节砺金石。","庭陛秋风生，飒然万象辟。","徐卿探乱源，杨子杜机逆。","将相伊吕俦，皇仁示微责。","大泽丧明珠，茫茫不可得。","斯物返其真，吾徒斗间色。"]},{"t":"杂诗九首 其三","f":"五言古诗","c":["甲兵举世隘，贫贱百年轻。","扰扰时人意，焉知肝胆诚。","吾贵中心悦，何用等浮名。","泽云固易变，溟渤亦可耕。","道苟后三光，岂在凋其形。"]},{"t":"杂诗九首 其四","f":"五言古诗","c":["客从东方来，车马何偪侧。","昔者魏其里，今趋武安宅。","武安高楼台，皇皇径百尺。","欢宴迷暮旦，黄金为上客。","魏其里中人，相与歌恻恻。","以此去时路，等彼来时迹。"]},{"t":"杂诗九首 其五","f":"五言古诗","c":["盈盈青闺女，皎皎明朱颜。","迥步惜流影，履綦戒前轩。","自爱鸾凤音，不闻中堂言。","君王下长秋，掖廷或见填。","既忧入宫妒，复愧黄金妍。","生业本田桑，昏旦劳所安。","毁艳以自秘，羞同狭邪传。"]},{"t":"杂诗九首 其七","f":"五言古诗","c":["公子敬好客，高义薄秋旻。","前堂罗钟鼓，后厨击肥新。","千金一言寿，琐琐何足云。","中夜杀声起，鸟兽东西奔。","四顾皆荆棘，安见堂中宾。","竭力前卫营，乃是爨下人。","公子追自咎，气结不能陈。","恩施岂不广，各自顾其身。","平生国士言，是非难等伦。"]},{"t":"杂诗九首 其八","f":"五言古诗","c":["步出城西门，雕甍横周络。","业篁上迫天，菱藕弥陂泽。","问是谁家墅，居人答相错。","春卉依都尉，秋条属金吾。","问姓良欲陈，后主恐复殊。","所遇多故物，百岁人焉俱。","贫富生丑好，来往为亲疏。","茫茫任宇宙，何用竟其初。"]},{"t":"杂诗九首 其九","f":"五言古诗","c":["如姬奉王寝，公子得兵符。","君恩岂不深，各报徇所图。","秦王幸赵倡，子政乃托躯。","谓为嬴秦祀，千载永欢娱。","子政自有父，赵倡自有夫。","将心向他人，垂死心未孤。","冥冥移社稷，雠敌安得如。","微衷亮何叩，恻怆以长吁。"]},{"t":"偶成","f":"五言古诗","c":["白日未易归，悄步庭中间。","蝉鸣高树枝，鸣声一何閒。","何知金飔袭，微质坐来捐。","世末竟难期，焉在誇少年。","亮无根株固，误使百忧煎。"]},{"t":"秋日感怀","f":"五言古诗","c":["孟秋辞残暑，稍稍澄露晞。","飞沙来填穴，玄鸟逝安归。","行人筹往路，还理箧中衣。","夜永尚易晨，白日渐如驰。","不惜流光逝，所惜来者非。","玄蝉虽徵响，哀思竟陈谁。","失志在饥寒，饱暖不可挥。"]},{"t":"杂诗 其一","f":"五言古诗","c":["东家有美人，日日理红颜。","春风爱如花，玉立当门前。","西家有美人，曲局不成鬋。","觕衣蔽韶质，深闺闲茂年。","荡子乐行游，共誇东家妍。","愿君弃所知，愿君重所捐。"]},{"t":"杂诗 其二","f":"五言古诗","c":["庭前有丹桂，西风吹落花。","贵者集裀幕，贱者泥与沙。","泥沙安足悲，裀幕安可誇。","既离本枝固，焉能念芬华。","毋为计荣辱，恻恻长自嗟。"]},{"t":"杂诗 其三","f":"五言古诗","c":["吾闻上古世，纯默澹玄始。","太和渐以散，皇纲荡无纪。","皓皓白日内，昏风忽然起。","生人无常遘，致福岂在已。","马以一鸣斥，凫以不鸣死。","生者岂必鸣，鸣者岂不生。","所以贤达人，顺时复安贞。","嗟彼倏与忽，无乃营神形。"]},{"t":"杂诗六首 其一","f":"五言古诗","c":["开卷意不怿，躧步临清池。","好风从东来，披拂中所宜。","群植欣向荣，谁能安后时。","踟蹰将西暝，稍稍见清辉。","明月虽投怀，不鉴中所悲。","非因一尊酒，畴为蔽余思。"]},{"t":"杂诗六首 其二","f":"五言古诗","c":["萋萋谷中兰，素质何葳蕤。","仰不睹天日，敢望雨露滋。","虽或微芬发，寂寞聊自知。","萧艾升君堂，左右争光辉。","与子固殊途，安用迫相疑。"]},{"t":"杂诗六首 其三","f":"五言古诗","c":["谡谡庭际松，一生恒孤植。","幸以斤斧馀，风霜时摧击。","亮无栋梁具，又乏桃李色。","安能媚春阳，为人事雕饰。","去去勿复言，敛分终山泽。"]},{"t":"杂诗六首 其四","f":"五言古诗","c":["班姬奉增成，衔理甘曲局。","宁知迫岁晏，商飙粟寒玉。","李平一侍儿，咳唾黄金屋。","朝矜赐膏沐，夕矜荐丝竹。","勿谗纨扇歌，此歌本当哭。"]},{"t":"杂诗六首 其五","f":"五言古诗","c":["山鸡具五色，毛尾长离蓰。","顾影殊沾沾，凤皇当如斯。","不独时世人，娄朱亦见欺。","栖栖檐际凫，颈秃爪距卑。","稻粱不时沾，鼎俎偶见遗。","寄声于凤皇，何忍亦何疑。"]},{"t":"杂诗六首 其六","f":"五言古诗","c":["采薇吴山阿，行行日将夕。","道逢羽衣子，授我药五色。","谓我当服之，与天无终极。","生趣久已沦，安能淹兹域。","饰申以待归，留者翻为客。","顾叹此寸心，千载谁当白。"]},{"t":"读史有感十二首 其一","f":"五言古诗","c":["汉武箠八荒，中原亦云蒿。","神鲛甘鼎腥，天马以游遨。","归来大受计，柏梁造天高。","赫哉轮台言，黔首息讴谣。","肝腑授亲臣，八柄唯所操。","钩戟化为耝，大农自称饶。","薄海颂明哲，宁知贤者劳。"]},{"t":"读史有感十二首 其二","f":"五言古诗","c":["子长负奇气，少多贤豪游。","堕身蚕室间，戢影旃孟俦。","推毂岂不廑，惧为君子羞。","彊戚䘍东都，帷幨运奇猷。","金章耀左貂，济济十九侯。","黄屋日以卑，炎烬掷洪流。","唶哉履霜叹，千载有遗忧。"]},{"t":"读史有感十二首 其三","f":"五言古诗","c":["秦王睨萯阳，怒若彪虎哮。","尸者二十七，末乃卿茅焦。","砺齿肉六雄，分甘先尉缭。","如何云阳狱，王孙中郁陶。","千古感说难，逆鳞不可调。","所以商山客，翛焉托渔樵。"]},{"t":"读史有感十二首 其四","f":"五言古诗","c":["长卿赋上林，将以明得意。","及乎谏猎书，凛然垂堂示。","驰骋私所便，能无忽神器。","众知乘船危，污轮诤何厉。","为谢张大夫，晓人当如是。"]},{"t":"读史有感十二首 其五","f":"五言古诗","c":["白发四老人，汉皇不能致。","羽翼功既成，飘然归地肺。","留侯虽强食，未闻更延世。","萧傅辞旧恩，怅然仇廷尉。","矫首前二疏，冥冥在天裔。","寄言风云者，倘来安足恃。"]},{"t":"读史有感十二首 其六","f":"五言古诗","c":["文帝繇代来，王臣尽朱邸。","不闻昌武辈，遂与绛灌齿。","椎朴据细旃，节啬贻来轨。","洛阳一少年，志欲扬汉美。","毋使元气漓，长者意乃尔。"]},{"t":"读史有感十二首 其七","f":"五言古诗","c":["不韦泣酖杯，业为钓奇误。","橐中千黄金，易君十万户。","李斯泣五刑，实以仓鼠故。","不见三川守，车马辉衢路。","巧尽拙自来，利往名独污。","所以西山客，居然一环堵。"]},{"t":"读史有感十二首 其八","f":"五言古诗","c":["昨者饮魏其，今来客田鼢。","朝事卫长平，夕从霍冠军。","矫矫任与灌，用志乃不分。","何如一岁星，濩落金马门。","醉来据地歌，去就两无闻。"]},{"t":"读史有感十二首 其九","f":"五言古诗","c":["汉魏世云季，王纲日下挠。","入则领尚书，出则揆百寮。","阴晴薄太阳，曀霭为不消。","喜怒变斯须，威福惟所操。","魑魅窃天权，雷霆废其曹。","大易戒履霜，为渐非一朝。"]},{"t":"读史有感十二首 其十","f":"五言古诗","c":["武帝掊阴山，失得与之均。","二李竟不归，汉骨委边尘。","及乎元成世，呼韩乃来宾。","舍馆葡萄宫，奉表称外臣。","彼运偶成衰，上策岂必臻。","所以外宁惧，腼焉思圣人。"]},{"t":"读史有感十二首 其十一","f":"五言古诗","c":["平陵朱阿游，请剑诛佞臣。","天怒再为折，殿槛不复新。","优游平津邸，笑谓薛赣君。","小生欲相吏，而我岂其人。","所效苟不雠，遂掷国士身。","是以达节者，千秋恒自伸。"]},{"t":"读史有感十二首 其十二","f":"五言古诗","c":["淳于挟帝私，公卿富交游。","婉㜻谁最亲，丞相高陵侯。","一旦淳于败，丞相荷帝留。","白简二十人，往往中所雠。","洎乎应大灾，君宠外虚优。","累累北邙上，恩怨同一丘。","千载读其书，令人慕巢由。"]},{"t":"拟古七十首 其一 李都尉陵从军","f":"五言古诗","c":["黄云被原野，策马欲何之。","鼙鼓劲前林，招摇动旌旗。","涕泪结为冰，婵媛将告谁。","长当生死诀，尽我酒一卮。","白露尚为霜，安能鬒不移。","惟有金与石，庶以表心期。"]},{"t":"拟古七十首 其二 苏属国武别友","f":"五言古诗","c":["驱车出郭门，北风何惨悽。","良朋相追饯，行李且光辉。","浮云为我停，晨风为我啼。","四牡既骙骙，御者安肯迟。","弹琴写情素，柱促令弦移。","泠泠流泉水，助我弦声悲。","何以将远别，杨柳吐青枝。","行人插枝去，往往自成围。","少壮若流飙，逝者不复归。","常闻忠与信，蛮貊可由之。","及时各努力，王路正清夷。"]},{"t":"拟古七十首 其三 班婕妤咏扇","f":"五言古诗","c":["妾有冰纨扇，云是齐宫作。","得尚君王手，扬飙芙蓉阁。","秋气忽见憎，冰簟同零落。","卷舒夙所易，衔分栖中箔。","物候代相迁，君恩终不薄。","敢以南薰至，逆笑狐与貉。"]},{"t":"拟古七十首 其四 孔北海融述志","f":"五言古诗","c":["栖栖岐山穴，避狄如走兔。","扰扰历下田，鹿豕朝与暮。","时至偶有为，人功竟焉数。","虞帝小鳏夫，虚名攘唐祚。","西伯老秃翁，脱身美人赂。","百兽岂自来，凤皇人谁睹。","垂死窜苍梧，荐禹如有负。","戎马践幽王，实以妖女故。","大运等循环，智巧安能度。","十读九废书，千秋荣朝露。","寄声谢时达，毋为圣贤误。"]},{"t":"拟古七十首 其五 郦徵士炎见志","f":"五言古诗","c":["势屈难见功，时危易为迹。","大海无圉鳞，高风有矫翼。","靳此万里抟，聊余一偃息。","清时奇遘隐，材士多失职。","小者州邑掾，大则公府辟。","卑颜窃升斗，揽袂承书檄。","寥矣帝者居，永绝渭川迹。","吹箫夕拜相，屠狗朝开国。","顾谓贾少年，兴文何太迫。","诗书一长物，礼乐终奚益。","圣主正当阳，群工但胁息。","富贵垂昌裔，名声施无极。"]},{"t":"拟古七十首 其六 魏太子丕公宴","f":"五言古诗","c":["置酒临西园，澄夜佐微凉。","华盖飘圆月，列宿散陂塘。","景风媚芙渠，冉冉布奇芳。","清吹相间发，惊鸟顾我翔。","急节促飞觞，为乐浩无方。","俄俄众宾举，相与歌太康。","芙渠自有芬，君子自有心。","良辰不重得，命爵莫沉吟。"]},{"t":"拟古七十首 其七 陈思王植赠友","f":"五言古诗","c":["成周宏昌业，多士乃日新。","远者由耕钓，迩则介弟亲。","赫赫我皇魏，九有悉来宾。","庸蜀为逋薮，江介有逆鳞。","圣心输纳隍，黄钺下秋旻。","楼船弥东渚，剑客出西秦。","天网布中逵，所希在凤麟。","畴为百金士，吾友气如云。","太阿拂朝霜，繁弱抱宵轮。","挥眸无前敌，抗志在必臻。","伊余忝藩翰，夙昔备宗臣。","同欢岐忧戚，厚禄豢其身。","狐白足禦寒，片腋非所珍。","铅刀望一割，微颖不见伸。","勇士思丧元，舍生乃成仁。","怀君笃明义，聊以示殷勤。"]},{"t":"拟古七十首 其八 刘文学桢陪宴","f":"五言古诗","c":["公子富令德，穷乐在清时。","卜昼启初筵，丙夜犹未疲。","丛篁夹文馆，碧萼缀丹梯。","潜月青林端，万颖射金池。","澄露滴华桐，薰风穆然吹。","炮炙参差进，觞醴纵横飞。","伎士慕新端，肉奋丝竹驰。","渊鳞中踊跃，宿鸟无宁枝。","冉冉东方曙，欢唱掩鸣鸡。","冠盖散交衢，粉泽有馀施。","畸客誇殊遇，叹息不可追。"]},{"t":"拟古七十首 其九 应文学玚侍集","f":"五言古诗","c":["乌鹊东北来，尾秃毛不全。","得与凤皇游，珍禽日周还。","今夕何良夕，公子开妙筵。","请宽童羖罚，听我醉后言。","少小事任侠，结束过邯郸。","邯郸有奇女，美盻辅朱颜。","一弹离鸾调，再弹别鹤弦。","感君缠绵意，千金坐来捐。","盟用南山石，好用蕙与兰。","兰芳有时歇，南山幸勿刊。"]},{"t":"拟古七十首 其十 王侍中粲怀德","f":"五言古诗","c":["炎德中崩溃，妖师乱天纲。","蛮荆非吾土，窜身不及详。","日月东西匿，雨雪正雱雱。","忾叹念周京，咨洟浩纵横。","桓桓今上宰，膺惩震八荒。","解我南冠绁，寘我侍从行。","譬彼粪上英，洗濯荐华堂。","公子推明爱，欢燕结不忘。","白云流尊觯，繟纚应朝阳。","万舞煜中庭，蛾眉吹素商。","常闻既醉诗，饮德厌膏粱。","摩顶皆君赐，何以报恩光。","窃希吉甫颂，清风播无疆。"]},{"t":"拟古七十首 其十一 阮步兵籍咏怀","f":"五言古诗","c":["昔我游蓬池，上有古时台。","长啸入青冥，万籁参差回。","返顾大梁城，棂扉相对开。","马头旦騀駊，日莫争飞埃。","汉尸既雍雎，项血复殷垓。","天地无精色，日月久徘徊。","唉汝二竖子，何如酒一杯。"]},{"t":"拟古七十首 其十二 嵇中散康言志","f":"五言古诗","c":["扰扰两象间，生人各自为。","余本田野夫，少小无远志。","圭组岂不华，好者方为贵。","习性偶成懒，敖乃非余意。","窃窥庄氏言，颇怀养生计。","忤外非有干，撄心乃足累。","结茆流水曲，绿槐信所植。","冶锻清阴下，弹琴衡门内。","仰见孤飞鸿，寥唳出天裔。","阮公青云度，浊酒幸与契。","山生何为者，嬲我殊不寘。","蜗庐欲枯壁，蛮触争何地。","翛然龙门色，顿忘寰中事。"]},{"t":"拟古七十首 其十三 应侍中璩百一","f":"五言古诗","c":["羲魄尚高舂，天命未我离。","云何纨裤子，往往意为师。","阿阁连曲房，沈深不可窥。","齐醴腐其肠，伐性有蛾眉。","姬姜奏新声，欢多乐不支。","药石为仇雠，美疢日以滋。","东岱添新籍，鬼伯来见追。","仰与高堂别，俯与亲爱辞。","宗祀日萧条，涕泪如绠縻。","人生非金石，快意多伏悲。"]},{"t":"拟古七十首 其十四 繁主簿钦咏蕙","f":"五言古诗","c":["娟娟孤生蕙，托根湘山厓。","上压千仞峰，下临万仞溪。","微质殊众卉，谓为造化私。","风霜相凌迫，雨露不见滋。","朔气旦夕深，清芬坐来移。","幸登君子堂，不足配芳徽。","仰惭桧与柏，青青长不衰。","俯愧东原草，犹得奉春时。"]},{"t":"拟古七十首 其十五 张司空华离情","f":"五言古诗","c":["飘风吹枯树，皎月鉴空墀。","曾是风不留，娟娟伫遐思。","飘若荡子心，皎如静女仪。","鸣琴中成瑟，哀弦来间之。","蜩螗乘秋沸，熠耀与暑辞。","苔藓历冬春，悠然骄履綦。","攒念乃攻中，徵瘁在蛾眉。","青阳何方至，桃李嫁路岐。","寄声松与柏，敛分守山崖。"]},{"t":"拟古七十首 其十六 何司空劭赠贻","f":"五言古诗","c":["宛洛何洋洋，经始先人庐。","崇巘夹脩篁，清波出文鱼。","栖遁焉足陈，仁里私有馀。","张侯负渊博，秉志乃冲虚。","出则寄干城，入则宏庙谟。","决胜开冀封，翛然良若无。","多惧昔忝均，耦耕亦今愉。","侯其谢鞅掌，就我暂为娱。","命爵复弹琴，徜徉非一途。","况有春阳色，蔼蔼在桑榆。"]},{"t":"拟古七十首 其十七 张黄门协苦雨","f":"五言古诗","c":["昏月初离毕，丹霞复荣朝。","女风扶轮毂，雌霓振旌旓。","杳杳七曜潜，沈沈二仪交。","穴蚁登嵬垤，水鹳徙故巢。","土社归狼籍，木偶竟飘飖。","立壁俱就颓，曲突黔以消。","密液肆沾飞，馀菑及蟏蛸。","九徙不足叹，百念徒尔劭。","念彼耦耕士，栖亩败禾苗。","念彼行旅夫，然桂中夕劳。","东征缺斧斨，北禦解筋胶。","眇矣发棠叹，弥哉塞瓠谣。","厌见沈蛙灶，妻子吐长嘲。"]},{"t":"拟古七十首 其十八 左记室思咏史","f":"五言古诗","c":["尧舜相为贵，不能屈巢由。","挂瓢箕山树，洗耳渭水流。","四岳等朝荣，二女亦蜉蝣。","黄绮卧商岩，目若无嬴刘。","烨烨五色芝，可以饱千秋。","如何崦嵫路，俛首建成侯。","神龙虽自尊，饥则鳅缮流。","寒蝉虽自眇，耻与鸟雀谋。"]},{"t":"拟古七十首 其十九 潘黄门岳述哀","f":"五言古诗","c":["忽忽寒将徂，冉冉春欲至。","寒徂复留恋，春至胡濡滞。","庭除无双迹，帷枕有孤涕。","犹残流黄机，上绣鸳鸟翅。","微音长辞听，手泽时流视。","行云仍恍忽，明月但髣髴。","恨彼伺晨鸟，精爽惊梦寐。","白日阙冥车，子来既不易。","黄泉稀生轨，予往将安至。","踯躅墟墓间，纵横窜狐魅。","宰木渐以拱，朽骨焉所恃。","余发既种种，时来能无会。"]},{"t":"拟古七十首 其二十 陆平原机羁宦","f":"五言古诗","c":["屯时播明社，厄遘点华宗。","逝以丘园贲，豫此拙薄悰。","阳春冠天来，松菌遂不终。","弓旌荷崇招，朱绂被微躬。","击楫指洪河，回首盼大江。","衔恩轻密戚，改谊诀故邦。","缪通承华籍，得托黄绮踪。","月请虽云薄，优游侍青宫。","献纳百未酬，敢希疏傅风。","衡门依清苑，日夕见嵩邙。","数往今诚乖，抚物己未工。","徵歌时自写，慨焉眷飞鸿。"]},{"t":"拟古七十首 其二十一 曹司马摅感旧","f":"五言古诗","c":["客与荣贵去，身将贱辱存。","昨日翟公罗，今张窦侯门。","中厨出旨酒，不足奉罍尊。","酒味非中薄，人情自寒温。","女萝与松柏，本自非一根。","松柏虽枯死，女萝尚攀援。","行人为代恨，不与盘石婚。","大火发昆冈，炎炎竟何论。"]},{"t":"拟古七十首 其二十二 傅司隶咸杂感","f":"五言古诗","c":["红女恋一机，丈夫慕九州。","拂袖出门去，妻子不足留。","二室造帝基，黄河喷天流。","一览意无馀，西入咸阳游。","咸阳帝子里，车马若云浮。","炊金复馔玉，赵瑟间齐讴。","东家霍司马，西邸平津侯。","南邻外人馆，北户文成楼。","鸡鸣先朝日，起者何所求。","试言平生业，十举九不酬。","北风旦夕吹，敝我黑貂裘。","低回返乡井，耕钓亦悠悠。"]},{"t":"拟古七十首 其二十三 陆司马云赠妇","f":"五言古诗","c":["春卉畏秋序，冬秀虞炎德。","亭亭南山柏，上敷芙蓉的。","凌风表贞操，承阳饶艳色。","眷怀结缡始，言在三星夕。","燕婉吐芳唇，绸缪展清臆。","靡靡辅属体，荧荧光汎席。","弧矢为我雠，车轮倘相迫。","明誓虽在今，合并非夙昔。","矫若分飞鸟，乖离恨羽翼。","何以示遥悰，托此花与柏。"]},{"t":"拟古七十首 其二十四 刘司空琨伤乱","f":"五言古诗","c":["虽云大厦颠，一木不能当。","在昔有靡氏，孤旅兴少康。","避狄奔岐下，周鼎日隆昌。","桓桓仲山甫，车攻佐宣王。","巨君挟狙诈，炎汉郁销亡。","九有尽为新，片烬起昆冈。","兴废固无端，贤者自有常。","天柱中崩绝，妖牝操皇纲。","鲁卫相鱼肉，聪勒噬边疆。","自余与祖生，束发共徊翔。","慷慨动鸣鸡，寒霜溢干将。","天意与我违，边尘飞晋阳。","干戈迫跬武，穹庐被川梁。","俨若笼中翼，欲飞触四旁。","岂不念昔贤，何以趾遗芳。","大海呷鲸波，一苇思自航。","悴柏束颠崖，陵苕摧素商。","存为七尺辱，没为千载伤。"]},{"t":"拟古七十首 其二十五 卢郎中谌感交","f":"五言古诗","c":["粳稻吐孤颖，狐貉献微腋。","岂不念饥寒，焉足充衣食。","顾此下中士，得陪虚左席。","投漆不违胶，援萝长附柏。","边尘冠天来，幽晋纷荡坼。","惭非千金璞，谬以连城易。","揆负故主恩，聊探昔贤迹。","程婴挟秘筴，赵宗复血食。","豫让秉贞信，辱身三不恤。","仓卒脱秦关，实繇鸣鸡力。","从容复齐相，乃是求鱼客。","衔报诚疚心，逢遘方显迹。","山川回东首，芊眠白云隔。","三复绕指言，忧来填胸臆。"]},{"t":"拟古七十首 其二十六 郭弘农璞游仙","f":"五言古诗","c":["东海焉可耕，衡庐不足家。","常闻金天女，漱液若木华。","高掌郁千寻，上有青莲花。","拍手呼鸾鸿，竦身凌紫霞。","子晋相绍介，洪崖御我车。","朱唇粲贝齿，永愿托姻娅。","碧藕吐瑶丝，火枣纷如瓜。","玉盎澄天酒，龙虎卫灵砂。","欢乐光景驶，千岁未为遐。"]},{"t":"拟古七十首 其二十七 孙廷评楚杂述","f":"五言古诗","c":["北风无停吹，玄发日夜素。","命驾遵虞渊，将适万里路。","亲朋来张祖，妻子挽悲慕。","大造本无知，安能随物铸。","精气偶然合，妄形为吾锢。","善恶既强名，祸福亦虚度。","东邻治彭老，服炼金石固。","西邻师蒙庄，谓等陵苕露。","达者竟何言，冥心黜两慕。","时至亦不辞，未来无烦虑。","寄谢醯鸡子，区区瓮中度。"]},{"t":"拟古七十首 其二十八 许徵君询自叙","f":"五言古诗","c":["方朔明大隐，君平探幽蹈。","去矣无足差，吾将从所好。","春理霅上耕，秋归剡中钓。","在物多饶境，选隙时一造。","丹霞挟回浆，白云装行屩。","奔险吐葱綪，芊眠含叫窱。","何以明有获，听然动微笑。","徇物非余术，资身良已要。","岂不爱微名，空谷将谁耀。"]},{"t":"拟古七十首 其二十九 谢仆射混游览","f":"五言古诗","c":["顾此有尽日，慨焉生游思。","讯谍纷委驰，解者应自寄。","清池届丛薄，沿洄信疲驷。","层观景风返，乔陵紫云憩。","跳波悦文鳞，回阳暖栖翅。","黄菊何棻蕤，萧条得其意。","时序非良适，取足竟有会。","寤叹言故欢，幽芳徒延迟。","彼境如可欣，合并安所事。"]},{"t":"拟古七十首 其三十 殷东阳仲文兴瞩","f":"五言古诗","c":["群秀方谢朱，忽与玄冥迫。","萧条在时寓，达者亦有适。","木落鲜滞欢，枫留蕴明色。","敛汎澄天根，回滋收地脉。","辽空吐纤翳，青崖间微滴。","兴至不尽觞，毋乃佳时掷。","况我英公子，肃徒罗周席。","密坐人起端，遴欢任所择。","纾华起物胜，用壮缘酒德。","窃冀燕然勋，敬为閟馀墨。"]},{"t":"拟古七十首 其三十一 谢仆射瞻秋饯","f":"五言古诗","c":["少皞承时柄，赤帝握天权。","清商应嘉节，飞眺俯中原。","群象俱投肃，万宝将告坚。","齐鲁遥拱带，河洛自回环。","肥遁感圣心，豫游布长筵。","旌旗代林组，笳箫按候宣。","黄菊华行李，玄酒返朱颜。","昌期选后夫，枉士思故山。","巢许容为客，虞德一何玄。","蓬心愧薄劣，兹尚讵能言。"]},{"t":"拟古七十首 其三十二 支道人遁赞佛","f":"五言古诗","c":["群象倡明茂，四气适清和。","凌晨将投礼，首宿事奢摩。","闪若太阳来，朗耀周九阿。","诸天从帝释，旌拂纷婀娜。","修罗戢怨刃，波旬解障魔。","馥郁旃檀树，彪炳珊瑚柯。","醍醐酿甘露，徐挟神飙过。","千叶青芙蓉，一一凌紫波。","流铃相间发，宝座郁嵯峨。","上有慈悲父，金顶秀青螺。","端严八十相，妙好一何多。","微吐柔细音，雍如鸣凤歌。","惠泽彻无间，哀响遍婆娑。","密迹中踊跃，大士亦隗俄。","独解舍利子，回心乾闼婆。","灵花散优钵，智果结庵罗。","法鼓撞震方，慧灯导恒河。","方广距由旬，成违仅刹那。","冥心归真谛，毋使叹蹉跎。"]},{"t":"拟古七十首 其三十三 陶徵君潜田居","f":"五言古诗","c":["贫来迫我耕，既耕贫不离。","谁云非长策，舍此亦奚为。","今晨作劳罢，曳耒归何迟。","邻父悯我劳，要我过其居。","芋叶荐鱼鲭，浊酒且盈卮。","慨焉思人世，百劝百不辞。","今人不为古，古人当在兹。","过隙能几何，为乐当及时。","劳者欲有歌，我歌自吾知。"]},{"t":"拟古七十首 其三十四 宋文帝北伐","f":"五言古诗","c":["内史斥楼烦，嫖姚越祁连。","将逞域外武，宁无务德言。","中土厌胜朝，左衽垂百年。","先皇振九伐，霈泽洒秦燕。","大业未逮终，妖氛日横缠。","版宇罹荡析，黔黎困倒悬。","玄黄既在篚，壶浆宁不前。","俯瞰单于台，秋风正萧然。","戎车虽闲饬，尚其赖诸贤。"]},{"t":"拟古七十首 其三十五 谢临川灵运游山","f":"五言古诗","c":["山水慕孔乐，丘园惭易贲。","殊恩赐初服，薄游返真理。","改策桐庐峰，遗舲富春涘。","阴崿攒空翠，阳崖吐清泚。","行鞋芳露润，饷榼流云止。","丛林蔽啁唽，徐风发旖旎。","解箨篁鸣玉，辞苞萼呈绮。","溜溜窦乳滴，活活溪源徙。","诧叹接来奇，邅回惜去美。","流光暮摇漾，白石何齿齿。","想见羊裘客，眇言旷千纪。","滞迹好尤人，选念良在已。","蝉緌信遗脱，渔钓从此始。"]},{"t":"拟古七十首 其三十六 颜特进延年侍宴","f":"五言古诗","c":["赤县腾真气，丹观切太微。","千祗肃羽卫，七圣扈鸾旂。","神舟二龙跃，天黄八骏归。","陆驰皆迹射，水击尽佽非。","行宫初戾止，张乐答澄辉。","神鱼翻镛贲，灵兽舞翟翚。","金珰景风触，琼弁白云围。","赵女击秦筑，吴娃鸣越丝。","巧夫歌人偶，眩士吐寒曦。","桃榴煜崖冠，荇薜灿波衣。","烟澄淮楚出，天阔江介微。","臣欢畏童羖，圣洽咏凫鹥。","沧溟返西注，濛汜郁东驰。","夭乔欣当御，鳞翰骄奋飞。","苕芼诚微贱，鼎俎内惭疑。"]},{"t":"拟古七十首 其三十七 谢法曹惠连叙别","f":"五言古诗","c":["微寄迫如丝，将适千里道。","仳心怜友于，言饯春原草。","顾听双鸰鸣，何以泄予抱。","解缆羡归潮，回膺怨层岛。","遥遥西陵浦，宛宛澄波流。","飘飘惊风发，汤汤沸陵丘。","挥锋割舲楫，吹素染旌斿。","八荒无岐色，七圣迷所由。","宾俦久告绝，含悰将诉谁。","仰希退飞鹢，俯感触藩羝。","冥息胪故欢，端居奏新悲。","悲新缠难遣，欢故杳莫追。","园林饶奇趣，往往媚居人。","哲兄昔领袖，伊予并沈沦。","篇裁不孤赏，席至无只陈。","华月在清圭，武夫映见珍。","予行浩未已，子处将何如。","青葱东斋沼，有无长新蒲。","紫箨解修篁，文鸳弄鸣雏。","从容命觞咏，倘以及睽孤。"]},{"t":"拟古七十首 其三十八 谢光禄庄郊游","f":"五言古诗","c":["泳思遵江广，托瞩在严坰。","百堞摇容滟，千棹和鏦铮。","来鸿欣知止，丛菊誇后荣。","盍簪攒云岫，散绮宿霞汀。","清霜披林览，枯卉感籁鸣。","究胜时扶策，沈怀聊屏觥。","容华非予擅，物序搅我情。","将治鹿门业，归耦长沮耕。","毋染临渊叹，遂为渔者矜。"]},{"t":"拟古七十首 其三十九 王徵君微养疾","f":"五言古诗","c":["秋风有奇色，能使昔邪黄。","一叶嘘商曲，群鸿尽南翔。","白云栖空除，华月湛匡床。","外门罗来雀，内户按啼螀。","卧疴与性会，华炫非所臧。","精液随年销，金石依形长。","湛然守寸宝，委顺无何乡。"]},{"t":"拟古七十首 其四十 鲍参军照戎行","f":"五言古诗","c":["严烽举中夜，游骑犯秦凉。","天子投袂起，剑屦在寝皇。","左锋当鱼丽，右铩按龙骧。","曾是东征返，离离缺斧斨。","束胸见使者，距跃讳残伤。","转战焉支岭，蹀血瓯脱场。","塞马劲如飙，横驱不可当。","部曲星散尽，独身擒其王。","枯骨遗鸢喙，英声贯人肠。","生存百年事，没者万年芳。"]},{"t":"拟古七十首 其四十一 袁太尉淑从驾","f":"五言古诗","c":["衣冠神游肃，弓剑圣情纡。","蒸新嘉周典，祠雍陋汉图。","万象改冬凛，九有悉春敷。","屏翳躬先扫，玄冥戒后诛。","金椎隐驰道，玉戚护乘舆。","蛟龙扰鞶革，麟凤翊流苏。","朝云煜容卫，夕宿灿周庐。","鸣镛震海立，传跸应嵩呼。","父老望张饮，士女欣大酺。","人文被岩壑，天藻冠京都。","陈诗悉二雅，稽典嗣三谟。","臣欢奉元首，赓歌幸未孤。"]},{"t":"拟古七十首 其四十二 休上人怨别","f":"五言古诗","c":["落日多媚景，楚士中不怡。","风吹湘山色，往往尽成疑。","彼美无与晤，旷伫生劳思。","三枯岫中蕙，再茁园柳荑。","博山寒虬烬，屈戍绣蛛丝。","徙倚翘芳迹，沈吟黯胶颐。","虚有焦桐尾，黄金为谁徽。"]},{"t":"拟古七十首 其四十三 谢吏部朓省直","f":"五言古诗","c":["禁籞森木天，文昌尔璇汉。","风色飞廉馆，波文属玉观。","银虬隐自鸣，金鸱对如玩。","薜衣绣丹涩，蜗书吐玄灿。","亭亭钟山秀，罘罳何历乱。","务简化日舒，兴言染柔翰。","即事台可悦，奚必休请浣。","敢用蓬户观，夕从朱门旦。"]},{"t":"拟古七十首 其四十四 王著作融游邸","f":"五言古诗","c":["风铎流清梵，天花坠妙译。","解脱身自馀，清虚胜能择。","薄游名王邸，俨如化人宅。","多宝墄基阶，明玑喷沼泽。","兰橑芬自栖，菼堤绿如积。","和薰调言鸟，轻烟媚垂薜。","束峡饶奇声，低舂出远色。","即境良非幻，冥心庶已寂。","至哉物外游，超然忘所获。"]},{"t":"拟古七十首 其四十五 沈仆射约饯别","f":"五言古诗","c":["九伐当熙代，十乘启元戎。","以我师中吉，占彼后夫凶。","皇仁等乾运，万㝢悉帡幪。","挥眸无拓拔，抵掌有山东。","盘龙五花剑，号乌七札弓。","蜂旗布飞宿，虎落绕长虹。","崤函既平践，峣关复斩通。","帐饮渴泾渭，军声摇华嵩。","高筵班勇爵，中坰建武宫。","翻嫌赐履狭，不数太师功。"]},{"t":"拟古七十首 其四十六 范仆射云贻友","f":"五言古诗","c":["蓐食向东畴，薄暮始言还。","遥见车马迹，蔼蔼散平川。","鸡犬若有恋，鸟鹊尚盘旋。","还顾问应门，错愕相告言。","言有冠盖客，眉宇何轩轩。","入门更左顾，徬徨回就辕。","北风吹马嘶，落日送旌旃。","沈吟思久要，畴为故所欢。","自非徐方牧，谁能顾闾阎。","贵贱常人态，君子自金兰。","楩杞振休风，高云薄旻天。","书此布区区，在下亮弗援。"]},{"t":"拟古七十首 其四十七 江记室淹卧疾","f":"五言古诗","c":["寒暑更代至，为我炼朱颜。","槐庭绿阴逝，稻垄黄云还。","鸟雀思改栖，鸡豚亦不閒。","据梧辞纷尚，采薪负奇艰。","推迁其所，睽离思乃殷。","遥心先枉渚，选友向江关。","橘柚组衰景，云霞分故山。","青灯代为耦，单巢竟成鳏。","蠲痾稀灵剂，循视在刀环。"]},{"t":"拟古七十首 其四十八 梁简文纲闺怀","f":"五言古诗","c":["欢闻子夜变，妾作懊憹憩。","城上乌毕逋，墙头雀劳利。","杨白风捲花，桃生雨辞蒂。","引念磁石难，分颜剪刀易。","密约悬庚癸，秘辞属丙丁。","何朝更尔尔，一一问卿卿。"]},{"t":"拟古七十首 其四十九 何水部逊示寮","f":"五言古诗","c":["泬寥澄丁夜，黯■流泓碧。","晓月媚独征，清霜凌行色。","稍稍曙吐帆，微微风饱席。","林辉惊栖乱，波响跳鳞激。","喟然川上逝，念此山中客。","晨凉在衾裯，昼事馀巾帻。","饮食不为人，游梦从所适。","抚已能无愧，达生遘隐迹。","年事离余往，简书代相迫。","寄声夔龙偶，终蹈巢由则。"]},{"t":"拟古七十首 其五十 吴记室均春怨","f":"五言古诗","c":["悠悠仓庚语，唤此帘栊曙。","万象欣遇新，贱妾不改故。","买愁榆荚钱，粘恨随杨絮。","草信忘忧难，花疑合欢误。","百种枕上心，千条梦中路。","眼波写欲竭，眉峰解还聚。","昨者玉关书，更移金河戍。","玄冥彼方辞，青阳兹已暮。","但睹朱成碧，未解鬒变素。","对影欲有陈，冥然不相顾。"]},{"t":"拟古七十首 其五十一 庾开府信校书","f":"五言古诗","c":["森蔚誇东观，渊穆表西清。","左史读丘索，孔公比老彭。","金壶浮泥汁，青藜太乙灯。","六纬受李氏，七略仿更生。","白马公孙辩，绣虎平原名。","身依昭回汉，职列葱离星。","陈矢徵肃慎，吴书问洞庭。","驺牙收边籍，贰负表山经。","穷探岁加我，执戟听沈冥。"]},{"t":"拟古七十首 其五十二 阴常侍铿送别","f":"五言古诗","c":["秦淮将征棹，西兴导返舻。","谁言剑合地，即是袂分途。","比带将同缟，拟蔌讵如蒲。","倚醉聊慷慨，临醒复郁纡。","遥帆雨中失，清尊月下孤。","裁书怅南雁，托梦怨单乌。","宝铰银平脱，珠韔金仆姑。","还期一文轨，方驾骋天衢。"]},{"t":"拟古七十首 其五十三 薛内史道衡酬忆","f":"五言古诗","c":["秋风吹大荒，秋月满河梁。","尺书问马走，一枕遍羊肠。","羊肠几屈曲，轮鞅声相续。","句里孟门青，意中淇水绿。","绿水如丝流，青天去不收。","王猷兴欲尽，卫玠始生愁。","愁人自宛宛，日长岁苦短。","蘼芜虚早齐，不睹松柏晚。"]},{"t":"拟古七十首 其五十四 杨司空素坐怀","f":"五言古诗","c":["幽居擅丘樾，块尔称独晤。","盘礴翰墨林，沈冥诗书趣。","袅影文昼寂，飞英点林素。","溪藤饮猿接，梁棘归鸟输。","四起垂天云，疑亡出山路。","屏刺少所通，非心不成故。","慨此穆如侣，抒言托遥慕。"]},{"t":"拟古七十首 其五十五 王参军勃梦游","f":"五言古诗","c":["役神苦烦慸，羁形困局促。","言揽化人祛，税驾从所欲。","瑶阶净于砥，宝观纷若簇。","清篁展云幄，言鸟流风曲。","舒霞缛流草，垂露布森木。","中有青莲冠，脩眸炯清淑。","授我琼函字，长跪不敢读。","秋飙触明珰，吹我堕几褥。","琳琅恍犹听，芊郁疑在瞩。","惆怅将起端，多岐浩难续。"]},{"t":"拟古七十首 其五十六 杨盈川炯游峡","f":"古风","c":["蜀江自西来，日夜流不息。","束为荆门峡，崩腾锁南国。","楚师既以?，秦疆渐以画。","万古擘石青，千秋吐灰黑。","我行仗三老，扬舲浩无极。","入耳寡停声，寓目鲜留色。","日落一线明，悄然中原碧。","惆怅为云女，虚无不可即。"]},{"t":"拟古七十首 其五十七 卢典签照邻咏史","f":"五言古诗","c":["昔有严先生，少妻仙尉儿。","泥涂两鱼泳，风雨六龙飞。","黄纸求故人，白云长见依。","遂令箕颍客，复睹勋华姿。","帝腹何便便，举足忽践之。","客星歘然去，帝座光芒披。","笑谓邓氏子，策杖一何卑。","岩穴澄秋色，烟霞蔚天辉。","怨见千秋士，寂寂西山薇。"]},{"t":"拟古七十首 其五十八 陈正字子昂感遇","f":"五言古诗","c":["园桃畏霜霰，零落不自己。","吾闻诸古人，衰荣亦常尔。","所以遇春荣，澹乎无可喜。","内外了不干，熹微识其始。","明月海上来，中天澄如洗。","至宝嗟已失，嚣然谀殇子。"]},{"t":"拟古七十首 其五十九 沈詹事佺期访道","f":"五言古诗","c":["玄天泄至秘，大地输真宅。","言访赤城居，试探黄庭策。","黄庭何其妙，幽阙守玄魄。","赤城信矣高，灵仙寄神迹。","鸾軿夜分至，凤管空中适。","眉掞芙蓉青，颜欺舜华白。","归霞散衣桁，流水澄巾帻。","泠然驭风来，倏尔凌云息。","劳役悲在今，夷犹叹夙昔。","因牵絓原网，遂铩冲霄翮。","愁云幕远近，欲火煎日夕。","隐隐移少年，沈沈散精液。","敬谢广成师，为我示天则。","竦辔昆崙颠，扬舲弱毛泽。","沧桑坐经变，濛汜何虞迫。","火枣幸有馀，乞师知不惜。"]},{"t":"拟古七十首 其六十 宋学士之问祠海","f":"五言古诗","c":["税驾依海壖，肃祠乘嘉月。","朝日侵夜生，春溟际天阔。","惊涛吐千崿，穷岛迫一发。","百谷俱让王，九州悉倾穴。","星河时翻动，天地中出没。","体荐秩礼殷，祼将醪芬发。","岿然祝融坐，肃矣群灵谒。","环佩趣飘飖，灵旗去恍忽。","缅怀拙薄踪，承明昔三入。","敢问乘海桴，窃希迷津筏。","弱水未易方，昆崙焉可越。","矫首贯月槎，极目含珠阙。","倘呼龙伯人，为我灼鳌骨。"]},{"t":"拟古七十首 其六十一 崔员外颢游侠","f":"五言古诗","c":["东风五陵畔，恣意少年游。","鲁酒银凿落，宛辔金雕锼。","狂童舞拍张，妖女弹箜篌。","酒酣万事出，横披宫锦裘。","尺八铁匕首，能令都市愁。","避雠从车骑，结客取凉州。","北断匈奴臂，西斩月支头。","论功独第一，天子赐旌斿。","图貌在麒麟，英风冠九州。","笑谓故所知，功多罪不忧。","当时杀人者，今日海西侯。"]},{"t":"拟古七十首 其六十二 孟襄阳浩然留客","f":"五言古诗","c":["散发池上酌，好客偶尔会。","童子三四人，盘飧无兼味。","蕖露时自滴，松风为谁至。","冉冉落日尽，悠然发真醉。","陶公既已往，千载沦兹意。"]},{"t":"拟古七十首 其六十三 王右丞维山居","f":"五言古诗","c":["为惜辋川好，携家事田作。","青山映如带，绿树相历羃。","燕乳林花乱，蚕肥桑阴薄。","微雨终南来，鯈鱼蔼然乐。","饷馌下鸢群，束书挂牛角。","樵斧入涧深，丁丁送馀斲。","归逢耦耕叟，问我来朝约。","坐爱微风吹，尚隐残日脚。","得暇便相过，床头有桑落。"]},{"t":"拟古七十首 其六十四 岑嘉州参塞宴","f":"五言古诗","c":["边草五月绿，秦马三春肥。","鸣鞭饰珂子，色夺宫罗衣。","朝谒府主出，夕从射猎归。","珊瑚照夜筵，行酒罗金绯。","赵女青丝弹，胡姬白玉围。","酒酣烛忽灭，语客任所为。","横行缠头锦，零落珍珠琲。","明月出东方，清波溢鸾旂。","鸦青约素腕，双双扶入帏。","北风旦暮吹，黄尘俱倒飞。","如何咫尺地，步步春光辉。","为谢盖大夫，时清刁斗稀。"]},{"t":"拟古七十首 其六十五 高常侍适咏途","f":"五言古诗","c":["少小爱渔猎，不解慕清朝。","春风荡孟诸，草绿胡马骄。","一剑挥两从，只羽贯双雕。","折节读诗书，策名列官僚。","虽与贫贱辞，未远案牍劳。","今朝涉淇上，中原莽萧萧。","天晴太行出，峡急黄河摇。","游鲤跳伏獭，飞凫堕鸣枭。","恍若旧时游，欲呼故所招。","夺标胡姬馆，走马河阳桥。","丈夫自有命，时来则金貂。","安能对玄经，终岁长寂寥。"]},{"t":"拟古七十首 其六十六 李翰林白自明","f":"五言古诗","c":["海色摇地绿，昆崙插天青。","天地不相忌，千秋弄精灵。","偶然复生余，抟作世人形。","俗眼不能识，强呼为岁星。","昨歌咸阳市，如意击玉瓶。","醉骂文成侯，白眼春冥冥。","新丰酒初熟，胡姬手如玉。","十千换一斗，醉即垆头宿。","中夜黎眉騧，银珰响相逐。","上帝奏钧天，名姓登紫箓。","蛾眉七十二，停筝待新曲。","揽笔虹霞生，鸣毫风雨促。","天姬粲瑶齿，重瞳亦回瞩。","衣我宫锦袍，葡萄发醽醁。","片言朝不投，夕买范生舟。","三神未欲返，五湖且须游。","鱼龙听咸池，遂为钓者求。","愀然发长啸，千金等云浮。","虞帝放丹均，波应及许由。","不然箕山客，今作浔阳囚。","黄鹄脱樊笼，低身瞰九州。","衔珠报恩德，然后访丹丘。"]},{"t":"拟古七十首 其六十七 杜员外甫述贬","f":"五言古诗","c":["昔我游山东，高李相先后。","豪鹰抟青冥，所击无不取。","斲句必老苍，骊珠恋吾手。","西入咸阳城，落魄鲜所偶。","驼锦青貂裘，半为酒家有。","时来异援出，三赋天子售。","泚笔中书堂，公卿尽回首。","虮虱脱洗沐，毛羽出抖擞。","清华文昌步，磊落国士耦。","欃枪亘北极，荧惑趋南斗。","哥舒小竖子，弃我潼关守。","万乘倏蒙尘，群公但奔走。","鸣呼上帝仁，苍茫意愈厚。","马嵬剪阴孽，朔方建阳纽。","桓桓汉阴公，玉玺主亲受。","制曰相国琯，汝往馘群丑。","戎车实闲饬，骄将违指授。","遂令陈涛士，义血漂杵臼。","天威震莫测，左右夺申救。","甫也一小臣，上书戒求旧。","孤忠报社稷，馀分推朋友。","幸免左伯诛，仍宽马迁咎。","优游上州佐，零落一野叟。","雪压履下趾，风吹衣前肘。","饥寒自切骨，虚名在人口。","穷途往念至，迟暮新恩负。","千载与百年，茫茫付杯酒。"]},{"t":"拟古七十首 其六十八 王龙标昌龄独游","f":"五言古诗","c":["屏出乖物情，薄游寓余目。","春风夫如何，时见千里绿。","蚕女犹未来，桑阴正渥缛。","上有戴胜鸣，间关奏丝竹。","彼奏非有适，此会如见属。","因之念友生，历乱我心曲。","沈思入迷径，回策从疲足。","归及午饷馀，言跨返耕犊。"]},{"t":"拟古七十首 其六十九 储参军光羲咏耕","f":"五言古诗","c":["农事有常期，侵晨向东畬。","岂不念筋力，要为口所驱。","大儿把桔槔，中儿佐犁锄。","小者力不任，饷榼绕周涂。","尽室事农耕，谁还读我书。","荣华诚快意，变态亦不疏。","团坐倾浊醪，移荫就桑榆。","好雨从东来，庶足代勤劬。","莫以玺角牛，当他驷马车。"]},{"t":"拟古七十首 其七十 韦左司应物寄僧","f":"五言古诗","c":["虑澹无可屏，端居生夜清。","秋风在长松，谡谡令松鸣。","因之动遥思，思我方外朋。","趺坐深草色，流尘瘗函经。","多露湿空山，欲往未能胜。","回心入初地，万象了不应。","方知见闻表，悠然有合并。","如何怨碧云，役役伤道情。"]},{"t":"杂感六章 其一","f":"五言古诗","c":["新秋凉气微，大火犹蒸濩。","不知当庭树，何繇中销落。","葺葺梁间垒，玄鸟翩然作。","今逝如有乖，昔来如有托。","人情亦已长，积衰方成薄。"]},{"t":"杂感六章 其二","f":"五言古诗","c":["冉冉西流日，杳杳东逝川。","弃女守空闺，不知时变迁。","膏沐一朝施，含羞不自前。","虽复回青盻，盛年坐君捐。","二八方偶进，骈齿复齐颜。","为媚须及早，为恩须及好。","再收当中热，再捐当何道。"]},{"t":"杂感六章 其三","f":"五言古诗","c":["赤骥困服箱，足下有八埏。","苍鹘困绦旋，翮下有九天。","东风吹孟诸，短草何芊芊。","鴐鹅飞我侧，狡兔出我前。","㸌如云间电，挽弓不及弦。","劲翮应脩蹄，为君荡群鲜。","人生非遇合，安能自称贤。"]},{"t":"杂感六章 其四","f":"五言古诗","c":["手携绿绮琴，去上高山阿。","落日四无人，萧瑟扬洪波。","凝神入天倪，心指遂相和。","归来奏清曲，商飙綷纤罗。","白云从东来，为我不忍过。","奏者岂不廑，听者已隗俄。","无情尚有知，有知当奈何。"]},{"t":"杂感六章 其五","f":"五言古诗","c":["贫贱诚难处，富贵宁易居。","畴为执两端，令我与愿俱。","藜藿犹未糁，列鼎穷珍腴。","饥者靡不佳，饱者不羡馀。","窈窕南山云，归乎恣所如。"]},{"t":"杂感六章 其六","f":"五言古诗","c":["千金买骏马，百金买辔头。","百千制狐白，十千珊瑚钩。","相从诸少年，宛洛书行游。","宛洛富名倡，挟瑟进清讴。","但知媚黄金，焉知我为畴。","出当从客欢，归当从妇谋。"]},{"t":"书感 其一","f":"五言古诗","c":["婵娟无终极，燕赵遍蛾眉。","百卉就春阳，芬艳迫参差。","美人临流坐，顾影中自怡。","岂以为人妍，皓齿发相讥。","卤莽乃时情，千秋长若斯。"]},{"t":"书感 其二","f":"五言古诗","c":["白露湿螀声，枯叶悲自和。","兰膏冻不发，三星渐沈河。","里中多轻薄，昏醉相经过。","两意既非当，虽欢其奈何。","亮无同衾愿，闭户敛双蛾。"]},{"t":"杂感 其一","f":"五言古诗","c":["朝阳发东隅，群动借其光。","流影忽西颓，万象亦含章。","谁云凉热变，迁代固所常。","尔日平沙堤，今来禾黍场。","鸟雀恋故枝，车马依他墙。","要知亲者短，不及疏者长。","邈矣任生操，咄哉魏其伤。","誓纫幽兰佩，雅谊畴能量。"]},{"t":"杂感 其二","f":"五言古诗","c":["髫龄操觚翰，冠弱庸清朝。","驽质谢鞭策，闭户甘阒寥。","挥汗畏请谒，四顾谁亲交。","此时大道边，车马争流涛。","举目灼夭华，回盻生秋蒿。","亮匪万年身，胡忍弃尘嚣。","呼儿理残编，手复量浊醪。","得意且如此，后来惟所遭。"]},{"t":"杂感 其三","f":"五言古诗","c":["为性本薄劣，聊乐在诗书。","稍与古人近，顿觉世人疏。","饱饭藉高卧，忽起临前除。","隐隐带西山，历历薄吾庐。","百里距非迩，爽气时吞嘘。","出门复入门，举足愁尘污。","以兹欣散秩，牢落扬雄居。"]},{"t":"初入理圜土 其一","f":"五言古诗","c":["日予事铅椠，握志在皇羲。","泣车岂不深，化理一何卑。","咎繇固贤圣，毋乃逊后夔。","人情如趋湿，盛时能豫衰。","更以秩守寄，身为狱吏师。","悠悠互朝暮，戚戚此圜狴。"]},{"t":"初入理圜土 其二","f":"五言古诗","c":["圜狴何崔嵬，贯曜丽幽方。","当昼日返冥，踰春草不芳。","纠纠禦呵怒，离离累讯伤。","下当迩重泉，上永隔天阊。","谁悉逝矣故，更悲来者长。"]},{"t":"初入理圜土 其三","f":"五言律诗","c":["庭前有高树，好鸟相因依。","固以效和鸣，鸣声一何悲。","疑歌复疑诉，流调更流悽。","此鸟宁有异，听怀多是非。"]},{"t":"我有一壶酒与于鳞赋","f":"五言古诗","c":["我有一壶酒，与君醉花下。","东风日夜至，群芳无停吐。","高歌荡浮云，白日光起舞。","陶然中心悦，忽往在千古。","匪以藉世赢，他人安能取。"]},{"t":"比曹初考述职有感","f":"五言古诗","c":["岁月不我即，禄食三已期。","揣分冒兢惕，程已惭素尸。","出负友朋属，入惭父兄规。","殿最他所任，得失中自知。","伊予少浅涉，夙好经生期。","稍见事乃谬，渐习心永睽。","咎繇固圣者，其究亦趋时。","南容复白圭，已甚非仲尼。","滔滔亘天路，戚戚将向谁。"]},{"t":"偶书","f":"五言古诗","c":["闭户延素晷，创足避华径。","所惟力不任，非繇意无竞。","沈沦既已甘，芬芳亦焉盛。","寄责聊簿书，娱怀乃篇咏。","策短世何长，瞿然恐难竟。","得酒且复斟，吾当醉陶径。"]},{"t":"遥望北邙山","f":"五言古诗","c":["遥望北邙山，冢墓郁相樛。","石兽蹲草间，妖狐误来求。","斧斤焉施伐，原窞各趋畴。","积泯渐成无，焉能睹其由。","生时藉世赢，迹往神不留。","岂若蓬蒿士，一语为千秋。"]},{"t":"省中视事有感","f":"五言古诗","c":["披案适不乐，起步临前庭。","顾视云中照，翳翳迫西楹。","过日若倾波，谁为念不停。","霜卉爱青阳，鬒丝忧素茎。","刀笔理何深，能令走世名。","蜀客虽寂寞，犹得守玄经。"]},{"t":"睍睆篇","f":"五言古诗","c":["初景革绪寒，浮阳依芳樾。","黄鸟何间关，言兹媚蚕月。","柔丝骄未调，轻簧冻难发。","听曲几其真，条风吹成歇。","迁乔焉所觊，求友翩更切。","我有盈樽酒，偕子候鸣节。","婉㜻中心契，忽往在天末。","羽翮临见乖，腼焉增烦结。"]},{"t":"三良诗","f":"五言古诗","c":["白日归苞栎，荒飙助游环。","阗道俱声咽，叹息此三贤。","临穴惴惴下，彷徨顾平原。","奄仲即长昏，针虎亦何怨。","逝者许一身，存者留一言。","清渭东南外，谁不忿王官。","戎乐既销亡，回首见雍川。","扣角与负薪，各自爱其全。","惜哉百夫特，粉黛同所天。"]},{"t":"蔡文姬归汉","f":"五言古诗","c":["汉相肇休业，威揽遍九围。","维昔先臣邕，蒙志赴屯夷。","太阳下回光，寒灰亦不遗。","黄金驰大卤，穹庐出蛾眉。","朝辞单于庭，夕宿广川湄。","众鸟媚其巢，接翼竞言归。","羁鹄将雏去，傍徨复置之。","仰悼双星色，俯割所恩私。","秦关忽在望，禾黍正离离。","庄馗改故迹，人民能不非。","不敢称董仇，戎首竟为谁。","韶齿掷边塞，中原渺焉依。","冉冉崦嵫景，条桑沐馀晞。","荃蕙化蓬茅，何能荐庭阶。","宝鉴既已毁，拂拭愧光辉。","寄语闺中质，千金当自持。"]},{"t":"古意","f":"古风","c":["采桑秦家女，皎若千金璧。","君王临高台，美人奏琴瑟。","忽来关雎操，远望中心怿。","遗以双明珠，绣袋文??。","家令君王臣，贱妾亦何匿。","槁壤比云霄，低昂畴能敌。","但恐失身素，玉体何当匹。","长跪前致辞，低眉中含抑。","本自不为双，悽然如初只。"]},{"t":"谒陵有述 其一","f":"五言古诗","c":["天开鸿濛秀，万古抱日月。","下有诸仙宫，神龙蜕其骨。","灵气函山泽，草木亦精发。","仰观太清表，隐隐浮员阙。","九幽导金灯，六丁护玉箧。","隧途流松风，霓旌昼明灭。","恐是七帝游，群真来趋谒。","小臣虽末贱，谬从大夫列。","尸禄帝所嗔，微诚何由达。"]},{"t":"谒陵有述 其二","f":"五言古诗","c":["文皇起北平，迅扫天下兵。","六飞燕然山，却刬单于庭。","千艘凌渤澥，象纬偃不惊。","遂令职方氏，王会所未名。","奇琛及怪兽，重译归我明。","卜鼎故龙潜，其阴郁佳城。","愀然边烽色，慷慨有馀情。"]},{"t":"谒陵有述 其三","f":"五言古诗","c":["太陵一抔土，仰视何嶙峋。","帝德浩如天，岂以黄屋尊。","垂衣十八载，象汇俱含醇。","非无阴阳接，四候均若春。","坐论颂贤佛，作行归俊民。","宁知神龙逝，化海邈无津。","握手三辅臣，扼腕竟何伸。"]},{"t":"晨入曹中即所见有感","f":"五言律诗","c":["东风吹微绿，一夜千树满。","黄鸟坐交枝，流声自睍睆。","侧生墙阴柏，憔悴一何短。","岂以真宰私，幽独受时缓。"]},{"t":"春旱三章 其一","f":"五言古诗","c":["皇天无颇泽，物运乃自乖。","柔木恋焦原，不肯展青荑。","赤日从东起，亢风复西来。","虽有肤寸阴，临合倏已离。","安得起骄龙，为我鞭疾雷。","恻彼丘中叟，负耒拟何之。"]},{"t":"春旱三章 其二","f":"五言古诗","c":["玄冬饶奇冽，霜霰无停飘。","墐户歌春德，冀以惠来苗。","女魃乘䖺䗤，末涂竟流焦。","阴阳无赢胜，贵在得所调。","燮理岂在隅，咎衅内惭招。","亮深为牺念，敢以一身要。"]},{"t":"春旱三章 其三","f":"五言古诗","c":["孑孑数馀黎，辽辽殊未央。","银镂穷天府，技击歼朱方。","比井稀宿籍，在公乏栖粮。","使者东西来，玺书正相望。","轮蹄金纠错，鞭笞血纵横。","侧窥骄阳意，毋乃帝未详。","矫首盻穹苍，沈深竟难量。"]},{"t":"感怀 其一","f":"五言古诗","c":["今晨东风至，吹我颜色佳。","揽袂不及裳，粉泽理光仪。","新荑承天露，朝荣际日晖。","雅步中宫商，顾盼有馀姿。","临当中门发，欲出故徘徊。","燕赵三千人，一一自蛾眉。","所愿在当怀，焉顾妍与蚩。","沈吟临芳镜，掩约内伤悲。"]},{"t":"感怀 其二","f":"五言古诗","c":["清晨出游目，顾见南山道。","挟弹美少年，容颜白如缟。","拉攞枯松树，上有乾鹊噪。","熻㸌朱丸流，宛转堕荒草。","企听犹未毕，吉凶不自保。","七尺长为人，焉能制余老。"]},{"t":"感怀 其三","f":"五言古诗","c":["人生垂衰老，俶如就途客。","药饵相扶持，攀车解輗轭。","不行将难免，暂留终何益。","著书以自宽，聊为存者识。","明晦既歧轨，焉用留遗迹。","贤圣知有馀，死生无中策。"]},{"t":"岁暮作","f":"五言古诗","c":["廓落鲜所娱，沈忧岁偕暮。","连岫无间绿，广庭有储素。","日气惨不舒，玄阴莽回互。","晨风旦夕号，岑棘窜狐兔。","引领俟春阳，春阳不我顾。","爽鸠代已往，羲和迫相度。","盈樽庶可逃，整辙将首路。"]},{"t":"早起书怀","f":"五言古诗","c":["晨鸡四鸣号，天地犹未白。","仰见众星低，历历如可摘。","揣来浩无端，数往已为迹。","言念乘轺始，徂岁三代易。","谬以理解资，而当髋髀役。","何悟茧丝辰，膺此保障责。","桑计非所工，商刑焉能择。","稍清萑苻泽，未愧莱芜室。","蒿目中竟乖，蓬心逝安息。","次且类羝藩，犹豫托鸡肋。","畴当邻畏途，为我一察识。"]},{"t":"愤篇","f":"五言古诗","c":["牵丝诵经籍，弱冠探仕录。","触绪多见违，夙言将安属。","策马涉鲸波，操舟令从陆。","扰扰红尘间，焉为问车毂。","渭水既入泾，谁当辨非浊。","骐骥虽工步，难与飞鹰逐。","神龙固天矫，变化求所欲。","乔松抖唐蒙，首尾竟成束。","将循李陵发，未卫鲍庄足。","衔愤戒伊人，富贵生局促。"]},{"t":"题帝王礼僧图","f":"五言古诗","c":["昔有庞眉师，九载面石壁。","置心诸地外，人天杳俱寂。","经猿六时拜，谈鸟掌中食。","日出天地开，蔼然旌旗色。","衬施填恒河，结束俨帝释。","虽屈万乘尊，对者了不识。","一吐无圣言，顿扫有为迹。","归路甘雨移，青林杏花白。"]},{"t":"辕马叹","f":"五言古诗","c":["辕马齧枯荄，枥马齧青草。","辕马谓枥马，我欲之长道。","劳者常苦饥，佚者常苦饱。","幽州碧眼客，鸣鞭如鸱噭。","银鬉凿落蹄，生怜为人好。"]},{"t":"题素节堂","f":"五言古诗","c":["汶岭垂坚霰，淇澳挺修筠。","讵若君子风，奕世鲜淄磷。","伊昔中兴初，尚书司国钧。","在公慕羔羊，操宪抑奔鹑。","及乎悬车日，不复朱其轮。","微言揭楣端，抗志薄商旻。","翛然湘江色，宁染京洛尘。","太仆称象贤，在坰歌未伸。","三径循夙资，百石非所欣。","安节承上道，素履率初真。","拂拭登君堂，頫仰愧其人。","孙叔请瘠邱，千秋能食贫。","嗟嗟黍离叹，榱栋尚维新。"]},{"t":"寄题清懒窝","f":"五言古诗","c":["秉介探夷尚，谢嚣负嵇癖。","虽复蜕污浊，安为事雕饰。","洋洋泌流水，结庐依其侧。","飞花聊为径，野草纷如积。","荆户启南薰，胡床挂东壁。","兴至时命琴，客来或不帻。","白云何英英，卧君庭中柏。","不随飘风逝，为君助幽色。"]},{"t":"除夕","f":"五言古诗","c":["江城岁云暮，北风何惨慄。","稍见亭午过，黯然中原日。","飞鸟时下来，人家扫祠毕。","稚子欣就新，华颠念趣失。","四十行已尽，明朝复加一。","踯躅山泽间，无闻亦奚恤。"]},{"t":"孙文学丌册庋","f":"五言古诗","c":["会稽表神閟，宛委徵帝藏。","讵若登君室，步武见前芳。","边笥有馀委，惠车不盈箱。","青荧藜床色，旖旎兰橑香。","低云润遗简，隙月窥流缃。","咏响出疏棂，回风自琅琅。","恒闻诗人旨，忮求乃不臧。","蔬饮枕曲肱，其乐自羲皇。","举趾触四周，抗心凌八荒。"]},{"t":"为顾生题其父太保公临赵承旨双松图","f":"五言古诗","c":["岁晏郁秀色，双虬挂晴空。","下有李元礼，谡谡松间风。","谁将一帧素，写此千尺雄。","承旨昔胜流，太保时宗工。","岂必论形似，心赏泠然同。","乔木存故家，甘棠比遗踪。","新篇并嵯峨，流沈各青葱。","置子高堂上，白云或从中。"]},{"t":"为凌郡丞题柴桑雅致图","f":"五言古诗","c":["陶令彭泽归，秋风何快哉。","与世既无营，返服宁不谐。","冁然一杯酒，时送寒山来。","至今柴桑地，远高严陵台。","矫矫凌大夫，清标冠时才。","半刺日翱翔，车马生红埃。","展图三叹息，欲往道疑乖。","应迹若浮云，丘壑在轩阶。","请以无累衷，契彼千载怀。"]},{"t":"将以伏阙北首晨发即事有作","f":"五言古诗","c":["维稍候鸣潮，伺钥遵广陌。","晨鸡再三号，使我天地白。","太阳丽层霄，万象欣自获。","痛彼泉下台，永閟无生色。","微抑不见宣，苟存终何益。","席藁一上书，引领希察识。","苍麟代司阍，精卫声不隔。","倘返杨公葬，得从原阡侧。","焚山无馀怼，誓墓有遗则。","远愧密亲来，杯酒相慰藉。","鸿雁冥冥飞，焉知非谋食。","负耒安馀年，托心在兹迹。"]},{"t":"二月朔渡淮即事","f":"五言古诗","c":["江南芳欲齐，淮北绿初抽。","曾是一水隔，候至物不周。","回风荡枉渚，落日多惊流。","榜人告宵征，剌剌生百愁。","去棹若攀崖，来帆如赴湫。","大小各有营，贵在中所求。","庶卉趣春阳，枯荄亦怀柔。","兹请苟未谐，何以返故畴。","没为九原愧，存为高堂忧。","亦知鬒畏素，遘此不能休。"]},{"t":"归怀示舍弟","f":"五言古诗","c":["北阙书虽上，南山业堪佃。","吾弟沮溺流，耦耕亦何怨。","轩冕诚可悦，焉能舍余贱。","谬忝七子列，居然五君选。","去去勿复陈，深衷晚当见。"]},{"t":"旅梦作恶书此自解","f":"五言古诗","c":["沟壑偶不死，来为世人弄。","太湖七千顷，烟霞竟谁共。","残月将曙来，清钟应霜动。","殇子久已觉，彭聃犹然梦。","去去勿复陈，吾生有吾重。"]},{"t":"谒孟庙敬述","f":"五言古诗","c":["呜呼五亩宫，兹实英气聚。","长楸径天风，森然虬龙舞。","岂无枭鸱托，噤嗉不能吐。","翔鸾翼丹桷，蟠螭绣文柱。","中有贵者像，峄碧流眉宇。","礼犹素王亚，秩非客卿伍。","杨墨既廓如，仪秦亦微沮。","伊昔传食时，天开齐梁主。","其用不一究，归乃成万古。","诸伧何为者，瑱珠列周庑。","三复仁义篇，悠然配神禹。"]},{"t":"题九松卷赠张生","f":"五言古诗","c":["洛下九老人，采药徂徕山。","化为九松树，萧然压尘寰。","苍髯掀天风，赤足踏潺湲。","顾谓五大夫，惜哉多厚颜。","夫子从之游，不复叹才艰。","盘桓峭茜下，箕踞嵯峨间。","黄鹤呼欲归，白云时与闲。","况有千秋苓，青尔双鬓斑。","勿谓辟谷侯，孤风遂难攀。"]},{"t":"迫檄首路拟再陈情感怀有作","f":"五言古诗","c":["山公援侍中，实以世交故。","周子怨都亭，知为一官误。","余本解宦人，岩薮焉能固。","况兹回光瞩，差用洗沈愫。","栖迟犹二始，踯躅当三辅。","孟门苟已出，康庄知前骛。","款段终在枥，谁为讥蹇步。","铅刀冀一割，锋锷恐非故。","巨痛时磔心，深忧恒栖嗉。","露款一申言，皇览不反顾。","陨涕别亲慈，含辛首前路。","嗣章倘见俞，改服还韦布。"]},{"t":"移文两台乞休有述贻示舍弟","f":"五言古诗","c":["疲马始恋闲，饥马始恋刍。","全魏夹澶漳，兹实饶逸区。","上宰匪私人，迫若中所图。","众知蛾眉好，混沌独惊呼。","富贵等逝飙，况不与愿俱。","徇知时中奋，欲往复次且。","再疏若沈波，单辞倘见俞。","欧冶辨金材，纯钩冀为耝。","鸿雁东南栖，遗音杳以疏。","因风及斯章，兹秉亮不渝。"]},{"t":"连得故里书亲友逝者五六辈皆齿相亚为之怃然有感","f":"五言古诗","c":["日子启北辕，密懿遵江垾。","念昔火乍流，兹今冰未泮。","如何违盻间，相携就涂炭。","冥摄不待符，当暮宁容旦。","百岁若须臾，况乃未过半。","虽匪邺下才，能忘子桓叹。","浮荣诱人老，流景疾于窜。","慨靡黄金术，可以凌霄汉。","窃聆无生言，庶几叶幽玩。"]},{"t":"静坐","f":"五言古诗","c":["兹方信閒适，吏事随所遣。","白日偶属余，胡为但令晏。","渔猎千古间，所得亦已鲜。","空檐滴残雪，寒垆袅馀篆。","默坐无所思，悠然端倪显。","欲窥静者功，微青冒枯藓。"]},{"t":"谒阳明先生天真书院","f":"五言古诗","c":["杖策寻幽巘，叩祠荐清蘋。","木落群姿尽，烂然见天真。","轻风飘须眉，萧萧若有神。","三字抉灵机，万古意忽新。","六经遂糟粕，千圣失经纶。","媚川在怀中，舍楫问鲛人。","笑彼愚公山，老昧襄城津。","重恐鱼目多，冥然骄自珍。","所以老氏叹，圣作大道湮。","下学而上达，吾意书诸绅。"]},{"t":"芙蓉园为用晦赋","f":"五言古诗","c":["桃李媚春阳，容泽不终持。","松柏虽后凋，谁为发华姿。","神飙自西来，百卉俱变衰。","感此亭亭质，皎然溪之湄。","绿叶凌劲霜，朱华然素漪。","君子含章美，脩尚不傅时。","衡庐藩兹植，聊用以自怡。"]},{"t":"题马远十二水","f":"五言古诗","c":["上帝两带垂，长江黄河流。","昆崙触天漏，下贮海一抔。","震泽与洞庭，汇作东南沤。","风云出千变，日月浴双辀。","泓渟写秋星，萧瑟竞素湫。","木落清浅出，石压琮琤抽。","其细沫贯珠，巨者膏九州。","谁能传此神，毋乃宋马侯。","解衣盘礴初，已动冯夷愁。","天一臆间吐，派九笔底收。","生绡十二幅，幅幅穷雕锼。","惜昔进御时，陡豁神龙眸。","遂令大同殿，涛声撼床头。","六宫摄其魄，所以不欲留。","杨妹即大家，女史司校雠。","朱填六玉箸，墨宛四银钩。","锦缥赐两府，青缃润千秋。","晴窗乍开阅，如练沾衣褠。","恍作银汉翻，浸我白玉楼。","当其郁怒笔，楣表腾蛟虬。","及乎汩舒徐，遥颈延鹜鸥。","动则开智乐，渊然与心谋。","老思鉴湖曲，兴尽剡溪舟。","左壁桑氏经，右图供卧游。","那能学神禹，胼胝终荒丘。"]},{"t":"过修武有叹","f":"五言古诗","c":["淮阴下广武，张耳佐其师。","全赵俱胁息，彊燕自风披。","忽逢隆准使，赤节艴朝煇。","斥易两雄帅，脱若提婴儿。","剪楚朝奏勋，夕乃失临菑。","所以云梦游，遂成曲逆奇。","蒯武岂不藏，带砺乃吾欺。","纯心奉明主，加罪宁乏辞。","九族为君尽，千载令人疑。"]},{"t":"题远菉堂","f":"五言古诗","c":["我园初离薋，君堂仍远菉。","岂无女媭戒，恶草非所欲。","荣芝当自秀，艺兰当自馥。","出为王者瑞，处为幽人服。","锄莠虑伤禾，伐莽表嘉木。","兹意幸偶同，相将保空谷。"]},{"t":"经彭泽有怀陶公","f":"五言古诗","c":["陶公辞彭泽，亦复聊其生。","磬折岂足劳，而以事躬耕。","安能如旅葵，百谷产中庭。","鼎鼎百年内，贵在愿与并。","浊醪佐新诗，聊以娱性灵。","偶然获为人，偶获千载名。","名者自随之，获者安所营。","窃窥逸民言，令人愧浮荣。"]},{"t":"题振衣千仞冈为许给事寿","f":"五言古诗","c":["我爱许武仲，春风隘尧天。","脱屣岳牧尊，挂瓢清颍边。","君岂苗裔耶，谑浪青琐贤。","所遇稍不合，葛巾遂翛然。","角里复绮村，奕煜紫芝鲜。","峰峰足振衣，何必箕山颠。","名当傲千秋，身当傲百年。"]},{"t":"题丘户部汝谦吾兼亭","f":"五言古诗","c":["傲吏漆园氏，大隐东方生。","心冥故黜迹，机悟乃超名。","彼美司农子，夙有天倪盟。","彳亍握算间，跌宕文史声。","抱案揖长官，了若不相婴。","拄笏对西山，悠然有馀清。","识真垢不辱，贵我物自轻。","何必规往哲，吾以师吾情。"]},{"t":"钟太傅荐季直表真迹后","f":"五言古诗","c":["千古谈钟书，宣示乃其最。","宁知黄初载，兹表有真际。","初英丽朝阳，杂羽栖霞汭。","刚柔自成克，疏密各异趣。","始展恍若新，熟玩转相媚。","遂令临池者，往往无宣示。","得新多忘故，我则异于是。","周鼎均所宝，康瓠乃识弃。"]},{"t":"过定远问漆园不得","f":"五言古诗","c":["兹地有漆园，是否庄生庐。","遗迹杳莫存，遗言亦成诬。","北风捲地来，鹏翼寒不舒。","岂必真逍遥，能无爱枪榆。","不才惧凫烹，存者乃为樗。","令我何所据，瞿然思遂初。"]},{"t":"思归二篇 其一","f":"五言古诗","c":["朝辞孟门险，暮即金阊驰。","天路虽云旷，枳棘犹未夷。","人情好居薄，为厚安得谐。","朗朗日中天，浮云伏崦嵫。","问齿虽少馀，其舌尚未隳。","自非偏师济，焉能日衔枚。","进当明所繇，退则保无为。"]},{"t":"思归二篇 其二","f":"五言古诗","c":["汉网既弥天，万羽争见张。","朔风起不周，安能远飞翔。","凤皇虽五色，在罗焉得祥。","仰天一雄鸣，雍然中宫商。","豪鸷击鲜翰，觜距血纵横。","与子既殊德，畴见不相妨。","虽复化为鸠，耽耽未可量。","竦翼东南飞，天池浩茫茫。"]},{"t":"题沈启南画虞山致道观昭明手植三桧初名七星桧","f":"五言古诗","c":["白云团虞山，有七苍虬舞。","云当梁初代，昭明读书所。","虽干乾坤庇，实饱冰霜苦。","其四托狐鸱，帝遣六丁取。","存类矍圃三，去杀秦封五。","宋人雅好事，往往为之补。","颉颃若昆季，厥始实孙祖。","隆准理固当，小巫气终阻。","昨余游真宫，脱冠憩其下。","日落长风来，飒然精灵语。","及乎微月上，脩鳞森欲吐。","沈翁长康流，为桧传世谱。","不欲令汉杰，轻与哙等伍。","尺楮移秋山，真宰在阿堵。","蓬窗一展看，森阴洗烦暑。","何必称七星，三星亦自古。"]},{"t":"今岁忽已知命仲冬五日为悬弧之旦不胜感怆聊叙今昔得六百字","f":"五言古诗","c":["薄游狎流光，五帙俄已至。","今为悬弧旦，使我废朝食。","窃拊有尽身，自抆终天泪。","罢牙息众嚣，闭阁负馀惴。","离疏非冠日，通籍乃韶岁。","为郎典方迓，业已三上计。","比舍饶俊民，兴辞骛遥诣。","虽匪大国香，岂为当门植。","众嫭方奏淫，如何独求退。","栖迟三辅谳，屏营东秦寄。","雈苻既如浣，萧斧永绝试。","烈炎弥原来，玉石同迸碎。","龃龉缇萦书，艰危子坚祀。","扣阍不睹天，洒血空坟地。","岂无经渎念，处死殊以未。","流哀悴松柏，馀辱蒙萝薜。","屯夷理垂极，鼎革时初际。","皇瞩回覆盆，谷灰起幽吹。","徊徨深隐恻，踯躅窥慈意。","南舟遍楚越，北辕轘晋魏。","蓬心绝羝触，栎质惭鼯技。","畴谓偏奇禀，谬中通人嗜。","三台敢希历，九列无乃赘。","牵马似有曹，攻驹岂吾艺。","是时秋欲暮，天子问郧帅。","尔以中执法，其往司节制。","寻叨玺书宠，仍拜宫壶赐。","肃肃萃冠簪，悠悠度旌旆。","如何渭桥色，已作天涯视。","严霜逐飞盖，脩路疲征驷。","汉水擘峡来，嵾峰蹈空置。","褒斜绾单毂，井陉艰列骑。","偶同王遵叱，无取子阳喟。","片檄寝赤丸，尺箠走墨吏。","捃拾虞军兴，纵舍伸主惠。","窃窥宽大朝，因驿上封事。","愚得或有一，斯狂岂可二。","既采葑菲诚，复贷尸俎罪。","虽尔竭涓涘，何由报恩施。","芳已凋蕙兰，辛犹残姜桂。","揶揄路鬼讥，婵媛女媭詈。","策足趣暮闉，长鸣顿其辔。","甘为退飞鹢，不作骧首骥。","松柏偶然乔，宁因青阳媚。","誓墓今已乖，入宫频见忌。","谬陪七子列，恐为颜延弃。","虽谢三君后，未甘李膺易。","数往已自疑，揣来人同愧。","伊昔虞舜慕，五十犹不替。","惟彼曼容秩，六百旋请致。","而我独何为，心迹两成悖。","鬓讶蒲柳零，身安匏瓜系。","雕虫业久贱，小草名还细。","服政政欲疲，知命命何冀。","纵识去者非，焉睹来者是。","昔人多无闻，今余焉足畏。","秋叶旦暮零，亲知同飘坠。","江水日夜流，富贵亦偕逝。","驻颜问刀圭，多难损根器。","皈诚悟正觉，庶矣超人世。"]},{"t":"赠王詹事元驭","f":"五言古诗","c":["紫宫何崔嵬，袅袅干青云。","铜龙启枫阊，白虎荐衿绅。","委蛇谈经术，天颜再为新。","日晏始言旋，竹素良自欣。","乃知清旃上，不废箕颍真。","仪羽岂独嘉，渐当寄丝纶。","大化一以漓，鲁叟不易醇。","无为守至正，天下自归仁。"]},{"t":"答刘太常子真","f":"五言古诗","c":["离离道傍芷，随风即芬敷。","习习谷中兰，引分任荣枯。","众姱竞承颜，静女长独居。","临当趣君召，且复立次且。","顾念幽忧侣，携手命同车。","膏泽谢当年，蛾眉日夜疏。","发短不受笄，衣短不受裾。","亮无入宫妒，焉能令君愉。","贵者但不忘，贱者亦自舒。"]},{"t":"寄石大理拱辰","f":"五言古诗","c":["昔我游漳河，遘子结欢好。","穆生携其醴，邃古恣搜讨。","及乎承平日，子壮予亦老。","朔风吹飞藿，倏忽辞中道。","为合长苦晚，为别长苦早。","蒲柳不待冬，引分就枯槁。","寄言和氏璧，斯世方共宝。","为照当有时，有光且自葆。"]},{"t":"晓起独步沿荷池","f":"五言古诗","c":["初日乘馀霁，洒然酿轻凉。","近市喧未起，群动各相忘。","问我何为者，出门钓沧浪。","环以清浅流，枕以绿萝庄。","新荷欲舒翠，轻飙散微芳。","游鱼点点见，一鸟高低翔。","溯沿路不极，含轸与俱长。"]},{"t":"西园雅集为邺中诸王作","f":"五言古诗","c":["改服乘春豫，徵徒何缤郁。","苑薄孟门塞，椒崇邺河曲。","霞空散丛绮，风漪写文縠。","笳翻驯鹿至，棠漾轻鸥逐。","桂魄徂屡谢，兰膏禅相续。","东西迷席改，昏旦遘欢促。","搦管俱骛先，飞觞竞谋速。","王其梁陈轨，宾亦邹枚属。","名非履亢显，道以撝谦笃。","设醴知不衰，官今益汤沐。"]},{"t":"棘寺春集","f":"五言古诗","c":["肃肃廷尉署，蔼蔼滋春阳。","薰风自东来，吹万悦群芳。","幽花媚和色，绣柏辞玄霜。","化永公府寂，政简初日长。","振策从英乂，幸遘此高堂。","雍容盛冠佩，朗郁森琳琅。","情至分欲舒，道迩契自彰。","暂言谢纷嚣，高揖称虞唐。","白云流飞觯，回景就移床。","檐际鸟上下，雍声效和鸣。","佳辰岂不欣，无乃流太康。","职思寅恭义，载申伐木章。"]},{"t":"西山道中候于鳞不至","f":"五言古诗","c":["弭驾登崇椒，回眸注遥鞅。","山谷日苍苍，寒蝉振悲响。","修途浩无端，征车递来往。","顾此尘中士，胡然殢余想。","聊失在须臾，浩如隔云壤。","意子或见迟，踟蹰两相向。"]},{"t":"仲夏昌平道中","f":"五言古诗","c":["初阳鸣仓庚，仲夏气清淑。","东风荡平芜，如剪湖水绿。","微流萦客骑，远饷附村犊。","妇女四五人，来刈麦禾熟。","农事岂不疲，欢言得所欲。","鸟雀呼相啄，馀喧在乔木。","行役多自愉，胡为悲局促。"]},{"t":"秋日过于鳞郡斋分赋十体得发字","f":"五言古诗","c":["入门登君堂，筐篚相罗列。","大妇治酒浆，小妇为炊食。","儿年十五馀，冠裳来肃客。","感君缠绵意，含吐待君择。","袖中双骊珠，光辉同秋月。","恒恐风雷掩，重襺不得发。","念当为欢始，胡言悲乖别。","河汉经高天，牛女成岐阔。","非无深宵契，曦晖难为悦。","列宿繁如雨，焉知中所结。"]},{"t":"秋日垂暮郊眺有感","f":"五言古诗","c":["迹往忽若冥，念来浩无倪。","遨游将抒抱，更使中不夷。","东轮背西鞅，荒楚属中逵。","芊眠平芜合，郁术浮云驰。","回首崦嵫湛，恍睹皇乾卑。","赴暝无停色，嘘枯有馀悲。","饥兔走顾罝，倦鸟详恶枝。","岂不怀休饭，虞在罗伏机。","奈何服明哲，俛首就衔羁。","大火弥原来，焉能以瑾辞。","龙战遗园绮，鸿冥辨孙嵇。","神龟安曳涂，雄鸡惮为牺。","冯生超自洒，人理其庶几。"]},{"t":"秋日与诸大夫登后湖阁宴眺有述","f":"五言古诗","c":["崇丽多挛局，置远足徜徉。","岂若登兹阁，二美适有当。","高栋切天居，华燕冠文昌。","凉飔躏嘉荫，落日暴崇冈。","千甍波鳞踊，双阙风翼张。","驰道东西直，轮鞅正纵横。","俯瞰澄湖波，皎若明镜光。","凫鹥下游鬣，菰稗出收潢。","虽无方舟具，兴至欲褰裳。","望舒随阳没，银灯嬉未央。","上客袭主权，行筹浩无方。","徒御私相谪，毋乃沦太康。"]},{"t":"赠况生药湖别业","f":"五言古诗","c":["兹湖信灵境，灵境贵所招。","维昔真人居，药就凌璇霄。","旗峰感女泽，环江导宾潮。","湛符填簸荡，遗砂寿肖翘。","至今清泠府，万象不得骄。","恍若太阳升，神丹现中宵。","金波迎潨射，玉衡澄泬寥。","枉汭款柔飔，阳荑配阴条。","天鸡忻孳育，朱鲤恣陵跳。","披岩肉芝长，犯雪黄精苗。","秀郁钟故奇，象胜理自超。","况生结精庐，窈窕临湖皋。","杯中泻云物，镜端行渔樵。","亮无晨风翰，偕子以逍遥。","勺水甘谷如，服食等松乔。"]},{"t":"游西山诸寺有感","f":"五言古诗","c":["西山二百寺，蝉缓琉璃刹。","其人中贵人，往往称檀越。","银汉割岧峣，珠宫斗巀嵲。","吐磴穷百盘，束流规千折。","蹙阶白玉尘，飞坐黄金屑。","斗削神力回，向背鬼工绝。","世尊趺青莲，妆严明秋月。","龙象左右陈，罗叉后先列。","我闻说法时，乞食仅一钵。","誓以不住身，普代众生孽。","长者虽布金，小果那得说。","柰何贪嗔念，希与圣谛结。","填沙南赡髓，饰像恒河血。","净土炯自如，广轮虚真辙。","呜呼西竺冤，万古谁能雪。"]},{"t":"岁暮自檀州发赴青州有述","f":"五言古诗","c":["奉期戒輶车，含辛拜严闑。","密戚追告途，新知来要辙。","是时冬向暮，微阳生阴冽。","断莽吐伏流，隐林遁馀雪。","麇趣纵横文，鸟革凄厉舌。","苍苍界飞素，暧暧动幽悦。","萦回中陂幰，遥裔前坰节。","之齐踪稍畅，恋魏慸犹结。","载讽陟冈言，终惭贲丘哲。"]},{"t":"夜起步中庭有感","f":"五言古诗","c":["罢酒出中逵，皓魄起前楹。","始见衔半规，稍稍渐成盈。","积雪焉藏照，天地吐馀清。","恍若玉龙飞，乔松郁峥嵘。","羁雌无停影，号雄有求声。","狐貉虽被躬，旷士中不胜。","安驾双鸾翼，并起翔天京。"]},{"t":"春日于西园望云门山有述","f":"五言古诗","c":["巨灵擘碣石，置之营丘东。","千秋窍混沌，间道开玲珑。","渐迩秋魄圆，稍迈晨星融。","流云时停憩，返景并垂空。","伊余怀禽好，之官偶齐封。","羁服含馀责，推案厌微躬。","曾是咫尺遥，故以简书慵。","行药步周畦，披襟延绪风。","倏如团鉴色，恍落清尊中。","蚀雾俄半规，吹飙豁全通。","靡靡呈苍翠，蔼蔼盈房栊。","数足无登轨，寓目有来踪。","峻陟淹徒御，卧游藉人工。","何如日箕踞，于此玩无穷。"]},{"t":"初夏西园偶成","f":"五言古诗","c":["铃阁何沈沈，初阳启烦嚣。","讯谍纵横至，群咻递相要。","虽靡片言才，往往不崇朝。","躧履向閒除，移床就繁条。","景风徐将拂，池荷乍与交。","绿竹吐新劲，黄鸟展馀骄。","诗书安其所，尊酒自为招。","送日未毕欢，来暝复携劳。","仕隐俄更荡，动静竟难调。","持镜问朱颜，那能忘不彫。"]},{"t":"雨后小酌西园 其一","f":"五言古诗","c":["业岫停阴润，遥空结层冥。","好雨东南来，媚我园中英。","下泻方池水，清文自然生。","荷盖亭亭出，圉鬣亦纵横。","中有双游鹜，延颈发欢鸣。","幽壁青莓苔，枯荔蒙其荣。","大小各自私，焉知皇泽平。","举爵吟微谣，聊以写余情。"]},{"t":"雨后小酌西园 其二","f":"五言古诗","c":["微雨中稍怿，按畦披榛莽。","群秀欣相托，悠然动真赏。","帙掩且罢开，尊来不虚往。","半酣凌层岛，冀以弘遐想。","屯阴弥在目，大埏无隙朗。","回看墙东蔓，胡乃先蕙长。","习习笼中翼，终成怨初网。"]},{"t":"初晴园亭即事偶书所怀","f":"五言古诗","c":["天地意无常，吾人宁久安。","今兹幸休暇，聊与为盘桓。","绪雨就归飔，微阳来湿翰。","箕颍匪在遥，步武生云端。","顾见清池影，茫然愧衣冠。","区区丹阳设，欲以敌东山。","不见先民语，富贵多忧患。","忧患从机发，那得借馀欢。","乔木恶崩崖，根株离见难。"]},{"t":"雨饮李氏伯仲草堂遣谢","f":"五言古诗","c":["负郭偃衡茅，停车遣幽讯。","隐侯竹间出，难弟墙东引。","耦耕及新麦，对漉饶夙酝。","改白王弘衣，冀青阮公瞬。","密雨战炎歊，初凉乘时进。","散沫染空阶，馀膏惠脩疄。","慈明既外朗，叔慈复内润。","玄言万飞屑，令色双联瑾。","愧以干旄旋，更为薜萝信。","早晚床头篘，愿言无所吝。"]},{"t":"庭有积雪指麾儿辈戏为雪山偶作","f":"五言古诗","c":["怡步向中庭，积雪何皑皑。","战日愈自坚，依飙渐成堆。","虽靡化人术，倏忽三峰开。","削成像仙掌，横度为天台。","更疑双灵鹫，一夜自飞来。","东风澹荡吹，对尔酒一杯。","不知吾与尔，玉山谁先颓。"]},{"t":"风日清美行园有怀吴峻伯率尔折简","f":"五言古诗","c":["亭午气清和，西园行挟策。","阶藉葳蕤红，窗延纵横碧。","时禽骄孤迈，芳草妒新迹。","慨然怀良友，胡为但役役。","刀笔余啸歌，诗书子徽纆。","博谷声条桑，永晷不重得。","愿言携琴至，呼尊命所适。"]},{"t":"泰安即事呈同事诸君 其一","f":"五言古诗","c":["忽闻谒台去，颠倒揽裳衣。","不知褦襶子，规腰何所师。","含吐将及唇，瑟缩未成辞。","流汗纷如浆，袖手不顾挥。","委蛇将出门，归我旧须眉。","轻风发微凉，白日已崦嵫。","张宴陈钟鼓，为乐不逮时。","北山有岱宗，南山有徂徕。","溟海中相隔，步武竟焉之。"]},{"t":"泰安即事呈同事诸君 其二","f":"五言古诗","c":["琼台双文篚，上有五色芝。","纤月承卿云，炜煜霞文披。","藉以流黄绮，贡之白玉墀。","违性虚见珍，虽贵非所希。","不如南山柏，千载长如斯。"]},{"t":"于役淄川途遇大雨有述","f":"五言古诗","c":["冥冥乾维改，殷殷坤轴摧。","女风嘘阴穴，族云布阳台。","海色二有合，嘉霖四望来。","玄鹳引吭鸣，游鱼矫鬐回。","萎叶贪故柯，柔苗媚其荄。","裳衣既颠倒，车马亦虺隤。","迂辔就衡门，野父进我杯。","请以甫田诗，宽彼东山怀。"]},{"t":"初夏晨起","f":"五言古诗","c":["初阳组林茑，轻飔衣屏障。","草绶生绿滋，筠阴捲清浪。","间发阴鹤和，时流黄鸟唱。","旷矣物不接，嗒然吾将丧。","虽靡向禽达，颇怀张邴放。","一命羁所之，千秋郁微尚。","郤案更沈吟，沈吟滋惆怅。"]},{"t":"过潍县故孔北海祠作","f":"五言古诗","c":["威凤虽在罗，耻与凡枭近。","神龙刬其角，目固无鲛蜃。","火垂赤帝灭，风犹素王振。","角总吐英谈，冠弱流乂问。","平原援中绝，北海诚空奋。","艰难傍馀爝，廓落甘异摈。","交祢岂慕狂，拒郤焉为吝。","巢倾卵俱覆，梁逝室亦震。","反谐鄢陵祝，不睹山阳恨。","余本骨体人，千秋凛遗荩。","高咏长寝篇，分香随澌尽。"]},{"t":"薄暮东牟道中有作","f":"五言古诗","c":["策骑缘海壖，兴发遂忘疲。","将晞九阳发，思振三神衣。","如何悲泉侧，阳乌欲罢飞。","川后约其波，以待朱轮归。","柳色有遗景，梓里无停晖。","空青就磨灭，光景向熹微。","二气既不分，吾人安敢违。","改辔趣林薄，命烛叩衡扉。","有酒但为欢，无酒且息机。","天鸡在东方，三鸣不须斯。","庶哉咸池浴，万象同赫羲。"]},{"t":"初至登州就台小憩","f":"五言古诗","c":["陆走费轮蹄，暑征困衣领。","浃旬嵎夷造，乃使烦虑屏。","税微公牍简，讼折人吏静。","海气蠲夙苛，山风荐微冷。","庭葵悄然落，小雨殢远景。","篇留浩荡域，酒引无何境。","卧起俱所适，低回发沈省。","彼烦焉终却，此逸宁遂永。","窃禄在牵丝，援阶类汲绠。","颜腼久京洛，心掩谈箕颍。","千石幸未踰，吾其从小邴。"]},{"t":"按部东海因怀鲁连逃迹慨然有述","f":"五言古诗","c":["溟色饶奇变，云岛相荡擗。","中有真人居，将无鲁连宅。","先生犹龙哉，夭矫物莫测。","灸輠辩与生，转丸机从匿。","抗辞折新垣，秦众外辟易。","飞书射聊城，燕将内捐嗌。","引危励安平，一鼓坚城坼。","提衡万师力，弁髦千金锡。","散发东海隅，肆志随所适。","他日圮上编，毋乃而黄石。","我欲竟其终，青天杳无迹。"]},{"t":"余游蓬莱阁睹弹子涡石因记苏长公一章歌之与参政姜公共拾取数十枚为玩遂戏效其体作数语书付道士并呈姜公公前身为白玉蟾高弟解服食法其有以教我","f":"五言古诗","c":["昔闻蓬莱顶，神仙好围棋。","争道不相娱，散掷东海湄。","海若鼓锋涛，为汝作玉师。","历落涵天星，皎镜支汉机。","数惊骊龙顾，或起陵阳悲。","我无菖蒲根，杯水浴置之。","岂必真壶峤，方圆亦参差。","宇宙在一掬，芥子为须弥。","姜侯蟾翁裔，服食夙所宜。","他日访三神，煮以疗吾饥。"]},{"t":"弥陀寺饭僧作","f":"五言古诗","c":["结夏依寂居，随缘憩脩轸。","宅惭周颙舍，米待郗超损。","僧衬鸣钟集，佛供导幡引。","霜研给孤麦，玉琢摩候菌。","慈禽恋清呗，怖鸽驯馀赈。","敢持有漏因，仰觊无生忍。","曾是夙力馀，内观了何朕。","追往踪既失，希来业难尽。","毋以罪福求，幻身同兹泯。"]},{"t":"弥陀寺遣暑作","f":"五言古诗","c":["岩泉饶奇趣，松柏寄远迹。","如何孤兰若，局蹐四蓬壁。","慈云不垂荫，朱离苦相射。","赫矣尼连火，邈哉阿耨泽。","四大久厌离，诸缘归灭寂。","是以烦恼身，更称清凉宅。","夜梵流妙音，朝观离空色。","窃从庞居士，巾发恣所适。"]},{"t":"早起","f":"五言古诗","c":["初月将曙辉，亭亭澹空碧。","微星渐以隐，存者犹历历。","玄蝉乍停号，宿羽时鼓翼。","时至钟未鸣，僧懒更成寂。","乃至欲观心，悠然不可得。"]},{"t":"听夜呗作","f":"五言古诗","c":["斋饭依八关，昏钟警诸妄。","陈王演真呗，深公吐玄唱。","清波徐潆洄，法雨渐调畅。","振如迅霆激，细若游丝飏。","哀籁流凡听，圆机转天吭。","我闻青莲坐，妙法宣无上。","魔王戢怨刃，龙女倾爱藏。","如何旃檀刻，不睹梵音相。","稽首悲宿因，誓心驱来障。"]},{"t":"晨起新城道中","f":"五言古诗","c":["野宿无淹寐，蓐食焉待饱。","主人戒鸡鸣，驱我就中道。","行徒非古欢，惴惴来就保。","隙月隐若窥，风林窣相恼。","严霜白于雪，照我颜色槁。","不恨颜色槁，但恨不自老。"]},{"t":"初春同俞仲蔚及舍弟敬美登马鞍山得四首以山高月小为韵 其一","f":"五言律诗","c":["落日犹命屦，爱此城内山。","初携惠连往，寻以长瑜还。","清磬杳蔼外，行人苍翠间。","扶酲过邻圃，独树梅花閒。"]},{"t":"初春同俞仲蔚及舍弟敬美登马鞍山得四首以山高月小为韵 其二","f":"五言律诗","c":["危坐揽群秀，天风吹布袍。","吴江疋练白，泖塔孤茎高。","斗酒寒不醉，剑歌短益豪。","谁怜今仲蔚，此下有蓬蒿。"]},{"t":"初春同俞仲蔚及舍弟敬美登马鞍山得四首以山高月小为韵 其三","f":"五言律诗","c":["冯策凌绝崖，呼觞陶嘉月。","疏林叩幽牝，泠然中心悦。","暝色坐来改，飞鸟时自没。","望望逼城嚣，徘徊不能发。"]},{"t":"初春同俞仲蔚及舍弟敬美登马鞍山得四首以山高月小为韵 其四","f":"五言律诗","c":["久矣甘尘栖，兹焉忽世表。","披襟当澹荡，纵屐探窈窱。","落日樵采竞，归路牛羊小。","何以见幽悰，入门后栖鸟。"]},{"t":"游惠山酌泉次唐人韵 其一","f":"五言古诗","c":["穷溪回崇巘，午色正苍苍。","上有千尺松，下有古时堂。","幽籁相间作，止鸟顾我翔。","乳窦溢清漪，杲日媚其光。","眉宇澄秋色，齿颊散天香。","念彼寻源人，慨然不能忘。"]},{"t":"游惠山酌泉次唐人韵 其二","f":"五言古诗","c":["落日饶远态，群象来趋人。","酌此涧下泉，爽焉各怀新。","暗壑穿文流，白石何磷磷。","岂不念远达，行当委时尘。","洗耳卧空山，抗志薄青旻。","頫仰千古士，思与巢许邻。"]},{"t":"游惠山酌泉次唐人韵 其三","f":"五言古诗","c":["精若栖林端，芳泉伏萝樾。","躧步信所之，渐与人径绝。","顾见潭影空，恍然超生灭。","叩斧斲涧云，负铛煮山月。","朗咏三君篇，清商四垂发。","千秋庶可要，与子偕首辙。"]},{"t":"避暑大兄山庄作","f":"五言古诗","c":["烦暑意不怿，聊适在山池。","阳崖饶轩豁，阴谷吐寒飔。","脩竹藩广除，落英文素漪。","鱼鸟各有得，余亦遂忘疲。","觞奕送归阳，返颍射东坻。","蔼蔼桑榆影，履舄任参差。","寄言邑居子，笼翮安所之。"]},{"t":"初秋屏居有感","f":"五言古诗","c":["偃息衡门下，旦夕寡来躅。","澄露将微风，披洒中所欲。","外苛稍已蠲，畴能解中燠。","玄蝉高树间，哀吟递相属。","不念金气厉，令我白日促。","循往心既乖，慨来身如束。","顾视庭之幽，兰芬一何馥。","幸免当门锄，居然安空谷。"]},{"t":"冬日集舍侄一敬所作","f":"五言古诗","c":["今辰风日佳，言集仲容庐。","是时岁功毕，场圃方告舒。","新篘嘈嘈鸣，黄鸡啄相趋。","罗者欢得凫，网者欢得鱼。","野人慕口腹，一饫不愿馀。","顾见斜阳影，蔼蔼媚桑榆。","群从更乐端，迭起求自踰。","但酌令我酣，悠然渐黄虞。","奚必青衿子，矩步诵诗书。","世有中圣人，舍我其谁与。"]},{"t":"章道华见访田居作","f":"五言古诗","c":["抱影寒庐下，春风怡然来。","问言何为尔，有客访蒿莱。","田家无夙供，鸡黍差足陪。","斗酒相劳苦，慷慨兴往怀。","抚衷虽难偶，循迹幸未乖。","携手望白云，海色正崔嵬。","因君明漆胶，友道谁终谐。"]},{"t":"閒居偶然作","f":"五言古诗","c":["晏坐无与适，叩门亦不至。","残叶时自扫，归云如相迟。","颓阳坐来永，依依昔邪际。","久矣城市间，始与懒一会。","佳境恍有得，稍焉竟茫昧。","寄言尘趋子，安知此中味。"]},{"t":"小除夕归途遇风雨作 其一","f":"五言古诗","c":["今朝风雨色，凄其成岁暮。","谁云望不迥，出门即非故。","我马既玄黄，仆夫将焉诉。","抚壮能几何，悠然怀往路。","茫茫百忧集，安为鬒不素。","稍明来者日，空悲昔者误。"]},{"t":"小除夕归途遇风雨作 其二","f":"五言古诗","c":["流雨泥我足，北风创我肌。","令我朱颜改，使我含辛悲。","举目见羊肠，日暮安所归。","黄芦杂苦竹，哀声鸣相和。","上有独栖鸟，下有长逝波。","归家犹云尔，离家将奈何。"]},{"t":"和仲蔚元日诗","f":"五言古诗","c":["衡门启初旦，冉冉岁行益。","节序人自欢，焉为同余寂。","块然守一室，惆怅将至夕。","天地虽更始，人生无终极。","念欲昉乐端，忧怀纷如积。","来者日以新，谁能返畴昔。","余生愉在野，披睹中有获。","托素毫翰林，千秋垂金石。","逢掖足禦寒，岂必尽狐白。","兴言实起予，偕子臞山泽。"]},{"t":"暑懒 其一","f":"五言古诗","c":["一暑生百慵，一慵百事简。","偃息衡门下，悠悠梦初转。","亭午鸟倦啼，槐阴自舒卷。","时有凉风来，泠然忽称善。","勿谓羲皇人，此意知者鲜。"]},{"t":"暑懒 其二","f":"五言古诗","c":["凌晨何所道，匡坐但调息。","客至了不关，眠者当分席。","围棋白云墅，采莲明月泽。","此赏非不领，烦暑将焉适。","秋至暑会舒，吾懒终何如。"]},{"t":"暮坐蓠薋园即景一首","f":"五言古诗","c":["高斋语来瞑，偶尔成幽憩。","峥嵘石色古，窈窕川流细。","新月在疏篁，娟娟自相媚。","顾此群籁寂，恍焉睹真际。","欲叩俄已忘，呼杯但成醉。"]},{"t":"季生夜猎不获一鲜赋此嘲之","f":"五言古诗","c":["翩翩季公子，被服何轻蹻。","骑从若浮云，行猎至我郊。","是时冬始仲，日暮黄云高。","罝网布原坻，左右建重茅。","暝立负玄霜，令严寂不嚣。","老狐饶先知，狡兔远伏逃。","虽欲纵群骁，争先安所操。","俄从灌莽间，稍辨东方鼌。","人马无光辉，饥犬顾我号。","东邻少年儿，竿杪置黏胶。","戢身一指顾，百羽遂充庖。","日入胡姬馆，灸鲜奏醇醪。","公子诚豪鸷，兹役不得骄。"]},{"t":"将游漆塘山汎五里湖作","f":"五言古诗","c":["放舟信所适，爱此湖中春。","春风剪澄眸，流光如盼人。","轻讴起閒羽，柔橹潜修鳞。","白云何方来，英英间青蘋。","四壁千芙蓉，回波散嶙峋。","寓目了无涉，适已中自亲。","顾彼微阴移，慨然眷芳晨。"]},{"t":"舍舟步漆塘山竹松间作","f":"古风","c":["亭午维芳涘，改策探要眇。","去美令神适，来奇信天造。","??伏泉流，湿我山中屩。","遁羽时自名，幽花炯相照。","清飔浮筠菉，白云弥松茑。","峭茜菁葱色，时复栖眉表。","回顾誇其俦，听然起微笑。"]},{"t":"登漆塘山绝顶望太湖作","f":"五言古诗","c":["逶迤导绝顶，旷朗澄心颜。","襟带萦吴楚，表里见湖山。","长风散庵霭，遥岭若连环。","出没一气中，变幻俄万端。","高天蔚浮蓝，黄金错其间。","静闻渔唱起，暝见孤鸿还。","长啸招䲭夷，缅邈不可攀。"]},{"t":"奉释典诸部经于小祗园藏经阁中有述","f":"五言古诗","c":["方广宣妙觉，总持谛真乘。","白马叶休期，金人肇奇祯。","伤哉末教日，圣泽渐以凌。","冥迹蹈恒河，狂飙吹慧灯。","我友条净业，慷慨惠函经。","奚必具羯磨，居然一摩腾。","小果固有漏，法施良足凭。","虽靡布金田，幸依化人城。","苍松云瀰滃，脩竹风琮琤。","层阁临广除，回流激清泠。","闼婆陈天乐，龙藏郁飞腾。","中有慈悲相，恍发妙音声。","玉笈启缃缥，流纨染翰青。","彷佛贝叶端，自然莲花生。","如日悬中天，万象借光明。","稽首两足尊，发此希有诚。","破除诸疑网，摧伏群魔兵。","前因获心通，后果希胜增。","愿以一切智，回施一切情。","巀嵲西逝梁，金篦导前行。","凡圣同超解，怨亲归合并。","执离文字间，犹为道所憎。","曹溪倘吾许，筌蹄讵堪徵。"]},{"t":"十三夜步月过邻家饮作","f":"五言古诗","c":["抱痾适不乐，强起无何时。","念此月色佳，那能恋床帷。","徐步叩东邻，觞席犹未移。","有酒但斟酌，焉问主人谁。","奇阴间木石，幽光蔼庭墀。","浴魄冰壶中，藻荇互参差。","泠然清声发，安辨竹与丝。","大化冶寓形，忧乐不须斯。","顾言隗俄际，所得其庶几。"]},{"t":"十四夜复步月过从弟饮作","f":"五言古诗","c":["秋气日以佳，秋月垂当团。","晚获徒步趣，相与复盘桓。","剥啄惠连门，揽衣不及冠。","呼妇出斗酒，手自裁肴餐。","素旻溢清波，炯然濯肺肝。","慨兹人间世，所受殊已难。","安能需令节，谋客始为欢。","白露下沾衣，北斗自阑干。","远树出严钟，隐隐将就残。","抚枕追往境，怅焉浩无端。"]},{"t":"十五夜于小祗园坐月作","f":"五言古诗","c":["纤阿应嘉候，祗园依化城。","感此牟尼珠，扬光濯清泠。","梵天白银桥，恍若燄摩升。","清溪相环带，空水互晶荧。","飞觞无遗憩，流霞湛然盈。","顺风奏丝桐，袅袅发奇声。","青松为我和，白云为我停。","酒德将调浃，颓然玉山倾。","披襟纳虚爽，万境皆光明。","安能守空观，枯寂送馀生。"]},{"t":"十六夜月徐荆州见枉作","f":"五言古诗","c":["欢宴申遥夕，疲薾辞请谒。","故人从东来，今我思超忽。","聊携一尊酒，相与陶嘉月。","熹微破泱漭，冉冉出丛樾。","是时初踰望，清可鉴毛发。","虽复表亏端，幽晖殊未歇。","玄鹤寥戾鸣，肃然惩栖鹘。","敢以斗柄斜，辞君玉壶竭。","携手仍与旋，清言至明发。"]},{"t":"秋日蓠薋园即事作","f":"五言古诗","c":["兹地不数武，亦复具池台。","亭午欣鸟雀，初凉愁草莱。","恍然石色古，乃是微云回。","竹润遥相借，兰芬时一来。","客至但坐耳，相对亦悠哉。","礼岂在巾帻，懒不废尊罍。"]},{"t":"秋日小祗园即事作","f":"五言古诗","c":["幽竹藩行径，客来无送迎。","石梁横秋色，高阁延远清。","爱此脩日景，弥耽静者情。","时探诸品毕，不省何经名。","微微甘雨至，稍稍凉风生。","迟暮且莫返，与君听松声。"]},{"t":"嘉禾道中","f":"古风","c":["方春爱行役，因与陶嘉候。","燕尾碧相袭，鸭头青始皱。","轻风怜舟师，为我来往奏。","收帆杨柳色，沽酒夕阳堠。","有友四五人，倾觞如悬溜。","丝鲙出网鲜，乳臇伏巢?。","扶兴端互起，谋欢策争售。","问余倾玉山，应须堕月后。","頫仰人间世，所得良不偶。"]},{"t":"海上访王子不值追会嘉禾道中斐然投作聊此志酬","f":"五言古诗","c":["芳波初成绿，柔杨亦已荑。","乘此嘉淑候，慨然效安期。","川涂虽绵邈，未获展光仪。","前维悄然发，后舸日夜追。","朗曜隔浮阴，景风为我披。","携手登巍堞，赠我以新诗。","彪毫等霞绚，溢齿若川驰。","辨胜晷欲流，神王鬒不移。","斐然见狂简，余归将庶几。"]},{"t":"吴兴访徐子与庐次作","f":"五言古诗","c":["溪回翠相袭，峰转青若招。","西日残危堞，东风进轻桡。","玄居在市廛，心清息诸嚣。","图书尘苫壁，素旐何萧萧。","念子虽茕然，犹能明久要。","生死非异岐，浮沉信所遭。","篝灯照华丝，斗酒为我劳。","因怀阮嵇尚，悲至讵能消。","引领俟明发，援笔摅长谣。"]},{"t":"海盐石堤与周生辈观日出作","f":"五言古诗","c":["日者万物母，海为百谷王。","两雄未荡摩，众有皆摧藏。","天鸡警宵发，波臣导余望。","穷纮露黝紫，极际见青苍。","回首顾中原，破睫犹茫茫。","倏忽金轮升，流光浴扶桑。","一发界灙漭，万鬣竞纵横。","湛湛天酒晞，煜煜云旗张。","波将骇骏上，猋与蹻龙翔。","无复虞濛泛，阳德炽方昌。"]},{"t":"伯父静庵公山池一首","f":"五言古诗","c":["昔我游兹园，申慕憺忘归。","园景非一态，事事令人怡。","白云团幽荔，朱卉冠阴崖。","疏沼延夕星，裁篁导春澌。","潜鳞乘吹起，宿羽应候啼。","谋奇开新术，戒返惑故蹊。","涧饮分霓渴，馆宿逊霞栖。","束帛违丘贲，悬金厌时夷。","去家不廿载，陵谷忽中移。","前逵改宿茑，后堂滋旅葵。","灌木代丝弦，宫往商不之。","回盻追前邈，抚景虞后衰。","所以羊钜平，游岘发清徽。","复闻桓司马，攀条泫然悲。","寓形靡不消，垂言将庶几。"]},{"t":"避痾山池月夜群从中有携酒至者即事作","f":"五言古诗","c":["兹辰负末痾，适与余懒会。","客来或不冠，客亦恕余意。","圆月从东起，神飙能徐至。","尊酒与盘飧，阿平诚知事。","语笑岂必佳，往往得真际。","时复邻笛声，乘风破遥裔。","去者勿复辞，陶公陶然醉。"]},{"t":"将游阳羡过华明伯饯我惠山因憩俞氏园一首","f":"五言古诗","c":["日余淹薖轴，托志在延搜。","遵途告密戚，饯我以行游。","选胜岂必遐，贵在获所求。","青松夹长坂，菉竹被文流。","探蠡酌清泠，沈慅洒然瘳。","层霞缓川暝，归日使径幽。","流憩仲蔚居，时兴浚冲愁。","昔揽并大藩，今守各一丘。","寄言天路者，寥廓多沈浮。"]},{"t":"发自义兴由东九抵湖汊一首","f":"五言古诗","c":["扬舲出荆溪，溪流浩无尽。","畴谓当萧辰，青山吐馀润。","惊鳞发潜响，振羽横遥瞬。","时见空翠来，焉知余榜进。","乔木生午烟，场禾表秋信。","茶叟携筐归，行歌渺然近。","顾余若有适，壶浆当为引。","明发从此辞，中宵衣时振。"]},{"t":"由张公后洞出前洞一首","f":"五言古诗","c":["冥搜出天巧，遐尚穷真域。","猿饮迫相辅，鸟伸骇所获。","金膏时自闪，琼乳静还滴。","窥天一线杳，察坠千鳞坼。","云烹丹灶温，芝耕石田瘠。","信足如已穷，俯身忽中辟。","浴日万象开，琉璃成五色。","芙蕖冠瑶柱，玫块填萝席。","缔搆疑化城，阴森恐蛟宅。","张公何为者，自言得灵液。","千载垂空名，其人郁为腊。","摄衣云霞颠，矫首三叹息。"]},{"t":"出张公洞经游玉女潭一首","f":"五言古诗","c":["疲足辞幽界，敞目凌玄都。","篁翠上交天，枫丹时缀涂。","高霞冠璇表，流飔荡银铺。","躧步瞰澄潭，恍若遘神姝。","青崖覆萝发，绀水湛明矑。","神往境自超，象胜理亦愉。","匪耽交甫好，冀与禽尚徂。"]},{"t":"探龙湫因观古琼树一首","f":"五言古诗","c":["素秋送馀晷，深山饶伏奇。","贾勇若无先，独造中所私。","纳云穿奇搆，画石置清漪。","天规隐䆗窱，壑舟入逶迤。","拊足唱高音，泠泠逗幽崖。","脩干吐潜虬，舞蛟出惊枝。","昔贤歌琼树，今我复来兹。","俯仰千秋意，泫然令心悲。"]},{"t":"归自东九汎西九访善权寺一首","f":"五言古诗","c":["归榜意不释，爱此澄湖晖。","白云何英英，荡潏令波肥。","所遘饶新境，沿洄遂忘疲。","改策向精兰，散履蹑青坻。","脩苍摩天风，潜翠沾人衣。","裁霞竦飞构，攀汉纳危扉。","左洞殊泓渟，下有鸣声悲。","兹赏未云饫，来奇信弗违。"]},{"t":"游善权洞作","f":"五言古诗","c":["巨灵两蹠拓，混沌七日开。","阴崖忽中敞，万巧纷然来。","廓如白玉堂，瑰柱芙蓉楣。","天酒滴历垂，石燕纵横飞。","泫泫含雾华，烁烁衔沙玑。","靓深时中赏，旷朗使众怡。","仙掌瞬若招，便嬽胜柔荑。","谓我为王烈，授我赤石脂。","灵境难久即，怊怅以徘徊。"]},{"t":"善权水洞一首","f":"五言古诗","c":["出幽托奇秘，荐至谐智乐。","朱华嵌岩椒，白云团衡壑。","群溜何泠泠，争往若有托。","奚必中宫商，噌吰即天乐。","飞空浥苍翠，悬沫成丹雘。","灵禽啁唽言，神鳞时腾跃。","空色鸣沿溯，微寒生回薄。","逝欲偕琴高，周身鲜灵药。"]},{"t":"碧云寺泉","f":"五言古诗","c":["苍龙戢其首，日夜漱寒玉。","助尔松风声，借之竹色绿。","时从斋厨下，泠然注空谷。","自爱穿云多，焉知出山浊。","一酌聆斯言，徘徊怆心曲。"]},{"t":"夜泊虞山下","f":"五言律诗","c":["明当向城府，维舟此山足。","奚必遂登临，聊以驱吾俗。","初月未拟规，浮云更成璞。","酒罢独何为，移书就残烛。"]},{"t":"金焦饯戚都督作","f":"古风","c":["大江耸金焦，兹实界宇甸。","圣灵深推毂，懿好将离燕。","春酒挹千流，崇肴指双巘。","柘鼓?晴雷，绮帆衡惊电。","回睇铜柱标，苍然天一线。","极目龙沙南，紫气出葱茜。","慷慨豫州楫，飒爽褒公箭。","分躯应北扫，馀烈留南填。","宾僚富词俊，文酒要酣战。","燕石尚可铭，畴当为君先。"]},{"t":"初至杭左史郭公右史莫公邀宴西湖大风雨归作","f":"五言古诗","c":["钱塘帝都会，西湖地灵杰。","天目日夜翰，神瀵汇兹穴。","山拥三面螺，城弯半弓霓。","谬余长五湖，斯往信所阙。","左相咏紫微，右枢和白雪。","银榼渟宫醪，湘縢载珍飶。","篮舆日骀荡，皂盖风飘瞥。","稍出清波门，驺声狎啼鴂。","色界纷送奇，目疲不得说。","舟子方进篙，黄衫浪花撇。","俄然两高墨，顿使万象涅。","天笑眵不收，块噫鼓中裂。","縠纹剪破碎，铁冠冒巀嵲。","罗刹怒欲翻，鹫头奋仍掣。","此辈逞狂怪，西子頩不悦。","骤雨面面来，蓬窗时时揭。","莫君如谢安，麈尾手徐挈。","微谓郭长公，虽奇泛宜辍。","仙舟固所慕，角巾毋乃折。","郭公笑王生，此变为畴设。","昨夜真宰过，颇畏灵秘泄。","袖君斲轮手，更卷雕龙舌。","不见渼陂行，雷雨亦愁绝。","玉立山未颓，鲸吞海仍竭。","携兴逼暮归，万燎吐明灭。"]},{"t":"薄暮赴臬中诸公期未归出憩湖上旋得新月湛然独胜因成此篇","f":"五言古诗","c":["整策嚣中要，改憩湖上宫。","东霞尚冠渚，西魄已收濛。","瀰瀰烟羃地，澹澹月弦空。","俄顷吐清照，万碧开朦胧。","潜虬饮遥沚，栖鹘磔幽业。","戢驺延远音，偃盖恣归艨。","净色坐相媚，灵景伫莫从。","酬赏诚少阙，会心何必同。"]},{"t":"吴比部范太史邀游岘山二章 其一","f":"五言古诗","c":["吴兴岘山色，不减襄阳紫。","气馀清和候，人是东南美。","亦有艖头鳊，佐之若下醴。","炊烟隔岭出，渔唱菰芦起。","醉谓故所知，何必羊叔子。"]},{"t":"吴比部范太史邀游岘山二章 其二","f":"五言古诗","c":["改席延绪飔，披襟向晴昊。","日染馀不水，烟平浮玉岛。","顾见青芙蓉，了了透蘋藻。","季重追旧欢，巨卿吐新好。","勿云兴易尽，新月在前道。"]},{"t":"与黎职方吕光禄共赋岘山石尊","f":"五言古诗","c":["李相昔鲸饮，颜公复鸿鶱。","遂令兹山名，远并太傅尊。","闰季大火流，清阴犹未髡。","选胜仍选良，避蒸因避喧。","稍惊蒙茸豁，遂辞䆗窱扪。","俨然见中洼，宛尔发清源。","北斗与南箕，不挹名空存。","安得泻天瓢，下注此石樽。","左揽仙人箸，右洗玉女盆。","夕旭代为薪，青山借作飧。","遥吹从东来，密箐轻飙翻。","一酌浇磊磈，再举超笼樊。","首骖华胥路，息驾众妙门。","始知汎三雅，有待犹为烦。"]},{"t":"石屋洞","f":"五言古诗","c":["招隐岂必深，幽绝在康庄。","天开一层轩，群秀纳青苍。","其阳类江瑶，云足钟离房。","右凹若旋螺，中栖太乙粮。","游履迥失疲，归悰澹将忘。","零雨滃四垂，飞润沾衣裳。","山僧供茗罢，欲出仍彷徨。"]},{"t":"病后初行园有述","f":"五言古诗","c":["幽忧屏时累，况乃寝瘵馀。","行散得中林，聊以境自舒。","初阳破晨冰，流波跳伏鱼。","松声坐来语，竹色窗中书。","外喧稍不接，内寂恒湛如。","安知浮荣在，且当谈遂初。"]},{"t":"小祗园小憩用陶韵 其一","f":"五言古诗","c":["昔有蹈海言，兹意惜未践。","踯躅孟门道，一官岂待免。","忧来日苦短，数往情屡缅。","春至不自知，稍闻鸟声善。","市穷中林出，境迩意乃远。","挟册水竹间，悠然忘其返。","顾景忽自哂，吾何待吾浅。"]},{"t":"小祗园小憩用陶韵 其二","f":"五言古诗","c":["群荣秀春气，天地遂不贫。","敢以百慵故，废我杯酒勤。","脩竹临绿波，清辉来媚人。","迹从逝晷旧，情与来景新。","游鱼故泼泼，时鸟亦欣欣。","南征稍知吝，西往尚迷津。","偶从静者说，获与兰若邻。","世累从此祛，犹足称逸民。"]},{"t":"送吴士游郧阳用贫士韵 其一","f":"五言古诗","c":["高树带微阳，倦鸟相与依。","本为聊托息，非用借光辉。","南亩有栖粮，矫翮且一飞。","晨当暂相辞，夕当复来归。","躄足未朝餐，原尝代其饥。","千载士失职，鼎鼎私所悲。"]},{"t":"送吴士游郧阳用贫士韵 其二","f":"五言古诗","c":["行游向郧楚，急憩鲜华轩。","路若经商山，为我吊绮园。","芝歌停遗响，麇迹但苍烟。","隐见无专是，出处人自研。","达为向平叹，倦为宗炳言。","要子以异时，庶几于二贤。"]},{"t":"焦山访郭道人次父不值用陶韵","f":"五言古诗","c":["爱彼江上山，息此尘中鞅。","故人今何许，令我发遐想。","云胡焦居士，亦复舍山往。","鸟雀渐以骄，菉葹渐以长。","人生贵适我，所向何必广。","慨焉发长谣，兹意存草莽。"]},{"t":"赠王复入山读书","f":"五言古诗","c":["挟册厌时嚣，蹑屩辞故林。","岩栖延孙啸，壤室鸣卜琴。","流霞润清缃，飞溜助高吟。","兰衷托隆古，萝尚谢兹今。","頫仰千秋士，庶协丘中心。","芊眠屯崖雾，羃历出岫霖。","窃用返招隐，冀子惠好音。","毋令三径合，言乖二仲寻。"]},{"t":"程君将北游谒余诗为赠君精易数独谓余尚当出余不许也","f":"五言古诗","c":["客有手一编，自云古周易。","纷然后人造，不出先天画。","西笑入长安，列肆坐秋色。","倘遇宋大夫，相与谈昕夕。","为言向子平，今已悟损益。","未便五岳游，且蜡几两屐。","去去勿复陈，遁爻许贞吉。"]},{"t":"过田家小饮有作","f":"五言古诗","c":["今晨风日佳，默默鲜所亲。","改服从田父，相与过西邻。","虽无超时韵，所得亦以真。","约略婚嫁资，岁功稍一论。","瓠壶盈浊醪，芋叶裹鲜新。","谦言酌卮酒，仓卒无主人。","啖我栖埘鸡，为尔代司晨。","东壁吐蚕丝，可以充钓缗。","笑谓指顾间，遂穷水陆珍。","代主计则然，毋乃非嘉宾。","隗俄复隗俄，目送西归轮。"]},{"t":"初汎湖乘风抵西洞庭","f":"古风","c":["萧晨风日佳，况乃汎澄漪。","扬舲指空白，回首觉翠微。","南望卞山址，北竟晋陵涯。","玉玦周三垂，朗鉴翳全规。","芙蓉插波心，花萼竞参差。","谷飙捲长空，?落迎帆来。","遥岫无停瞬，近濑有定姿。","玄醴染惊颜，觞至当不挥。","寄言探奇者，此胜不易追。"]},{"t":"入林屋洞天不能竟有述","f":"五言古诗","c":["林屋第九天，中藏万金庭。","北穿丈人峰，西达蛾眉陉。","垂滋结乳玉，穿㙧散空青。","㟏岈藏石门，噌吰吐神钲。","是时秋始暮，积潦尚澄盈。","虽负褰裳勇，踝击中不胜。","迩惭孺子托，远愧灵威生。","誓欲偕青童，飙轮探窈冥。","千载灵文出，圣治冀可徵。"]},{"t":"月夜登曲岩由竹林下山家观屏岩丙洞入阳谷作","f":"五言古诗","c":["支策辞道林，飞镜挂大空。","回光散玉岫，潜颖射金淙。","扪萝入窈窕，循垓践玲珑。","稍窥樵采径，获与园林通。","璀灿间脩篁，琮琤乍因风。","慕奇惜奇尽，贪胜冀胜逢。","仄足丙洞穴，耸身屏岩峰。","骇瞩纷自来，浩倡乐无终。","土豹吠寥阒，天鸡破鸿濛。","谁言兹宵既，能使余兴穷。"]},{"t":"下缥渺峰由西湖历东湖抵资庆诸寺","f":"五言古诗","c":["傲睨穷四周，轻风信余屧。","既谢上岭危，颇忻下山捷。","澄湖夹双瞳，乔松振千鬣。","稍深疑无地，忽转长天接。","古刹藏白云，疏林出红叶。","估客喧归步，渔舟满收夹。","饭候寻寺钟，菌香吐僧榼。","斟酌声闻酒，颠倒居士祫。","冥醉时一醒，空青忽交睫。"]},{"t":"汎小洞庭观奇石","f":"五言古诗","c":["兹山饶奇石，混沌帝所凿。","坠如渴猿饮，森若惊鹘搏。","龙睛过犹闪，猊坐望还却。","万窍吸籁号，一柱危崖阁。","玲珑蔽秋涨，突兀生摇落。","赤鲤舷际惊，白乌波面掠。","挥手揽青苍，为余佐杯勺。"]},{"t":"度竹坞岭","f":"五言律诗","c":["上岭若攀天，下岭若穿井。","落日犹半规，深松已先暝。","事将馀兴败，足与归念梗。","时觉虬龙争，肃然发深警。"]},{"t":"将至建业大风雨作","f":"五言古诗","c":["挂席凌大江，斗觉风云颠。","日脚金琐碎，山头墨蜿蜒。","高天忽下垂，密与沧波连。","不辨川后界，坐失阳乌权。","咫尺晃微白，浪花骄不圆。","攒矢斗壁剥，神钲击喧阗。","徙坐蔽束书，低眉睨长年。","两仪退归所，万象仍悠然。","山色媚举卮，波声清扣舷。","变故在须臾，所得能不迁。","是以暂往身，托志在归全。"]},{"t":"早入庐山首路作","f":"五言古诗","c":["徙符五岭外，归沐三冬前。","及兹道彭蠡，九叠青依然。","授衣变寒暑，击汰改流连。","决策扣庐君，蓐食理枉阡。","微月隐纷纶，流云渐芊眠。","树杪生遥曙，草际出哀泉。","来奇若故赏，新踪繇往缘。","分无幽栖躅，慨焉叹诸贤。"]},{"t":"入东林精舍","f":"五言古诗","c":["晨色悬抗旌，流泉徇扶藜。","贪看香垆曙，忽已过虎溪。","古树绣上方，荒草掩前阶。","屈戍蔓蟏蛸，军持跃醯鸡。","寻胜冀获新，探往浩无倪。","昔希遗民誓，永怀尘外栖。","今憩东林轨，犹恋区中迷。","悔濯当自今，赏愧庶无睽。"]},{"t":"由云峰取道锦涧历险至绝顶","f":"五言古诗","c":["改装问绣涧，徙屩披蹑云。","涧仄愁陵缅，云杂争崩奔。","急湍令玉危，缓溜使弦温。","稍息一会心，屡踬复惊魂。","参差吐锋距，倏忽变朝曛。","前径为雾绝，后呼若空闻。","矫䜪属大观，贾勇非离群。","会已人世远，何繇叩天阍。"]},{"t":"由武当之紫霄历青羊桥憩五龙出仁威观有述","f":"五言古诗","c":["跻危意方倦，入幽良自适。","岩峦非一态，云日饶奇色。","活活伏流来，泠泠深崖滴。","腾虬悟风树，渴猊知水石。","拿攫令魂惊，蜿蜒觉根坼。","俶诡青羊涧，窈窕五龙室。","彼美如有待，余欣宁无获。","改辙见平畴，蔼蔼禾黍夕。","归虑中未搅，目境时有失。","安得乘蹻道，遥青庶可摘。"]},{"t":"由南岩寻北岩谒不二和尚","f":"五言古诗","c":["降陟虽疲迹，眺览用怡心。","心怡体自调，支策探道林。","是时春初暮，遥绿结屯阴。","一幡飏空表，双树吐缘寻。","初窥但绝壁，缓步得精蓝。","开士久杜机，眄睐不能禁。","延我坐芙蓉，啖我以林檎。","清梵和流泉，噌吰海潮音。","忽睹西岫景，圆规已半侵。","归来愧禽鱼，自得忘高深。"]},{"t":"古意赠伯玉中丞二首 其一","f":"五言古诗","c":["娟娟闺中秀，托质为君助。","中夜理笄总，日织三丈素。","本用报君恩，惰者反成妒。","蛾眉当秋风，飒然垂将暮。","二八更代进，回光焉反顾。","芙蓉鉴铅华，使我欲不御。","岂在惜朱颜，实以宗祀故。","止止且勿陈，欢爱尚中路。"]},{"t":"古意赠伯玉中丞二首 其二","f":"五言古诗","c":["煜煜双纯钩，磨者益其锋。","谡谡孤松树，耻为霜霰容。","良骥疲太行，骧首思腾冲。","万翮摩广原，畴能韬劲弓。","之子负宏奇，郁为盖代雄。","闽山有馀荫，粤海无惊风。","惜哉世路晚，刺促难为工。","君子任其劳，小人代其庸。","天顾犹未宁，毋为悲道穷。"]},{"t":"送舍弟敬美北上 其一","f":"五言古诗","c":["嘉运开骏招，轮帛四交驰。","之子起自厉，为报当及时。","杯酒指河梁，悢悢不能持。","十载虽茕独，与子不相离。","仰见晨风鸟，矫吭鸣何悲。","脩翼摩劲飙，一举绝天池。","岂不快所往，念此卑林栖。","舒卷无违性，动静各有宜。","努力爱景光，千载以自期。"]},{"t":"送舍弟敬美北上 其二","f":"五言古诗","c":["方舟遵枉渚，落日上征衣。","离筵启方序，吾弟感仳离。","愚哲虽异规，畴不慕昌期。","哲者任其劳，愚者食其贻。","上有晨昏奉，下有伏腊资。","偃仰恒一编，耕钓不失时。","子其宁尔怀，余处良以怡。"]},{"t":"送舍弟敬美北上 其三","f":"五言古诗","c":["春星罗广陌，熹微依徵传。","雄鸡无停号，炯尔天地旦。","浮阴忽来滋，焉能长清汉。","脩条未易材，微萌无难蔓。","送客各自媚，谁当发浩叹。","仕宦恒苦晚，行乐恒苦短。","所以邴生秩，往往不待满。"]},{"t":"送舍弟敬美北上 其四","f":"五言古诗","c":["窃有和氏璧，皎洁如秋月。","当其未辞璞，忧在长埋没。","初日奏秦庭，精光荧然发。","美人粲玉齿，九宾为惊绝。","在执苟不虔，能无中玷缺。","子其爱连城，完归用将别。"]},{"t":"信口赠莫山人","f":"五言古诗","c":["再起犹畏途，斯意久郁郁。","月俸已送官，早晚将解绂。","留君一杯酒，乃是家田秫。","丈人未悉恭，生平无长物。","念欲饱果然，新诗不堪乞。"]},{"t":"与吕生谈有感","f":"五言古诗","c":["仕路无拙速，众口令亲疏。","吾本不忧怫，谁能使之愉。","一语朝不谋，夕当赋归欤。","云霞傍人生，天地待心舒。","试与论往事，且复探故书。","峥嵘后来薪，掩抑前钓鱼。","物情固何极，意足恒自如。"]},{"t":"孙崇明政成乞归以诗慰送","f":"五言古诗","c":["孙郎负宦声，而乃发遐想。","厌作海外丞，愿为五湖长。","父老揽袂言，神君欲何往。","宝山一拳石，聊用压轻舫。","归拜尚书阡，清风世无爽。"]},{"t":"别罗李袁三君","f":"五言古诗","c":["上书不待报，解绶归田庐。","斯岂悦隐沦，遽欲言遂初。","衰慈遘沈■，医药寡异谟。","百念不并牵，仓皇即脩途。","我友二三子，祖宴此城隅。","缱绻握手间，形滞神不俱。","西望九折坂，我肠更郁纡。","北风排雁行，踬羽日夜疏。","五里一返顾，十里一哀呼。","非君回云照，浊水永自涂。","努力敦兰好，合并亮不诬。"]},{"t":"答明卿 其一","f":"五言律诗","c":["今兹暑用壮，衡荜藩吾身。","白雪从南来，令我思郢人。","故者日以疏，新者何自亲。","所以一杯酒，黯然向沈沦。"]},{"t":"答明卿 其二","f":"五言律诗","c":["越女强入宫，顾影中不怡。","群口浩无端，安能自蛾眉。","窃悲幽贞志，至死不见知。","所以双素腕，浣纱空江湄。"]},{"t":"助甫远驾见访遂成四章情见乎辞 其一","f":"五言古诗","c":["为欢日苦短，为别日苦长。","与子期燕中，不知几星霜。","寒枝噪乾鹊，故人登我堂。","东风随裾来，四坐为芬芳。","缱绻未及申，命酒且尽觞。","流尘满金徽，拂拭荐瑶床。","弹者志文王，听者称望羊。","击节三起坐，掩抑以彷徨。","安得双鸾翼，凌云共翱翔。"]},{"t":"助甫远驾见访遂成四章情见乎辞 其二","f":"五言古诗","c":["踰立谢兵符，始托君子盟。","嬿婉甫再秋，十五为别龄。","人生能几何，霜鬓不再青。","故友艳春华，屈指若晨星。","存者散各天，逝者忽已冥。","拭泪荐君卮，安能令不盈。","北斗向阑干，携手步中庭。","景光各自爱，竹素以为徵。"]},{"t":"助甫远驾见访遂成四章情见乎辞 其三","f":"五言古诗","c":["前人工织锦，后人但织缟。","缟故不足言，无锦缟亦好。","念我平生驩，来自千里道。","契阔未及陈，涕泪如横潦。","鼎养随形尽，恩诚委秋草。","所以先达言，荣名竟为宝。","搦管不自斑，安能为君藻。","矫矫济南生，其骨惜已槁。"]},{"t":"助甫远驾见访遂成四章情见乎辞 其四","f":"五言古诗","c":["举世谋选良，中野弃千里。","扰扰骊黄内，安能别识此。","駊騀牛羊间，其志乃四海。","纯钩当夜鸣，所望在知己。","五步不留行，郁为匣中水。","紫气横斗牛，房星耿河沚。","流光荡人目，拂拭从此始。","骤驰当防蹶，骤试当防毁。","三复老氏言，书绅赠吾子。"]},{"t":"赠徐子之楚臬二章凡三入矣 其一","f":"五言古诗","c":["委蛇问南征，结束戒明发。","方舟指江汉，竹马遵沙汭。","蔚蔚棠树阴，君鬒幸未雪。","无情犹思御，有情宁无悦。","二南将嗣徽，四履日以阔。","为君起深叹，功成在三折。"]},{"t":"赠徐子之楚臬二章凡三入矣 其二","f":"五言古诗","c":["使君何翩翩，五马一马骢。","后乘艳春花，前旌拂南鸿。","士女日袨装，矫首兰台宫。","万木森变青，窃因被雄风。","镃基既逮时，黍稌当遂丰。","庶希弹冠侣，非复泣车穷。"]},{"t":"答戚希仲","f":"五言古诗","c":["秋兰秇深谷，春英冠芳圻。","当此摧掩日，是尔芬敷时。","明堂大布政，哲匠顜英规。","片言程金石，九有播令徽。","焉睹耦耕子，参往商不随。","皇天诱衷素，飞帛江之湄。","方轨即周行，媚我以好姿。","嬿婉甫及缡，千秋遂为期。","论心当论远，结交须结晚。","远心胜近面，晚交深缱绻。"]},{"t":"别汪仲淹一章","f":"五言古诗","c":["阳鸟北回翔，西南厉其翅。","岂不恋比翼，群生各有制。","衔草未遑食，顾巢焉能憩。","念子乃从兄，怆予偏别弟。","置祖荐大烹，行留各有味。","子其珍尔璞，毋为贱工弃。"]},{"t":"南明卷为刺史封中丞孙翁题","f":"五言古诗","c":["有凤含灵文，五色正葳蕤。","矫翼西南天，流彩于滇池。","政成感神雀，荣名垂碧鸡。","非无圣人德，为祥不逮时。","歌舞乐尧年，梧竹表馀栖。","有子字鹓雏，阿阁朝见仪。","出者庆来章，处者颂黄离。","请看罗施国，处处生光辉。"]},{"t":"次俞仲蔚题赵吴兴画陶元亮归去来辞","f":"五言古诗","c":["陶令罢彭泽，正及黄花开。","有酒不辞浊，长歌归去来。","千载义熙波，谁能溯其洄。","学士返吴天，椎发白毰毸。","回首感宗周，掷国一婴孩。","篮舆蹇柴桑，紫骝捷蓬莱。","时睽迹更殊，畴能不见猜。","惜哉丹青美，托尚隔云埃。"]},{"t":"萧懋建户部弃官后游杭以西湖诸长歌见寄赋此为赠","f":"五言古诗","c":["当时萧次公，不受后曹诘。","幞被归去来，秋风卧石室。","尽橐买一船，钱塘比湘汩。","壮气黯不收，虹霓缠其笔。","两峰斗嵯峨，千秋写萧瑟。","诧谓官不贫，珠玉纵横出。","地留西湖胜，天与山人日。","纵有䱬文鳐，勿疗敬微疾。"]},{"t":"次陆太宰全卿题戴文进画卷七首 其一 浣溪春行","f":"五言古诗","c":["朝出锦官城，暮投浣花渡。","步步花媚人，那能舍花去。","但使有酒沽，不妨花下住。"]},{"t":"次陆太宰全卿题戴文进画卷七首 其二 卧听松泉","f":"五言古诗","c":["谡谡松际风，泠泠涧底泉。","宫商偶时合，来搅幽人眠。","恍然梦中境，洞庭奏钧天。"]},{"t":"次陆太宰全卿题戴文进画卷七首 其三 竹湾夜泊","f":"五言古诗","c":["维梢傍村坞，黯黯天地绿。","忽有渔歌来，悠然逗深竹。","不知月出否，稍见玲珑玉。"]},{"t":"次陆太宰全卿题戴文进画卷七首 其四 雷峰夕照","f":"五言古诗","c":["西风不酿雨，东雷空自疾。","莲女叶盖头，相将委花出。","但采了不妨，请看塔尖日。"]},{"t":"次陆太宰全卿题戴文进画卷七首 其五 凭阑待月","f":"五言古诗","c":["十五团团月，当已离海岛。","立残双莲瓣，夜色犹未好。","非关月出晚，应是侬来早。"]},{"t":"次陆太宰全卿题戴文进画卷七首 其六 西湖雨霁","f":"五言古诗","c":["似传西湖霁，西子初赐沐。","宛尔碧髻鸦，娟然青曼睩。","欲住听晓莺，吴王忌人宿。"]},{"t":"次陆太宰全卿题戴文进画卷七首 其七 东篱秋晚","f":"五言古诗","c":["英英篱边菊，不与青阳遇。","芳意终有合，宁为叹迟暮。","百卉各竞时，葳蕤今何处。"]},{"t":"送表兄出居 其一","f":"五言古诗","c":["中庭桃李树，蓁蓁夹庭阶。","枝枝交荫带，叶叶互相依。","雨露方齐润，东风亦均吹。","何必同根蒂，然后乃宜家。","此树本无言，移者自为蹊。","昔合尚有分，今分合何时。","送子出门去，挥泪不成辞。"]},{"t":"送表兄出居 其二","f":"五言古诗","c":["今夕高宴会，登歌含惨吁。","借问何为尔，送子以离居。","离居多苦辛，歌浅思有馀。","忆昔童冠时，朝暮两相于。","胡为向康庄，改辙行自驱。","比邻固匪遥，疏者曰以疏。","但令心期迩，踪迹岂必俱。","再拜与子别，四望野踟蹰。"]},{"t":"华员外改南司马部分韵","f":"五言古诗","c":["忆昔岁在癸，我发初就弁。","不以阿戎少，俾托阮公宴。","以兹一分手，长思奉颜面。","金闺幸同籍，未得展婉嬿。","胡然重离别，翻令恨相见。","归帆逐新水，落日在河县。","殷勤戒尺素，愿将南归燕。"]},{"t":"嘉靖丁未夏四月余以进士隶大理得左寺凡九人朝夕甚乐也又明年六月则八人者以次授去独予在晨候大吏升揖散步空馆顾影凄然为赋一章","f":"五言古诗","c":["棘署同试政，濯濯多清佳。","亮匪平生亲，忽成一朝谐。","本为转蓬枝，愿申松柏怀。","衡晷乍改岁，捷羽各分飞。","松柏谅靡他，转蓬飘何依。","昔者偶然合，今者为谁乖。","零落山葵花，犹然媚空阶。","茕茕顾流影，戚戚有馀悲。"]},{"t":"过维扬有怀子相","f":"五言古诗","c":["淮南万木落，蒹葭鸿雁秋。","回瞻大江水，极眺黄河流。","念此区中士，天翰阻同游。","岩岩丽神京，英俊满宾帱。","岂乏携手好，抗志乃绸缪。","浮沉众自睹，安测衷所由。","奈何各分离，徽音邈以脩。","子如宵行烛，分辉均道周。","予如汀际鸳，哀鸣望其俦。"]},{"t":"淮阳署中早起作","f":"五言古诗","c":["九衢晨钟竞，千门秋色扃。","隐隐赴人语，稍稍迫稀星。","虚户渐舒白，条松尚蒙青。","光华迥一照，暝晦失千灵。","感彼狴中士，凛慄向严刑。","伊予奉明役，薄劣敢遑宁。"]},{"t":"为子与赠吴生","f":"五言古诗","c":["朋友天地间，斯途日荆棘。","吴生山海人，雅好在朱剧。","十六游燕市，颇与酒徒昵。","一诺倾市中，寒榛回生色。","徐子幸见知，握手为莫逆。","徐子无一钱，英贤罗宾席。","生也辍朝餔，力为助其啬。","生也无一钱，大笑秋云白。","千金或再至，心知恐遂失。","营卫未掩身，于人计长溢。","呜呼岂有要，浮云愧变易。","不见扰扰者，原申无上客。"]},{"t":"寄徐郎中文通","f":"五言古诗","c":["脩途岐交踪，遐慕并夙轨。","伊昔沐休遘，西游徐与李。","彳亍时名外，违心不复已。","结佩遗所欢，要之相终始。","斯道多苦心，勇者竟其止。","君行在何所，乃在剑门里。","层空削蛾眉，悬索仅度指。","下临千仞壑，回湍浩无底。","周营戒一失，那能不涉此。"]},{"t":"赠俞山人允文 其一","f":"五言古诗","c":["束发慕姣服，远媾托幽燕。","名都富奇娼，入门各自妍。","何意南威子，晦迹厕通廛。","烂若朝霞际，濯若澄露鲜。","蕴步肌芳发，黛粉出天然。","璞璧铲光辉，何悟天质完。","惜哉狎游客，口观失朱颜。","葹杜满中洲，兰芬竟何言。"]},{"t":"赠俞山人允文 其二","f":"五言古诗","c":["冠盖罗长道，畸人困偃仰。","极眺六合间，浮云何惝恍。","焉睹槁与壤，含露发清响。","浩浩沧溟流，珊瑚罥其网。","虽靡任公力，躧步思泱漭。","相顾及千载，时好忽以往。","灼灼中园华，畴能无欢赏。","不因凉飔候，宁知同草莽。"]},{"t":"赠俞山人允文 其三","f":"五言古诗","c":["伊予际微遘，素短应人略。","冠佩婴其躬，容颜为时作。","鸿鹄渐华阶，虽重非所托。","贵贱当岐趣，念欲两居薄。","人生非根株，取愿谁能博。","华卿縻好爵，管生蹈丘壑。","龙质既以殊，低昂成虚度。","慨然革余往，从子甘藜藿。"]},{"t":"别李于鳞 其一","f":"五言古诗","c":["今日别我友，还望之故乡。","故乡岂无欢，我友安得将。","行者惨不辉，居者以彷徨。","肉骨虽摎拊，既析亦相忘。","惟有肝与胆，委照差可方。","焉顾非日月，东西扬景光。","情知谐亲遘，乃在媒慨慷。","虽有绸缪泪，何以写中肠。"]},{"t":"别李于鳞 其二","f":"五言古诗","c":["韦布走四海，万乘失一畸。","悬知势分剧，心各有所施。","踯躅生人间，含悃将向谁。","夫子绝俦匹，吾道幸不疑。","出门各有好，谓为媚予私。","矫矫孤凤皇，翩翩向豳岐。","鸱枭喧中野，鹪鹩骇卑枝。","山鸡学仪羽，举世安可欺。"]},{"t":"别李于鳞 其三","f":"五言古诗","c":["置酒前为别，炙笙治哀丝。","中有艳明珰，二八绝代姿。","轻裾回芬发，自然成蛾眉。","色授不能道，婉娈心所知。","弹作双鸳鸯，流飙忽间之。","含辛上车去，引领涕沾衣。","时俗慕朱颜，朱颜识为谁。"]},{"t":"古意寄李于鳞 其一","f":"五言古诗","c":["幄中有奇质，拟是吴宫姝。","腰间瑰瑜佩，耳缀大秦珠。","宛若惊鸿度，灼如舜华敷。","动摇幽芬发，行止宫商俱。","游徒非古欢，枉盼意相驱。","礼乱并一身，千金在须臾。","明誓指秋天，谁能信不渝。","临当相诀绝，抱此尽区区。"]},{"t":"古意寄李于鳞 其二","f":"古风","c":["黄鹄辞天池，周游于中土。","秋禾郁如绣，徘徊能无下。","所顾充口腹，当眸失罘?。","斑斑原中雉，踯躅同鼎俎。","以此唳霄质，俛首凡禽伍。"]},{"t":"古意再贻于鳞 其一","f":"五言古诗","c":["飘风起何因，吹氛荡华月。","为照虽未周，畴能讥其缺。","众草媚春晖，亭亭违阳柏。","雪霜心已知，侵凌表孤直。","秉道不见明，愚者嗤无益。","覼缕类谗词，要子在深择。","子其宁尔怀，齐轨之中陌。"]},{"t":"古意再贻于鳞 其二","f":"五言古诗","c":["结发奉君子，明誓要不薄。","山岳起苍黄，欢途为悲别。","思喻随形影，昏旦无期辍。","上堂顾宗祀，下堂顾身托。","驱车周道中，足若罗荆棘。","松秀太华颠，虞同稂莠植。","岂不亮子心，爱深生虑博。"]},{"t":"赠谢榛","f":"五言古诗","c":["脱屣平原客，振衣燕昭台。","吾人实龙矫，白日天崔嵬。","广陆奏清商，悲风四垂来。","俯仰狎世观，一二当中怀。","极厄不顾知，中介有馀谐。","亲者无愧亲，排者任其排。","萧索一韦裳，傲睨千古才。","扰扰冠盖徒，零落青门埃。"]},{"t":"贻吴舍人","f":"五言古诗","c":["日出群动发，大小各有营。","之子何所为，泊然坐沈冥。","抽翰掞华辞，踯躅畏时英。","累却不遽前，一出万象惊。","衔杯藉高咏，指顾浮云凝。","勖哉深沉思，此物未可轻。","奚必公与卿，然后展高名。","不见扬马辈，为郎动西京。"]},{"t":"赠吴给事明卿 其一","f":"五言古诗","c":["汉宫郁崔嵬，层霄缭阿阁。","维昔先后谟，三灵奠鼎卜。","国是岂不显，往往沦华毂。","仰睹双飞龙，夭矫盘丹艧。","畴为翼其尊，高言赞宵服。","乔木抗衡飙，卑枝欣有托。","翳子翔天步，栖栖安余乐。"]},{"t":"赠吴给事明卿 其二","f":"五言古诗","c":["岱宗何油油，触石起层阴。","夭乔希生态，色飞讵能禁。","为施苟失时，被物故不任。","良苗杀其根，百草蔓相侵。","远轨牵流潦，归翰泥故林。","委弃衢道间，谁能明嘉霖。","天泽岂不甘，怨者谥为淫。","毋以贤达资，中彼谗夫心。"]},{"t":"高邮别子相","f":"五言古诗","c":["回轸出君方，脩途意弥恻。","浮云莽互驰，奄然羲轮匿。","中夜理夙炊，惋恋不能食。","往遘岂乏欢，念若遗行迹。","姣服谐奇慕，安能顾掩抑。","举世各自矜，娟情无终极。","脉脉睹何言，察此眉间色。"]},{"t":"赠子相考功 其一","f":"五言古诗","c":["猗猗孤生蕙，托根泰山崖。","上蒙千寻干，下临百仞溪。","雨露既无当，地势使人疑。","阳春自何来，为我发光辉。","馨香中思奋，不能自致之。","绿叶缛紫茎，令其媚庭阶。","物性虽无适，贵在得所施。"]},{"t":"赠子相考功 其二","f":"五言古诗","c":["飞来孤白鸐，皑若流云色。","秋冥发扶摇，直上万里息。","朝饴芝田实，夕揽方壶碧。","苍鹰摩天来，虽峻非我匹。","彷徨思俦侣，踯躅不能食。","俯见荒丘莽，下有华池翼。","鸣皋一唱和，鸿濛听为坼。","所希在同声，宁论奋栖迹。"]},{"t":"寄俞仲蔚","f":"五言古诗","c":["维昔休明代，委运忘悦康。","山泽饶栖遁，霄汉富翱翔。","穷显无鳏职，操志略相当。","念余与之子，揽佩撷奇章。","弱植不固含，明廷幸见扬。","恒恐摧剥候，玄露负微芳。","四兵东南来，杀气被乾纲。","湖海波荡潏，一苇安得航。","桃李植通衢，搴摘固其常。","幽兰秀深谷，樵采虞见伤。","我生非磐石，焉睹鬒不霜。","奚必婴祸罗，百年等归藏。","许子以不刊，勖哉爱景光。"]},{"t":"再赠谢榛","f":"五言古诗","c":["浮云四何之，高天莽回互。","空谷非所依，畴能测衷慕。","念我平生欢，挥手不反顾。","朔气日夜侵，霜霰浩无度。","洪流飒然交，万木倏改素。","庐巷墐户炊，停车饭中路。","吐沫鲜馀润，裁襦狭广步。","隐士代失职，达者惭其故。","欲以俭世工，御风而飧露。"]},{"t":"赠彭年黄姬水","f":"五言古诗","c":["日余雠夷峤，委迹窜吴中。","虽无兰椒臭，托佩君子躬。","彭生掞秋实，黄友撷春荣。","参差申微尚，婉娈未逮终。","凯风从南来，吹我向幽邦。","亲故感仳离，遵渚饯宾鸿。","妙辞将柔翰，煜若双琮璜。","挥手鹜声途，湛心耽患丛。","咫尺平生好，惝恍恨河嵩。","众耳迫相求，显者代称工。","慨此蓬蒿士，永谢轮鞅踪。","抚壮岂需偕，濛汜恐未容。","何以表殷勤，江介凋芙蓉。","矢言要齐轨，庶其慰忧悰。"]},{"t":"答仲蔚","f":"五言古诗","c":["当春弥不怿，委薄日纷樛。","捐脰延远怀，密阴覆曾丘。","忽枉故人书，言短旨何脩。","苍苍眉间宇，尽入云霞流。","婉娈若崇朝，何云隔三秋。","黄鹄啄玄浆，稻粱宁见谋。","虽蒙天池泳，不忘故匹俦。","颐辂生食醯，愧以嗜相投。","将为同枝誓，良辰去我遒。","庭卉未扬芬，欲报不能酬。"]},{"t":"贻梁伯龙","f":"五言古诗","c":["乔木竦崩崖，下临千仞溪。","岂不虞倾折，根株讵能移。","回风吹转蓬，飘飖穷天垂。","念此岁云晏，廓落竟焉归。","两慕中未宣，安睹已所悲。","周道横豺虎，饬步讵成规。","君子忧世患，小人偷自怡。","恒恐羲轮逝，为谋不毕时。","唯有贻竹素，可以惬衷期。"]},{"t":"贻梁公实","f":"五言古诗","c":["箕斗亘穹霄，万古各相望。","精光无初合，虽暌固其常。","自予与之子，明誓结肝肠。","孔雀畏北风，徘徊竟南翔。","离思生欢洽，往遘积苍茫。","茹藘洵绛哉，茱萸发微芳。","寓目恐见移，于衷固无当。","采彼蕙兰花，衡湘邈以长。","白露虽天物，玄飙荡为霜。","盛时不见佩，枯槁空自伤。"]},{"t":"赠子与 其一","f":"五言古诗","c":["衔命首皇畿，遵途蓟北疆。","阊阖风云至，回瞻浩苍苍。","慨我同心友，携手周道傍。","廓落鲜故欢，踟蹰问他方。","行人无期返，留者恐不长。","念欲更余辙，偕子以遨翔。"]},{"t":"赠子与 其二","f":"五言古诗","c":["遨翔黄鹄颠，焦螟望为疑。","昔与二三子，坚白守空规。","天贻乔松质，何惧风不持。","岂意雷霆举，击我双连枝。","宁无一杯酒，杯尽华嵩移。","延首盼穹荒，愯然中奋飞。"]},{"t":"赠子与 其三","f":"五言古诗","c":["奋飞以何为，行迈指三吴。","黄金填城郭，兵甲荡为墟。","天地不相亲，生人安得娱。","豺狼来称友，荆棘夺我庐。","与子殊形影，所往竟难俱。"]},{"t":"赠子与 其四","f":"五言古诗","c":["难俱亦何言，意至轻别离。","鸣驺越脩坂，飞盖风逶迤。","阳春缘轮发，白日借光辉。","大小各有营，焉能预为期。","明河中荡潏，三星亦相辞。"]},{"t":"赠子与 其五","f":"五言古诗","c":["相辞携年逝，玉貌焉独留。","堂下三株桃，遗核手为掊。","再见如人立，三见等松楸。","汤汤黄河水，浩浩东南流。","白骨日夜消，犹能积为丘。","亮无安期药，何以经千秋。"]},{"t":"赠子与 其六","f":"五言古诗","c":["千秋无终极，蛾眉若朝霜。","初阳虽云薄，凝气自无常。","蒙庄忧生士，忧在等彭殇。","畏至欲无言，离居能自臧。","皛皛双圆景，终古媚其光。","太岳鼓洪垆，流风扇八荒。"]},{"t":"赠卢楠 其一","f":"五言古诗","c":["葳蕤山中桂，零落随飘扬。","何意回风起，将尔向高堂。","绮裀承金粟，四坐誉芬芳。","萧艾故匹俦，敛分终道傍。","履荣虽谐遘，超贱讵无方。","受质既殊伦，畴能竟不臧。","唯有倾城国，可以喻文章。"]},{"t":"赠卢楠 其二","f":"五言古诗","c":["国相脱齐骖，越石始称人。","宁为终胥靡，不作下坐宾。","区区夷门卒，偃蹇魏王孙。","执辔恭弥下，因疏翻见亲。","虽非巢由节，两分故相尊。","卢生完城旦，磬折何逡巡。","宁无知音望，仓卒谁见伸。","肉食侵士权，藜藿竟焉陈。"]},{"t":"赠卢楠 其三","f":"五言古诗","c":["丈夫所贵生，岂在乡闾雄。","文章一睚眦，缧绁被其躬。","白刃幸见违，沟壑又来宫。","脱粟寄他家，焉能先日舂。","陈骚激飞霜，演辨驻回风。","遂令黄河水，西与岷湘通。","造化虽无情，为恩宁不终。","矫矫邢大夫，千秋以先容。"]},{"t":"答陆鸣羽秀才","f":"五言古诗","c":["晨翮慕劲飙，夕羽眷乔林。","子称烂白石，予游倦黄金。","箕踞灌木阴，四野助悲吟。","世才总津要，吾道甘陆沉。","出处毋论迹，所希在知音。"]},{"t":"赠许殿卿左迁镇夷州","f":"五言古诗","c":["送子城东门，言适万里道。","维昔罗施境，亥步困周讨。","高天閟清泠，毒雾施百草。","鼪鼯窜深穴，山都啼木杪。","霮霮去踪绵，悠悠回轮渺。","妖氛缠南极，汗漫无时晓。","在远虽明代，犹虞不自保。","兰荃饶香泽，金气成枯槁。","何以贻所欢，誓言偕衷好。"]},{"t":"答周比部胤昌见怀 其一","f":"五言古诗","c":["我有盈樽酒，与子结绸缪。","欢悰未逮终，当萦黄河流。","枥马媚其群，三星起相雠。","飞藿因风值，飘荡不自谋。","绿绮何方来，含音袅以悠。","安得凌霄翰，并起双遨游。"]},{"t":"答周比部胤昌见怀 其二","f":"五言古诗","c":["泰山何崔嵬，乃在天之东。","海日割夜生，元气浩无终。","上有七十帝，往往苍苔封。","吾子挟飞仙，乘化观鸿濛。","区区云门色，焉以驻游踪。"]},{"t":"答周比部胤昌见怀 其三","f":"五言古诗","c":["释靷挹济流，返驾阅齐菑。","暧暧芳草色，千里绿成荑。","春晖将见娱，旷处反为悲。","俱称远游子，行留竟焉岐。","往遘匪不繁，今追良已稀。","唯有飞鸿羽，可以展遥徽。"]},{"t":"赠周武冈胤昌时以考功法坐浮薄谪 其一","f":"五言古诗","c":["长安旭日动，轮鞅错中逵。","飘盖青云端，徒御亦光辉。","朝游平津邸，夕宴曲阳池。","为快非一状，志士鲜所希。","穷巷春风来，往往与醉期。","一闻预汰议，幞被省中归。","微哂向时人，兹险胡不夷。"]},{"t":"赠周武冈胤昌时以考功法坐浮薄谪 其二","f":"五言古诗","c":["苍苍千秋色，沈沈何时旦。","一与王生游，遂为浮薄冠。","尊酒关他人，诗书同兹难。","寻形诮嵇阮，传声依绛灌。","虽邻长沙谪，尚迩交州窜。","拂拭瑶琴徽，为君再三叹。"]},{"t":"赠周武冈胤昌时以考功法坐浮薄谪 其三","f":"五言古诗","c":["子昔游荆门，守相效前驱。","山川来笑人，手板今与俱。","万事相低昂，吾道竟焉殊。","峡雪寒自坚，巫云暮还舒。","虽有千金药，狂疾勿令除。","王生在东海，东海亦吾庐。"]},{"t":"寄茂才陆师","f":"五言古诗","c":["少小疏剑术，委神役诗书。","思厌曼容禄，将寻仲长庐。","微好不逮宣，踯躅东海符。","解髋虞阙芒，烹鲜守馀模。","行逢少年子，磬折安所图。","顾影若杯棬，何能不揶揄。","劳翰媚深林，潜鳞冀天衢。","吾师荆山秀，三刖泣路隅。","至宝不自明，谁为辨璠玙。","一朝奏秦廷，光映十五都。","春华随阳逝，秋英方见舒。","大美终必扬，蚤莫竟焉殊。","远言营丘伯，乃是老匹夫。","迩记菑川生，六十滞公车。","茫茫通人趣，变化在泥涂。","愿言保真贵，为子尽区区。"]},{"t":"故人王逢年书来云留辟太保府中书记多甘泉应制之作且为日东访余于青州率尔言答","f":"五言古诗","c":["在屈龙从蠖，乘伸鹄为凤。","言念子渊材，无惭部史贡。","讲德既有述，得贤能无颂。","夕吐丞相茵，晨割大官供。","骖乔白鹿新，祠滇碧鸡重。","隐大难为名，才多不自用。","远戍欢鲤椷，孤臣抱醯瓮。","朝星稷下士，汗雨临淄众。","赤丸昼瞥起，绿沈春恒动。","敢衰拥彗迎，恐乖炙毂送。","愿以湖海心，托君云霄梦。"]},{"t":"遣信要徐汀州入计不值声问久空言此志慨","f":"五言古诗","c":["客岁何郁郁，聊止太山隅。","言念平生亲，踯躅鲜与娱。","使君东南来，五马不踟蹰。","音尘旷无接，形影忽若殊。","昔合胶投漆，今离叶辞株。","昔怜扶竹生，今愧并鸟徂。","安得乘云气，长与故人俱。","恒恐猋风至，弃掷在须臾。","变态中心交，焉能测所如。","感此清商曲，弦绝调弥孤。"]},{"t":"冯子览余簿集裁诗誉借率尔奉酬因见倾倒","f":"五言古诗","c":["蹇余负偏业，束发慕修辞。","虽非通人好，往往中所私。","濩落青云交，泥涂渐言归。","清庙奏朱弦，听者晨已疲。","更为新声转，四坐尽歔欷。","识曲辨其真，遘子良以希。","流水何冷冷，归鸿在遥圻。","为君起三叹，拂拭黄金徽。"]},{"t":"别李于鳞 其一","f":"五言古诗","c":["黄鹄何昂藏，肃肃金为衣。","感帝发嘉祥，徵歌幸见仪。","非无稻粱惠，所志在天池。","矫吭中宵鸣，悲声扬四垂。","翩翩随阳鸟，夙昔幸相依。","托身昆弟间，小大不自疑。","冲飙如弦发，倏忽弃南归。","言归非一状，欲举复徘徊。","短翮双枯蓬，安能中迅飞。","衔芦化为棘，口血正漓漇。","雕鹗横空来，罝网布川坻。","鼎俎在斯须，长与故侣辞。","存者千里隔，没当千岁期。","起顾见晨星，东北乍离离。","一为鸿雁曲，涕咽不成洟。"]},{"t":"别李于鳞 其二","f":"五言古诗","c":["遘难走齐郊，怦营厌微生。","微生且不惜，焉在冠与缨。","何意双丝短，羁绁我长征。","羸马顾其辕，局蹐悲以鸣。","对影惭须发，不如一缇萦。","浮云东北驰，圆景赴西溟。","俯见黄河流，溅溅感人情。","宋意不可期，谁为变羽声。","腆辞将飞素，白虹亘青冥。","落木先蓐收，旦知清露零。","匣中五丝桐，为我奏不平。","诚知弦当绝，流水尽君倾。"]},{"t":"别徐汝思","f":"五言古诗","c":["张祖在河梁，悢悢不忍辞。","戢身就一苇，翩翩焉所归。","河水日夜生，原树为之低。","乌啼正骚屑，阳雁感仳离。","曾是肥遁占，改繇就明夷。","白日吐雷霆，青阳霜憯悽。","悬山呼庚癸，谁问渴与饥。","时难人心出，介者终不移。","良雨固均沾，枯槁被殊私。","合并将何日，冥报其庶几。"]},{"t":"天津问汪氏不遇","f":"五言古诗","c":["忉怛赴家难，仓皇纳符节。","露宿寄杪蝉，水征委波叶。","伏阙将上章，微诚希见雪。","沧溟浩茫茫，精卫日衔血。","蝼蚁悲原土，虎豹守天闑。","次且夷门里，冀与侯氏诀。","河岳变须臾，风云走飘瞥。","岂乏长者过，蓬蒿掩其辙。","乃知洗颍意，惧贻焚山孽。","同隐复异悰，含辛当谁说。"]},{"t":"彰义门别舍弟作","f":"五言古诗","c":["谴绻西郭门，仓惶见车辕。","岂无连珠泪，哽咽不能弹。","车人唱登程，掩耳畏游环。","鸿雁孤飞鸣，噭噭悲以酸。","岁暮有临岐，乃在兄弟间。","况我罗家难，严亲滞深犴。","百恤在二人，行留竟何言。","留者差一身，行者百念攒。","白日布高天，不照幽谷寒。","高天会有卑，幽谷会有迁。","豺虎卧中逵，狐狸为司藩。","勖哉閟其口，毋乃令人传。"]},{"t":"答俞氏 其一","f":"五言古诗","c":["肃肃短后衣，烈烈北风吹。","譬彼罗原雉，毛羽乍摧颓。","婉娈唯古欢，踯躅惠来绥。","言当谐缱绻，不谓中乖离。","欲留不须臾，往者会无期。","临别仰天叹，星斗纵横垂。","腹中双车轮，宛转先路驰。"]},{"t":"答俞氏 其二","f":"五言古诗","c":["严冬河水涸，扁舟不可方。","君子念仳离，中夜奏清商。","四坐皆掩袂，欲起更彷徨。","浮云南北垂，宿鸟东西翔。","我欲和此曲，沈块结中肠。","竦身就危途，欢爱竟茫茫。","勖哉居平思，毋为厌景光。"]},{"t":"答俞氏 其三","f":"五言古诗","c":["悲与知友别，生死尽一言。","请说南山松，嵯峨上摩天。","陵谷中崩溃，倏忽委道间。","虚有榱栋材，谁为匠石宣。","樵夫薪其枝，斤斧日丁丁。","长当辞丘壑，掩郁复怔怦。","中有千岁膏，下有万年苓。","芬芳幸未歇，倘以奉遐龄。"]},{"t":"沙头送曹甥比部之京作","f":"五言古诗","c":["之子初赴除，张筵广川涘。","飘盖垂杨端，征驹草相媚。","伊余芒屩者，径来一把袂。","偶咏颜远篇，不挥殷生泪。","归卧东海庐，苍然白云至。"]},{"t":"古意慰子与使君","f":"五言古诗","c":["南山孤松柏，落落干苍冥。","天籁发其颠，旦夕鸾凰鸣。","烟霞时栖托，日月避精灵。","玄霜冠穹来，郁郁不改青。","何意东风举，摧我虬龙形。","语客请勿轻，客亦勿见凌。","东风谥为狂，松柏自有名。","中有千岁脂，下有万年苓。"]},{"t":"送华存叔北上","f":"五言古诗","c":["大江日夜声，寒云摧天黑。","江头一樽酒，言饯东山客。","鸿雁因高风，翩翩各南北。","念当乖形影，昵昵不忍释。","王睢为代言，乘时厉羽翮。","抚壮当及功，竖儒多自失。","隗俄燕昭台，黄金栖其侧。","毋以千里资，轻为世人得。","骧首忽长鸣，幽州莽生色。"]},{"t":"病中别沈子嘉则之扬州","f":"五言律诗","c":["溽炎始见蠲，微痾俄相逐。","故人弃我去，使我惊局促。","杂绪难尽言，轻帆易辞目。","惆怅离后思，广陵雨中绿。"]},{"t":"复张幼于","f":"五言古诗","c":["荆璞虽自良，在閟谁见赏。","鸣球悬东序，匪搏焉为响。","托契并冲融，扬辉何高朗。","之子邓林彦，髫年吐神爽。","鸾姿谢雕饰，蠖伏韬宏养。","虽尔时所趣，居然汰群奖。","九域衡捭阖，千龄恣偃仰。","乃以拙薄姿，当君中心往。","御李匪自华，比杨仍差长。","树敌牙颊间，抗交云霞上。","携手汎具区，所睹但泱漭。","日月驰双驭，乾坤发遥想。","勖哉爱兰芬，毋使沦霜莽。"]},{"t":"过扬州留寄方德新侍御","f":"五言古诗","c":["君前潞河发，我前广陵去。","野人工策蹇，使者虚乘遽。","北风江上来，停云冒成絮。","归心亦如此，安能为君住。","惆怅丛桂月，苍苍已如雾。","含辛即路岐，摅衷在毫素。"]},{"t":"赠陆丈人","f":"五言古诗","c":["逢君衢路间，憔悴车马姿。","斗酒相慰劳，拂拭故冠衣。","长跪问旧乡，掩涕不自支。","催徵多异政，庐井无新炊。","昔为州郡佐，投劾强言归。","今者一老翁，县官更相欺。","弱息苦不任，白首愿多违。","谁云田家乐，翻令仕路嗤。","彭泽者何人，当其归去时。","种秫以卒岁，高枕咏皇羲。","我欲营菟裘，太息不成辞。"]},{"t":"读李献吉何仲默徐昌谷三子诗 其一","f":"五言古诗","c":["夔峡收英灵，乾坤无真色。","扰扰操觚士，各务徇所得。","恍若襄城辙，俱迷阴陵泽。","明兴我高帝，神武肆荡涤。","七叶开人文，畴能承休德。","是时北地生，草昧发超识。","手挽天河流，千秋鸿濛坼。","坐令景从辈，齐声谐其则。","矩步宁敢渝，狂者羞践迹。","宁知龙变化，夭矫不可即。","彼以蛙黾趋，胡然矜相测。"]},{"t":"读李献吉何仲默徐昌谷三子诗 其二","f":"五言古诗","c":["孝皇握鳌极，万宇扬休光。","艺士被天来，大雅竟难方。","北地既龙举，信阳遂鸾翔。","彼美在弱冠，振馥戢时芳。","二华削莲花，高掌媚太阳。","朝霞洛溆波，因飔自文章。","二子琢相就，流趋互雌黄。","听曲昧其名，焉在讥颉颃。","寄言夸毗者，冥趋良可伤。"]},{"t":"读李献吉何仲默徐昌谷三子诗 其三","f":"五言古诗","c":["伊昔吴都彦，挥翰藻思披。","珊瑚间木难，粉黛映参差。","岂乏妖丽观，适志良以稀。","奕奕昌谷生，中道起其微。","青天荡胸表，白日行须眉。","秋鸢搏羊角，夏雨结虹霓。","泠泠松泉响，濯濯芙蓉姿。","当其所得意，直与作者期。","为郎叹寂寞，短年悲奄遗。","匪但一世隘，终焉造化疑。","贞也乡之人，瓣香夙所私。","广陵怅云绝，山水欣自知。","要令千岁后，更奏金兰辞。"]},{"t":"二贞篇 其一","f":"五言古诗","c":["徐卿志恬穆，闇然不自持。","虽复兴文藻，要非中所施。","踯躅俦侣间，咸顾私胜之。","营卫若千金，一捐不复疑。","青天见河岳，白日回光仪。","所遇各自失，焉能强攀跻。","汝往稽剡滨，高视浮云驰。","余复白驹篇，太息不成辞。"]},{"t":"二贞篇 其二","f":"五言古诗","c":["任侯神明守，吏道将余师。","东风被蒿莱，欣欣各自私。","力欲洪波偃，一苇恐难支。","俯窥龙蛇宅，仰睹星辰移。","志士轻丧元，白刃蹈如归。","能令行间伍，戚若同根枝。","老父抚国殇，为侯捐不辞。","婺妇泣其夫，身今得所施。","精诚贯烈日，天听竟能卑。","纠纠干城士，厚禄拟何为。"]},{"t":"五子篇 其一 济南李攀龙","f":"五言古诗","c":["纤阿出溟渤，皓魄中天发。","列宿岂不显，杳然精灵摄。","先秦收正始，六代时汩没。","夫子扬嘉馨，千载驭飙軏。","思排入渊旷，象成自昭晰。","至理中所赏，胡然见时悦。","夫子乃沉沦，纷纷亦奄忽。","六合惨淡间，微生借嘘拂。","并啸倚崆峒，苍苍极秋色。","上有三危露，芝菌芬樛结。","攀英啜其滋，虹霞动灵宅。","却笑羡门者，长生等澌沫。"]},{"t":"五子篇 其二 吴兴徐中行","f":"五言古诗","c":["蔼蔼洵吉士，产秀自天目。","冷冷穆风披，青阳振膏馥。","调气玩时人，幽怀被商曲。","客从东方来，贻君以迷谷。","含吐兹未酬，宛然中心笃。","柔条沃嘉霖，虽罢中所欲。","良璞困铝错，连城谢其琢。","逝将因君御，并起双鸿鹄。"]},{"t":"五子篇 其三 南海梁有誉","f":"五言古诗","c":["大溟湛珊瑚，陆离灼丛条。","龙伯何神举，弱纬连六鳌。","之子为国经，含英奉清朝。","汎澜先民蕴，眷念首阳椒。","杜权形俱敛，匪战理自超。","贱或重千钧，贵则等逝飙。","罗浮七十二，一一摩层霄。","玉笈子长往，金徽予罢操。"]},{"t":"五子篇 其四 武昌吴国伦","f":"五言古诗","c":["高旻漏元气，泻作黄河流。","排荡识其支，焉睹昆崙丘。","武昌蕴夙解，独往恣神搜。","亥步亦何穷，原问非所雠。","仰窥太乙精，冷然注天湫。","调浪鼓青阳，馀风映素秋。","下士俱大笑，哫訾不能休。","宁知帝弄臣，坐令鞭九州。"]},{"t":"五子篇 其五 广陵宗臣","f":"五言古诗","c":["伊人璠玙彦，履盛无婴躬。","岂鲜盈门轨，匪其径寸衷。","为寿不在年，千秋以为终。","斯道苟不芜，排卫当谁功。","沉沦知夜光，鸿鹄高天风。","枉矢射彭城，逸劲饮石梁。","谁谓汉哉广，裹糇航扶桑。","竦身太华颠，群途杳茫茫。"]},{"t":"后五子篇 其一 南昌余曰德","f":"五言古诗","c":["德甫负耿介，往往排群好。","楚咻非所顾，齐风乃同调。","续缗媚沈川，夜光为之耀。","累柯刈宿楚，山骨露幽峭。","有向必当心，寻源乃深造。","是时西曹彦，苦李在周道。","所以获自全，闽天舒清啸。"]},{"t":"后五子篇 其二 蒲圻魏裳","f":"五言古诗","c":["魏生狷者流，勃窣名理窟。","物好都不营，而以求真悦。","眄睐当世人，迷津要余筏。","片语识其端，雄思坐超发。","莽苍大卤间，一抔何硉兀。","挥手出嵩乔，青天距如发。","安得凌风翰，送子排真阙。"]},{"t":"后五子篇 其三 歙郡汪道昆","f":"五言古诗","c":["伯玉人间人，忽往在千古。","矫矫先秦则，耻为东京伍。","匠郢斤成风，所至自规矩。","一汰尘调非，耳观众稍沮。","论交岂必面，飞书示肝腑。","四十开闽疆，黄金絓其组。","吾道何必然，诸子气亦吐。"]},{"t":"后五子篇 其四 蜀郡张佳胤","f":"五言古诗","c":["才士地不乏，岷峨所钟英。","之子试为令，快若刃发硎。","循吏在中牟，亦足垂其名。","改途遵词苑，方驾结齐盟。","雅郑纷奏前，至耳选其正。","白雪发高倡，下流皆令声。","安得凌风翰，长翱于玉京。"]},{"t":"后五子篇 其五 新蔡张九一","f":"五言古诗","c":["助甫秉天秀，弱龄藻辞锋。","一出宰岩邑，百吏趣下风。","入佐天子铨，搢绅所景从。","折节礼楚累，群诼藉相攻。","揽辔西南纪，清商变炎空。","下蔡出倾城，皎若青芙蓉。","宁为众人妒，不为众人工。"]},{"t":"广五子篇 其一 昆山俞允文","f":"五言古诗","c":["俞生不偶世，削迹混屯夷。","时冶避大质，天籁窍幽机。","怀璧非所愆，含英竟焉辉。","晨炊不逮暮，室人交谪讥。","玄商吹衡宇，霜霰无停飞。","悠然眉间色，忽映西山薇。","娄水逝洋洋，偕子以乐饥。"]},{"t":"广五子篇 其二 魏郡卢楠","f":"五言古诗","c":["卢生富结撰，扬马有遗则。","及乎为诗歌，雅好在李白。","春风扬波澜，浩渺靡所极。","仰见朝霞媚，俯见水五色。","蛾眉一成妒，雄飞铩其翮。","朝奏狱中书，夕为坐上客。","妻子不殢人，长歌下震泽。"]},{"t":"广五子篇 其三 濮阳李先芳","f":"五言古诗","c":["伯承侠者雄，摛词何尔雅。","芙蓉秀浊水，清芬自堪把。","往知在倾盖，携手即中野。","四顾邈无俦，幽怀浩倾写。","行行愉江宰，悒悒谁与解。","讼庭凉飔生，商歌和弥寡。","有志迫未竟，强为时人下。"]},{"t":"广五子篇 其四 孝丰吴维岳","f":"五言古诗","c":["峻伯青云姿，饰玉振鸣步。","二十游京邑，兴文粲烟雾。","一出时贵倾，匪在戚与故。","此道行世间，识者如其素。","岂不谐众欢，要睹中心慕。","纾怀历下生，改辙遵广路。","雅郑辨已勤，况乃垂韶濩。"]},{"t":"广五子篇 其五 南海欧大任","f":"五言古诗","c":["欧生最晚交，其识乃先曙。","旁猎六代言，郁为西京路。","五十而释褐，微官历扬豫。","一为邑文学，再典州掌故。","游宦岂必达，深衷托豪素。","掩抑再三叹，少小为名误。","宛宛照影姝，沾沾不虞妒。"]},{"t":"续五子篇 其一 阳曲王道行","f":"五言古诗","c":["明辅瑚琏姿，清芬溢其齿。","二十典方州，三十赐金紫。","虽负循吏声，雅非中所喜。","魔来付禅观，战胜归名理。","馀事乃及诗，亦方开元轨。","贻君山林日，朗旷自此始。"]},{"t":"续五子篇 其二 魏郡石星","f":"五言古诗","c":["石生昔抗章，攀天动星辰。","芬芳一世间，谁能不见亲。","论交须论晚，辨材须辨真。","肺腑一相披，灼然世无人。","未央郁造霄，赖子表嶙峋。","慨焉念漳流，沦没连城珍。"]},{"t":"续五子篇 其三 岭南黎民表","f":"五言古诗","c":["昔余客招提，黄鹄为徘徊。","五子临乖隔，黎生翩然来。","方响入丝桐，所奏靡不谐。","濩落金马门，骊龙狎其颏。","非无蛾眉妒，隐酒不见猜。","和光同其尘，老氏我所推。"]},{"t":"续五子篇 其四 豫章朱多煃","f":"五言古诗","c":["骥足有八荒，惜哉枥中老。","王孙负奇气，少即成潦倒。","幸无诗书禁，千古恣搜讨。","窘回长沙袖，迂逐淮南宝。","俯仰宇宙间，局如束湿草。","富贵非所求，令名良自保。"]},{"t":"续五子篇 其五 虞邑赵用贤","f":"五言古诗","c":["子师名家隽，出入珠玉府。","所获岂不赢，而以求真与。","将无一时屈，所伸在千古。","寸铁宁不顽，连城繇兹睹。","入夜必自光，勖子无轻吐。","秦人已睥睨，荆人犹龃龉。"]},{"t":"四十咏 其一 高太史启","f":"五言律诗","c":["季迪负神启，骏发自名郡。","纵毫动天籁，调篇黼皇运。","遘世无永晷，后身有嘉问。","琏琢藉未工，楚氓悲其瑾。"]},{"t":"四十咏 其二 黄给事钺","f":"五言律诗","c":["叔扬践华省，食贫无异操。","奋为墨衰举，匪以弓旌招。","借箸画勤王，湛渊报久要。","形泯神自王，松柏苍然乔。"]},{"t":"四十咏 其三 王逸人宾","f":"五言律诗","c":["逸人挫荣者，浮沈竟阛阓。","折姚见玄理，访戴袭奇秘。","既殊紫芝宦，复异鹿门娶。","玄德诚可师，毋乃为孝累。"]},{"t":"四十咏 其四 姚少师广孝","f":"五言律诗","c":["少师遁儒迹，握筌理玄符。","业由杀机发，教以神用敷。","赫赫不迁庭，侑公配宏谟。","胡然踏迷复，缁衣即永途。"]},{"t":"四十咏 其五 杨尚书翥","f":"五言律诗","c":["杨公岿然老，故人握璿玑。","遂令武昌戍，阳春回赭衣。","曳裾时豹隐，推毂乃龙飞。","优游桑梓间，树惇以全归。"]},{"t":"四十咏 其六 陈僖敏镒","f":"五言律诗","c":["僖敏长者度，时展经纶才。","白马出秦关，虬髯何壮哉。","河陇既以奠，尸祝至今开。","岂知衿裾士，威誉扬九垓。"]},{"t":"四十咏 其七 陈佥事祚","f":"五言律诗","c":["退翁昔持宪，骢马何翩翩。","先疏已致身，敢望天子颜。","臣祚诚无状，百折宁不前。","虽或谢几哲，终焉保贞坚。"]},{"t":"四十咏 其八 俞司寇士悦","f":"五言律诗","c":["太保禀刚峭，面色凌壁铁。","所至如子元，网络甚张设。","赭衣忽被体，永谢孤卿列。","道遇金齿公，后车亦齐辙。"]},{"t":"四十咏 其九 徐武功有贞","f":"五言律诗","c":["武功蕴宏略，希世遘奇表。","挟日肇封祚，治水赞熙皞。","大勋古难恃，令名当自保。","迢迢南中云，恻恻羡飞鸟。"]},{"t":"四十咏 其十 刘文恭铉","f":"五言律诗","c":["文恭达节者，畏荣恒惄如。","群谋徇天步，独行竟何濡。","食报遗后人，位绌永令誉。","乃知癯然叟，可以托遗孤。"]},{"t":"四十咏 其十一 张提学和","f":"五言律诗","c":["穆也非不佳，节之难为弟。","当其射策时，英声动宸扆。","斲轮见老手，藻鉴存清视。","造物亦忌人，荣名沦散位。"]},{"t":"四十咏 其十二 韩襄毅雍","f":"五言律诗","c":["襄毅秀弱冠，扬策振天路。","中踬乃益习，晚柄谐所遇。","威伸七纵略，功成五月渡。","壮心寄隐迹，坐惜齿龄暮。"]},{"t":"四十咏 其十三 叶文庄盛","f":"五言律诗","c":["文庄琐垣彦，直志济遐瞩。","边土仗雄望，岭越借宁隩。","日晏坐繁省，归来奏清曲。","古道终有谐，今焉叹时服。"]},{"t":"四十咏 其十四 鱼开封侃","f":"五言律诗","c":["鱼侯治雄都，贪吏逆洗迹。","中岁赋归欤，妻子犹菜色。","虽乖清泌乐，终守西山则。","人事良可悲，天心竟焉极。"]},{"t":"四十咏 其十五 刘参政昌","f":"五言律诗","c":["太中少颖脱，往往出新诣。","跌宕郎署间，清芬蔼然萃。","五岭穷履迹，三苍辨鼎识。","乃知忌者心，翻然为名计。"]},{"t":"四十咏 其十六 孔侍郎镛","f":"五言律诗","c":["司空守荒郡，筚路启山林。","万面若猿猱，片言剖其心。","箫鼓荐丛祠，生存多飨歆。","是以临没候，列宿表精祲。"]},{"t":"四十咏 其十七 吴文定宽","f":"五言律诗","c":["文定秉谦退，冥志在坟典。","所树苟先众，宁辞步趋蹇。","朝回对花竹，落日照开卷。","此意今所难，吁嗟德音鲜。"]},{"t":"四十咏 其十八 王文恪鏊","f":"五言律诗","c":["文恪辞家流，广庭振华毂。","帝时绌师臣，遥迹肇枚卜。","竖人窘犬步，惄焉叹一木。","归卧洞庭野，世往誉恒馥。"]},{"t":"四十咏 其十九 陆太常釴 张脩撰泰","f":"五言律诗","c":["二君青云彦，摅辞复同调。","釴也千仞壁，苍翠绝奔峭。","泰如飧芝露，九咽动灵窍。","黼黻未章施，长算屈短造。"]},{"t":"四十咏 其二十 先祖司马讳","f":"五言律诗","c":["昔我先司马，敡历遍遐荒。","至今讼庭树，往往比甘棠。","蔼如三冬日，凛若九秋霜。","千载循吏编，庶以绍龚黄。"]},{"t":"四十咏 其二十一 李少卿应祯","f":"五言律诗","c":["少卿善书法，强起侍中秘。","诏为译经藏，卿也独奏记。","吾道有九经，上其幸留意。","百折终不回，荣名沦末位。"]},{"t":"四十咏 其二十二 陆太宰完","f":"五言律诗","c":["陆公秉戎枢，受脤事横征。","中流荡日月，殷波血鲵鲸。","归来宴父老，故里高车迎。","没齿甘巨僇，焉能终令名。"]},{"t":"四十咏 其二十三 杨仪部循吉","f":"五言律诗","c":["仪部志狂者，坟丘事冥讨。","三十而挂冠，握机岂不早。","胡哉昧远算，一出为小草。","揽其遗文辞，悼彼耄昏夭。"]},{"t":"四十咏 其二十四 毛文简澄","f":"五言律诗","c":["毛公践华显，秉性乃恬易。","杜门饮醇酒，口不谈世事。","一遇鼎革间，铿然践坚议。","天怒百不回，秋风有归计。"]},{"t":"四十咏 其二十五 顾太保鼎臣","f":"五言律诗","c":["文康自讲筵，磊落真主识。","锁钥见深寄，版筑遗芬泽。","坐客悚莫干，虬须紫如磔。","少选出新声，彷佛安昌席。"]},{"t":"四十咏 其二十六 徐迪功祯卿","f":"五言律诗","c":["昌谷振奇士，玄览意何卓。","芙蓉秀浊水，苍隼击寥廓。","调古鲜同驱，名高远时作。","讵为坎轲恨，短年亦予乐。"]},{"t":"四十咏 其二十七 魏恭简校","f":"五言律诗","c":["魏公秉渊著，雅志慕古昔。","时衍洙水流，力断曹溪脉。","巷牖稍已乖，簪缨遂中辟。","三绝苍颉编，往往明心画。"]},{"t":"四十咏 其二十八 朱尚书希周","f":"五言律诗","c":["尚书握留铨，五十遂悬车。","优游更三纪，块然返其初。","眉宇蔼春阳，和风被里闾。","良璞犹未雕，见者称璠玙。"]},{"t":"四十咏 其二十九 周恭肃用","f":"五言律诗","c":["恭肃故长者，所历多恬穆。","及乎握台纲，霜天见雕鹗。","藻鉴虽已晚，弹冠众相乐。","车门日夜开，无金可称却。"]},{"t":"四十咏 其三十 沈居士周","f":"五言律诗","c":["沈生逸者流，夙尚丘壑贲。","缅怀徇所好，十日一山水。","游戏无全目，纵横得真理。","平生所馀事，耿耿乃在此。"]},{"t":"四十咏 其三十一 祝京兆允明","f":"五言律诗","c":["希哲寄声酒，诙谐放情素。","翰墨人尽研，巧者由机悟。","游龙宛霞浦，芙蕖发朝露。","世上亦何有，悲此邯郸步。"]},{"t":"四十咏 其三十二 方太常鹏","f":"五言律诗","c":["庶子负书淫，终岁勤述作。","谢病再起官，将因传礼乐。","鹤禁屣若遗，清卿秩仍削。","悠悠见素心，所享不辞薄。"]},{"t":"四十咏 其三十三 文待诏徵明","f":"五言律诗","c":["文翁负耿介，至巧亦天性。","髫年却金赙，中岁辞藩聘。","既三郑氏绝，仍齿伏生境。","遥裔播休华，千秋犹辉映。"]},{"t":"四十咏 其三十四 周寺丞凤鸣","f":"五言律诗","c":["大理世其官，能文法无害。","执宪昌言朝，如何与谴会。","音容自矩律，筴算几蓍蔡。","积俭乃起家，栾伯惭其汰。"]},{"t":"四十咏 其三十五 朱中丞纨","f":"五言律诗","c":["中丞匪躬者，仗钺事专征。","瘴海肃鲸波，舟航偃不惊。","涣群婴众铄，披已乃孤诚。","安能对狱吏，慨焉捐此生。"]},{"t":"四十咏 其三十六 陆太常粲","f":"五言律诗","c":["浚明经国才，所逊在勇沈。","虽复豪文战，而乃非素心。","鸣凤吐朝阳，渐鸿遁中林。","幽怀故有托，宁为遘荒淫。"]},{"t":"四十咏 其三十七 王选部谷祥","f":"五言律诗","c":["禄之当佐铨，皛皛若冰玉。","归来三十载，岁月天所属。","辟书再及门，澹若云过目。","何必写匡山，胸中有岩谷。"]},{"t":"四十咏 其三十八 先御史大夫讳","f":"五言律诗","c":["外侮中不竞，疏者亦暂亲。","矫矫先大夫，一身当百身。","白日照披肝，噫气成星辰。","痛无九京辙，为言诛佞臣。"]},{"t":"四十咏 其三十九 王太学宠","f":"五言律诗","c":["履吉藉甚年，灼乎舜华敷。","非酒使人酣，况乃荐醍醐。","玉树困霜风，良騊蹶脩途。","其迹犹尚新，其人骨久枯。"]},{"t":"四十咏 其四十 黄徵君省曾","f":"五言律诗","c":["勉之富三馀，垂言亦惊众。","收名良已博，负大不易用。","公车一报罢，遂甘醯鸡瓮。","有子能象贤，居然冢枯重。"]},{"t":"三杨诗 其一","f":"五言古诗","c":["矫矫射洪君，累资奉卿列。","勋称或后人，所治多惠辙。","金紫外相縻，生平一短褐。","权貂干天纪，况挟左道蠥。","内禅移襁褓，社稷丝系绝。","群公满台省，往往比稷卨。","相顾但摇首，彼睹恒结舌。","君也义所愤，草奏遂身诀。","神仙归杳茫，药石吐祻孽。","秦王与汉武，远鉴乃昭晰。","岐嶷固齐圣，万几恐未哲。","臣某甘砧盎，为国谋岂拙。","是时阊阖开，宿卫浴金铁。","一传常侍诏，班行胆为裂。","青天朱云槛，碧日苌弘血。","皇灵终动变，魑魈亦归灭。","至今穆清表，帝座烱长彻。","国事甘一身，微诚竟何雪。","万古涪江流，剑岭更巀嵲。"]},{"t":"三杨诗 其二","f":"五言古诗","c":["天地气不灭，今古递流行。","岩岩富平君，所得何太赢。","朝籍未云久，浩然厌承明。","绌志终老亲，食力乃躬耕。","贷粟耻监河，独行异于陵。","峨峨獬豸冠，一出狐豕惊。","两分既以展，慷慨示平生。","訾亹探乱源，力欲奸谀清。","屈指及四五，天怒不为恒。","九关下虎豹，白日纷雷霆。","沈冥狴犴间，血肉浩纵横。","十载无生晷，万死有馀诚。","荷校诵遗编，庶几演周经。","茹甘岂以蓼，就燠岂以冰。","诚知非身计，心各有重轻。","终荷帝垂察，役服等齐氓。","未永鼓腹游，溘哉大命倾。","此疏忆昨传，夜灯尽荧荧。","片纸或只言，若引九鼎絙。","归骨二华颠，咸秦遍精灵。"]},{"t":"三杨诗 其三","f":"古风","c":["踯躅广莫间，乾坤迫迟暮。","一接容城生，遂令豁衷素。","往者大难集，边尘窘天步。","?藩托援师，皇诚柰深顾。","阴谋重借寇，耗我黔首赋。","谓遘互市欢，弭其来侵路。","生也叫阊阖，画沙请前箸。","堂堂如中国，戚戚仅奸竖。","障尉适穷边，年命不反悟。","乾威■竖魄，伏机乃大露。","命尔尚书郎，忧天渐成痼。","赐环主恩深，请剑臣节固。","安危托将相，腹心横巨蠹。","岂惟臣私愤，万口胁莫吐。","吏议既以深，龙鳞遂终忤。","惨淡滨海臣，传章复寻讣。","夕卧五四起，明河望东注。","颇闻草奏时，业已为棺具。","元造竟何心，茫茫一身付。","所忧在国谋，敌志谐举措。","大泽沦兼城，澜涛谁能募。"]},{"t":"偶书 其一","f":"五言古诗","c":["郁郁桓魋墓，白石何嶙峋。","惜哉三年力，不能葬其身。","空见抚琴士，千载悲斯人。"]},{"t":"偶书 其二","f":"五言古诗","c":["黄雀拟螳螂，下乃见弹射。","古来奸雄辈，颇复遇其敌。","祸败徇所常，胜者亦焉得。"]},{"t":"偶书 其三","f":"五言古诗","c":["邯郸倡家女，巧笑倩红妆。","如无好颜色，何以结不忘。","借谓鲜所私，何以得为倡。"]},{"t":"偶书 其四","f":"五言古诗","c":["长安狭邪客，片语黄金千。","归来但壁立，四座称豪贤。","称者渐不识，零落一身偏。"]},{"t":"偶书 其五","f":"五言古诗","c":["贾客狎风波，黄金如山积。","人云贵明珠，遂适海外国。","垂老鲸鲵身，呜呼竟何惜。"]},{"t":"将赴计偕呈同志","f":"五言古诗","c":["神都亘天北，长河万里开。","文星起吴会，熠煜凌金台。","朔气日夜深，我行何壮哉。","君看孤舟去，应驱驷马来。","丈夫但有足，迹当遍九垓。","长揖辞故知，肯为儿女怀。"]},{"t":"秋风","f":"五言古诗","c":["燕台廪秋速，永夜何萧萧。","高树回天风，木杪溢洪涛。","初至惊客梦，忽来侵薄裯。","纨扇委故箧，园英悴新朝。","烈炎宁久固，时至讵能逃。","吾将感世运，行矣任所遭。"]},{"t":"除夜有感","f":"五言古诗","c":["此岁尽此夕，此夕不再得。","大化何心去，流光长自惜。","明日更明年，明年重可怜。","花迷上林月，梦落楚江烟。","相逢半游子，陆沉金门里。","朝典苏季裘，暮乞侏儒米。","千岁递相送，那能屡禁此。"]},{"t":"斋日作","f":"五言律诗","c":["兹辰方致斋，况乃停推剖。","无事卧起迟，日色在杨柳。","瓢壶盈豆粥，煮茗用当酒。","诸君勿复言，予祷亦已久。"]},{"t":"阻风下邳南待发有作","f":"五言古诗","c":["积风见日色，久客见容颜。","翳翳昏黄交，桑柘自生烟。","惝恍一飞凫，乃是天际帆。","倏焉过舷际，欲挽不得言。","去者日以去，还者何时还。"]},{"t":"初拜使命抵家作 其一","f":"五言古诗","c":["去家未十载，结绶始言还。","惝恍梦寤间，历历陌与阡。","耆老揖且疑，安识众少年。","昔别犹髫龀，今来室家完。","酒炙争慰劳，陆博夜喧阗。","解带著庭树，改席临后轩。","离合诚欲轻，焉睹鬒及前。"]},{"t":"初拜使命抵家作 其二","f":"五言古诗","c":["乍出城东门，秋禾郁离离。","池塘渐为窞，鸡犬亦声微。","冠者五六人，不能具裳衣。","庐舍虽如昨，亦复少光辉。","借问何所因，何以不成辞。","摇手长吏嗔，恻怆涕交颐。"]},{"t":"初拜使命抵家作 其三","f":"五言古诗","c":["道逢皤然叟，罄折前揖之。","叟顾何官宦，姓名尔为谁。","光彩溢闾里，于职竟焉宜。","罄折前谢叟，汗洽失陈辞。","天子衠明圣，叵测异威施。","小臣实微贱，三尺安能持。"]},{"t":"初拜使命抵家作 其四","f":"五言古诗","c":["出户明星薄，隐隐见苍黄。","稻禾集若云，杵臼捣为霜。","东邻呼看社，西邻馈酒浆。","鸡犬随亦喧，况乃童稚行。","挂我新时冠，着我旧时裳。","居然一田父，岂必言庙廊。"]},{"t":"天津道中述怀","f":"五言古诗","c":["宛然天津树，一夜风吹索。","停耳多哀音，寓目寡鲜泽。","况乃淹道途，脉焉芳华铄。","浩浩四序交，天地为常格。","忧欢生殊态，岂必当摇落。","阮公回车恸，虑生诚不薄。","陶令爱沉酣，中怀何能度。"]},{"t":"德州渡口","f":"五言古诗","c":["月细仅如钩，疑升复疑没。","美人沙间坐，白露湿罗袜。","低头怨去船，举头愁残月。"]},{"t":"朱象玄太史册封楚藩云将取道南游太岳诗以送之","f":"五言古诗","c":["于皇展亲睦，宗子介樊襄。","玉圭黄金册，炜晔出尚方。","伊余同门友，洵美清而扬。","诏其辍史幄，尔往钦哉将。","天都辟阊阖，九奏何锵锵。","莲烛际宸晖，星裾搴御芳。","前呼薄崇椒，后饯塞津桥。","白茅仍拥节，班马重横镳。","雪里蓟门树，花前汉江桡。","汉江一千里，方城暮烟紫。","鸣钲荡鱼龙，解缆采兰芷。","荜路捧霓旌，从价蹑珠履。","帝命尊若天，王封固于砥。","此时雍堤柳，柔条尽抽绿。","上客金马姿，小儿铜鞮曲。","山问诸葛龙，门访庞公鹿。","羊碑摩绝翠，鲛渚泛明玉。","壮游重茫然，弭节太和巅。","挥手弄日月，荡胸拂云烟。","中有两仙童，跪捧琅函编。","奇字不可识，閟之二千年。","今遇蓬莱客，始宣至人传。","归上紫皇寿，珥笔长周旋。"]},{"t":"见边庭人谈壬子三月事有述","f":"五言古诗","c":["戍从上谷来，疮痍半侵面。","对酒不能酌，未语泪珠溅。","借问何为者，告我三月战。","妖氛祁连发，杂部呼衍遍。","令速飙雨集，台荒烽火眩。","卒然遇山头，狐兔窜散漫。","我师不盈千，敌众已号万。","拓弓鸣霹雳，走马蹙飞电。","层冰煜戈甲，乌云罩发辫。","中间两旗出，倏忽天宇变。","况乃积威后，吏士总灰汗。","低头念父母，黄泉去几线。","亡矣存不知，人耶鬼难辨。","桓桓时将军，擐甲流英盼。","饮水贾逸勇，解鞍示馀算。","坚重麾下当，腾骧诸孙先。","赴敌均戴天，丧元等飘霰。","屡冲亡移足，再接莫逃眴。","批捣肉郊原，喧呼涛江汉。","日莫围未解，炊烟出胸咽。","白马飞护军，朱缨光灿灿。","斩其前却骑，赏彼兵锋冠。","长空双眸疾，宛转堕一箭。","咋指大众遁，横戈锐行殿。","橐驼墙外收，野老沟中看。","痛定还神魂，追思更摇瞑。","倘不天意在，人尽乌鸢饭。","呜呼一千卒，将军实枢干。","昨者捷书闻，欢溢未央殿。","论功非常格，行赏绝淹旦。","南金䮍蹄方，蜀锦兽袍茜。","捧出皆动色，光辉耀驰传。","元戎何骄盈，闻之怒椎案。","手自推毂臣，不如偏裨贱。","十万羽林儿，膂力岂不健。","节制纷下施，功成违亦谴。","头颅完万死，肝胆折一见。","居平慕廉吏，募士黄金散。","家有鄠杜田，为寿前致献。","所丐假威严，那能望恩眷。","不然却敌身，充庖若凫雁。","妻子诟未平，部曲私相唁。","死生已独当，宠辱他人擅。","东邻酒家胡，洛阳业商贩。","甲胄为何物，勋名首腾荐。","人奴岂卫青，通侯及韩嫣。","纷纷貂尾续，汲汲羊胃烂。","天子实明圣，涂肝亦何惋。","所虑缓急膺，诸边士心玩。","请剑天茫茫，王室勿多难。"]},{"t":"薄暮发古城即所见志怀","f":"五言律诗","c":["一水天末明，馀霞乱相射。","错落披金膏，喷流万瑟瑟。","长啸招天风，为我驭海席。","吴越指掌间，黄花正秋色。"]},{"t":"行淮扬境汎甓社即事有作","f":"五言古诗","c":["湖波二百里，元气何茫茫。","天随一线尽，日起万鬣张。","无论南北风，但见来往樯。","炯若青铜镜，掩映美人妆。","惊鸥散明玉，唼藕夺冰霜。","纤鳞一入手，大嚼无馀觞。","冥见渔火微，静闻稻禾香。","榜人前后歌，语语子夜长。","人生剧可乐，何如近故乡。"]},{"t":"十五夜泊彭城无月呼酒既醉信口而歌成此一章","f":"五言古诗","c":["所至无可饮，欲邀中天月。","此夜桂树寒，姮娥蔽瑶阙。","玉兔寂无春，焉能天香发。","群山青不断，一一随沦没。","手酌自为欢，长歌入窈忽。","安得扫妖氛，鞭鲸度溟渤。"]},{"t":"天子诏职方张君子畏发齐兵平吴世贞吴人也恨不得从一卒之列慨然歌五言长篇为赠","f":"五言古诗","c":["太空下欃枪，化作千长鲸。","血吹海波立，高天斗峥嵘。","白骨为丘山，草木杀气腥。","朅来佳艳地，倏忽无所凭。","昨夜明光宫，君王议南征。","青齐良家子，少小学纵横。","白马雕蝥弧，银鎗鬘胡缨。","匣中报雠剑，得施欢自鸣。","横流一鼓噪，黄河西北行。","能使赤日暗，又令秋云明。","不待发远县，临淄人尽兵。","立看徒步间，往往足公卿。","此时羽檄使，矫若双千城。","乘传张廷尉，结袜王先生。","慷慨大风歌，发指上填膺。","轻飙荡雄心，散入鼓角声。","长鲸肉万类，终就鼎俎烹。","举头笑真宰，此辈竟何成。","惟应千年后，独书公等名。"]},{"t":"读梁公实诗有感","f":"古风","c":["罗浮七十峰，峰峰白云住。","鳌?海上来，吹君向何处。","咳唾落沧波，遂成珊瑚树。","欲作万古色，精英莽回注。","摩娑三叹言，胡人不可遇。"]},{"t":"为彭州李徵君题会泉隐居","f":"五言古诗","c":["帝女勺银汉，泻之岷峨间。","恍如一匹练，飞界万仞颠。","喧奔虬龙啸，错落琼珠圆。","蜀人有李意，学道殊精坚。","浇田出白璧，炼药返红颜。","何如饮神瀵，一住三千年。"]},{"t":"自燕中来者云斥逐轻薄朝士殆尽赋此解嘲","f":"五言古诗","c":["叱羿射狂日，令娲补漏天。","千秋绝至技，万象横妖躔。","问我今何适，吞声滞穷边。","问我何名姓，碧玉琬琰镌。","上帝有弄臣，戏博太山巅。","争道误一叱，中谗堕风烟。","临岐酌沆瀣，渴吻三十年。","月为琉璃盌，星是黄金钱。","小儿东方语，乡里惊不传。","一字犹未识，调笑司马迁。","左氏盲老公，龌龊诸侯编。","插天昭王台，至今在幽燕。","挟策往从之，飞翰独翩翩。","鱼服误白龙，豫且嬉广渊。","一为湛朱网，蛙黾遂来牵。","骧首叫阊阖，七萃俱茫然。","西入鹴鸠司，惨淡白云篇。","何来四五人，自称俱谪仙。","其魁广成子，安期或偓佺。","惝恍识其故，昔者上帝前。","托陪瑶池饮，归共青辎軿。","悟来忽大笑，灵气生五咽。","岂无兜离乐，不得誇喧阗。","高歌灞陵畔，落日珊瑚鞭。","酒间呼白雪，片片下琼筵。","四海水四勺，五岳五石拳。","且移华阳席，改就糟丘眠。","一言斗突兀，万目纷睊睊。","猛虎欲齧人，不肯避豪贤。","腐鼠岂入眼，鹓雏遇鹰鹯。","执戟鬓垂白，巧宦笑其玄。","举世逐狂且，南威故不妍。","头颅无凡骨，不爱插貂蝉。","君自吹胡管，我自挟朱弦。","请君勿相忌，君亦勿见怜。","但令放之去，归种南山田。","野夫事真宰，肯受时人权。"]},{"t":"醉赠故张职方重","f":"五言古诗","c":["匈奴十万骑，席捲燕山红。","羽檄天下兵，谁能辨英雄。","张侯尚书郎，倜傥国士风。","还他惠文冠，佩我乌号弓。","匣中吴钩色，煜煜青芙蓉。","三晋侠少年，结束花䯀骢。","一呼万众合，片语千金空。","还迁缙云氏，上计葡萄宫。","颐指金吾帅，长揖司马公。","画地作黄河，波涛起其中。","挂冠神武外，买田平陵东。","匕首铸腰镰，吹愤气成虹。","我本落魄人，衣带绁其躬。","相携一斗酒，醉眼天朦胧。","掷君牛角书，莫令我辈逢。","请看长安道，功名谁得终。"]},{"t":"过东阿怀古","f":"五言古诗","c":["步出齐东门，遥遥飞车壒。","荒城阙睥睨，外与颓垣会。","榛芜侵周道，鸟雀骄有赖。","伫想英王风，凛焉今安在。","千秋阿大夫，当时偶一败。","茫茫长安日，归欤欲谁待。"]},{"t":"方子出示吴徐二子诗有感","f":"五言古诗","c":["二子吾诗南，苍茫散星斗。","招提终天泪，万象俱頫首。","如何双骊珠，荧荧落君手。","虬虎攫春冥，风雷走晴昼。","须眉恍相值，谈笑若在口。","薄谪吾人事，荣名定谁久。","匡庐武夷间，真宰亦知否。"]},{"t":"参议范君视事三日即出泰安过莱海还赍表而北赋此赠之","f":"五言古诗","c":["范叔倜傥士，南州多令声。","忽如阮陈留，骑驴向东平。","饮酒仅三日，翩然朝玉京。","昨闻太岳来，呼吸通神明。","题诗丈人石，万象俱峥嵘。","东游观莱海，海水殊浅清。","中有贯月槎，乘之汎蓬瀛。","天门为君辟，河鼓扶道迎。","莫采白榆钱，人间失岁星。","水击九万里，倘其念南溟。","尺鴳在衡藩，栖栖竟何营。"]},{"t":"诸方警报丛至用成孤愤投寄翁朱二公","f":"五言古诗","c":["淮海惊鳞踊，江介衡波流。","会稽栖组练，槜李集星斿。","鹊兴晋阳甲，猬起牂牁雠。","闽岭无完土，燕秦鲜宿糇。","谁谓八纮广，束我如一抔。","戢戢趍亨士，寥寥倾否猷。","结发辞家食，举宗被恩休。","陈列郎署间，剖符东海陬。","揣分虽不任，匪职难为谋。","慨矣扶风啸，越石不梦周。","率尔千乘答，仲尼或哂由。","况乃我严君，受寄在戎辀。","曾是北顾纾，缅怀中制忧。","久戍赋清人，零雨东山遒。","回光冀日月，返驾贲林丘。","请用微薄躬，上为君父酬。","七尺终归尽，寸心谁与投。","进虞处堂燕，退愧营巢鸠。","投分报公父，裁书谢阿游。","方驾骋天衢，执鞭如可求。","毋使局足鸣，重贻伯乐羞。"]},{"t":"过故陆虞部第有感","f":"五言古诗","c":["昔余奉使还，两饮虞部家。","虞部三郎君，各各斗豪奢。","初筵行大白，邀我醉梅花。","此梅十亩阴，老龙吐嵯岈。","酒酣吹铁笛，万玉乱横斜。","落月参黄昏，笑上白鼻騧。","再醉牡丹亭，春光亦繁华。","斗大赪金盘，朵朵压红纱。","疑将并州刀，碎裁洞庭霞。","珊瑚续夜照，不惜鞭日车。","此乐难数得，往往逢人誇。","转盼不十年，陵谷忽迁沦。","牡丹剉食马，老梅斧为薪。","东风依旧吹，惟见菜甲春。","额是虞部额，人非虞部人。","中有刁家奴，浊气搏秋旻。","虞部昔肺腑，况乃手足亲。","一为并吞念，百巧日夜新。","二子散他州，长者委黄尘。","问主既已非，此梅安足论。","归来见儿竖，骄騃不能驯。","抚心长太息，恻怆涕沾巾。"]},{"t":"夏日村居有述","f":"五言古诗","c":["江村养余懒，颇不病幽独。","维时仲夏初，长天气清淑。","野人太无事，自起为约束。","凌晨盥嗽毕，叩齿三十六。","始浇庭中花，次洗屋后竹。","荐麦欣及新，分葵味馀馥。","弄笔南窗下，醉沈凭淋漉。","金石四五编，骚雅一再读。","吸涧煮茗旗，松声腾波绿。","小啜清飔来，尘襟净于沐。","课童抄酒经，进客命棋局。","树影俄已圆，厨人报藜熟。","饭罢何所道，出门信其足。","扶耒古陇傍，垂纶清溪曲。","维东有兰若，经藏可游目。","随意手一编，无烦證耆宿。","斜阳语来下，炊烟布平陆。","及归尚未暝，蓬汤芬初沐。","晾发风衡门，明蟾破茅屋。","有友二三人，非雅亦不俗。","劝酬久已荒，匕箸肆所欲。","醽倾若下酒，粳汎宜城粥。","恍惚尘外语，星河莽相属。","瑜枕竹方床，湘文簟如玉。","中有腾腾乡，容吾便便腹。","缅怀康庄士，声势迫驱逐。","红尘沾褦襶，白汗脂炙毂。","所得仲孰多，百年亦良促。","寄言斧斤者，吾甘不才木。"]},{"t":"王生近诗爽然有天际真人想乃父沂州君濡首吏牍俱所不晓赋此赠之","f":"五言古诗","c":["我昔偕若翁，共醉燕山月。","寒飞双疾羽，惊风散仓卒。","回首秋色中，白云陶余悦。","半刺足翱翔，谁能念汩没。","落日琅琊台，萧然映华发。","岂伊莼鲈兴，不从步兵发。","识尔汗血时，英声动长安。","十年偶一见，握手罄所欢。","蓬蒿仲蔚地，山水伯牙弹。","天堕五色霞，赤城仙人餐。","吾子忽啖之，齿颊俱清寒。","太湖水浅深，要我弄鱼竿。","昨夜腐鼠过，鹓雏了不看。","仲尼畏后生，余亦惭先尔。","毋作一丘观，丈夫志弧矢。","大鹏戢两翼，黄雀不知止。","寄声招若翁，早访云壑里。","子其息南溟，九万从此始。"]},{"t":"邵子携同年袁鲁望诗来乞赠尊甫守中先生之作辄嗣响焉","f":"五言古诗","c":["凌晨叩门者，翩翩一佳士。","须眉映初日，清波溢其齿。","为余语若翁，少颇习名理。","种瓜东陵陌，卖药吴趋里。","迨乎耳顺年，遂三丈夫子。","子既饶青衿，翁乃傲黄绮。","忆昨上寿时，台使致筐篚。","门有守令辙，足无公庭趾。","上客陈珠玑，错落照翁几。","袁羊古遗狂，其言当不靡。","顾余亦有作，要为后期耳。","早晚春花开，醉翁三荆底。"]},{"t":"与松上人","f":"五言古诗","c":["昔我游丛林，颇与耆宿伍。","弹指百千偈，纵横藏中语。","自谓得宝珠，有取无不与。","今来谒松师，一语不得吐。","乃至欲吐时，涊然汗如雨。","回首青天空，荆棘皆净土。","持此拟叩师，恐师竟无许。"]},{"t":"读汪襄阳作顾季狂诗叙有感","f":"五言古诗","c":["昔我游燕山，宗李中所私。","高歌命白雪，片片纵横垂。","醉醒华阳馆，坐见青天危。","狂语两相厄，宁容世人知。","顾生业游者，一再侍酒卮。","风吹浮云散，信意南北驰。","契阔几十年，闻颇豪于诗。","矫矫汪襄阳，握手惠前绥。","谓余旧有赠，迪功乃其师。","左袒在中原，江左良见嗤。","自余遘家祸，戢身一茅茨。","名姓落人间，谁当齿颊之。","寄语谢襄阳，勿令豪杰窥。","吴门饶俊彦，诗卷日追随。","莫言秦越人，为秦作儿医。"]},{"t":"案头苏诗一编偶展读之有云龙钟三十九劳生已强半岁暮日斜时还为昔人叹公倅馀杭日作盖取白乐天语兴感也此公尚为摇落语吾辈宁无穷途之恸因成一章兼示舍弟虽然公兄弟名位穹显晚节各天而吾以早废弃故相守田亩间差为优耳他固不敢较也","f":"五言古诗","c":["偶诵苏公诗，龙钟三十九。","身犹一方佐，名满天下口。","伊余射策年，与公颇先后。","虽忝大夫列，六载归南亩。","人间失意事，所历无不有。","多岐梦犹惴，百炼心欲朽。","雌黄堕齿颊，雄白空知守。","西风傲短褐，居然成野叟。","流年蠹书卷，残日渔杯酒。","用禅文寂寞，塞兑防秽呕。","斋前种白杨，萧瑟鸣虚牖。","顾谓吾季方，吾言汝知否。","今古伯仲名，无出苏公右。","风云壮接翼，天地老分手。","踯躅瘴海间，能无叹不偶。","万事吾敢如，一得颇无负。","蓼莪固永废，棠棣幸终友。","去去入吴山，相携共白首。"]},{"t":"虎丘老僧有竹林精舍文伯仁为图之王履吉书疏于后余游竹林僧出示此卷履吉下世已三十载矣为之怃然因成此诗","f":"五言古诗","c":["山僧业静者，翛然无世氛。","朝疏淇澳雨，暮浣潇湘云。","老可湖州笔，为竹写清芬。","况有王子猷，英标冠人群。","自言读书处，何可无此君。","我来憩其下，流飔散馀醺。","其人不可作，太息读遗文。","新粉含幽月，苍翠郁纷纷。","截作山阳笛，凄凉安可闻。"]},{"t":"题赵千里画船子和尚卷后","f":"五言古诗","c":["秋江战寒飙，一叶纵横走。","船子有伎俩，舵柄时在手。","借问自渡者，还能渡人否。"]},{"t":"题募缘卷后","f":"五言律诗","c":["闻欲创招提，藉众檀越力。","而我贫里人，翻乞常住食。","所馀唯一物，无价亦无色。","念欲施山僧，觅之不可得。"]},{"t":"陆仲子为其友索题云洲即以塞白","f":"五言律诗","c":["白云不须山，沧洲不须海。","所以吏隐人，迹混心不改。","浮沉任波色，舒卷依天籁。","寄言采芳者，杜若青犹在。"]},{"t":"王山人自称十岳先有二诗见寄极国士之许千里命驾曾未淹日欲留金陵长篇见贻拂衣北首聊此和赠 其一","f":"五言古诗","c":["凤鸟摩青天，片羽飞东海。","却堕七尺篱，鴳目荧然改。","骊龙颔下珠，夜必吐光彩。","绿醑骄欲鸣，青灯耿相待。","不谓双垂杨，果系出剡舟。","野夫虽称病，为汝梳白头。","沈沈薜色夏，忽起商飙秋。","特达壮士胆，未许黄金酬。","谓予九州外，当复有九州。","男儿志五岳，逝将十岳游。","酒间扣所适，泰岱曾入手。","马迹重云巅，鸡声浴日后。","狂扣玉女盆，中原散培塿。","自揽烟霞色，语语不离口。","十岳天中外，子尚馀其九。","寒暑炼玉容，去日各非有。","昔予读损益，亦复思名山。","晚师维摩诘，旦夕栖衡关。","纵横千界表，乃在弹指间。","笑攀青莲花，归插玉女鬟。","奚必策重踝，役役劳心颜。","我语虽大佳，听之了无答。","杯酒散城烟，孤帆凌超忽。","唯馀留别句，掷地金石发。","后夜倘见怀，长江弄秋月。"]},{"t":"王山人自称十岳先有二诗见寄极国士之许千里命驾曾未淹日欲留金陵长篇见贻拂衣北首聊此和赠 其二 赠奕者程生","f":"五言古诗","c":["世才不可尽，豪鸷争辈出。","国手何纵横，令我难甲乙。","李生自燕京，雅与颜鲍匹。","飘然来江左，百战不摧一。","惊电随指生，坚城望风失。","朅来得程郎，少年美清扬。","所遇无上驷，云蹄郁腾骧。","及乎与李角，贾勇不可当。","李如李将军，部曲神飞扬。","程如程卫尉，号令严秋霜。","为李固左袒，推程亦军冠。","铜池垂杨侧，隐若辟楚汉。","程虽近巧迟，往往诣玄观。","落子黄叶深，收枰烛花半。","吾日殊有馀，毋乃樵斧烂。"]},{"t":"楚臬陆子还吴","f":"五言古诗","c":["仲宣久厌楚，季鹰忽悲吴。","挂冠北阙下，散发南山隅。","笑谓武昌鱼，何似江东鲈。","余岂尘世人，偶然废耕锄。","八月凉风生，白云满江湖。","但从最深处，觅有王生无。"]},{"t":"题孙君竹鹤斋","f":"五言古诗","c":["缑岭既云夐，夹池亦以往。","讵若过君斋，悠然令神爽。","玄飔逗幽窱，白云团虚幌。","瞻澳来远姿，鸣皋流清响。","葱茜承露碧，嘹戾排空上。","匪由乘轩羡，庶谐君子赏。","高咏遂初篇，振衣发遥想。"]},{"t":"信阳王子祖嫡过访王子能文章谈诗而不饮酒","f":"五言古诗","c":["汝颍足名士，燕赵饶悲歌。","此地忽遇尔，不醉当如何。","君自银不律，我但金叵罗。","笑谓千秋业，所得仲孰多。","流徵杂清商，大陆扬素波。","明年一匹练，倘访青山萝。"]},{"t":"周生为亡友王子馆甥颇有沦落之叹怆焉念旧为赠此诗","f":"五言律诗","c":["忆从维扬楫，风尘失而舅。","幸馀延陵诺，不堕孝标口。","玉犹当日润，璞更何年剖。","恻怆今昔言，乾坤重回首。"]},{"t":"题霞川卷","f":"五言古诗","c":["高斋傍霞屿，川光时复暝。","浮天自五色，含飔忽千片。","陆离媚初旭，窈窕横晴巘。","文鱼欣欲上，遥鹜孤难辨。","为语谢临川，如绮复如练。"]},{"t":"赠石给事拱辰","f":"五言古诗","c":["烈士婴逆鳞，岂在明月珠。","念欲醒睡龙，润泽四海枯。","我逢石中郎，白晰好丈夫。","韶年入青琐，玉树含冰壶。","气塞指鹿臣，愿行斩马诛。","封事八九条，一一社稷谟。","雷霆横白日，人鬼在须臾。","九关虎豹号，魑魅亦揶揄。","一为蔺生叱，万发立头颅。","捶摘纷下来，血肉顿模糊。","君家铁如意，欲碎红珊瑚。","微贱何足言，毋乃圣德渝。","昨窥中兴诏，坐见海宇苏。","惜哉反掌间，迷阳罥天衢。","岂不愿良臣，良臣不易图。","搆茅漳伾傍，天锡万死躯。","朝与牧竖出，夕归樵父俱。","贫无南山田，足挂牛角书。","余本骨体人，为君重踟蹰。","男儿未盖棺，各自智其愚。","宇宙大茫茫，努力爱前驱。"]},{"t":"下彭城而南微雨即事","f":"五言律诗","c":["稍尽彭城山，悠然见清淮。","微雨虽沾衣，能令山色佳。","出没前后旌，浮云时与偕。","浊酒两三行，聊以佐归怀。"]},{"t":"莫公远移居武林","f":"五言古诗","c":["皋桥无旧业，吴阊多少年。","白眼冷相睨，青衫凋自怜。","以兹掉头去，鼓楫西湖边。","幸逢郗北海，为营剡下椽。","复从王江州，乞取酒家钱。","朝斸灵隐云，夕卧南高烟。","笑指飞来峰，共汝两寓贤。","失意则蓬累，且诵逍遥篇。"]},{"t":"答赠张参政钦伯","f":"五言古诗","c":["昔领金华省，今治金华部。","去携香案烟，来作冰壶雾。","君身自仙骨，世岂知其故。","萧洒八咏成，悠然片鸿度。","汀际白蘋秋，江东彩云暮。","吴兴差卑小，焉足当君慕。","最后蓬莱仙，此语闻白傅。"]},{"t":"济川篇为太医邢先生题","f":"五言古诗","c":["在佛说法时，药王为导师。","太乙操莲叶，下救人阽危。","儒用久寂寞，其功或明医。","邢子利涉才，托迹在黄岐。","朝饮苏橘井，夕饮长桑池。","江阴十万家，家家春风吹。","馀波来惠吴，起我北堂慈。","傅楫吾所难，清泌可乐饥。","彼哉问津人，愧汝济川辞。"]},{"t":"华婿水部病起赴官","f":"五言古诗","c":["卫郎别我去，玉立秋风前。","自无膏肓疾，不待彦辅痊。","观潮壮起色，策马蓟门烟。","金掌出层霄，零露正纤圆。","乞取芙蓉杯，归寿蓬莱仙。","大江饶白云，南望更依然。","我期临邛令，春江候楼船。"]},{"t":"送沈九畴还四明","f":"五言古诗","c":["曩时四明客，倜傥能文章。","挥毫写秋色，眼底天茫茫。","家多渥洼种，白眉矜最良。","今朝逢阮咸，果胜步兵狂。","咳唾出珠玑，半落奚锦囊。","抗手别我去，孤帆渡钱塘。","倘成郊居赋，须寄王中郎。"]},{"t":"有上人者号景峰意为念其师也乃至作图日寓目毋乃执有乎为成数语聊以示规","f":"五言古诗","c":["若不破名相，此图空在卷。","譬如阿闪国，一现不再现。","若破名相尽，无见无无见。","百亿须弥峰，峰峰入师眼。","余本峰中人，焉能睹峰面。","倘师为竖拂，翛然已忘辨。"]},{"t":"寄题张伯子兑园","f":"五言古诗","c":["春至三河阴，百卉皆悦怿。","主人何为者，席花读周易。","毋为閟其口，相与成丽泽。"]},{"t":"仲子兑池","f":"五言古诗","c":["仲氏日规池，泓渟复清泚。","蘋末巽二风，斗间天一水。","汇为感山泽，青山在其底。"]},{"t":"叔子兑亭","f":"五言古诗","c":["宛宛帝女云，疑出巫山岫。","过君草玄亭，芊眠入窗牖。","便能呼季雅，相与赏此否。"]},{"t":"偶成齿发吟作长庆体示伯龙子念君载","f":"五言古诗","c":["发白况乃寡，齿痛行复落。","此事当渐来，委蜕偶先觉。","观电等浮荣，嚼蜡如好爵。","驰思佐坟典，策勋播寥廓。","其名在千古，真识久冥漠。","先民有遗言，及时当行乐。","稍往忽已空，未来畴能度。","营为醇醲腐，精恐佳丽凿。","惝恍出世言，渺茫长生药。","成證聊自暖，齐物终妄作。","事事能误人，破了亦无着。","语罢当更愁，愁来又成错。"]},{"t":"四瑞卷为顾母题","f":"五言律诗","c":["朱明吐南极，群祯时辐辏。","上元捧玉觞，王母前称寿。","三花复加一，丛芳仍再秀。","何意谢庭荣，翻为顾家妇。"]},{"t":"盛子时泰过访有赠","f":"五言古诗","c":["盛子金陵来，语语甘小巫。","能令陆平原，不敢赋三都。","綵笔健秋鹰，锦囊压奚奴。","暮寻华阳馆，眼醉天模糊。","莫逐时名去，人言多自诬。"]},{"t":"江黄二州谒白尚书苏端明祠有感","f":"五言古诗","c":["白傅佐浔阳，匡庐落其手。","苏公谪宜黄，游踪寄樊口。","物情岂相为，天意良不偶。","挥泪对青衫，垂腰厌黄绶。","是时二公年，四十加八九。","飞腾在俄顷，纶綍相先后。","而我同兹岁，楚宪起南亩。","却顾所佩章，叨窃惭已久。","椒浆荐落日，馀沥自为寿。","髫年弄笔墨，老至忘其丑。","颇谙游戏禅，更贪声闻酒。","别业娄水傍，岁功良亦厚。","园多履道竹，门种杭堤柳。","功名善愚人，人生好自负。","造物亦苦悭，安能令多取。","真乐随形无，虚名背身有。","洛下醉朱唇，天南摇白首。","明年定挂冠，不蓄赵瑟妇。","以此叩二公，公其默许否。"]},{"t":"赠李方伯师孟","f":"五言古诗","c":["余昔游太原，赖君佐提刑。","有酒不孤赏，所吐皆兰馨。","北风吹晋祠，冰作涕泪零。","及余吴兴政，旧刃发新硎。","平阳许画一，临淮实精灵。","起家再游楚，值君方锦停。","谬脂岭右辖，是君所遗軿。","官自雪鸿迹，人如大海萍。","吴越代两政，晋楚若一廷。","生平易解官，各若秋梦醒。","更有大奇事，我谈君试听。","太湖五百里，中有两洞庭。","洞庭八百里，中一君山青。","尔我长对之，濙然双客星。","欲造即驭风，云车会青冥。","安能傍尘世，蝇聚袭膻腥。"]},{"t":"幡经台","f":"五言古诗","c":["西望幡经台，萧条欲非故。","陶令呼不来，谢监推不去。","远公既以远，兹意畴能悟。"]},{"t":"三笑亭有感","f":"五言律诗","c":["昔闻虎溪笑，谓已契无言。","及览般若愿，犹觉有待烦。","青山不点头，白莲腐其根。","净土何必归，况乃思雁门。"]},{"t":"答与绳太常","f":"五言古诗","c":["故人尺一来，字字皆肺腑。","谓余老善醉，醉复多泄语。","甚醉解伤生，泄恐终误汝。","幡然指其口，汝罪发可数。","奈何司出入，废职媚其主。","兴至不我却，机发不我阻。","口拜前致辞，公言胡不伦。","趣死且百岐，岂必尽饮醇。","不应北邙土，日日埋醉人。","籍令畏语泄，独酌仍杜门。","在耳不在舌，可掩不可扪。","耳听复大笑，借官重于身。","何如归去来，小酌松醪春。","耕钓一二翁，杯斝三五巡。","小酌不损神，小语不汩真。","珍重故人札，赋此等书绅。"]},{"t":"助甫称疾以见父出访真阳有赠","f":"五言律诗","c":["鸿冥方自叹，玉立见吾子。","离忧小语失，往事深杯起。","僧弥固难兄，万年那可死。","努力各加餐，联翮当此始。"]},{"t":"赠不二和尚","f":"五言古诗","c":["苦无道民好，披缁礼远公。","劳师破吾执，所破随亦空。","饭罢了无语，趺坐苍山中。"]},{"t":"赠范丫髻","f":"五言古诗","c":["一瓢更一杖，此外都不闻。","瓢还颍水月，杖付葛陂云。","挥手嵾山顶，却笑洪崖君。"]},{"t":"为李员外悼亡","f":"五言古诗","c":["矫矫双鸿鹄，羽翼忽已分。","岂不念佳匹，飘然辞浊氛。","君子怅独晤，美人旷何群。","杂佩空瑶响，流苏陈绮文。","清心馀玉映，丽质罢兰薰。","非乖庄生达，尚挹荀令芬。","徵歌惜倾国，流梦为行云。","去来杳难迹，盼睐恍有闻。","亮无排空驭，毫素表殷勤。"]},{"t":"挽歌 其一","f":"五言古诗","c":["昭昭天宇日，倏忽堕虞渊。","如何盛年子，光彩中弃捐。","白日当再晨，逝者不复还。","素旐纷前发，迫我向重泉。","华栋自云浮，甘此七尺棺。","子弟来相饯，饯罢各言旋。","平生所著书，往往留心肝。","妍蚩他人口，已自不得言。","束发悟生趋，往复杂忧患。","但言身日短，不睹身后先。","仰问巫阳师，安能为我权。"]},{"t":"挽歌 其二","f":"五言古诗","c":["丈夫事四方，魂魄恋故乡。","今我胡为尔，委命付穷荒。","临殁辞明去，亲知不在傍。","寸桐为我车，腐革为我裳。","魑魅为我御，瘴雾为我粮。","蝼蚁司门庭，青蝇来吊丧。","鬼伴群侏离，与语不能详。","道逢司命君，示我返魂方。","长跪告司命，生人多患伤。","不愿复为人，但愿长彷徉。"]},{"t":"挽歌 其三","f":"五言古诗","c":["甲兵冠天来，朝野靡宴宁。","背亲为王臣，焉以辞国殇。","青霾吹荡翳，金鼓惨不扬。","贵贱并一时，颅趾委沙场。","日暮轮蹄尽，乌鸢来啄创。","有手不能驱，有目无精光。","朔风吹朝夕，枯骨渐坚强。","家人具衣冠，延我之北邙。","羽卫骖驔列，空为存者倡。","两地竟谁真，千秋浩茫茫。"]},{"t":"伤卢楠","f":"五言古诗","c":["北风摧松柏，下与飞藿会。","词人厄阳九，卢生亦长逝。","桐棺不敛胫，寄殡空山寺。","蝼蚁与乌鸢，耽耽出其计。","酒家惜馀负，里社忻安食。","孤女空抱影，寡妾将收泪。","著书盈万言，一往恐失坠。","唯昔黎阳狱，弱羽困毛鸷。","幸脱雉经辰，未满鬼薪岁。","途穷百态攻，变触新语至。","词场四五侠，往往走馀锐。","大赋少见赏，小文仅易醉。","醉后骂坐归，还为室人詈。","我昔报生札，高材虚见忌。","自取造化馀，何关世途事。","呜呼卢生晚，竟无戢身地。","哭罢重吞声，皇天有新意。"]},{"t":"张幼于庐墓","f":"五言古诗","c":["遥望白华山，山石郁嶙峋。","中有白华吟，吟声何悲辛。","之子怀永慸，结庐在丘闉。","荆榛初往蹊，松柏自成邻。","念彼长夜台，痛此百岁人。","挥泪循脩垄，高恸逮萧晨。","晨猿无停和，垄草不易春。","悲风吹北陆，惨日就西奫。","重冥稀生搆，九陌绝幽轮。","音容旷不接，志意邈难伸。","朝露夕自霜，暮兰旦为薪。","愲结令中耗，安能延子鬒。","非虞仲举谪，冀全嗣宗真。","弧矢庶可扬，竹素将不泯。"]},{"t":"九松篇","f":"五言古诗","c":["寒色无早暮，玄冈翳重阴。","连蜷九松树，偃蹇不成林。","上有含哺鸟，啄血正涔淫。","念欲昼哀啼，弹射恐见侵。","存为没者身，没为存者心。","衔土塞东溟，鲸波浩沉沉。","一弹塘上篇，再弹履霜吟。","我欲竟此奏，弦绝多悲音。"]},{"t":"会葬故陆丈吉孺 其一","f":"五言古诗","c":["生世仅卅载，旅殡二十春。","落日射空棺，棂宇尽为薪。","今朝一抔土，始得返于真。","少妇竟华颠，交友半已陈。","长衢连交鞅，歌哭递相因。","神气无不之，焉问疏与亲。"]},{"t":"会葬故陆丈吉孺 其二","f":"五言古诗","c":["游魂久已逝，归魄从此始。","玉树埋土中，悢悢不能已。","秋风怜空桑，悲音缘谁起。","卮酒饭一盂，寡妻代为子。","有友三两人，聊与歌蒿里。","芳名良何益，空尘世人耳。"]},{"t":"遣吊卢楠墓","f":"五言古诗","c":["昔骑紫骅骝，翩翩游魏都。","绿醽呼明月，踉跄堕冰壶。","倚醉别卢楠，春草十二枯。","腰间黄金鱼，久逐酒家胡。","魏节重入手，雪亦侵头颅。","卢楠化为土，遗骨知在无。","两女胜才人，下嫁厮养徒。","中原散遗集，历落照乘珠。","薄酹指焦峣，若敖夺汝餔。","风吹英雄泪，忽与千秋徂。","倘遇襧正平，狂鬼晚不孤。"]},{"t":"哭王樗全茂才二首 其一","f":"五言律诗","c":["才似习凿齿，摧残称半人。","废同殷渊源，咄唶叹疏亲。","到了力输命，兼之惫与贫。","长歌士不遇，为尔重沾巾。"]},{"t":"哭王樗全茂才二首 其二","f":"五言律诗","c":["五鬼烧车船，得志仍跳梁。","二竖畏针砭，挟筴走膏肓。","书淫不成疗，笔冢聊并藏。","古今失意事，不敢问穹苍。"]},{"t":"悲七子篇","f":"五言古诗","c":["文翁信其真，履坦物不隔。","许老初耿介，晚负长舆癖。","通蔽虽互妨，典刑尚可则。","元朗业任侠，声酒恣所适。","翩翩梁公子，养交不忘饰。","子传青云姿，杜门事探索。","如何中天谪，病使心志易。","沈生慕落拓，王子工便辟。","此曹富词源，兼多善酒德。","年命一朝倾，转盼成陈迹。","奄忽邺中论，恻怆山阳笛。","神往形随敝，人生非金石。","逝者不须臾，存者亦瞬息。","安能使不悲，长悲竟何益。"]},{"t":"宝刀歌","f":"七言古诗","c":["昆吾精铁光灼烁，不论风胡手中作。","涪江水淬明月寒，汉冶风回赤蛟跃。","锋尖七曜隐芙蓉，匣里双环吐龙雀。","少年醉舞洛阳街，将军血战黄沙漠。","记取衔恩一片心，扶君直上麒麟阁。"]},{"t":"吴节妇吟","f":"古风","c":["秦家女，吴家妇。","东风吹折连理树，霜摧树枯凛如故。","吴氏子，秦氏儿。","东风吹长寄生枝，但令枝盛何足悲。","儿能成名孙复显，吴家鼓吹迎旌典。","五十馀年影语身，青灯白发不知春。","九泉下见夫君面，犹是当时执手人。"]},{"t":"竹窗歌题同年周叔夜父卷","f":"七言古诗","c":["主人卜筑松江曲，数武茅斋一窗竹。","主人之节清且素，况与此君共朝暮。","婵娟蹙拂摇曙烟，主人自为汲湘川。","寒飙夜雨天籁发，主人行歌互相答。","疏影历历声珊珊，入帘翠色秀可餐。","主人为主君为客，倦鹤閒云各分席。","主人对君一撚髭，世上小草吾何知。","谁道新篁发平地，咫尺便有摩空势。","嶰谷裁将鸾凤音，中山尽吐龙蛇气。","即看雨露天上来，无数琅玕次第栽，主人不乐何为哉。"]},{"t":"袁履善惠芡实作鸡珠儿歌遗我走笔谢之","f":"七言古诗","c":["袁君赠我鸡珠儿，为我更作鸡珠歌。","使我应接不能暇，欲读废食且奈何。","问余旧游吴水隈，菱芡贴水参差开。","吴中女儿娇可爱，采得鸡珠和菱卖。","当时解发林间卧，顷刻便啖三千颗。","丹篚初倾历落圆，玉肌乍剥温柔露。","芳腴满中更可人，坐令莲的无精神。","煮石太硬苦费齿，鸡珠自是真仙饵。","一朝失足辞渔矶，可怜方朔长苦饥。","明朝神武挂冠去，知余不为莼丝归。"]},{"t":"华员外改南司马部分韵","f":"七言古诗","c":["华君自返苏门啸，垂白公车待明诏。","司农榷税力不任，愿得閒曹寄渔钓。","朝游采石访李白，夕向金陵歌谢眺。","长安冠盖者谁子，珥玉纡朱互矜耀。","龙颔欲结千岁穴，青春已随东去曜。","鹓雏高逝腐鼠嚇，鹪鹩卑栖黄鹄笑。","君家学士亦如此，碧山焚鱼尚年少。"]},{"t":"征西将军行","f":"七言古诗","c":["征西铁冠双缦胡，结发百战当匈奴。","虎头自是万里相，猿臂能轻三石弧。","七更帅印控属国，再踏王庭擒骨都。","白头据鞍偏矍铄，赤胆悬胸何卓荦。","西河太守血吮疮，护羌校尉躬持药。","负土亲填光禄塞，绝甘不作嫖姚幕。","清秋候气度刁斗，中夜筹沙坐铃阁。","传烽一点若星流，便凿凶门上臂韝。","个个健儿擐越练，家家少妇砺吴钩。","争道鸿毛等微命，共祈龙额早封侯。","横行要赭天山色，独立能高紫塞秋。","由来壮士矜才气，耻学低眉事文吏。","儿女俱能道颜色，公卿不见通名字。","万死常怀马革心，一归羞作菟裘计。","天子临轩总第功，赋诗谈檄尽豪雄。","谁更封侯并拜相，李蔡为人在下中。"]},{"t":"寿宁侯故第歌","f":"古风","c":["谁家甲第横道周，路人齐指寿宁侯。","空馀棨戟连云暗，不见轩车学水流。","卧壁蟏蛸閒向暮，当门鸟雀乱先秋。","道傍老翁眠不起，自谓能言寿宁事。","貂珥那传就日功，椒房已挟薰天势。","当年兄弟同侍直，白马前后黄金勒。","天子宫中赐欢笑，五侯门外看颜色。","有时日晡复召宴，龙锁东华归不得。","秃袖黄衫倚醉逃，别院春风坠香帻。","邓山横压蜀云低，郭穴偏承汉露滋。","去夺冠军沁水里，凿成安乐定昆池。","初来后厕浑疑错，乍入危栖意欲迷。","三尺珊瑚斗如意，千金蹀躞射弹棋。","歌屏掩翠镜窥红，妆粉围春肉阵风。","急管瀪弦开永巷，朱帘高栋胜离宫。","石家富贵乾坤小，霍氏功名旦夕空。","可怜世路同转毂，君恩覆水难再复。","西第千甍不足居，东门尺土翻相逐。","陇头寒食麦饭青，若敖无人馁鬼哭。","君不见羊肠峻阪危插空，后车肯问前车覆。"]},{"t":"自从行送子贤兄判武定","f":"古风","c":["自从书生好官职，万事都道书生力。","朱幡皂盖者谁子，满目疮痍救不得。","我兄昔作东平日，却罢逢迎劝耕织。","闾党豪宗伺嚬笑，郡国守相低颜色。","枳棘谁为凤凰叹，鹓雏颇遭老鸱嚇。","归去旅葵堂上多，种将菰米湖田瘠。","去年汝出东平道，父老初惊渐相识。","争献浊酒肥鸡猪，为言童稚今有室。","棠树已见堪把抱，汝鬓何由尚如漆。","武定风土亦不恶，临别殷勤怆今昔。","男儿光彩逐手生，将相功名到头识。","君不见汉家循吏黄颍川，亦要禾廛出三百。"]},{"t":"苦旱歌","f":"古风","c":["君不见岁已在酉魃为虐，五月黄尘恣飘瞥。","农家儿女窃愁叹，辘轳殷殷夜不绝。","原草新疑野火烧，山田久作十字裂。","我欲伸眉向谁说。","东南转漕匮奔送，西北军声尚澒洞。","桑林不闻六事祷，柏梁已上乾封颂。","阴云油油乍东至，远近欢呼声动地。","恶风忽从云际起，顷刻荡散归天意。","青袍皂带者何事。","中夜不眠坐待旦，三星在空月烂烂。","偶思东海亦可怜，一妇横死枯三年。","京师赏罚未足算，李斯痛哭咸阳之市边。"]},{"t":"吴郎行赠吴判官转浙藩都事","f":"古风","c":["吴郎醉骂金陵席，骑马却赴通州谪。","三载黯淡风尘深，始作江南幕中客。","吴郎濩落偃蹇且莫论，尔是文定尚书孙。","书生不及文定世，父老犹传孝皇事。","洛阳长沙初拜相，华容浮梁互相让。","九重握手赐颜色，万里君门若咫尺。","是时文定称近臣，深谋密语上所亲。","朝集凤池间委佩，即看鱼水更何人。","由来大厦须梁栋，不独文章为世重。","鼎湖忽攀龙驭髯，寰海但使苍生恸。","只今相去四十载，万事那期一朝改。","玉几沈深北极尊，金鱼寂寞青云在。","呜呼往事生新愁，我歌吴郎双泪流。","闻道君王思故剑，莫令衫袖湿江州。"]},{"t":"森桧堂歌","f":"古风","c":["结茆近城市，不闻车马声。","一登丘公堂，恍然遗世情。","堂中何所见，金石一千卷。","堂前何所植，老桧参天三百尺。","根出太古垂青铜，霜皮剥凿金芙蓉。","长空冥冥挂云雾，白日隐隐撑虬龙。","秋阴障大暑，春色凌穷冬。","秦皇若见之，泰山不得封。","罗盖团晴怪枝偃，少室嵩坛道非远。","树杪遥飞瑟瑟泉，望中高映层层巘。","摩娑此桧公所栽，天与一气长崔嵬。","人间但看长年岁，卑枝亦是清庙材。","我闻阙里二千载，祝融横来复安在。","虞山七星亦近古，何处老翁更作主。","那得此桧还此堂，森然并矗公之乡。","道傍过者诧相指，千林乔木摧昂藏。","为公作歌重叹息，丈夫立身须正直。","君不见丘家堂前一老桧，扶持尚有神明力。"]},{"t":"张将军歌","f":"古风","c":["张将军，虬髯铁面勇绝伦。","双眦直上见贼嗔，左腾右踔七尺身。","倏忽飞动威天神，方印缚肘金麒麟。","是时六月军声变，风尘蔽天不相见。","云中健儿面如土，妻女仓皇泪飘霰。","将军独提其麾下，意气不数天山箭。","关头老弱数百骑，酣呼赴躯逞一战。","捉生卤获偏裨任，胡乃区区好趣便。","角声忽从敌中出，杀气天昏纵腾越。","弓刀蹙沸震风雨，戈甲光芒耀日月。","将军大叫鼓声绝，吏士空拳奋白骨。","骨都当户稍欲遁，中原贼臣教奔突。","汉兵如山自坚壁，回看从校星迸逸。","顷刻血肉俱零乱，将军头颅辨不得。","敌骑叩鞍咋指欢喜剧，狼头羽纛扫太白。","阴飙淅瑟燐火明，落日惨澹鸟兽匿。","男儿要在尸裹革，人生百岁须有极。","云中帅者谁其俦，十年之间梁与周。","亲披荆棘开军府，躬起疮痍败敌谋。","毕万虽能老牖下，李广终然望彻侯。","将军继之亦不恶，可怜鸟葬终荒丘。","呜呼北山石椁东园器，肥酒大肉同千秋。"]},{"t":"题剡溪障子","f":"古风","c":["晋有王子猷，风流掩前辈。","高屐郤公门，拄笏马曹岁。","归来百事稀，种竹凡几围。","贪看镜湖白，坐失青山辉。","风吹大空雪，片片镜中飞。","千岩鸟雀冻不喧，田父墐户垆头眠。","孤棹苍烟放歌去，故人应在剡溪边。","人间戴生宁易得，其若归心浩还发。","空林无枝玉凌乱，独破寒流载明月。","相逢稚子候荆扉，东方渐高迹已微。","偶然适意差足快，千载何人劳是非。","谁为强被丹青色，令予欲访山阴宅。","荻花茫茫不知路，中夜披图兴萧瑟。"]},{"t":"送赵员外行边歌","f":"七言古诗","c":["烽火夜照甘泉赤，万马南来踏秋色。","汉家推毂三将军，幕府羽书尚充斥。","塞内屯营称戊巳，兵前击柝连朝夕。","射鸟小儿拜期门，牧羊贾人助田宅。","纷纷争睹献前筹，寂寂谁同天子忧。","朝贵俱投骠骑里，书生多著鹔鹴裘。","学得量沙任转饷，能言画地便封侯。","赵君自是关西侠，平生报恩身似叶。","倚马逡巡草檄文，论兵慷慨弹长铗。","已令野史传循良，复要云台策勋业。","须臾持节按榆关，金城形势奏书还。","受降横夺单于胆，长乐全回圣主颜。","不学蒙恬绝地脉，誓同飞将定天山。","铙歌倘俯长城窟，哀吹缘霜夜中发。","东都甲第金满闉，京观何人辨枯骨。"]},{"t":"侠客篇","f":"古风","c":["七国养士何纷纷，谁其雄者信陵君。","击柝雍容据上座，鼓刀慷慨却秦军。","其外碌碌诸公子，借日回春互争绮。","列鼎常食三千人，俱簪珊瑚蹑珠履。","就中脱颖君不见，一片雄心为谁死。","燕丹恨秦贯白日，易水东流羽声疾。","倚柱倨骂大事去，惜哉不讲刺剑术。","金丸马肝亦何益，田光先生太仓卒。","咸阳击筑变清调，碧血殷霜染秋草。","明月还辉博浪沙，沧波岂没齐王岛。","五陵射猎倚醉归，眶眦杀人无是非。","髡奴赫奕拜卿相，天子威权下布衣。","黄金坞，当中路，走马过之不肯顾。","五花骝，狐白裘，轻薄少年非我俦。","四座酒莫倾，请听侠客行。","海内万事何言平，袖中吴钩霜雪明。","出门一笑失所向，十日大索长安城。"]},{"t":"赋得养龙池送莫膳部视贵州学","f":"古风","c":["我闻贵竹罗施异西极，两山夹陂深莫测。","神物蜿蜒走其上，顷刻下降房星赤。","蜀王内厩五千匹，云锦丛中逞颜色。","遥将万里白玉墀，奚官执鞚不敢骑。","囊沙覆压三百日，辛苦风云国士知。","麟鬐染汗珠络惊，秋霜濆沫桃花明。","郊尘不动落日缓，六飞恍若空中行。","从此峰名号腾越，诏图真迹留神阙。","濠阳贵人凡几人，云阁勋名齐日月。","只今一百八十载，高岩大泽依然在。","房星不明五星聚，学士青衿盛文彩。","何当塞徼多驰驱，君王按图空踟蹰。","黄金筑台买死骨，骐骥碌碌悲盐车。","君不见养龙坑旁云气薄，咸阳苜蓿横秋漠。","长鸣发迹自有时，谁其驭者今伯乐。"]},{"t":"谢生歌七夕送脱屣老人谢榛","f":"古风","c":["长安送别今七夕，北斗卓地银河昃。","此时痛饮不快意，青衣行酒无颜色。","呜呜击筑为秦声，和以短铗霜纵横。","大白入手葡萄惊，慷慨为尔歌平生。","谢生长河朔，奇笔破万卷。","日月纵游翱，乾坤任偃蹇。","开元以来八百载，少陵诸公竟安在。","精爽虽然付元气，骨格已见沉沧海。","先朝北地复信阳，一柱不障东澜狂。","人握隋珠户和璧，及吐中夜无精光。","谢家一瓿椒浆水，晨兴自荐开元鬼。","俯仰宁教俗子骂，声名肯傍豪贤起。","妻孥生计环向愁，掉头且吟五岳游。","青春断不淹富贵，白眼何以干公侯。","赵王自是平原君，玳簪珠履三千人。","生衣短衣巾角巾，握管从容踞上宾。","从此王名贤好士，浊漳往往成清醴。","座中谁出夷门右，海内愿为公子死。","生岂不恋王家濡，龌龊忍为辕下驹。","仰天大笑失所向，忽复束书来帝都。","帝都云甍接九衢，委巷独满群公车。","剧谈麈尾击唾壶，囊中欲探一钱无。","其时卢楠下浚狱，白雪无功白云辱。","九歌草就人不知，生也手持向人读。","读之未竟泪簌簌，清霜倒飞鬼神哭。","绣衣使者从天来，幽谷煖吹邹律灰，欢声欲动黄金台。","朝为俘囚夕贵客，生言于楠何有哉。","忆初识尔崔都尉，何人不慑回天势。","谑浪时存尔汝交，酒盏肯及县官事。","乃知豪杰无不可，婴儿世态狎乳虎。","片语能令万象归，雄心直向千秋吐。","生今去余向何所，生不在天之上、地之下。","前不值古人，后不值来者。","纵无长绳系汝足，安能一揖轻相舍。","为言聚散等流萍，贯月查来可暂停。","明年牛女桥成夜，指点依稀见客星。"]},{"t":"赠通帅袁君正","f":"七言古诗","c":["忆昨匈奴十万骑，连烽上烛甘泉红。","穹庐韦鞲蔽原野，殷殷鼓角驱丰霳。","老人伏颈刃洗血，少女椎结骑花骢。","岂无棘门诸将士，噤手欲堕乌号弓。","是时兵机戒顷刻，天子昼坐明光宫。","敖仓积粟数百万，不救赍敌何匆匆。","相言主臣幸无恙，蜡书直入回重瞳。","节符三发旌守土，益以副帅今袁公。","袁也手提一长剑，灿如白雪凌崆峒。","恩收健儿共肝胆，气夺万众无英雄。","旄头凝冰代马尽，太白入月秦关通。","将军按甲息馀勇，辕门大旗横朔风。","投壶雅歌太平事，衽革尝胆将无同。","野人倘忆城下辱，太史犹闻书土木。","挥鞭直踏燕然山，一洗穹碑为余读。"]},{"t":"歌行长短三首赠梁公实谢病归 其一","f":"古风","c":["公实汝胡遽为别，郊原黯淡无颜色。","未论咫尺即万里，鸿飞冥森塞云侧。","南看舟楫北冠盖，落日滔滔岂终极。","乾坤去住亦何限，丈夫岂尽关胸臆。","迩者吾醉长安陌，忽醒双眼文章伯。","雄心颇折历下生，侠志兼许淮南客。","徐卿慷慨见同调，每语富贵真堪掷。","酒酣吾歌独能楚，掀髯一笑秋天白。","亡何汝称抱奇疾，踯躅下羡夷门卒。","裁成芰衣仅掩胫，欲向空山采芝术。","呜呼日月知汝留不得，缩地回颜竟何术。","千年好振在吾党，万事可足婴公实。"]},{"t":"歌行长短三首赠梁公实谢病归 其二","f":"七言古诗","c":["南海明珠久寥寂，贡来光彩倾都国。","汉宫照乘岂不赏，汝抱欲重江湖色。","江湖秋寒毒龙卧，至宝乃得还其故。","冥冥青天走日月，淼淼巨窟生烟雾。","长安邸中按剑谁，龟兹贾人泣相慕。"]},{"t":"歌行长短三首赠梁公实谢病归 其三","f":"七言律诗","c":["汝谋结室罗浮顶，下饮仙人葛洪井。","桂树宛宛山日深，松花濛濛白云冷。","我亦仅买蜻蜓舟，归与少年为薄游。","采莲一曲杳然去，得醉即卧清溪头。"]},{"t":"醉中漫歌","f":"古风","c":["贵亦一丈夫，贱亦一丈夫。","昔脱短裘付酒垆，人人唤我高阳徒。","有时醉猎南山下，倒骑萧家生秃驹。","人间万事无不作，唯不能作平津客。","朅来十载游燕市，眼中茫茫尽堪白。","黄金纵积如丘陵，何可枉没长安城。","且为尽买中山酒，卧看悠悠世上名。"]},{"t":"击鹿行","f":"古风","c":["匕首不肯避君鹿，一击波红写盘玉。","乍如错落摧珊瑚，下泛碧海之醽醁。","伊尼右手大白左，两者并是神仙禄。","已堪桓陆片时欢，未烦楚汉诸公逐。","此生分绝安期驾，不死反并嵇康戮。","王子欲罢仍踟蹰，忽忆少年诸猎徒。","骅骝蹶起匹练色，日落不落云模糊。","翻然草际出此物，银牌隐项垂流苏。","少年拓弓霹雳响，鹿也宛转无前途。","霞丝雪缕袒分割，一饱尽付黄公垆。","凋零侠气久已甚，忽复遘此万事无。","徐君徐君且莫歌，丈夫失据当如何。","桥林丰草世无限，苦复扰扰趋田禾。","宁为披裘酌涧水，鹿门山色青嵯峨。","不然老作长安客，岂异尔鹿婴其罗。","呜呼，岂异尔鹿婴其罗。"]},{"t":"别子与","f":"古风","c":["江左吾与徐中行，相逢一言心遂倾。","蓬累世事岂足齿，所不醳然千载名。","吾其阴崖振孤木，子独阳野敷群英。","声华落落敢伯仲，肝胆炯炯无平生。","忆为子昔歌击鹿，豪气尽压长安城。","琥珀下坠鸾刀紫，葡萄寒摧大白明。","长歌自令浮云合，双眼忽向高空横。","惊枝一羽破秋色，万象頫首随南征。","荆轲曼声渐离筑，易水凝流如欲鸣。","故乡鲈鱼无不有，击鲜者谁人得否。","眼前豪杰难称意，君不见徐卿尚逐衣冠走。"]},{"t":"太原侯歌","f":"古风","c":["海云压山昼驱?，时危甲兵满天地。","儿女走啼城不开，太原将军怒裂眦。","旌旗无光鼓声死，空拳欲呼奋难起。","如林白刃凌秋霜，茫茫四海一父子。","闺中婉丽人共惜，肯以蛾眉事雠敌。","夜光迸裂胭脂红，闽山草树增颜色。","岂无冠盖诸商胡，炊金切玉烹酡酥。","开门夜半走大漠，得不枉杀称丈夫。","呜呼，得不枉杀称丈夫。"]},{"t":"送周一之从大将军出塞","f":"七言古诗","c":["去年搀抢扫幽蓟，千村万落无完郛。","汉家长技五不一，边沙猎猎吹神都。","甘泉天子赫威怒，手授大将双雕弧。","幕下黄金三十万，纷纷侠儿辞酒垆。","强弩射波裂鲛兕，长剑斫石惊于菟。","静如凝冰日惨淡，动若迅鹘天模糊。","谁其短裘誇揖客，缓颊辕门奏奇策。","握管能书窦宪碑，据鞍解草陈琳檄。","时从铃阁借前筹，或向平津抗宾席。","侠儿岂无好身手，出门低头候颜色。","兵起不定公侯相，时来也着书生力。","今年太白秋入月，单于祭旗狼头折。","粟马青嘶蒲类烟，洗刀赤染浑邪血。","驱军更夺燕支山，从此妇女愁无颜。","归来天子赐汤沐，笑拥如花金市间。"]},{"t":"昌平侯铁劵歌","f":"古风","c":["英皇昔日困鱼服，惨淡四庙精灵哭。","乾坤膏血付边马，乌鹊昼向行人啄。","于公石帅独当柄，指顾号令无翻覆。","天下勤王颇不少，杨侯上谷能神速。","鸣鞭游骑出飞狐，咋指单于遁涿鹿。","候气已见平吞敌，左右弧矢垂双箙。","居庸关头落日黄，饥卒尽饱降人肉。","新皇论功独召宴，剑履醉向明光宿。","貂蝉换出惊妻子，犀玉手授称腰腹。","当时报功恨不极，促制铁劵黄金饰。","无论此劵一尺铁，带砺河山开社稷。","百年倏忽岂更远，里门不朱插荆棘。","洛下唯闻许史封，边陲尚指杨王力。","即看铁劵黑似漆，金书，黯■无颜色。","岂唯金书无颜色，侯家子孙看不识。","为道己巳年间事，始复吞声泪填臆。","昨者蓟门火，横连甘泉北。","捷书未必当贼锋，血战还应长见抑。","尚方之劵陈如山，男儿赤手那可得。","君不见濠梁勋旧奚足数，坟墓秋霜窜鼷鼠。","于公丧元石帅族，风尘久赖成心膂。"]},{"t":"送徐汝思郎中使蜀虑囚兼悉鄙志","f":"七言古诗","c":["长安二月百花明，花间好鸟嘤其鸣。","骑马低回问所适，眼中何人一李生。","李生为予赋白雪，击节高歌唾壶缺。","两心炯炯中自知，至赏岂得逢人说。","谁其之子清而扬，抚琴不弹弦意长。","高山流水偶自会，浮云落日那能忘。","从此论诗更吾子，予也开襟荐兰芷。","沉钩溟渤红珊瑚，明月波光夜深起。","文章陆沉世所贱，千年得失人不见。","其若天涯生咫尺，陌头飞英乱飘霰。","青丝鹔鹴桃叶马，徐卿持节称使者。","倾城冠盖走相送，众中无言泪盈把。","汉天西尽有光辉，诏许推环国士知。","陇云马首三千折，栈道猿声十二时。","峨眉山深白日照，锦官溪冷东风吹。","巴人诵檄输賨布，夷女迎船歌竹枝。","滟滪秋沉疾如矢，白帝江陵七百里。","锦袍嵬坐映江水，徐卿丈夫当尔尔，岂无故人王与李。","足迹凄凉金马门，烽烟慷慨铜驼里。","古人恒悲生别离，灞桥水东不复西。","朱颜鬒鬓有时易，蕙质兰芬应未携。","对君长揖藏吴钩，鸊鹈膏湿寒芒愁。","它日延津倘相遇，三星斗间银河流。"]},{"t":"赠李伯承之新喻令","f":"古风","c":["平生寡所识，识君恨不早。","到处诵新诗，山东李白好。","岂无长安一席地，令汝却向青门道。","道傍车马何喧阗，我欲试奏钟期弦。","柔丝弱指冻不发，玉轸金徽空自怜。","掩泪持将赠君子，相随锦囊行万里。","吟龙高调结冰霜，别鹤孤怀寄山水。","宓子风流竟惘然，遥传清响下吴天。","期君一鼓南薰什，莫咏琵琶江上篇。"]},{"t":"寿申封君歌题青鸟图","f":"古风","c":["君不见申公七尺虬髯苍，双目棱棱紫石光。","赋成不肯献天子，大笑拂衣归故乡。","生驹挽弓三石强，妙舞剑器黄金装。","解言报恩公子里，亦曾结客少年场。","怀中蓝田双白璧，但令心知轻一掷。","归来叩床忽绝倒，绿酒新熟琥珀色。","何言中路多龃龉，闭户谈玄学冲举。","石室时窥龙虎文，洪崖亦送烟霞醑。","邺河之旁春卜居，三花琪树郁庭闾。","忽闻青鸟瑶池使，衔得长安天子书。","囊中岂无羽化药，相期且尽人间乐。","玳筵急管醉莫辞，迟尔三山驾鸾鹤。"]},{"t":"燕山雪后歌","f":"七言古诗","c":["蓟门十月玄风起，吹尘夜合滹沱水。","似猬还应缩马毛，先车竟复纷狐趾。","岁暮天涯已足愁，何当雨雪重淹留。","沾裘起粟声频禁，龟手垂鞭冻不收。","慄慄危桥冰柱折，遥遥孤戍铜龙咽。","江头已断河伯书，海上能凋使臣节。","蓟门道旁烟火微，蓟门城中有光辉。","流苏凤暖胡姬馆，韎韐貂轻公子衣。","百盏深巡浑不醉，千场纵猎未言归。","复有董仇持汉权，邀迎戚里罄交欢。","解以重帏违昼夜，能将炙手变炎寒。","此时谁惜空门卧，此际谁歌行路难。","雨雪偏摧蓟门客，丈夫毋为厌偪侧。","不见临河征戍儿，暮枕雕戈照霜色。"]},{"t":"祝京兆法书歌","f":"七言古诗","c":["吴兴公子二百载，尺素往往流云霞。","仲温急就散隶色，骨格虽尔风神赊。","狂鬼鸱张学士腕，东海小儿竟涂鸦。","凤池綵笔难再问，鸡林高价徒相誇。","人间不识祝京兆，何处还逢书大家。","此君自称枝指翁，指间蠕蠕出天工。","寒花夜发白兔锋，谁其赠者索与钟。","少年临池亦已精，晚节自喜愈纵横。","当其得意缣素表，一扫万古开精灵。","人云颠旭亦尔尔，毋乃大令更其名。","恍如青天嗷飞瀑，崖翻石走风雷惊。","皂雕秋回击羽坠，绿耳电摄排空行。","兰筋剑距时横出，逸态雄姿随手生。","迩来家鸡轻野鹜，却向真书大矜束。","即看京兆更遒绝，小茧游丝染明玉。","离离落日施荒草，淡淡疏烟挂寒竹。","邻女捧心但益丑，世人贵耳翻见辱。","玉树长埋呼不起，侪辈声名眼前死。","处处黄金购遗迹，东家覆瓿三尺纸，自古文章亦如此。"]},{"t":"今昔行送袁荆州丈","f":"七言古诗","c":["十载之前颇能忆，与子跌宕长安陌。","人间快事无不有，一醉两见东方白。","我歌若舞各自爱，日居月诸非所惜。","边尘一夜动蓟门，汉殿三秋问军檄。","趋曹自是小臣分，扼腕岂仗书生力。","陈卿已赋蜀道难，吾亦思从季鹰策。","事往那能计容鬓，时来且办生毛翮。","只今子作荆州守，列牙横纛驱前后。","荆州小儿骑竹马，吏人花间互奔走。","游刃理解万事无，抱牍丝棼片言剖。","十日不治一日尽，狱市岂足妨杯酒。","雄风昼接梦泽长，壮气涛连峡江吼。","都门把鞭话今昔，红尘萋迷万杨柳。","子若秋登落帽台，座上得少王生否。"]},{"t":"夕梦数恶赋此自解","f":"七言律诗","c":["湘帘碧梧秋一叶，匡床夜夜迷蝴蝶。","六候何烦辨吉凶，五衰未必根缘业。","由来蕉鹿妄纷纶，尹氏那能胜役人。","陇上行车陇下骨，君看此梦定谁真。"]},{"t":"观李于鳞射歌","f":"七言古诗","c":["李侯手挽三石强，左射右射势莫当。","饮羽犹然动逸劲，白日迥接星飞芒。","綵旌乱驰鼓人震，徐插繁弱神扬扬。","江南野夫不肯降，气挟岱岳超扶桑。","乍腾手势身亦转，矢落不见东西飏。","道傍儿女相走笑，比着束手无馀长。","主人玉杯竞前醉，李侯颇欲誇其技。","自云昔者师刘焘，罢看诗书驰猎骑。","珊瑚仆姑千金装，戎锦韎韐五花队。","焘也逡巡独前出，指顾万象俱辟易。","皎如宵月横控弦，飒尔秋霜见鸣镝。","众看云中一片白，宛转血坠摩空翼。","猿猱叫号麋鹿窜，袒跣手割分肩肋。","精能远出都护右，猛志坐夺材官色。","风尘将相在一身，往见主揽甘泉策。","刘子慷慨欣握符，李侯沉冥困执戟。","非但折节攻三馀，亦逐时人理簿书。","雄心隐隐见眉睫，世事忽忽甘籧篨。","英雄善藏须莫识，辱国之艺何欷歔。","我醉为歌平原下，青霾森森日色亚。","安得一箭万里空，野夫饱饭看君射。"]},{"t":"短歌自嘲","f":"古风","c":["我不能六翮飞上天，又不能摧眉折腰贵人前。","为郎五载，偃蹇不迁。","讯牍再过心茫然，但晓月费司农钱。","移书考功，令愿赐归田。","考功笑谓：汝犹须眉在人面，留之何益去不全。","西山山色青刺眼，为我拥鼻赋一篇。","乃公调笑亦常事，有酒且逐东风颠。"]},{"t":"送卢生还吴","f":"七言古诗","c":["卢生善诗逸者流，百结鹔鹴安足愁。","冁然一笑别我去，春花落尽胡姬楼。","欲留不能意弥恻，众中谁怜好颜色。","短裘倘过邯郸道，青草已没平原宅。","吴趍小娃迎问郎，北游满地尘茫茫。","采菱深处唱一曲，岂若芦笳能断肠。"]},{"t":"刁斗篇","f":"七言古诗","c":["匈奴铁骑动妖氛，大汉金城上属云。","始隶西宫程卫尉，还从骠骑霍将军。","将军令严鼓声急，辕门夜寒刁斗发。","淅沥频敲万古霜，凄清坐转三更月。","剥剥啄啄如有情，丁丁鍧鍧咽复鸣。","初疑玉漏传筹响，忽忆银砧捣练声。","六边健儿好身手，中夜闻之气盈肘。","匹马横度祁连道，弯弓射得单于首。","绝塞唯言奏凯歌，中原不复听刁斗。","城南少妇郁金香，织却流黄不下堂。","愿得凭风试吹去，要知此声能断肠。"]},{"t":"题周翁画云槎图赠张隐君","f":"古风","c":["昔有博望侯，凿空访河源。","归谓中国人，青天半昆崙。","黄河捲地轴，日夜东南奔。","何如海上槎，逢此方外客。","飘然犯银汉，白榆寒历历。","织女笑解装，橐中支矶石。","两奇不相遭，万古疑其神。","周翁貌此图，无乃为解纷。","嵯牙老龙浪所斤，一纪一贯秋空轮。","乘槎之客今姓张，飘须渥丹双眼方，燕颔不取黄金章。","泠泠腋风助徜徉，白云如茧天茫茫。","冲波万颖玉不定，空青一点衔扶桑。","道逢扶桑君，挽之不肯住。","我欲冯虚叩广寒，高扃璚宇无眠处。","褰裳访织女，怪谓汝曹好传天语，令汝徘徊不得去。","倘过酒星烦致声，人间尚有王先生。","天瓢沆瀣如未熟，笙鹤何年醉太清。"]},{"t":"落花叹","f":"古风","c":["叹落花，花落何飘零。","狂风如剪刀，越罗綷縩不胜情。","蹀?灞陵陌，潆洄御沟水。","落花欲有陈，狂风殊未已。","叹落花，掩泪辞故枝。","枝枝同根蒂，片片各分离。","只今踪迹无处所，忆昨容华能几时。","歌落花，莫咨嗟。","请说上苑千条绮，请说河阳万树霞。","七宝储胥金平脱，九华步障玉辟邪。","标题琬琰双牌小，承日流苏八字斜。","谁不暂缓青丝络，谁不暂驻七香车。","香车丝络春相待，弄态流娇宛如在。","只道朱颜日更新，那知转盼恩仍改。","歌落花，君歌未阕攒我颦。","昭阳媫妤汉侍者，邯郸厮养赵才人。","空将今日今年旧，难拟来年来日新。","东邻小娃才十五，恰似芳苞未曾吐。","已饶花落不关愁，又道花开为谁妩。","还逢路唱落花歌，萧飒寒烟扫翠蛾。","惆怅不堪临镜意，自怜三月梦中过。"]},{"t":"乙卯病后遇生日独酌至醉漫歌","f":"古风","c":["东风吹酒星，倏忽辞青天。","自堕吴江湄，一住三十年。","十年抱案尚书前，腰腹半已成杯棬。","归来览镜忽大笑，笑汝低眉为俸钱。","忽逢萧相营未央，虽有月请归朝堂。","酒肠唧唧如欲诉，且向文君乞鹔鹴。","阳昌垆头春酒香，白眼瞪视天茫茫。","杜曲梨花飞，灞陵杨花落。","不愁花落无处归，只恐长条坐萧索。","以兹日作烂漫游，妻嘲女谏安足酬。","汝曹骨肉偶相合，世间万事俱蜉蝣。","君不见王元美，昨者病欲死。","眼前七尺无奈何，胸中万卷长已矣。","只今幸逐春阳苏，那不尽倒白玉壶。","当时倘便骑鲸去，北斗南箕未可沽。"]},{"t":"独酌","f":"七言古诗","c":["懒癖如斗安吾胸，应门有刺勿复通。","小妇行炙大妇酒，冁然不辞双颊红。","儿能跳地作虎子，汝乃赋橡随徂公，呜呼得不笑若翁。"]},{"t":"坐有石季伦金谷图事因与于鳞共赋新体一章","f":"七言古诗","c":["石家金谷斗繁华，春风占尽河阳花。","连云锦帐五十里，压角流苏玉辟邪。","瑩蹄快犊夜光衔，平头小奴火浣衫。","君王珊瑚敌不得，七尺神柯产日南。","回峦别起清凉台，绮楯交疏面面开。","芙蕖千顷映朝日，日炙风掀香气来。","杨柳低纤姹女支，琵琶小按明君辞。","九齐芳尘验履迹，舞罢珍珠第赏迟。","急管繁弦响清汉，酒阑金钿自凌乱。","小婢收将处仲衣，胡姬解拾安仁弹。","翾风退房泣秋草，绿珠转眩青春好。","回眸一盼光彩生，八百蛾眉尽如扫。","长安使者白鼻騧，升堂左顾何矜誇。","连枝分折秋霜手，不入侯门映绛纱。","何人白首咏同归，倏忽豪华事已非。","唯有残霞零落处，至今犹是坠楼时。"]},{"t":"题松赠沈大夫郎中科父","f":"楚辞体","c":["沈大夫，与汝游兮，泰山登天门日观之高峰。","其上有五千年松，樛蟠挺屈撑虬龙。","鳞文剥蚀自成理，白日变态涛汹汹，胡为强颜秦哉封。","松根茯苓雪似脂，山灵下閟神不驰，奇者或臂为婴儿。","沈大夫烹食之，肌发鬒泽双瞳方。","下招松间鹤，八极同遨翔。","君不见秋霜夜飞摧万卉，香飘色堕俱泥滓。","七十二主犹眼前，泰山五株青不死。","大夫者何赤松子。"]},{"t":"送袁抑之给事监兵北伐","f":"七言古诗","c":["双垂韎韐绣鸂鶒，金羁马头雪花白。","秋星乍稀承明庐，慷慨遗策长安陌。","城社已见狐鼠空，关山要令豺狼辟。","今为颇牧出中禁，岂但汲卫誇揖客。","飞书再看鲁仲连，奏记不数崔亭伯。","匈奴祭马秋欲动，连峰蔽天朔塞赤。","六郡材官三十万，一一翘关衽金革。","期门募士身若飞，属国降番鬣如磔。","此辈自昔称英强，见敌虽多惯局蹐。","时时大官出银币，往往宿将甘巾帼。","呜呼主上恩不薄，忍使骄敌犹充斥。","君行帅府青天高，挥檄霜寒净沙碛。","安得一骑驰王庭，为君预扫燕然石。"]},{"t":"结交行寄赠于鳞诸子","f":"七言古诗","c":["自从管鲍不复见，天下黄金斗胶漆。","往者吾过翟公门，其雀可罗树萧瑟。","时来肯怕贫贱讥，势去还将姓名失。","吾侪此聚若有神，骊珠荧荧夜光溢。","但忆论文碣石空，宁知凿窍高天嫉。","即今偪侧荒城畔，残月犹明梦回室。","饥鸢冻鸱慰相语，丹凤哀呼问其匹。","淮南万木迎风愁，浮云淡沲寒不收。","凭高四顾乏羽翼，要使黄河西北流。"]},{"t":"淮阴侯庙歌","f":"七言古诗","c":["咸阳倾城葬祖龙，嫔嫱掩泣千花红。","十二金人销不尽，揭竿斩木飘于风。","是时韩生业钓者，其志固已无山东。","辕门执戟重瞳子，巴蜀为坛隆准公。","白帝雄图久成灭，乌江独马非为功。","归来故乡高筑宫，黄金如山一日空。","齐赵诸侯在指掌，俛仰宇内无英雄。","三夺军权再被缚，束手不待如发蒙。","乃知天授岂人力，代相之约何匆匆，当时幸不烹蒯通。","呜呼馀子焉足数，往往铁劵埋膏斧。","骊山刑客布乎王，长安彻侯哙等伍。","微时犹营万家墓，贵日翻悭一抔土。","尚令黄河羞汉带，日夜崩涛夺钲鼓。","乍可吾徒设瓣香，莫令儿辈陈牲酤。","荒阶突兀见老桧，乾坤荧荧日渐吐。","五陵王气横亘天，亦复寂寞成今古。"]},{"t":"从军篇","f":"古风","c":["君不见匈奴游猎犯边疆，复从朝那入渔阳。","孤军惨淡秋看月，万马奔腾夜踏霜。","促诏元戎屯细柳，还闻烽火接长杨。","金符电发徵车骑，玉剑星移下窒皇。","博士持和令守障，牧儿助费拜为郎。","横行尽选六郡士，转饷俱赍百日粮。","六郡良家侠少年，从来结客不论钱。","生将猿臂能穿叶，铸得龙泉独吐莲。","去逐轻车驰騕袅，还要剧孟睹婵娟。","双层铁锁桃花甲，三尺绒缘玛瑙鞭。","自道青云能立上，复誇黄石有真传。","机头少妇悲相向，亲党临岐重惆怅。","太白三杯醉不辞，凉州一曲歌偏壮。","海内常埋甲胄尘，人间自少公侯相。","新投主帅霍嫖姚，长揖辕门意气饶。","别将晨驱玄菟塞，奇兵多断白狼桥。","行逢使者曾书雁，捕着番儿惯射雕。","疏勒西来通帝朔，居延北望绝天骄。","酡酥酒进阏氏捧，夷乐传教敕勒调。","燕然刻石名居首，汉殿颁恩世稀有。","已赐甲第高入云，更悬金印大如斗。","功成莫傲机头妇，灯寒月沉君知否。"]},{"t":"送黎唯敬还南海因怀梁子","f":"七言古诗","c":["海内自与黎生左，蹑履竟入罗浮山。","罗浮璇房七十二，往往仙迹非人寰。","天门上达勾曲领，石臼碓沫飞潺湲。","濛晴零雨净峰色，一一麻姑呈翠鬟。","近者余与二三子，被发行歌燕市间。","黄金突兀差快意，那得久驻尘沙颜。","众中闻生不相识，余亦夷门抱关卒。","倘过石室采黄精，其畔或有梁公实。"]},{"t":"松楼歌","f":"七言古诗","c":["金华真人列仙丈，叱石初成气愈王。","自云神仙好楼居，结巢百尺松之上。","黯淡曾回日月光，屈蟠尽作虬龙状。","楼中之人鬓萧骚，岸帻独卧青天高。","窗间数下千年鹤，障里常飞六月涛。","不学秦封污岳观，欲同庄社混蓬蒿。","松脂夜明茯苓白，手持长镵斸其侧。","饱吸清泉九咽寒，更倚栏干啸秋色。"]},{"t":"捣衣篇","f":"七言古诗","c":["惊乌扑速起空林，辚辚雕轮过渐沉。","此时何处青楼女，此际无限塞垣心。","青楼小女字莫愁，织得流黄锦并头。","记别狂夫辞故里，昨传书信在凉州。","机头金剪三四转，灯下玉箸一双流。","荧荧青灯轧轧机，还理狂夫箧中衣。","宛转涕泪新痕积，约莫腰肢旧带非。","杵影高低尚自双，茕然贱妾伴空房。","捣成白练浑如雪，愁得蛾眉已似霜。","规月苍黄低落雁，商飙悉律和鸣螗。","意怯腕弱夜还赊，谁能闻罢禁咨嗟。","疑是梁州砧响绝，十年零落不思家。"]},{"t":"梦游虞山拂水岩","f":"古风","c":["虞山近乡国，今隔二千里。","我攀元气蹑恍忽，一夜飞度大江水。","大江云渺瀰，为我送置虞山侧。","千林鸟啼尚不断，倏然已坐颠岩石。","下有阴壑流潺湲，罡风倒吹飞满山。","恍若神人散天花，喷流瑟瑟明秋霞。","中间一道或如练，上注银河星斗斜。","洪涛汹汹，溪谷谽谺。","擘拆老桧，屈蟠龙蛇，鳞甲隐起纠纷拿。","濛阴黯淡不辨色，西看茫茫大江碧。","欲招李白天姥颠，跋浪鲸鱼竟难测。","谁?清泉洗余耳，下视浊世俱浮蚁。","长啸归来始自惊，犹疑几席岚烟起。","往者王使君，邀余上客华阳巾。","酒酣剑门峡，手弄兹山云。","转头不见秋霏霏，但馀香雾沾人衣。","昨来梦境更奇绝，试问庄生谁是非。"]},{"t":"寄赠李顺德于鳞","f":"七言古诗","c":["昨秋送我蓟门侧，天日黯作琉璃碧。","强以雄心挥别泪，俯视万象俱堪掷。","千言昵昵未肯尽，片语仓皇各深惜。","高艑长驱不断风，被发悲歌向震泽。","道逢北使行相问，生其果厌承明席。","钜鹿西驰七百里，扶风秩中二千石。","黄金横带历下过，里门高车排画戟。","海内但不书生穷，大笑便出长安陌。","何能毫末见文章，乍可沉沦就时格。","贞也高阳一狂客，英雄草莽成莫逆。","杯酒浮沉到处非，寸心炯炯留生识。","昔者击鹿过徐卿，匕首忽奋珊瑚惊。","立谈秋风搏雕鹗，纵饮沧海吞鲵鲸。","生独嶷然摄神气，太华千叠云峥嵘。","须臾瞪目奇句发，独扫满座无留行。","更为击筑变清羽，起视河汉西北倾。","生骑羸马出秋曙，一榻已下相予迎。","每寻知己必往古，倘示新篇非世名。","今予北来更牢落，眼中徐卿渐有情。","拂袖低回望牛斗，掩耳刺促愁蝇声。","勉㫋与生各自爱，胡为局蹐多哀鸣。","请看日月岂相比，万古不废东西明。"]},{"t":"谢许殿卿寄中山酒歌","f":"古风","c":["酒如金波腊不流，谁其赠余许赵州。","垆头一倾千日醉，顿扫抑塞磊磈之穷愁，且为莫脱青貂裘。","赵州生平未相见，英雄肝胆宁谋面。","古人不作今人稀，醉语苍黄斗谁健。"]},{"t":"人日同魏顺甫过子与分韵枣字","f":"七言古诗","c":["蓟门车尘白浩浩，乍有馀青着荒草。","银灯渐烂明月高，光辉遍逐行人好。","徐卿邀予中山酝，稚子烹葵妇剥枣。","箕踞高歌若有神，魏生击节为予道。","去岁兹日过何门，相逢总握灵蛇宝。","虽无蜀州零落态，汝辈突兀峙穹昊。","风涛微茫散倏忽，海内今看谁自保。","往事俱从酒阑得，孤怀转向清时抱。","呜呼此语郁未伸，李守难呼谢榛老。"]},{"t":"送大司寇顾公还山歌","f":"古风","c":["孝皇宾天五十载，海内喁喁想颜色。","曾传策士吁真才，往往睹接夔龙席。","呜呼此意苍茫竟谁答，一老岿然峙南极。","日月长悬魏阙心，波涛竟展渑池翼。","自从拂袖离夫椒，安石强折苍生腰。","十年再压铜柱碛，两都重肃金天飙。","巍如大衡悬东序，耸若乔木干层霄。","珊瑚欲枯沧海钓，云母隔坐天门朝。","谁其青骢绣为袍，望公崔嵬不得骄。","片言出口捩眼鼻，一疏脱屣甘渔樵。","菰城社者刘司空，啸作鼓吹惊鸿濛。","轻舟握手慰劳苦，苕水尽发桃花红，青山无言忽两翁。","为公萋菲意良厚，时有时才任奔走。","阴森狐狸固城社，潦落麟凤沈郊薮。","不堪屈指孝皇年，试论更得如公否。"]},{"t":"长歌送徐子与","f":"古风","c":["日予别诸君，杖节淮南天。","羽声浮云立，四座俱茫然。","挂帆沛流歌大风，调笑当时隆准公。","淮阴祠前双眼白，嚄唶竖子非英雄。","怒涛西来厚坤坼，突兀金焦峙拳石。","天令片语破鸿濛，祜辈岂得施颜色。","吾家菟裘近震泽，桃花欲飘不自惜。","故国鲸鲵恣吞噬，长安马蹄甘局蹐。","平生之交李与徐，徐卿自握灵蛇珠。","畅如金尊濯醽醁，煜若铁网擎珊瑚。","傍徨祗忧吾道绝，偃蹇肯受时名趋。","建安七子总词客，开元八仙多酒徒。","只今龌龊吴子辈，为汝跋扈开雄图。","华阳碣石俱模糊，短裘数付黄公垆。","卿今揖予何为乎，使旌不惊乾象改，匕首忽逝秋虹孤。","君不见河之浒，津人如云棹人鼓。","前迎王生后迎汝，桂枝丛丛蚌辉吐。","彩毫一飞真宰失，迫胁江山傲千古。"]},{"t":"为吴舍人题匈奴出猎图","f":"七言古诗","c":["谁为舍人画此图，高堂日落秋汹汹。","细看乃是单于猎，白草黄云骨俱悚。","马如游龙戏溟渤，人即饥乌暗霜垄。","无论众马姿态雄，饮龁虽异骄心同。","嘶鸣欲追青海日，蹴踏乱起祁连风。","魋结健儿鞭寒空，中间画纛摩双熊。","一矢奔传号令出，霹雳尽响乌号弓。","苍鹰脱韝乍有神，撇捩羊角盘车轮。","迥如流星渐不辨，白羽散坠飘红尘。","小奴拍马呼声频，夺将头鹅任众嗔。","臂鹰瞅目逞绝叫，百鸟骨折颠高旻。","草中狐兔眠难稳，卢鹊何甘让秋隼。","一线光衔尾初及，千林越遍心逾紧。","岂无狡捷胜东郭，年命今衰气力尽。","哀魄黯䨴归荒烟，肩稍袒割太剧颠。","櫜声小击万马敛，群奴笑立穹庐前。","黄金犀比上功赏，妻子改色欢相延。","此时单于醉何有，极目茫茫失飞走。","鹍弦教上叱拨调，酡酥列捧阏氏手。","天留大卤任长驱，莫作欃枪犯南斗。","汉家天子猎甘泉，头白扬雄罢草玄。","烦君好手图王会，为是呼韩款塞年。"]},{"t":"千秋行再赠殿卿","f":"七言古诗","c":["许生少小青门客，一日交游满东国。","雕鹗秋盘九塞云，骅骝气压千群色。","夭矫长虹挂银汉，浩荡高风来碣石。","是时历下李攀龙，往往道汝文章伯。","贞也乾坤昧夙昔，飞书莽苍神相识。","蓟门红尘万杨柳，五马初停赵州守。","酒徒零落声华尽，且复低眉事奔走。","乍看恐失许赵州，胡为刺促不能休。","要知肝胆酒边露，还是当年荆聂俦。","清霜片片压羽曲，北斗插地河西流。","有足肯蹑朱门履，独棹南天破盘水。","未容魑魅快时人，尚有头颅辨山鬼。","携手慷慨河梁篇，丈夫微名安足怜。","眼前离合差挂意，此辈岂与千秋权。"]},{"t":"短歌行二章送江少卿冕之长沙 其一","f":"七言古诗","c":["土伯九约嶷其角，陆海峥嵘咨吞啄。","方壶之仙诉天帝，欲扫么么还碧落。","霹雳衡驱白日变，此辈精灵坐销铄。","帝关虎豹羞其群，仙人去逐三湘云。","仰天大笑跨黄鹤，九辨清商如不闻。"]},{"t":"短歌行二章送江少卿冕之长沙 其二","f":"七言古诗","c":["忆昨天子明光宫，谁其荚者字文通。","黄金骨起骏马色，白羽手却妖狐风。","往日百身不相借，此时尺地难为容。","洛阳少年汉廷客，一忤绛灌虚前席。","宣室虽多问鬼神，愿君莫忘长太息。"]},{"t":"孙思邈受龙宫方歌","f":"古风","c":["白龙子，混鱼服，遨游于江湖。","焉为踯躅罗网间，力不能任诸奴。","风云变化落人手，沧海万里天模糊，何者一翁素发渥颜而飘须。","解衣赠龙子，行放之洪涛，喷沫八千尺，恍忽万象同欢娱。","双旌吸虹鼓鸣鼍，蜃关蛟窟长鲸殳，琉璃夺目龙所都。","老龙抱其子泣致辞：谁为救尔，答言一翁素发渥颜而飘须。","此翁昔吞太白精，调铸六气成昆吾。","区区报恩一寸胆，老龙自与凡鳞殊。","河伯使者飞朱符，倏然翁来下霓车。","龙子色踊腾相趋，雕盘八角垂流苏。","蟾蜍手捧明月珠，海人金缶坼珊瑚。","瑰玮错落，不可名猜。","众水辟易，三光徘徊。","翁如不见，此何为哉。","曾闻秘方三千首，帝遣玄冥毒龙守。","投诚赠翁不得辞，么么失据雷霆吼。","大柄翻回真宰前，阴功肯落岐农后。","此翁拂衣朝紫真，龙亦鼓鬣嬉青旻。","乃知草昧未可忽，虽在泥涂或有神。"]},{"t":"放歌送王明佐","f":"古风","c":["汉代梁伯鸾，挥手出秦关。","五噫满天地，其人阛阓间。","千秋王生亦如此，北游黯淡风尘里。","海上珊瑚属银汉，匣里莲花郁秋水。","傲骨长横肮?寒，雄心肯受泥涂死。","侯门马勃空见收，燕市狗屠无不游。","黄金自兀国士馆，黑貂且付胡姬楼。","天子方祠太乙神，甘泉赋客争前陈。","岂无蜀人扬得意，相如不救成都贫。","蓟门駃騠雪花白，临别殷勤绕朝策。","病夫竟逐车尘归，偃蹇衣冠失颜色。","掉头汝誇五岳盟，鞭抶万象无留行。","眼前岁星人未识，何用区区变姓名。"]},{"t":"醉歌赠明卿","f":"古风","c":["吴生吾为若楚歌，若为吾楚舞。","吾歌若舞不易得，窈窕青冥下雷雨。","冯夷鼓怒万灵奋，真宰仓皇向谁主。","么么碣石溟海外，黯淡齐州一抔土。","建安七子开元客，其人往往何足数。","昔贤踯躅襄陵辙，今贤龌龊邯郸武。","安得神鳌断足立四极，烛龙衔光导玄府。","羲和鞭，巨灵斧，王子借尔挥千古。","邢州太守朝天来，日日相过问吾汝。","曰：大儿孔文举，小儿杨德祖，呜呼吴生勿轻吐。"]},{"t":"金吾行赠戴锦衣","f":"古风","c":["金吾缇骑不可当，迥若饥鹘搏大荒。","碧瓦雕甍战崷屼，貂裘玉勒纷辉光。","但令奚雏剪头至，赤手卧夺黄金章。","人间陆海天茫茫，岂无英雄遂俛昂。","戴子不肯誇身强，邀我坐我堂中床。","葡萄暖发茵陈香，羽声春激白帝霜。","五侯七贵他自足，要令名姓登词场。","呜呼戴子一洗金吾色，野人愧杀尚书郎。"]},{"t":"解嘲三章答明佐 其一","f":"七言古诗","c":["长安酒旗红刺日，少年半死邯郸瑟。","三月飞花何太疾，庆卿被发悲且歌。","故人相遇不尽饮，明日单车愁奈何。"]},{"t":"解嘲三章答明佐 其二","f":"七言古诗","c":["乡里小儿爱儿戏，丈夫胡为亦如此。","头颅四十可知矣，铜池池上南风微。","庾公无金但袖手，何人赎取太真归。"]},{"t":"解嘲三章答明佐 其三","f":"七言古诗","c":["刘郎壁立无担石，少年场中逞颜色。","袒跣豪呼众辟易，彭城有客亦摴蒱。","乾坤一掷分枭卢，区区百万何为乎。"]},{"t":"戏题 其一","f":"七言古诗","c":["落魄不休衰自惊，学书学剑俱无成。","壶中有酒君且倾，男儿七尺何所用，借汝一驻千秋名。"]},{"t":"戏题 其二","f":"七言古诗","c":["长安日落俱苍然，炎风大雪天无权。","醉来得语醒不传，鄙夫五斗不敢厌，与贼共著吴中田。"]},{"t":"戏题 其三","f":"七言古诗","c":["何来赭衣青犊车，昨者玉带黄金鱼。","先生此时卧读书，闺中小妇不解事，问尔刺促终何如。"]},{"t":"明月篇","f":"古风","c":["长安月，团团薄太清。","初见扶光浴东海，俄看垂象满西京。","东海一轮承日起，西京万户回光里。","叶叶坠云衣，溶溶飘露蕊。","露蕊云衣湿奈何，三衢九陌胜偏多。","鳷鹊观头银作栋，凤皇池内玉为波。","谁家冶女能閒坐，若个游人不啸歌。","此时汉帝发长扬，白马鸣珂返建章。","群乌争宿玫瑰树，双燕元栖玳瑁梁。","甲帐全铺云母润，湘床欲透水晶凉。","亭亭绰约还旖旎，宛宛参差更颉颃。","小解罗缡交菡萏，回看碧瓦甃鸳鸯。","别有愁规永巷中，轻寒如水浸房栊。","葳蕤尽涩朱门锁，飒瑟偏归玉井桐。","陈后黄金买夜色，班姬纨扇箧秋风。","千年羿嫔长生药，百鍊秦王照胆铜。","捣兔分辉浑不羡，栖鸾顾影半成空。","分辉顾影愁无已，天上人间略堪拟。","先驱蹀?富平家，后引鞦韆冠军里。","琥珀千钟写不寒，珊瑚七尺看逾紫。","吹箫弄玉醉楼头，夺篦秦宫卧花底。","为道难忘复易知，结愿同生便同死。","东家羁妇望刀环，西邻弃妾守钗钿。","织成霞绮愁难写，捣尽霜砧响不传。","熠耀熹微时自没，络纬刺促解相煎。","明添密障银灯恨，暗促芳机玉箸悬。","玉箸银灯耿沾臆，龙城一去无消息。","军前刁斗郁边声，匣里芙蓉炼玄魄。","片片精光应太阴，声声凄调中无射。","候满俱惊似璧圆，临流忽映如丝白。","托梦还乡未有期，驰辉见君浑不得。","初二三夕展蛾眉，四五明蟾已蔽亏。","君听乐府关山月，只向征人唱别离。"]},{"t":"与高大夫游盘山歌","f":"七言古诗","c":["高侯挟我游盘山，下盘已见凌大荒。","一峰长悬辽海色，千涧暗发松花香。","寒流触磴挂玉乳，老桧破石垂青裳。","虎豹盘挐斗屈强，虬龙甲鬣森开张。","芒鞋恍蹑元气度，竹榼欲借春云装。","行穷杳霭径将绝，忽有钟声来上方。","排空独创舍利塔，凿壁更筑支公房。","我疲足力欲就枕，高侯贾勇不可当。","俯看群山一培塿，榆关铁岭横苍茫。","建牙吹角浩无际，飞刍转饷遥相望。","天门绝顶仅咫尺，安得送侯北斗傍。","坐挥如意夺敌胆，万马不敢骄秋霜。","野夫饱弄兹山色，何似日作尚书郎。"]},{"t":"戏题 其一","f":"古风","c":["君不见道傍石，太古留一拳。","自从陵阳过之泣，千椎万琢不得全。","野夫有语且自保，肯受龌龊时人传。"]},{"t":"戏题 其二","f":"古风","c":["君不见道傍柳，昨者黄金丝，今日萧条秃于帚。","人间毁誉风雨来，万事莫落书生口。"]},{"t":"怀柔六槐歌","f":"七言古诗","c":["怀柔署中六槐树，小者百尺凌穹苍。","五如五岳峙大荒，一若小室嵩之阳。","行天白日不能下，呼雨阑风势莫当。","金钱万缗夺春色，珠玑千斛抟秋霜。","饥乌怪鸱啼不歇，亦许狐兔穿其傍。","根蟠老大托后土，区区斧斤宁见伤。","东家梧桐仅人立，青皮剥落神摧藏。","虽有凤凰不肯顾，安得送汝参天长。"]},{"t":"端午日观骑士校艺怀来歌","f":"古风","c":["五月五日千花晴，怀来川头组练明。","乘骢使者出行营，张侯手抚诸干城。","?翿小带垂金铃，马耳削立听军声。","弯弓技似无甘蝇，满若纤阿霹雳鸣。","尾衔飞镝双流星，锦毬揉裂纷紫缨。","瞥然鸽起凌空冥，董生剑舞技何精。","雪山怒压霜涛崩，须臾突骑鼓不停。","降番猬鬣殊狰狞，决骤拟肉中原兵。","何来一校驰相迎，恍如云中白角鹰。","爪距格格摧秋翎，栏腰师比七尺轻。","败马局蹐不能行，掷来猊雏万众惊。","问之乃是前董生，黄金凿落珊瑚倾。","野夫鲸吸乾沧溟，酒间慷慨涕泪零。","漠南咫尺皆王庭，狼牙大纛天纵横，呜呼汝曹慎莫矜。"]},{"t":"亚泉行吴仲子索也","f":"古风","c":["谁罅五色石，下注昆崙丘。","泓然万顷玻璃秋，坼为两派江河流。","再画中原膏九州，蒸云噏日元气浮。","初分一线莲花边，要种白璧浇蓝田。","但看错落琼珠圆，往往上接沧浪天。","君不见康王谷头吐勺水，敢道人间第一泉。"]},{"t":"夜入保定公署秋隘风雨横来戏成一首","f":"七言律诗","c":["樊舆城中数椽木，蔓藟骄生妒人足。","使者何妨入狗门，诸君岂解惊牛屋。","此时天公太有权，行风逐雨相扶颠。","遥闻柏府沈深甚，不分啼乌竟夕眠。"]},{"t":"余定州飞白歌","f":"七言古诗","c":["吾家子敬不再得，千载能飞讵能白。","天公缩入余生手，独洗残碑悟神迹。","三尺生绡写相赠，草堂顿尔生颜色。","矫如溟壑盘虬龙，迅如雕鹗击大空。","细如游丝飏白日，澹如远汉垂晴虹。","黄河九道拆天倒，潆洄沸灪争相雄。","野夫平生好涂抹，小巫气索难为工。","呜呼吾欲游五岳，挟君题名遍寥廓。","六丁敛手那得妒，好与匡庐斗飞瀑。"]},{"t":"戏宗吏部买妾","f":"七言律诗","c":["江东小妇春十五，珊瑚荧荧海光妩。","千载唐昌夺颜色，帝遣琼枝待君吐。","鸦头步袜生莲金，胭脂销红玉箸侵。","半夜鸡声挽欢起，畏听旁帐白头吟。"]},{"t":"秋日过于鳞郡斋分赋十二体得俱字","f":"七言古诗","c":["使君匹马万里途，东观碣石沧瀛枯。","朔风吹寒金仆姑，道逢侠客胡虬须。","千金买宴争摴蒱，为他一掷狼居胥。","低眉急毂趋天都，道傍轻薄多揶揄。","使君大笑青云徂，中山酒薄不肯沽。","下马突入邢州厨，皎然文君坐当垆。","问我不醉何为乎，把舞如意惊珊瑚。","古人往矣不可呼，今人龌龊非吾徒。","与尔頫仰天模糊，安得化影长相俱，鞭双飞龙竟八区。"]},{"t":"是何行赠徐汝思参议","f":"七言古诗","c":["是何健儿来叩门，令我衣裳欲颠倒。","金华徐卿乍相见，落日金绯照枯槁。","老驺为倾厨头酝，醉夫手剥盘中枣。","入眼黄花巧相媚，促膝青灯寒更好。","未将华发论夙昔，更出新诗见怀抱。","自尔高歌蜀道篇，八数秋霜变原草。","山东李生大卓荦，晚得宗吴亦不恶。","迩来太华失帝意，下遣巨灵斧其角。","冠山神鳌颠簸荡，鬣风长鲸怒喷礴。","燕中贵人若反掌，江南佳丽同飞藿。","即使乔松亦摧挫，岂唯桃杏能索莫。","问我诗名如许细，黯淡逢人尚深削。","长安九衢春自阴，尺地尽化为黄金。","纵有文章挂北斗，其人往往皆陆沈。","腰间辘轳双玉鞘，十日不出芙蓉深。","临岐慷慨解相赠，报尔悠悠千古心。"]},{"t":"龙伯篇赠徐子与守汀州","f":"古风","c":["我驰轺车去京国，君拥楼船下震泽。","风尘片语成古今，星斗垂天各南北。","云扶恒顶大陆青，海擘鲸鬐九江黑。","贵人刺促虚见雠，处处江山真宰愁。","华阳洞中按谪籍，此曹落魄未可收。","不然簿牍纷相樛，混沌少足延春秋。","我今蹭蹬之青州，君亦五马东南游。","五马翩翩五赤龙，玉华天开玉芙蓉。","汀溪溪发桃花红，落花徐飞讼庭空。","讼庭往往烟霞色，案头一峰青欲滴。","醉后频呼白接䍦，兴来且着临川屐。","莫论名世五百年，例是词人二千石。","飞章报君还自言，道傍青绶何便便。","男儿身在无不可，即使折腰那足怜。","君不见龙伯灼鳌鳌极转，帝罚龙伯令之短。","犹能蚁观尘世人，仰摘匏瓜未为晚。"]},{"t":"游侠篇 其一","f":"古风","c":["侧坐犁眉騧，双牵短尾刁。","豪鹰逐呼来，万里天风骄。","平芜如裀杨柳绿，新丰酒美兔肩熟。","白日衔山不肯归，醉拥胡姬野中宿。","归来唾谓文成侯，汝曹爨下不自羞。","斗大黄金何足问，独身西断郅支头。"]},{"t":"游侠篇 其二","f":"古风","c":["碧眼昆崙奴，腰间双明月。","杯酒然诺间，寸心纵横发。","三尺吴钩七尺身，为君一掷同秋尘。","白虹射日日无色，咸阳道血波溅人。","君不见平津邸车门，戟士夜如蚁，乾坤不平从此始。","曷不一洗报天子，轵深里人安足拟。"]},{"t":"壶公篇","f":"七言律诗","c":["昔有汝南白头翁，手提玉壶称壶公。","壶中美酒十万斛，桃花树树骄春风。","长房小儿错狡狯，三试不过同沙虫。","我今但入不肯出，一醉天地无终穷。"]},{"t":"放歌赠子相考功出参闽省","f":"古风","c":["自从上帝与富媪不相得，展鳌一足摧一极。","黄河漰■向西北，赤水妖株扫奎壁，天下文章夺颜色。","君不见历下生尔时，脱屣辞承明。","道傍黄绶不肯跪，刺史刺促惭颜赪。","吴郎楚狂人，凤歌往往嘲公卿。","朝来襆被门下省，交游顷刻藏其名。","丈夫得失为龙蛇，精灵变化空咨嗟。","君不见王世贞，其人口吻俱烟霞。","令裤铁裲裆守东海，探丸杀吏纷如麻，绿沈枪头雪生花。","腰间有骨不自保，屈曲脂韦竟谁道。","欲诣扶桑数红日，可向中原照颠倒。","数子岂不甘沉沦，长安城中一宗臣。","酒酣击筑气益振，高歌四座空无人。","恍如玉山映秋旻，句成不知有鬼神。","翩然黄鹄离天津，要驱娲石绣七闽。","霓为车，风为马，张石帆，槌河鼓。","叱来武夷君，余与汝细数。","崇峰三十六，一一峰尖凤凰舞。","只今西太华、东岱宗，两山壁立峙太古。","不知南天竟何力，谁撑柱。","乃今知有武夷之颠高巉岩，使君为益千仞岩，不忧岳神上相谗。","世贞昔东迁，宗也遗之宝剑篇。","试弹蒯缑歌，歌曲未竟风冷然。","玄商起眦眦尽裂，回光滔荡难识察。","遂令人间三尺铁，夜夜星辰莽回列。","我欲还君剑、报君诗。","恐君试过延津道，化作双龙乘雨飞。"]},{"t":"民兵行","f":"七言古诗","c":["竹皮之冠双鹖尾，绣箙雕襕插弧矢。","匣中濙濙三尺水，马蹄纵横雪花起。","鲸波如山荡南纪，壮士肯作寻常死。","使君扪腹千卷书，那能血掴黄金鱼。","去时拜跪何足道，回时使君应不如。"]},{"t":"为俞使君赋紫云裘","f":"古风","c":["谁割五朵云，裁为使君裘。","使君自是补天手，天孙夺巧霓裳愁。","忆初裘敝西出秦，弃繻颇畏关头嗔。","苍皇五羖未称意，蹉跎一绨愁故人。","风尘变化在反掌，双熊却抱殷朱轮。","谁言汉家貂不足，翠羽明珰插晴陆。","九重忽念东征寒，逡巡捧自黄金屋。","玄菟雪花大于席，千嶂回飙咽哀角。","老上穷庐匿河渚，苏卿旄节凋沙漠。","芙蓉秀涩铁如意，葡萄昼冰银凿落。","使君披裘出按塞，恍若青阳照幽朔。","珠羁玉控汗血肥，锦鞲络臂腰师比，降人偶立听指挥。","三军顿其温挟纩，天子不废高垂衣。","只今平明登紫微，如花笑拥如云归。","酌君酒，为君寿。","周家翠凤竟何在，孟尝狐白那能守。","我有羊皮差胜君，桐江已落垂纶叟。"]},{"t":"醉后信口便成九韵","f":"七言古诗","c":["王生劝汝一杯酒，自古英雄落人手。","冠星饭露竟何限，马足车轮为谁久。","昨者磬折少年前，顾影俄然见老丑。","枵腹晨昏不得谢，归来仓皇詈其妇。","新诗赋就掩关读，风雷为我排晴昼。","千秋受驱万象役，曹刘失魄扬马走。","但使古人百不欺，笑任雌黄世间口。","吴江莼鲈解秋熟，七尺尚属王生有。"]},{"t":"李于鳞罢官歌","f":"古风","c":["人间奇事竟何限，李生掉头西出关。","金鱼紫衫掷中道，曳耒长耕历下山。","巨灵高掌摭不住，玉女噏呓愁云鬟。","以东岳海奋生色，星河错落雄其间。","雕锼万象抉元气，从此天公不得閒。","词场雁行忝王李，怅望逸翮胡由攀。","燕京冠盖但巀嵲，狂夫往事犹能说。","酒歌哀弦下风雨，剑舞急调排虹霓。","谢榛十诗九不道，布衣吾侪甘折节。","凤凰池头失傲吏，馀子散作中原别。","已许肮脏骄青云，复将飘零斗白雪。","虽其远游足畅意，五斗往往摧余舌。","呜呼李生太奇绝，赠生两丸弄千秋，骑一黄鹄览九州。","君不见古来豪杰多自量，屈宋焉敢兼巢由。"]},{"t":"大雨行","f":"七言古诗","c":["祝融朱鞭骑赤兕，砾石蒸波汗欲死。","谁令屏翳走天末，笞双骄龙立海水。","鳌转翻平大陆颠，槎回倒见银河底。","先生此时映帘坐，絺衣悉窣凉飙起。","新篘嘈嘈泣相语，先生鲸吸从此始。","缶中湖目将破颜，道傍禾头渐生耳。","先生起为屏翳约，三日一来来即止。","布谷罢唱催登场，莫遣耕夫怨秋耒。"]},{"t":"放歌答张助甫吏部","f":"七言古诗","c":["宗生自出尚书省，嵇氏罢草绝交篇。","长安项领胜培塿，使君腰腹为杯棬。","青州之城如斗大，纵有微言谁为宣。","乌声哑哑詈鸑鷟，谓尔枳棘不足怜。","衣裳五色亦楚楚，吉凶岂与人间权。","武昌不羞官长跪，历下但守妻儿眠。","此物居然在吾世，遇之不得空茫然。","何来青鸟衔一札，似是谷城黄石编。","虹电缭綟出其表，风雨却过龙蛇颠。","不道加飧长相忆，但道上下三千年。","顷从宗生骘王子，谓起腐令兼青莲。","斯言太重吾岂敢，后生颇畏前人贤。","君携琅玕坐斗柄，九关虎豹愁睊睊。","世途反覆日千变，不信但看沧浪天。","丈夫故有青云手，慎勿苦语众今传。","还君此札一大笑，野人早莫南山田。"]},{"t":"读胡侍鸿胪诗有感因遗其从子邑博叔才","f":"古风","c":["十年但耳胡鸿胪，鸿胪之墓三草枯。","世人自失凤凰羽，此日满把骊龙珠。","虽于风雅未县合，往往时材骨格殊。","辞官著书欲何作，书成不换囊青蚨。","床头一绨酒家共，缶中半菽时有无。","齐名关西者谁子，肯放白雪骄巴歈。","中丞冠峨铁獬豸，辽阳马被貂襜褕。","胡家岂无双玉树，或摧秋霰今穷途。","呜呼胡生慎莫学汝伯，汝伯文章老成癖。","不见山鸡敢凤鸣，且向人间斗毛色。","封侯拜相在一言，枉杀书生万言策。"]},{"t":"醉后信口劝客饮","f":"古风","c":["今日为客，挂却头上豸，解我腰间鱼。","簪缨缧绁不足道，形骸土木终何如。","少年弹棋六博兼摴蒱，一一将置前庭除，与客递起为欢娱。","东流之水西上舻，世人自贤吾自愚。","客不见洛阳苏生恶少年，开口造化俱无权。","横六黄金五车裂，总为城南二顷田。","客不见魏齐声势同山丘，厕中死人断君头。","黥徒马食相堂下，当时溺者秦应侯。","人生反覆难预期，精灵一别千忧随。","请看草木有荣悴，荣者何恩怨者谁。","丈夫不能龌龊权门取荣贵，驱遣七尺供妻子。","又不能仰面看屋梁，万岁千秋亦如此。","浊泾清渭何能理，先生一言客记取，拍浮酒船吾足矣。"]},{"t":"走笔恼徐汀州入计","f":"古风","c":["尔时邢州侯，伏谒上帝前。","称友四五臣，各自操其权。","清狂在膏肓，一切不受痊。","朝拥红鹔鹴，夕挂酒垆边。","北斗神浆竭，南斗为相延。","大呼阳春倡，忽恼天公眠。","擿令巨鳌走，漂沦众神仙。","岳分太古色，海吐齐州烟。","君今五马去，亦自称朝天。","回首阊阖空，其臣谁复然。","乃知宇宙能作态，风雨一度三千年。"]},{"t":"于鳞遗苦酒瓜酱夜醉放歌戏用为报","f":"古风","c":["朝对云门雪，隐如两玉山。","时无一杯饮，何以俱颓然。","平头大奴尺一书，戟之不得中庭趋。","青丝提绳白玉壶，郁金香夺银酡酥。","沉瓜片片芍药酱，压来纤甲痕珊瑚。","削瓜进酒咍不止，谓我卒当以乐死。","雪花为茵不肯寒，夜半歌声剑波起。","兰缸茕茕漏丁丁，罢舞起看头上星。","南有匏瓜北有斗，碧霞之脯天公酒。","虚名误人竟何有，安期生，闭女口。","瓜出蔡姬酒，李侯八千年来汝得否。"]},{"t":"慰明卿再谪长短歌二章和李于鳞 其一","f":"七言古诗","c":["明堂堂成不见帝，十二牧伯朝逡巡。","丞相肩舆入内殿，摇笔一扫三千人。","王生束装视黜籍，乃见武昌吴国伦。","无官可谪左已久，有地足徙恩仍新。","甘泉诸贵气成云，吴也亦是甘泉臣。","小臣无状业万死，尚许短檄随风尘。","长沙坐中止鵩鸟，鲁东门外悲麒麟。","何方魑魅不抚掌，何处猿猱不鼓唇。","李侯杜门十月矣，唶女再黜奚其陈。","此时尺一驰南康，府主揶揄目吴郎。","卷衣大笑出府舍，一舸乘风上武昌。","匡庐五老宛相揖，长江九派流飞觞。","归来萧条四壁立，大妇谇骂小妇伤。","女等徒称弦金石，岂无宗徐李与王。","时从处士誇鹦鹉，可救文君典鹔鹴。","何物故人能见负，却令妻子徇文章。","啼寒泣饥苦未已，东驰西窜穷遐荒。","燕中炊米若炊玉，公田种秫不种粳。","贡家车马谁与买，季子貂裘胡计藏。","解道人间富官职，女岂不念头上霜。","吴郎欲答答不得，王生请为歌夙昔。","日者岁之丙辰前，五星犹闻在奎壁。","片语高呼白雪飞，寸心肯让青云色。","吾宗少年强解事，吴郎目摄遗其舄。","岂唯吴郎众辟易，但语吾曹少坚敌。","司空挝鼓尽裸袒，武安行酒半膝席。","小儿仅呼杨德祖，一钱可拟程不识。","倘闻曹中理公事，君其且看西山碧。","故知万变同翻手，风雨青天昼能吼。","遗舄少年坐上坐，谁哉捧案前奔走。","世人荣辱强相制，吾辈行藏终自取。","妻子宁须饶远略，且用七尺饵其口。","即使女官更削尽，豫章男子得活不。","女乏江陵千树橘，来共吴门千畦韭。","耕尽要离墓上云，洗眼看他竟何有。"]},{"t":"慰明卿再谪长短歌二章和李于鳞 其二","f":"古风","c":["呜呼，吴郎似不欲女人间住，毕竟何方可容女。","造物由来有深意，丈夫未必终穷苦。","屈家老翁错解事，强作区区不平语。","迷魂大招招不得，鼪鼯对啼江上雨。","鱼腹脂消骨何在，海内文章竟归楚。","湘山九疑江九派，天地为之尚吞吐。","回首当时一子兰，澌流草没施荒烟。","英雄七尺本有托，断不俯受凡人怜。","吴郎未买南山田，拂衣且登五岳颠。","倘有韩众授丹诀，入口白日升青天。","不然来访王与李，片语共作三千年。","男儿死则有死耳，安能再辱咸阳之道边。","噫嘻，劝君归去者谁子，其人折腰车马前。"]},{"t":"送陈副使罢官还蜀","f":"七言古诗","c":["陈侯不愿二千石，西望三巴鬓为白。","台中解绶欲生还，御史下堂相苦迫。","荐书空自满承明，紫马翩然辞帝京。","河东股肱任尔毁，山人腰骨今殊轻。","却过九折回车地，大笑当时叱驭生。","为问君恩竟多少，无烦令伯陈情表。","郫筒酒底东风宽，邛竹杖头明月小。","更羡春鸡问寝归，支颐坐对峨眉晓。"]},{"t":"过张吏部留题","f":"七言古诗","c":["君家屏风五尺雪，上有颠蓑迹盘郁。","麈尾蟏蛸半壁垂，胡床以外无长物。","使君酒圣谁当敌，新丰酽夺梨花色。","饮酣不识袁彦道，布帽已染吴兴墨。","金壶丁丁水欲尽，临行掷杯意难忍。","安能三日不相过，令我真成轻薄尹。"]},{"t":"歌送董佥事之大同","f":"古风","c":["盘雕锦袍铁䯀骢，绣旗双飐桃花红。","董家南塘聊一出，万舸不敢乘春风。","健儿百战髓力尽，天子高卧咸阳宫。","抚髀之对何匆匆，谁夺我公向云中。","南粤王头阙下矣，六裸北首穹庐空。","代人巷贺吴人哭，安得分身来救侬。","剑歌大白须满饮，天下健者唯董公，呜呼天下健者唯董公。"]},{"t":"即事有感寄故张职方","f":"七言律诗","c":["燕中冰雪正磊砢，行人马头日駊騀。","别驾那辞广柳车，中丞且进琅珰锁。","牙旗甲帐少辉光，玉箸红颜泣数行。","如渑酒在不得醉，悔不潦倒尚书郎。"]},{"t":"夜过前中丞翟廷献饮醉作","f":"七言古诗","c":["翟公之门雀可罗，五马焉用长经过。","丈夫意气偶相许，不惜葡萄千石多。","君家食单况无敌，蒸饼能为十字坼。","凫臇金缕压鹅黄，蟹擘霜螯胜熊白。","洛城可数饮乳豚，安定虚传噎鸠麦。","问君行年七十强，红颜绿鬓双瞳方。","手谈意彄尽奇品，高歌激尘飞绕梁。","一杯一曲殊未已，残月千门夜如水。","欲别无劳问姓名，其人高阳酒徒耳。"]},{"t":"即事书怀二章 其一","f":"七言古诗","c":["四十不足三十馀，如何辄拥连城居。","以兹但饮淄流水，不敢时通政府书。","旦暮移文如湿束，东西手板同驱逐。","何武公然欲露章，山涛久矣忘除目。","宁使鲛龙困蝼蚁，岂容燕雀知鸿鹄。","任他牙爪日纷纷，难向青山攫白云。","我自安排容足处，裁诗先属太茅君。"]},{"t":"即事书怀二章 其二","f":"七言古诗","c":["十年对客归去来，往往坐被商山咍。","使君嚄唶不自了，知我者谁御史哉。","吴中风土殊不恶，葑田虽微给衣药。","那能请急淹岁时，便可逃荣老丘壑。","骠骑终输第五名，仆射难胜酒杯乐。","躬耕手钓骄未能，学书学剑慵无成。","唯应侍膳春朝后，饱看云霞弄太清。"]},{"t":"翁中丞南巡歌","f":"古风","c":["自公之昔除烦苛，规调如山刍粟多。","居人渐徙虎豹穴，大海欲戢鲸鲵波。","片言龃龉辄投劾，安石不出苍生何。","归来束书四壁立，岂有蜡屐双青蛾。","若耶若镜不足钓，抱膝时时闻啸歌。","夷德虽轻犹未厌，以兹颇晚山公荐。","西汎三江奏春雪，南驰五岭开炎霰。","汉筴恒馀圮上编，齐书尚郁聊成箭。","今年五月天山定，圣主推轮飞六传。","中丞獬廌铁作冠，宣室麒麟玉为殿。","轻裘缓带来东吴，妖氛却扫旄头孤。","星辰莽动铁如意，风雨长鸣金仆姑。","拊循三军挟貉纩，惕息诸将昂虬须。","馀皇万艘?驱叶，组练千重霜剪芜。","南越王头挂大白，马蹄扑簌累夷俘。","儿童抛弃竹马拜，父老不用藜杖扶。","我公五载犹一夕，鬓发全无半茎白。","寇恂谁借留河内，李晟天生为社稷。","露章日夜走长安，竹宫祠釐动颜色。","御史趣刻蟠螭印，丞相且画交龙敕。","若若双垂绶青紫，万户侯兼二千石。","牙璋不动画戟横，朱幡映夺沧浪清。","此时王生一游客，步入辕门人尽惊。","愿为十日布衣饮，客星倒据三台明。","何人可当虚左席，扪腹无踰于此生。","孟坚好推勒石颂，仲宣愧杀从军行。","公犹未发我未去，丈夫有志事竟成。","大鹏尺鴳各有适，不废万古俱垂名。"]},{"t":"歌赠邢先辈","f":"古风","c":["邢郎眼如紫石棱，自云昔者师神僧。","胡床踞坐铁如意，一一空青指玉绳。","紫微坐中金不收，荧惑莽动心为愁。","天公瞆瞆双眼合，天上星辰俱倒流。","安得叱长虹，化银桥与君上。","?取璚波灌白榆，业风千岁无排荡。","归来北斗挹神浆，更有匏瓜可摘尝。","莫槌河鼓惊阊阖，只向机头请七襄。"]},{"t":"荆玉篇","f":"古风","c":["君不见道傍石精，光自缭绕。","夜夜天中属白虹，时时海上来丹鸟。","卞生持抱入昭关，愿学虞廷一献环。","沂水未应输若水，昆山不敢傲荆山。","祝宗虚闻誇祭饰，太史那能上占式。","未必君廷俱宋相，其奈工师有周客。","回首群灵尽黯然，龙文欲吐咽苍烟。","璠䃉首列乌绨几，对此云何不可怜。","智矣如葵能卫足，问君泣足还泣玉。","窃比东门独角麟，宁言使者空笼鹄。","君王三听未为劳，好向昆吾问宝刀。","煜煜阳乌升碧汉，亭亭魄兔浴银涛。","捧出倾城动颜色，隋珠越镠咸辟易。","共道应偿十五城，何须更爱二千石。","膝行向前中自伤，野人焉敢食陵阳。","唯凭寄语乐正子，三月胡为不下堂。"]},{"t":"题十八学士春宴图","f":"七言古诗","c":["梁园碧筠潇湘玉，小山丛枝缀金粟。","天公驱龙耨秦土，移入秦王天策府。","虬髯主人马上客，手掴中原血华赤。","芸氛霏霏讲初罢，狮子骢头散鞭喏。","软罗半臂春风偏，十八奚驹嘶紫烟。","玉酥宫痕纤月甲，银瓮戈书小黄押。","大槽乱拍真珠流，葡萄就煖沈香虬。","琵琶掩瑰鹍鸡促，声声破阵秦王曲。","羲轮半舂启明曜，莱公起舞密公笑。","就中小薛醉隗俄，龙门老师奈若何。","太子宫前演鸡戟，铜马时时齧荆棘。","诸君诘朝且虚左，隽州流人来上坐。"]},{"t":"承大司马濮阳苏公惠览诗集率尔有酬 其一","f":"七言律诗","c":["青门耕烟一老臣，黄石赤松先后身。","天书姓名隶琬琰，何足道哉汉麒麟。","自谱游仙度红玉，凤笙云璈宛相属。","犹有军中突厥盐，污他半部清商曲。"]},{"t":"承大司马濮阳苏公惠览诗集率尔有酬 其二","f":"七言律诗","c":["苏家五言李少卿，半割汉语归王庭。","昨埽祁连并收得，奚珠错落珊瑚明。","焉支山头湛卢紫，仰划天河赤璚水。","写作人间龙凤鸣，一洗千秋濮中耳。"]},{"t":"怅怅行闻吴明卿至遗之","f":"七言古诗","c":["忆昔弹冠事明主，奕奕轩车走环堵。","雄白那能守一身，雌黄直是论千古。","当时意气迥堪怜，家难飘零燕市边。","乞食监河无羡粟，橐饘深室不论钱。","骠骑沉沉似九阍，低头抢地欲销魂。","生男未免仓公辱，失势方知狱吏尊。","吞声馀息还如死，削迹何人是知己。","挂剑空馀落日心，援琴几废高山指。","生平国士定谁如，消息经年恨有馀。","千回杜曲杯前梦，一字衡阳雁外书。","野夫昨夜惊耳热，闻有金明雨中辙。","青镜婵娟欲奋飞，掩泪沉吟更愁绝。"]},{"t":"吴明卿以再调至京值余方事家难不数数见也于其行聊以拟古歌二章赠之南冠楚音相对歔欷无复易水慷慨之致繇才气都尽耳 其一","f":"七言古诗","c":["薰风如饴昼履霜，之子何役向河梁。","哀鸿摧弦离披翔，有似游子不获宁。","往遘千绪结中肠，欲言未言以彷徨。","浮云踟蹰鉴我伤，谁言无情不见明。","连城如山拉然崩，穿墉啸莽伏豺狼。","鬼车旦鸣獝猖狂，嗟嗟独留殢高堂。","黄河浊流限清湘，子今胡为厌故疆。"]},{"t":"吴明卿以再调至京值余方事家难不数数见也于其行聊以拟古歌二章赠之南冠楚音相对歔欷无复易水慷慨之致繇才气都尽耳 其二","f":"七言古诗","c":["浮云淡淡日就沦，请室漫漫何时晨。","我欲偕子眇无因，美人如花玉为颜。","妙舞黄鹄体仙仙，何以当笑黄金千。","众女谣诼令亲疏，失身为君君不愉。","空房迢迢清夜徂，东邻弃娃仲卿妻。","生少不谐常独栖，兰摧璧陨委涂泥。","兰摧璧陨宁再全，君恩虽逝犹当还。","为君抵节歌盘桓，栈马当刍意流连。","仰看北斗正阑干，迹往虞来伤肺肝。"]}]};